function Clear-TmpViejo([string]$donde = '') {
    # Devuelve @{ ficheros; bytes; nombres }. Solo el primer nivel y solo ficheros: tmp\voz es
    # la cache de la voz y tiene DUENO -tts_worker.py la poda sola con su propio tope de 60 MB-,
    # y dos limpiadores sobre la misma carpeta es como se pierde una cache entera.
    $r = @{ ficheros = 0; bytes = 0; nombres = @() }
    if (-not $donde) { $donde = $TmpDir }
    if (-not $donde -or -not (Test-Path -LiteralPath $donde)) { return $r }
    try {
        $vivos = New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)
        foreach ($v in $TmpVivos) { [void]$vivos.Add($v) }
        # NADA DE LO ESCRITO DESDE QUE ARRANCO ESTE PROCESO: si algo se ha tocado hoy, esta vivo
        # por definicion, y la edad podria enganar con un reloj movido.
        $desde = (Get-Date).AddDays(-1 * $TmpVidaDias)
        $secretos = @()
        foreach ($f in @(Get-ChildItem -LiteralPath $donde -File -ErrorAction SilentlyContinue)) {
            if ($vivos.Contains($f.Name)) { continue }
            # .lock y .flag son senales, no datos: valen cero bytes y su ausencia significa algo
            if ($f.Extension -in @('.lock', '.flag')) { continue }
            if ($f.LastWriteTime -gt $desde) { continue }
            # UN SECRETO SE AVISA ANTES DE BORRARLO, no despues: si se borra callando, braya no
            # se entera nunca de que tiene una clave que rotar.
            if ($f.Length -lt 4096) {
                try {
                    $c = [IO.File]::ReadAllText($f.FullName)
                    if ($c -match '(?:sk-[a-z]{2,4}-[A-Za-z0-9_-]{20,}|AIza[A-Za-z0-9_-]{30,})') { $secretos += $f.Name }
                } catch {}
            }
            $r.ficheros++
            $r.bytes += [int64]$f.Length
            $r.nombres += $f.Name
            Remove-Item -LiteralPath $f.FullName -Force -ErrorAction SilentlyContinue
        }
        if ($r.ficheros -gt 0) {
            Log ("TMP: solte $($r.ficheros) fichero(s), $([Math]::Round($r.bytes / 1MB, 1)) MB: " + (($r.nombres | Select-Object -First 12) -join ', '))
        }
        if ($secretos.Count -gt 0) {
            Log ("SECRETO EN CLARO: " + ($secretos -join ', ') + " llevaba(n) mas de $TmpVidaDias dias en tmp; lo he borrado, pero hay que rotar esa clave")
            [void](Send-AvisoEntorno 'secreto-en-claro' `
                ("He encontrado una clave escrita en claro en un fichero viejo de mis temporales y lo he borrado. Deberias cambiar esa clave, porque llevaba dias ahi.") 'alto' 43200)
        }
    } catch { Log ('tmp: no pude barrer: ' + $_.Exception.Message) }
    return $r
}

function Clear-CachesDisco {
    $antes = 0.0
    try { $antes = [Math]::Round((New-Object System.IO.DriveInfo('C')).AvailableFreeSpace / 1GB, 2) } catch {}
    $tocadas = 0
    foreach ($c in $CachesLimpiables) {
        if (-not $c.ruta -or -not (Test-Path -LiteralPath $c.ruta)) { continue }
        try {
            # SE BORRA EXACTAMENTE LO QUE SE CONTO (revision del 23/09). Get-TamanoMB cuenta
            # FICHEROS, recursivamente, y por la fecha DEL FICHERO; esto listaba solo el
            # primer nivel, miraba la fecha de la ENTRADA -carpetas incluidas- y borraba con
            # -Recurse. Medido en su %TEMP%: se anunciaban 193 ficheros viejos = 12,3 MB y se
            # borraban 22 entradas = 0,44 MB. Pedir permiso para doce megas y soltar medio es
            # exactamente lo que la casa no tolera. Y de paso se iba la punta peligrosa: una
            # carpeta vieja se llevaba por delante los ficheros de ayer que tuviera dentro.
            $items = Get-ChildItem -LiteralPath $c.ruta -Recurse -File -Force -ErrorAction SilentlyContinue
            if ([int]$c.dias -gt 0) {
                $corte = (Get-Date).AddDays(-[int]$c.dias)
                $items = @($items | Where-Object { $_.LastWriteTime -lt $corte })
            }
            foreach ($it in $items) {
                # y NUNCA la carpeta de Nova: ahi viven sus propias copias y medidas
                if ($it.FullName -like "*voice-ctrl*" -or $it.FullName -like "*claude*") { continue }
                try { Remove-Item -LiteralPath $it.FullName -Force -ErrorAction SilentlyContinue; $tocadas++ } catch {}
            }
            # y despues, las carpetas que se hayan quedado vacias. De dentro hacia fuera, y
            # solo si no queda NADA: una carpeta con un fichero de hoy no se toca.
            $dirs = @(Get-ChildItem -LiteralPath $c.ruta -Recurse -Directory -Force -ErrorAction SilentlyContinue |
                      Sort-Object -Property { $_.FullName.Length } -Descending)
            foreach ($dd in $dirs) {
                if ($dd.FullName -like "*voice-ctrl*" -or $dd.FullName -like "*claude*") { continue }
                try {
                    if (-not (Get-ChildItem -LiteralPath $dd.FullName -Force -ErrorAction SilentlyContinue)) {
                        Remove-Item -LiteralPath $dd.FullName -Force -ErrorAction SilentlyContinue
                    }
                } catch {}
            }
        } catch {}
    }
    $despues = $antes
    try { $despues = [Math]::Round((New-Object System.IO.DriveInfo('C')).AvailableFreeSpace / 1GB, 2) } catch {}
    return @{ antes = $antes; despues = $despues; soltado = [Math]::Round($despues - $antes, 2); tocadas = $tocadas }
}

# LIMPIAR LO QUE CREE SABER DE BRAYA (23/09, funcion 5 de la tanda de funciones nuevas).
# perfil.md tiene 59 datos y el tope son 60: esta a un dato de llenarse, y a partir de ahi
# cada dato nuevo expulsa a otro. Y solo las 15 ultimas lineas viajan en cada prompt de la
# charla, o sea que lo que este ahi arriba le vuelve hablado. Hoy, OCHO de esos 59 se los
# comen dos nombres MAL OIDOS: cuatro lineas de "Meramiau"/"Mira mio"/"Meramian" -que
# acabaron inventando un gato que no existe- y cuatro de un juego llamado "Amin"/"Amino".
# (Contado hoy sobre el fichero: 59 lineas que empiezan por "- "; Amino en las 16, 18, 19 y
#  20, y los Meramiau en las 24, 25, 27 y 34.)
# El caso que lo prueba es del 20/09 a las 23:09-23:11: sus DOS correcciones seguidas del
# nombre del juego se guardaron como dos datos NUEVOS encima del malo, en vez de corregirlo.
#
# COMO SE LIMPIA SIN INVENTAR: no se decide solo. Se buscan los dos datos que mas se parecen
# entre si -los que casi seguro son el mismo con dos redacciones- y se le PREGUNTA con las dos
# opciones delante. Una pregunta, dos opciones, y el que sobra se va. Nada de borrar a ciegas
# lo que el escribio.
$script:perfilPar = $null
# Resuelve el par: 1 = me quedo con la primera, 2 = con la segunda, 0 = las dejo las dos.
# La usan las DOS vias -la voz y el mando-, asi que el borrado esta escrito una sola vez.
function Resolve-PerfilPar([int]$cual) {
    $p = $script:perfilPar
    $script:perfilPar = $null
    if (-not $p) { return 'ya no tengo esa pregunta abierta' }
    if ($cual -ne 1 -and $cual -ne 2) { return 'vale, las dejo las dos' }
    $fuera = if ($cual -eq 1) { [string]$p.b } else { [string]$p.a }
    $dp = @(Get-DatosPerfil)
    Save-DatosPerfil (@($dp | Where-Object { $_ -ne $fuera }))
    Log "PERFIL: braya eligio la $cual; fuera '$fuera'"
    Add-Estadistica 'perfil-limpia' $fuera
    return 'hecho, me quedo con la otra'
}

function Get-ParParecidoPerfil {
    $datos = @(Get-DatosPerfil)
    if ($datos.Count -lt 8) { return $null }
    # las palabras que salen en medio perfil no distinguen nada (ver Add-DatoPerfil): el mismo
    # calculo, para no medir el parecido por "braya" y "tiene".
    $cuenta = @{}
    foreach ($y in $datos) {
        $cy = (((ConvertTo-Suave $y) -replace '[^a-z0-9 ]', ' ') -replace '\s+', ' ').Trim()
        foreach ($w in @($cy -split '\s+' | Where-Object { $_.Length -ge 4 } | Select-Object -Unique)) {
            $cuenta[$w] = [int]$cuenta[$w] + 1
        }
    }
    # MAS ESTRICTO QUE EN Add-DatoPerfil, y a proposito: alli se compara un dato NUEVO
    # contra los viejos, y aqui se comparan los 59 ENTRE SI. Con el liston de un tercio,
    # "tiene" (15 de 59) no contaba como vacia y emparejaba "tiene dificultad con
    # Meramiau" con "braya tiene algo que se le acaba", que no tienen nada que ver.
    $topeV = [Math]::Max(3, [int][Math]::Ceiling($datos.Count / 6.0))
    # UN NOMBRE PROPIO NUNCA ES UNA PALABRA VACIA, por pocas lineas que haya. Con diez datos
    # el tope sale 3, y "Amino" -que esta en tres lineas- se marcaba como comun y desaparecia
    # justo el caso que se venia a cazar. Los nombres propios se calculan abajo, asi que aqui
    # se dejan fuera del filtro por su forma: empiezan por mayuscula dentro de la frase.
    $conMayus = @{}
    foreach ($y in $datos) {
        $pal0 = @($y -split '\s+')
        for ($k0 = 1; $k0 -lt $pal0.Count; $k0++) {
            $w0 = $pal0[$k0] -replace '[^\wáéíóúñÁÉÍÓÚÑ]', ''
            if ($w0.Length -ge 4 -and $w0.Substring(0, 1) -cmatch '[A-ZÁÉÍÓÚÑ]') { $conMayus[(ConvertTo-Suave $w0)] = $true }
        }
    }
    $vacias = @($cuenta.Keys | Where-Object { $cuenta[$_] -ge $topeV -and -not $conMayus[$_] })
    # Y LOS NOMBRES PROPIOS, que es donde esta la basura de verdad. Su perfil tiene hoy tres
    # lineas de un juego llamado "Amino" -"se llama Amino", "usa Amino", "juega en Amino"- y
    # dos de un "Meramiau" que el oido se invento. Son frases de dos o tres palabras: por
    # proporcion no se emparejan nunca, porque casi no tienen palabras que comparar.
    # La señal es otra: comparten un nombre PROPIO (con mayuscula y no al principio de la
    # linea) que sale en pocas lineas, y las dos frases son cortas. Medido sobre sus 59 datos,
    # eso encuentra las tres de "Amino" y el "Steam" repetido, y ni un falso: los verbos
    # comunes -"prefiere", "quiere"- se caen solos porque van en minuscula.
    $propios = @{}
    foreach ($y in $datos) {
        $pal = @($y -split '\s+')
        for ($k = 1; $k -lt $pal.Count; $k++) {
            $w = $pal[$k] -replace '[^\wáéíóúñÁÉÍÓÚÑ]', ''
            if ($w.Length -ge 4 -and $w.Substring(0, 1) -cmatch '[A-ZÁÉÍÓÚÑ]') {
                $propios[(ConvertTo-Suave $w)] = $true
            }
        }
    }
    $mejorA = ''; $mejorB = ''; $mejorP = 0.0
    for ($i = 0; $i -lt $datos.Count; $i++) {
        $pa = @(((((ConvertTo-Suave $datos[$i]) -replace '[^a-z0-9 ]', ' ') -replace '\s+', ' ').Trim() -split '\s+') |
                Where-Object { $_.Length -ge 4 -and $vacias -notcontains $_ } | Select-Object -Unique)
        if ($pa.Count -lt 1) { continue }
        for ($j = $i + 1; $j -lt $datos.Count; $j++) {
            $pb = @(((((ConvertTo-Suave $datos[$j]) -replace '[^a-z0-9 ]', ' ') -replace '\s+', ' ').Trim() -split '\s+') |
                    Where-Object { $_.Length -ge 4 -and $vacias -notcontains $_ } | Select-Object -Unique)
            if ($pb.Count -lt 1) { continue }
            $comunes = @($pa | Where-Object { $pb -contains $_ })
            # el caso del nombre propio: dos frases cortas que hablan de lo mismo
            # EL TOPE ES 6 Y NO 4 (revision del 23/09): su perfil tiene CUATRO lineas de
            # "Amino", asi que con "-le 4" entraba por los pelos y una quinta -que llega
            # sola, porque el oido sigue inventandoselo- sacaba del rango justo el caso que
            # se viene a cazar.
            $raras = @($comunes | Where-Object { $propios[$_] -and [int]$cuenta[$_] -ge 2 -and [int]$cuenta[$_] -le 6 })
            $cortaA = (@($datos[$i] -split '\s+').Count -le 8)
            $cortaB = (@($datos[$j] -split '\s+').Count -le 8)
            if ($raras.Count -gt 0 -and $cortaA -and $cortaB) {
                # GANA EL NOMBRE QUE MAS LINEAS ENSUCIA (revision del 23/09). Antes se fijaba
                # un 0,9 plano y se comparaba con "-gt" estricto, asi que ganaba el PRIMER par
                # de 0,9 que apareciera y todos los empates posteriores se tiraban. Medido
                # sobre su perfil de verdad: salia el par "tiene 14 juegos instalados en
                # Steam" / "Braya usa Steam" -que son dos datos DISTINTOS, o sea que Nova
                # proponia borrar informacion buena- y las cuatro lineas de "Amino" no se
                # ofrecian jamas. Con la cuenta, "Amino" (4 lineas) gana a "Steam" (2).
                $sc = 0.9 + 0.001 * [int]$cuenta[$raras[0]]
                if ($sc -gt $mejorP) { $mejorP = $sc; $mejorA = $datos[$i]; $mejorB = $datos[$j] }
                continue
            }
            if ($comunes.Count -lt 2) { continue }
            $p = [Math]::Max($comunes.Count / [double]$pa.Count, $comunes.Count / [double]$pb.Count)
            if ($p -gt $mejorP) { $mejorP = $p; $mejorA = $datos[$i]; $mejorB = $datos[$j] }
        }
    }
    # 0,6 es el mismo liston con el que Add-DatoPerfil decide que dos frases son el mismo tema
    if ($mejorP -lt 0.6) { return $null }
    return @{ a = $mejorA; b = $mejorB; parecido = [Math]::Round([Math]::Min(1.0, $mejorP), 2) }
}

# MONTAJES CON NOMBRE (23/09, funcion 3 de la tanda de funciones nuevas).
# Es lo que mas ha pedido braya y lo unico que nunca consiguio: el propio codigo lo tiene
# contado -en catorce dias la pantalla dividida no se ejecuto bien ni una vez por voz, cero de
# once intentos-. Y no es un capricho suelto: YouTube en una mitad y Pinterest en la otra sale
# en ocho momentos distintos, y el 18/09 a las 20:04 se quejo por voz ("solo abriste Pinterest,
# nunca abriste YouTube ni dividiste la pantalla"). Su perfil dice para que le sirve: quiere
# recrear una foto con su pareja -las referencias en Pinterest, el tutorial en YouTube-.
# Hoy hay cinco patrones peleandose por adivinar como lo dice. Con un nombre no hay nada que
# adivinar: "guarda esto como el tablero" y luego "pon el tablero".
#
# EL MONTAJE NO SE SACA DE MIRAR LA PANTALLA: se guarda de los destinos YA RESUELTOS de un
# "dividir" que Nova acaba de ejecutar bien. Asi guarda "https://www.pinterest.com a la
# izquierda" y no "dos ventanas de Edge", y no le hace falta saber leer la barra del navegador.
$MontajesPath = Join-Path $MemoriaDir 'montajes.json'
$script:montajes = $null
function Get-Montajes {
    if ($null -ne $script:montajes) { return $script:montajes }
    $script:montajes = @{}
    try {
        if (Test-Path -LiteralPath $MontajesPath) {
            $crudoM = Get-Content -LiteralPath $MontajesPath -Raw -Encoding UTF8 | ConvertFrom-Json
            foreach ($pm in $crudoM.PSObject.Properties) {
                $script:montajes[$pm.Name] = @{
                    izq = [string]$pm.Value.izq; der = [string]$pm.Value.der
                    izqTipo = [string]$pm.Value.izqTipo; derTipo = [string]$pm.Value.derTipo
                    cuando = [string]$pm.Value.cuando
                }
            }
        }
    } catch { Log ('montajes: no pude leerlos: ' + $_.Exception.Message) }
    return $script:montajes
}
function Save-Montajes {
    # MODO INVITADO: lo que diga otro no se queda (17/09). Un invitado puede MONTAR los que
    # ya hay -eso no escribe nada-, pero no crear ni borrar montajes en la consola de braya.
    if ($script:invitado) { Log 'montajes: modo invitado, no guardo nada'; return }
    try {
        [System.IO.File]::WriteAllText($MontajesPath, (ConvertTo-Json -InputObject (Get-Montajes) -Depth 4),
                                       (New-Object System.Text.UTF8Encoding($false)))
    } catch { Log ('montajes: no pude guardarlos: ' + $_.Exception.Message) }
}
# ABRIR O ENFOCAR, que no es lo mismo: 'dividir' siempre hace Start-Process, asi que si el
# navegador ya estaba abierto te abre OTRO. Aqui se mira primero si ya hay una ventana suya.
function Show-OAbrir([string]$tipo, [string]$destino) {
    if ($tipo -ne 'url') {
        $nom = [System.IO.Path]::GetFileNameWithoutExtension($destino)
        $pv = $null
        try { $pv = @(Get-Process -Name $nom -ErrorAction SilentlyContinue | Where-Object { $_.MainWindowHandle -ne 0 })[0] } catch {}
        if ($pv) {
            try {
                [void][AX]::ShowWindow($pv.MainWindowHandle, 9)
                [void][AX]::ForceForeground($pv.MainWindowHandle)
                return $true
            } catch {}
        }
    }
    try {
        if ($tipo -eq 'url') { Start-Process $destino -ErrorAction Stop }
        else { $null = Start-Process $destino -PassThru -ErrorAction Stop }
        return $true
    } catch { Log ("montaje: no pude abrir $destino"); return $false }
}

# AJEDREZ A CIEGAS (23/09, lo pidio braya). Las reglas las lleva python-chess y juega
# Stockfish: aqui solo esta el puente. Un turno = un proceso que arranca y se muere (medido:
# 1,2 s, de los que 0,15 son pensar); un worker vivo ahorraria medio segundo y le quitaria
# memoria al juego durante horas, que es justo lo que no se quiere.
#
# LA TRIPLE LLAVE para que una frase cuente como jugada, y las tres hacen falta:
#   (a) hay partida abierta -si no, ni se mira-;
#   (b) la frase tiene FORMA de jugada, con patron anclado en ^...$, no un -match suelto;
#   (c) y python-chess la valida contra las jugadas legales de ESE tablero.
# Si falla cualquiera, la frase sigue su camino de siempre y aqui no ha pasado nada. Por eso
# esto va en Process-Texto y NO dentro de Invoke-FastCommand: a esa la llaman las reglas, los
# perfiles de juego y las traducciones, y ninguna es braya hablando.
# Se puede apagar entero desde config.json (juego.ajedrez = false), como todo lo demas.
$AjedrezOn = [bool](Get-Cfg 'juego' 'ajedrez' $true)
$script:recuerdoPide = ''        # de que se le pidio acordarse (ver funcion 4)
$script:ultimoDividir = $null     # el ultimo 'dividir' que salio bien, para poder guardarlo
$script:ajedrezActiva = $null      # $null = aun no se ha mirado el disco en este arranque
$script:ajedrezPreguntaHasta = 0   # hasta cuando vale contestar "la primera" / "la segunda"
$AjedrezPy = Join-Path $LogDir 'ajedrez_turno.py'
function Test-AjedrezAbierta {
    if ($null -eq $script:ajedrezActiva) {
        $script:ajedrezActiva = Test-Path -LiteralPath (Join-Path $MemoriaDir 'ajedrez.json')
    }
    return [bool]$script:ajedrezActiva
}
function Invoke-AjedrezPy([string[]]$args2) {
    try {
        $salida = & $PyExe $AjedrezPy @args2 2>$null
        if (-not $salida) { return $null }
        return ([string]($salida -join '')) | ConvertFrom-Json
    } catch { Log ("ajedrez: " + $_.Exception.Message); return $null }
}
function Invoke-Ajedrez([string]$texto) {
    if (-not $AjedrezOn) { return $null }
    $pl = ConvertTo-Plain $texto
    if (-not $pl) { return $null }
    # EMPEZAR. Se reconoce siempre, haya partida o no.
    if ($pl -match '^(?:(?:juguemos|jugamos|juega|jugar|echamos|echemos)\s+(?:una\s+partida\s+de\s+|al\s+|a\s+)?ajedrez(?:\s+conmigo)?|(?:una\s+)?partida\s+de\s+ajedrez|ajedrez\s+(?:a\s+ciegas|mental))$') {
        $r = Invoke-AjedrezPy @('--empezar')
        if ($r) { $script:ajedrezActiva = $true; return [string]$r.decir }
        return 'No puedo con el ajedrez ahora mismo.'
    }
    if (-not (Test-AjedrezAbierta)) { return $null }
    # SALIR. Siempre con salida clara: braya rechaza los modos de los que no se sabe salir.
    if ($pl -match '^(?:dejamos?\s+(?:la\s+)?partida|deja\s+(?:el\s+)?ajedrez|abandono|me\s+rindo|borra\s+la\s+partida|cierra\s+la\s+partida|ya\s+no\s+juego)$') {
        $r = Invoke-AjedrezPy @('--cerrar')
        $script:ajedrezActiva = $false
        return $(if ($r) { [string]$r.decir } else { 'Partida cerrada.' })
    }
    if ($pl -match '^(?:por\s+donde\s+(?:vamos|ibamos)|como\s+va\s+la\s+partida|a\s+quien\s+le\s+toca|que\s+jugada\s+vamos)$') {
        $r = Invoke-AjedrezPy @('--estado')
        return $(if ($r) { [string]$r.decir } else { $null })
    }
    # DESHACER, que es la salvaguarda de esto: no se confirma con un "si" -al 70,4 % de oido,
    # un si mal oido no es una confirmacion-, se deshace.
    if ($pl -match '^(?:retira\s+esa|retira\s+la\s+jugada|deshaz(?:\s+eso)?|no\s+era\s+esa|vuelve\s+atras)$') {
        $r = Invoke-AjedrezPy @('--deshacer')
        return $(if ($r) { [string]$r.decir } else { $null })
    }
    # CONTESTANDO A "¿foxtrot tres o charlie tres?" -- con la voz de siempre. El mando
    # (funcion 10) es la OTRA manera, no la unica: aqui se cierra el selector si estaba.
    #
    # SOLO SI HAY UNA PREGUNTA VIVA (revision del 23/09). Antes bastaba con que hubiera
    # partida abierta, y la partida vive DIAS: un "dos" suelto tres dias despues hacia la
    # jugada que quedo pendiente. Ademas cada una de estas dos lineas arranca Python (~1,2 s
    # con el bucle parado) aunque no hubiera nada que elegir. El lado de Python tiene su
    # propia caducidad de 60 s; esta es la de aca, y ahorra el arranque.
    if ($script:ajedrezPreguntaHasta -gt 0 -and $sw.ElapsedMilliseconds -ge $script:ajedrezPreguntaHasta) { $script:ajedrezPreguntaHasta = 0 }
    if ($script:ajedrezPreguntaHasta -gt 0 -and $pl -match '^(?:la\s+)?(?:primera|primero|el\s+primero|uno)$') { $script:ajedrezPreguntaHasta = 0; Close-Eleccion $false; $r = Invoke-AjedrezPy @('--elegir', '1'); return $(if ($r) { [string]$r.decir } else { $null }) }
    if ($script:ajedrezPreguntaHasta -gt 0 -and $pl -match '^(?:la\s+)?(?:segunda|segundo|el\s+segundo|dos)$')  { $script:ajedrezPreguntaHasta = 0; Close-Eleccion $false; $r = Invoke-AjedrezPy @('--elegir', '2'); return $(if ($r) { [string]$r.decir } else { $null }) }
    # UNA JUGADA. El patron es la llave (b): pieza o columna, y una fila. Anclado en ^...$ y
    # escrito contra lo que LLEGA (ConvertTo-Plain ya lo paso a minusculas y quito la coma).
    $piezas = 'rey|dama|reina|torre|alfil|caballo|peon'
    $cols = 'alfa|bravo|charlie|delta|echo|foxtrot|golf|hotel|be|ce|de|efe|ge|hache'
    $filas = 'uno|dos|tres|cuatro|cinco|seis|siete|ocho|[1-8]'
    # Y LA CORONACION (revision del 23/09). formas_de() ya generaba " corono dama" desde el
    # principio, pero el patron de aqui estaba anclado justo detras de la fila, asi que
    # "peon echo ocho corono dama" no llegaba nunca: era codigo muerto desde este lado.
    $corona = '(?:\s+corono\s+(?:dama|reina|torre|alfil|caballo))?'
    if ($pl -match '^(?:enroque|enroco)\b' -or
        $pl -match ("^(?:$piezas)\s+(?:a\s+|come\s+en\s+)?(?:$cols|[a-h])\s+(?:$filas)$corona$") -or
        $pl -match ("^(?:$cols)\s+(?:$filas)$corona$")) {
        $r = Invoke-AjedrezPy @('--dicho', $texto)
        if ($r -and $r.decir) {
            # SI PREGUNTA ENTRE DOS, EL MANDO LAS RESUELVE (23/09, funcion 10). Es el caso
            # con mas motivo de todos: las dos opciones se parecen un 70 % al oido -por eso
            # se pregunta-, asi que contestar hablando es pedirle al oido justo lo que no
            # sabe hacer. Con la cruceta no hay nada que entender.
            if ($r.opciones -and @($r.opciones).Count -ge 2) {
                $script:ajedrezPreguntaHasta = $sw.ElapsedMilliseconds + 60000
                [void](Open-Eleccion @($r.opciones) 'ajedrez')
            }
            return [string]$r.decir
        }
        return $null      # tenia forma pero no era legal: que siga su camino
    }
    return $null
}

# LO QUE DICE AL HACER UNA ORDEN, CONJUGADO (23/09, idea 1 de la cuarta tanda, y lo pidio
# braya: "que lo diga conjugado en todas las frases que se pueda").
# Invoke-FastCommand devuelve el nombre interno de la accion -"abrir steam", "cerrar
# navegador", "volumen al 50 por ciento"- y esa misma cadena se decia en voz alta. Medido en
# assistant.log: 139 respuestas locales en infinitivo, 77 formas distintas, y "abrir steam" es
# la frase mas repetida de toda Nova (23 veces). Sonaba a fichero de log.
#
# TRES REGLAS, y las tres importan:
#  1. LISTA CERRADA y anclada al principio. Lo que no reconoce se devuelve TAL CUAL: mas vale
#     un infinitivo suelto que una frase inventada. Aqui no hay modelo ni adivinanza.
#  2. NO se toca el dato interno. $a.desc sigue siendo "abrir steam" en el log, en la memoria
#     de la charla y en los bancos: lo que cambia es solo lo que sale por el altavoz y por la
#     capsula. Si se tocara el dato, se romperian 22 comprobaciones que lo afirman, la
#     respuesta de "repite" y lo que la charla recuerda de la ultima orden.
#  3. NI la rama de confirmacion. La pregunta "¿Abro SILENT BREATH?" ya esta conjugada por su
#     lado, y deformarla seria tocar justo la frase con la que braya dice si o no.
# Los planes se dicen ENTEROS, cambiando el ';' por ' y ': la capsula no conserva la lista
# -Show-Popup escribe y Say la pisa milisegundos despues-, asi que recortar ahi quitaria los
# pasos de la voz Y de la pantalla.
function Get-FraseAccion([string]$txt) {
    if (-not $txt) { return $txt }
    $trozos = @()
    foreach ($t in ($txt -split ';')) {
        $u = $t.Trim()
        if (-not $u) { continue }
        # el orden importa: lo mas especifico primero, y todo anclado en ^
        $v = switch -Regex ($u) {
            '^abrir\s+(?:la\s+carpeta\s+)?(.+)$'            { "Abro $($Matches[1])"; break }
            '^cerrar\s+todo$'                               { 'Cierro todo'; break }
            '^cerrar\s+(.+)$'                               { "Cierro $($Matches[1])"; break }
            '^mostrar\s+el\s+escritorio$'                   { 'Muestro el escritorio'; break }
            '^mostrar\s+(.+)$'                              { "Muestro $($Matches[1])"; break }
            '^volumen\s+al\s+(.+)$'                         { "Pongo el volumen al $($Matches[1])"; break }
            '^brillo\s+al\s+(.+)$'                          { "Pongo el brillo al $($Matches[1])"; break }
            '^subir\s+(?:el\s+)?(volumen|brillo)(.*)$'      { "Subo el $($Matches[1])$($Matches[2])"; break }
            '^bajar\s+(?:el\s+)?(volumen|brillo)(.*)$'      { "Bajo el $($Matches[1])$($Matches[2])"; break }
            "^buscar\s+'(.+)'\s+en\s+(.+)$"                 { "Busco $($Matches[1]) en $($Matches[2])"; break }
            "^escribir\s+'(.+)'$"                           { "Escribo $($Matches[1])"; break }
            '^dividir\s+pantalla\s+con\s+(.+)$'             { "Divido la pantalla con $($Matches[1])"; break }
            '^dividir\s+pantalla\s+(.+?)\s+con\s+(.+)$'     { "Divido la pantalla entre $($Matches[1]) y $($Matches[2])"; break }
            '^reproducir\s+(.+)$'                           { "Reproduzco $($Matches[1])"; break }
            '^silenciar$'                                   { 'Silencio el sonido'; break }
            '^pausar$'                                      { 'Pauso'; break }
            '^bloquear$'                                    { 'Bloqueo la consola'; break }
            '^minimizar\s*(.*)$'                            { "Minimizo $($Matches[1])".Trim(); break }
            '^maximizar\s*(.*)$'                            { "Maximizo $($Matches[1])".Trim(); break }
            '^apagar\s+(.+)$'                               { "Apago $($Matches[1])"; break }
            '^encender\s+(.+)$'                             { "Enciendo $($Matches[1])"; break }
            '^activar\s+(.+)$'                              { "Activo $($Matches[1])"; break }
            '^desactivar\s+(.+)$'                           { "Desactivo $($Matches[1])"; break }
            '^enfocar\s+(.+)$'                              { "Voy a $($Matches[1])"; break }
            '^copiar$'                                      { 'Copio'; break }
            '^pegar$'                                       { 'Pego'; break }
            '^poner\s+(.+)$'                                { "Pongo $($Matches[1])"; break }
            '^crear\s+(.+)$'                                { "Creo $($Matches[1])"; break }
            '^borrar\s+(.+)$'                               { "Borro $($Matches[1])"; break }
            '^mover\s+(.+)$'                                { "Muevo $($Matches[1])"; break }
            '^instalar\s+(.+)$'                             { "Instalo $($Matches[1])"; break }
            '^leer\s+(.+)$'                                 { "Leo $($Matches[1])"; break }
            '^enviar\s+(.+)$'                               { "Envio $($Matches[1])"; break }
            '^grabar\s*(.*)$'                               { "Grabo $($Matches[1])".Trim(); break }
            default                                          { $u }
        }
        $trozos += [string]$v
    }
    if ($trozos.Count -eq 0) { return $txt }
    # el primero con mayuscula; los demas pegados con ' y ' y en minuscula, que es como se
    # dice una lista hablada ("Abro Steam y pongo el volumen al 50 por ciento")
    $out = [string]$trozos[0]
    if ($out.Length -gt 1) { $out = $out.Substring(0, 1).ToUpper() + $out.Substring(1) }
    for ($i = 1; $i -lt $trozos.Count; $i++) {
        $sig = [string]$trozos[$i]
        if ($sig.Length -gt 1) { $sig = $sig.Substring(0, 1).ToLower() + $sig.Substring(1) }
        $out += ' y ' + $sig
    }
    return $out
}

function Add-TildesVoz([string]$s) {
    if (-not $s) { return $s }
    if (-not $script:TildesVoz) {
        $a = [char]0xE1; $e = [char]0xE9; $i = [char]0xED; $o = [char]0xF3; $u = [char]0xFA; $n = [char]0xF1
        $script:TildesVoz = [ordered]@{
            'entendi' = "entend$i"; 'aqui' = "aqu$i"; 'ahi' = "ah$i"; 'alli' = "all$i"; 'asi' = "as$i"
            'todavia' = "todav$i" + 'a'; 'despues' = "despu$e" + 's'; 'tambien' = "tambi$e" + 'n'; 'ademas' = "adem$a" + 's'
            'musica' = "m$u" + 'sica'; 'bateria' = "bater$i" + 'a'; 'cancion' = "canci$o" + 'n'; 'ultimo' = "$u" + 'ltimo'
            'ultima' = "$u" + 'ltima'; 'ultimos' = "$u" + 'ltimos'; 'rapido' = "r$a" + 'pido'; 'numero' = "n$u" + 'mero'
            'pagina' = "p$a" + 'gina'; 'dia' = "d$i" + 'a'; 'dias' = "d$i" + 'as'; 'podria' = "podr$i" + 'a'; 'habia' = "hab$i" + 'a'
            'tenia' = "ten$i" + 'a'; 'queria' = "quer$i" + 'a'; 'minimo' = "m$i" + 'nimo'; 'maximo' = "m$a" + 'ximo'
            'manana' = "ma$n" + 'ana'; 'segun' = "seg$u" + 'n'; 'algun' = "alg$u" + 'n'; 'ningun' = "ning$u" + 'n'
            'volvera' = "volver$a"; 'sera' = "ser$a"; 'estare' = "estar$e"; 'avisare' = "avisar$e"; 'recordare' = "recordar$e"
            'boton' = "bot$o" + 'n'; 'microfono' = "micr$o" + 'fono'; 'conexion' = "conexi$o" + 'n'; 'configuracion' = "configuraci$o" + 'n'
            'telefono' = "tel$e" + 'fono'; 'dificil' = "dif$i" + 'cil'; 'facil' = "f$a" + 'cil'
            'sabado' = "s$a" + 'bado'; 'miercoles' = "mi$e" + 'rcoles'; 'dificiles' = "dif$i" + 'ciles'; 'rapida' = "r$a" + 'pida'
        }
    }
    if (-not $script:TildesVozRe) {
        # UNA sola expresion para todas: se llama en cada frase y en cada tarjeta
        $script:TildesVozRe = New-Object System.Text.RegularExpressions.Regex(
            ('\b(?:' + (@($script:TildesVoz.Keys) -join '|') + ')\b'),
            ([System.Text.RegularExpressions.RegexOptions]::IgnoreCase -bor [System.Text.RegularExpressions.RegexOptions]::Compiled))
    }
    # conserva la mayuscula inicial ("Ultimo" -> "Último")
    return $script:TildesVozRe.Replace($s, {
        param($m)
        $r = $script:TildesVoz[$m.Value.ToLowerInvariant()]
        if ($m.Value -ceq $m.Value.ToUpperInvariant()) { $r = $r.ToUpperInvariant() }
        elseif ([char]::IsUpper($m.Value[0])) { $r = $r.Substring(0, 1).ToUpperInvariant() + $r.Substring(1) }
        $r
    })
}

# El texto TAL CUAL llega a la voz: espacios, tildes y el corte a 300 letras. Aparte
# porque la voz preparada (Send-PrepVoz) tiene que pedir exactamente el mismo, o no
# acierta en la cache.
# LAS PALABRAS QUE BRAYA NO AGUANTA (23/09, funcion 2 de la tanda de funciones nuevas).
# Se lo ha pedido TRES veces y seguia pasando: 20/09 23:05 "deja de decirme man, no me digas
# asi", 20/09 23:19 "deja de llamarme tio", 21/09 00:03 "deja de decir tio, no me gusta esa
# palabra, guardalo en memoria". Nova prometio dos veces que no, y el 22/09 a las 21:48:35:
# "No te sigo, tio".
# Y lo peor no es que siguiera diciendolo: es lo que APRENDIO de la queja. En memoria\perfil.md
# quedo escrito "braya habla con acento español (usa 'tio')" -el dato del reves: la muletilla
# es de ella, no de el- y esa linea viaja en el prompt de todas sus charlas, o sea que la
# queja realimentaba justo lo que molestaba.
#
# EL FILTRO VA AQUI DENTRO, NO EN Say, Y ESO IMPORTA: la charla pre-sintetiza la voz con
# Get-TextoVoz y la cachea por md5 del texto. Filtrando despues, en Say, el md5 no cuadraria y
# cada frase tocada perderia la voz ya preparada: casi un segundo por frase. Aqui, los tres
# caminos de la voz comparten el mismo texto y la capsula enseña lo mismo que se oye.
# Y SOLO LO QUE NOVA REDACTA. El correo, el OCR, los nombres de juegos o lo que ella repite de
# un dictado no se tocan: censurar un correo que dice "man" no es obedecerle, es mentirle
# sobre lo que pone en la pantalla.
$PalabrasNoPath = Join-Path $MemoriaDir 'palabras-no.json'
$script:palabrasNo = $null
function Get-PalabrasNo {
    if ($null -ne $script:palabrasNo) { return $script:palabrasNo }
    $script:palabrasNo = @()
    try {
        if (Test-Path -LiteralPath $PalabrasNoPath) {
            $script:palabrasNo = @((Get-Content -LiteralPath $PalabrasNoPath -Raw -Encoding UTF8 | ConvertFrom-Json) |
                                   Where-Object { $_ } | ForEach-Object { [string]$_ })
        }
    } catch { Log ('palabras-no: no pude leerlas: ' + $_.Exception.Message) }
    return $script:palabrasNo
}
function Save-PalabrasNo([string[]]$lista) {
    # MODO INVITADO: lo que diga otro no se queda (17/09). Esta lista son SUS palabras, las
    # que a el le molestan; un invitado no se las cambia.
    if ($script:invitado) { Log 'palabras-no: modo invitado, no guardo nada'; return }
    $script:palabrasNo = @($lista | Where-Object { $_ } | Select-Object -Unique)
    try {
        [System.IO.File]::WriteAllText($PalabrasNoPath, (ConvertTo-Json -InputObject @($script:palabrasNo) -Depth 2),
                                       (New-Object System.Text.UTF8Encoding($false)))
    } catch { Log ('palabras-no: no pude guardarlas: ' + $_.Exception.Message) }
}
function Remove-PalabrasNo([string]$texto) {
    $lista = @(Get-PalabrasNo)
    if ($lista.Count -eq 0 -or -not $texto) { return $texto }
    $t = $texto
    foreach ($p in $lista) {
        $pl = [regex]::Escape((ConvertTo-Plain $p))
        if (-not $pl) { continue }
        # PALABRA ENTERA Y SIN TILDES: "man" a secas se come mando, manda, semana y comando
        # -y Nova le lee los cuatro mandos-; y "tio" con tilde no caza el "tio" que escupe el
        # modelo la mitad de las veces. Ademas se lleva la coma del vocativo, para que
        # "No te sigo, tio." no quede como "No te sigo, .".
        $t = [regex]::Replace($t, '(?i)\s*,\s*' + $pl + '(?=[\s.,;!?]|$)', '')
        $t = [regex]::Replace($t, '(?i)\b' + $pl + '\b[\s]*', ' ')
    }
    # y la coma huerfana que queda cuando el vocativo iba al PRINCIPIO ("Tio, eso no lo se"
    # se quedaba en ", eso no lo se")
    $t = ($t -replace '\s+', ' ') -replace '\s+([.,;!?])', '$1'
    $t = $t -replace '^[\s,;:]+', ''
    if ($t.Length -gt 1) { $t = $t.Substring(0, 1).ToUpper() + $t.Substring(1) }
    return $t.Trim()
}
function Get-TextoVoz([string]$texto) {
    $t = Add-TildesVoz (Remove-PalabrasNo (($texto -replace '\s+', ' ').Trim()))
    # RESPUESTAS LARGAS ENTERAS (15/09): con el tope en 300 letras la voz se callaba a
    # mitad de una respuesta del agente ("se corta y deja de hablar") mientras la tarjeta
    # ensenaba el resto. Ahora el tope es 1.200 letras, y la voz tiene mas plazo.
    if ($t.Length -gt 1200) {
        # POR EL FINAL DE UNA FRASE (14/09): cortar a secas dejaba la voz a mitad de
        # palabra. Se busca el ultimo punto; si no, el ultimo espacio.
        $corteV = $t.Substring(0, 1200).LastIndexOfAny([char[]]'.!?;')
        if ($corteV -lt 400) { $corteV = $t.Substring(0, 1200).LastIndexOf(' ') }
        $t = if ($corteV -gt 0) { $t.Substring(0, $corteV + 1).Trim() } else { $t.Substring(0, 1200) }
    }
    return $t
}

# VOZ PREPARADA (14/09). Una frase nueva tarda ~1 s en sintetizarse (medido: 0,99 s
# de media) y una ya hecha 2 ms. La charla llega frase a frase, pero cada una se
# sintetizaba al tocarle, con ~1 s de hueco entre frase y frase. Un segundo worker
# de voz, igual que el de siempre y con la misma cache, las va preparando en cuanto
# llegan; al decirlas ya estan hechas. Escribe con .part y renombra, asi que los
# dos pueden pedir la misma sin pisarse. Su salida no se lee: no hace falta.
$script:prepVozProc = $null
function Send-PrepVoz([string]$texto, [string]$emo = '') {
    if (-not $texto -or -not $script:ttsProc -or $script:ttsProc.HasExited) { return }
    try {
        if (-not $script:prepVozProc -or $script:prepVozProc.HasExited) {
            $psiP = New-Object System.Diagnostics.ProcessStartInfo
            $psiP.FileName = $PyWorker
            $psiP.Arguments = "-u `"$TtsWorker`" $VozOnlineNombre `"$VozCache`""
            $psiP.UseShellExecute = $false
            $psiP.RedirectStandardInput = $true
            $psiP.CreateNoWindow = $true
            $psiP.WorkingDirectory = $LogDir
            $script:prepVozProc = [System.Diagnostics.Process]::Start($psiP)
            try { $script:prepVozProc.PriorityClass = [System.Diagnostics.ProcessPriorityClass]::BelowNormal } catch {}
            Log "voz preparada: worker PID=$($script:prepVozProc.Id)"
        }
        $script:prepVozUltima = $sw.ElapsedMilliseconds
        $envioP = if ($emo) { "{emo:$emo} $texto" } else { $texto }
        $bytesP = [System.Text.Encoding]::UTF8.GetBytes($envioP + "`n")
        $script:prepVozProc.StandardInput.BaseStream.Write($bytesP, 0, $bytesP.Length)
        $script:prepVozProc.StandardInput.BaseStream.Flush()
    } catch { Log ("voz preparada: " + $_.Exception.Message) }
}

# EL MP3 ABIERTO ANTES DE HABLAR (22/09). Play-Audio hacia Open() y Play() pegados, y eso
# cuesta: desde el Open hasta que sale sonido pasan 464 ms de media (120 medidas en esta
# maquina; el rango 453-547 ya estaba apuntado en Play-Audio, en EL CUARTO DE SEGUNDO QUE
# SE PAGABA EN CADA FRASE). Con el mismo mp3 YA abierto en otro MediaPlayer, ese Play()
# suena en 31 ms. Son 433 ms menos por frase, y en el log de braya hay 599 frases de voz:
# 259 segundos de Nova callada esperando a que cargue un audio que ya tenia hecho.
#
# DONDE SE PUEDE PAGAR POR ADELANTADO: en la charla. Las frases llegan en cola
# (charlaFrases) y la siguiente no se dice hasta que acaba la que suena, o sea que hay
# SEGUNDOS de margen, y durante ese rato la voz preparada ya le esta haciendo el mp3. La
# ruta no hay que adivinarla: tts_worker.py (~226) la saca de md5(VOZ|[ritmo|][tono|]texto),
# asi que se calcula igual aqui y se abre en cuanto el archivo aparece.
# De las 599 frases del log, 309 llegaron "ya preparadas": esas son las que esto gana. Las
# otras 290 se sintetizan al momento, y de un mp3 que aun no existe no hay nada que abrir.
#
# SI LAS DOS CUENTAS SE SEPARAN, NO PASA NADA: Play-Audio compara con la ruta que DEVUELVE
# el worker. Un md5 que no cuadre solo significa no ganar los 433 ms.
#
# LO QUE NO SE TOCA, A PROPOSITO:
#   - el "+450" de Say-Online ($dur = $n * 50 + 450) NO es margen de cola: es esta misma
#     latencia de Open, y con ella se fija pausaHasta, que es la VENTANA DE SORDINA. Si se
#     bajara a la vez que la latencia, el instante en que Nova vuelve a escuchar se
#     adelantaria y podria oirse a si misma: eso es una orden equivocada, que es lo peor
#     que le puede pasar. Dejandolo en 450 la sordina se abre EXACTAMENTE en el mismo
#     instante de reloj que hoy (Refresh-UI no se ha movido); lo unico que cambia es que la
#     voz empieza y acaba 433 ms antes, o sea que la sordina sobra un poco al final, que es
#     el lado seguro. Y la charla encadena en el mismo instante que hoy, ni antes ni despues.
#   - el "-300" del reloj de la envolvente en nova_ui.cs (~2976) tampoco se toca, pero NO
#     por el motivo que puse aqui primero. Escribi que era "lo mismo por el lado de la
#     capsula", o sea que compensaba este Open, y es falso: el -300 entro el 11/09 en el
#     commit 866db98, seis dias ANTES de que nadie midiera Open. Nunca compenso nada de
#     esto. Y tampoco hay "boca" que se desincronice: el ecualizador de cuatro bandas se
#     quito el 12/09 porque "parecia una boca de palitos y se veia mal" (nova_ui.cs:1053),
#     y lo que queda solo mueve el resplandor y el tamano del punto entero.
#     Lo que hay de verdad, medido: desde el 11/09 ese punto late ~170 ms POR DELANTE de la
#     voz, en 599 frases y ocho dias de log, y braya no lo ha mencionado ni una vez. Esa es
#     la unica medida real de lo que se nota, y es >= 170 ms. Con el adelanto puesto pasa a
#     ir ~270 ms por detras: mas, pero del mismo orden, en un brillo y no en unos labios.
#     Asi que NO queda apuntado como paso pendiente: no hay dato que diga que molesta, y
#     cero casos en el log todavia. Si algun dia lo dice el, entonces se mide y se arregla.
function Get-RutaVozCache([string]$texto, [string]$emo = '') {
    if (-not $texto -or -not $VozCache) { return '' }
    try {
        # la misma cuenta que velocidad() en tts_worker.py (~166): el numero de
        # velocidad.txt, recortado a -50..100
        $vv = 0
        $fVel = Join-Path $VozCache 'velocidad.txt'
        if (Test-Path -LiteralPath $fVel) {
            try { $vv = [int](([System.IO.File]::ReadAllText($fVel)).Trim()) } catch { $vv = 0 }
        }
        $vv = [Math]::Max(-50, [Math]::Min(100, $vv))
        # y AJUSTE_EMOCION (~179): alegre suma 6 y sube a +6Hz; suave resta 8 y baja a -5Hz
        $tonoV = '+0Hz'
        if ($emo -eq 'alegre') { $vv = $vv + 6; $tonoV = '+6Hz' }
        elseif ($emo -eq 'suave') { $vv = $vv - 8; $tonoV = '-5Hz' }
        $vv = [Math]::Max(-50, [Math]::Min(100, $vv))
        $ritmoV = $(if ($vv -ge 0) { '+' + [string]$vv + '%' } else { [string]$vv + '%' })
        # el ritmo y el tono solo entran en la clave cuando NO son los de siempre
        $trozoR = $(if ($ritmoV -eq '+0%') { '' } else { $ritmoV + '|' })
        $trozoT = $(if ($tonoV -eq '+0Hz') { '' } else { $tonoV + '|' })
        $clave = $VozOnlineNombre + '|' + $trozoR + $trozoT + $texto
        if (-not $script:preVozMd5) { $script:preVozMd5 = [System.Security.Cryptography.MD5]::Create() }
        $hV = $script:preVozMd5.ComputeHash([System.Text.Encoding]::UTF8.GetBytes($clave))
        return (Join-Path $VozCache ([System.BitConverter]::ToString($hV).Replace('-', '').ToLowerInvariant() + '.mp3'))
    } catch { return '' }
}

function Open-VozAdelantada {
    if ($script:charlaFrases.Count -eq 0) { return }
    try {
        $cabezaV = $script:charlaFrases.Peek()
        $crudoV = [string]$cabezaV.t
        if ($crudoV -ne $script:preVozTexto) {
            # la cabeza de la cola cambio: se calcula la ruta UNA vez y se guarda, que esto
            # corre en cada vuelta del bucle. El texto y la emocion se sacan igual que al
            # decirla de verdad (Get-TextoVoz dentro de Say, Get-EmocionFrase al sacarla de
            # la cola); si no fueran los mismos, el md5 no coincidiria y no se ganaria nada.
            $script:preVozTexto = $crudoV
            $script:preVozCalc = Get-RutaVozCache (Get-TextoVoz $crudoV) (Get-EmocionFrase $crudoV)
        }
        if (-not $script:preVozCalc) { return }
        if ($script:preVozRuta -eq $script:preVozCalc) { return }           # ya esta abierto
        if (-not (Test-Path -LiteralPath $script:preVozCalc)) { return }    # el worker aun lo esta haciendo
        if (-not $script:reproductorPrevio) {
            Add-Type -AssemblyName PresentationCore -ErrorAction Stop
            $script:reproductorPrevio = New-Object System.Windows.Media.MediaPlayer
        }
        $script:reproductorPrevio.Open([Uri]$script:preVozCalc)
        $script:preVozRuta = $script:preVozCalc
        $script:preVozDesde = $sw.ElapsedMilliseconds
    } catch { $script:preVozRuta = '' }
}

# Habla sin bloquear el bucle: la sintesis tarda ~60 ms y Play() es asincrono.
function Say([string]$texto, [string]$emo = '') {
    if (-not $texto) { return }
    $script:vozFinReal = 0
    $t = Get-TextoVoz $texto
    if ($t.Length -eq 0) { return }
    # en una llamada no se habla: la capsula lo ensena y late (ver SILENCIO EN LLAMADAS)
    if (Test-EnLlamada) {
        try { Set-UI 'hablando' $t 5000; Send-UIEvento 'pulso:llamada' } catch {}
        return
    }
    # Silenciar la escucha mientras hablamos. La reproduccion es asincrona, asi
    # que se estima la duracion por longitud del texto (~70 ms por caracter) y
    # el bucle principal reanuda al vencer el plazo.
    try {
        $script:finVoz = $sw.ElapsedMilliseconds
        $estimado = [Math]::Min(90000, ($t.Length * 70) + 1200)
        $previaV = $script:pausaHasta
        Pausar-Escucha $estimado $t
        # si fue ESTA estimacion la que alargo la pausa, Say-Online la puede acortar
        # a la duracion real del audio (ver LA PAUSA REAL)
        $script:pausaEstimadaVoz = if ($script:pausaHasta -gt $previaV) { $script:pausaHasta } else { -1 }
        # la capsula muestra lo que se dice y vuelve al reposo al callar. El
        # audio se anade despues, cuando se sabe cual es (Say-Online).
        $script:uiAudio = ''
        Set-UI 'hablando' $t ([Math]::Max($estimado, 2500))
    } catch {}
    # LO QUE LLEVA DATOS SUYOS NO SALE DE CASA (27/09, idea 116). Va ANTES de la eleccion de motor
    # y se prueba Piper primero; si Piper no puede -no esta, no arranca, no contesta-, la cadena de
    # abajo sigue igual que siempre, porque callarse seria peor que decirlo.
    # LA BANDERA DE LO PRIVADO SE LEE AQUI Y SE BAJA AQUI (28/09, tras la revision). Tenia dos
    # fallos que son el mismo: se bajaba en el sitio equivocado.
    #
    # 1) LLEGABA SIEMPRE APAGADA. Los seis caminos que la levantan corren dentro de
    #    Invoke-FastCommand -el correo, el texto de un mensaje privado, los nicks de los amigos de
    #    Steam, los nombres de sus ficheros-, y el camino local la ponia a $false JUSTO DESPUES de
    #    usarla para redactar la linea del registro, unas veinticinco lineas ANTES de llamar a Say.
    #    O sea que la mitad "bandera" del filtro de la idea 116 no ha funcionado nunca: una
    #    respuesta privada que no llevara palabras de dinero salia entera por edge-tts. De las 220
    #    frases que Nova ha dicho en los dos registros, 214 salieron a internet, y entre ellas las
    #    dos del 25/09 con los nicks de sus amigos y a que estaban jugando.
    # 2) Y CUANDO SI SE LEVANTABA POR OTRO CAMINO, SE QUEDABA PUESTA. Complete-Confirmacion reentra
    #    por Invoke-Correo, que la levanta en su primera linea, dice la frase y vuelve con return
    #    sin bajarla: desde ese 'si' y hasta la siguiente orden local, TODO lo que dijera Nova -la
    #    charla, un aviso, un 'vale'- se sintetizaba con Piper. Un modo que se queda puesto, que es
    #    la regla 2, y encima poniendo la voz que braya no quiere.
    # De un solo uso y en el unico sitio que la consume: quien la levanta ya no tiene que acordarse
    # de bajarla, y si un camino se levanta y revienta antes de hablar, lo peor que pasa es que la
    # frase siguiente se diga en casa. Ese es el lado bueno del error.
    $privadaV = [bool]$script:respuestaPrivada
    $script:respuestaPrivada = $false
    if (Test-VozLocal $t $privadaV) {
        if (Say-Piper $t) {
            Log 'voz: esta frase lleva datos tuyos, la digo con mi voz de casa'
            return
        }
        Log 'voz: queria decir esto con la voz de casa y Piper no pudo; va por la de fuera'
    }
    # cadena de respaldo: si la red falla, sigue habiendo voz
    if ($script:ttsProc) { if (Say-Online $t $emo) { return } }
    # PIPER NO ARRANCABA NUNCA, Y ESTE RESPALDO NO EXISTIA (21/09). $script:piperProc
    # solo se llena en Initialize-Piper, y a Initialize-Piper no se llegaba jamas: la
    # linea de arriba de Initialize-Voz -'if ($VozMotor -eq online -and
    # (Initialize-Online)) { return }'- hace return en cuanto arranca el worker en
    # linea, y config.json tiene voz.motor = online. Asi que piperProc era $null para
    # siempre, esta linea no se cumplia nunca y Say-Piper era codigo muerto. Los 73 MB
    # de piper.exe y el modelo es-MX llevan sin usarse desde el 10/09.
    #
    # LO QUE COSTO: 20/09 23:39:12, en mitad de una charla y con braya delante.
    #   charla dice: Te esta enganchando o aun estas viendo como va la cosa?
    #   voz online: ERR [WinError 32] ... mp3.part -> mp3
    #   voz: no hay ninguna voz disponible
    # Dijo media respuesta y se callo. Ni Piper, ni Windows. Igual el 19/09 a las
    # 09:24:46 y a las 09:25:08.
    #
    # Say-Piper ya arranca Piper sola cuando piperProc esta vacio, e Initialize-Piper
    # devuelve $false en seco si faltan el .exe o el modelo: cuando la red va bien esto
    # no cuesta nada, porque Say-Online ya devolvio antes.
    if ($VozOn -and $VozMotor -ne 'windows') { if (Say-Piper $t) { return } }
    # MUDA Y SORDA HASTA 90 SEGUNDOS (17/09). La pausa se fija ARRIBA, por cuenta de
    # letras y antes de saber si va a sonar algo: con el tope de 1.200 letras de
    # Get-TextoVoz son 85 s. Solo Say-Online la corrige. Si no hay voz ninguna se salia
    # por aqui dejando el plazo entero: el worker ignorando el microfono, la capsula en
    # 'hablando' moviendo la boca en silencio (Tic33 simula silabas si no hay envolvente)
    # y "callate" sin servir, porque tambien pasa por el microfono pausado. Un modo
    # pegado de los peores.
    #
    # Se reanuda SIN -Forzar a proposito: si braya dijo "no me escuches media hora", eso
    # manda y Reanudar-Escucha lo respeta. Aqui solo se deshace lo que puso esta frase.
    if (-not $script:vozSyn) {
        Log "voz: no hay ninguna voz disponible; no me quedo sorda esperando a un audio que no va a sonar"
        $script:pausaEstimadaVoz = -1
        Reanudar-Escucha
        $script:uiHasta = 0
        Set-UI 'reposo'
        return
    }
    try {
        $st = Await-Voz ($script:vozSyn.SynthesizeTextToStreamAsync($t)) ([Windows.Media.SpeechSynthesis.SpeechSynthesisStream])
        if (-not $st) { return }
        $dr = New-Object Windows.Storage.Streams.DataReader($st.GetInputStreamAt(0))
        [void](Await-Voz ($dr.LoadAsync([uint32]$st.Size)) ([uint32]))
        $bytes = New-Object byte[] $st.Size
        $dr.ReadBytes($bytes)
        $wav = Join-Path $TmpDir "voz.wav"
        [System.IO.File]::WriteAllBytes($wav, $bytes)
        $script:vozPlayer.SoundLocation = $wav
        $script:vozPlayer.Load()
        $script:vozPlayer.Play()
    } catch {
        Log ("voz error: " + $_.Exception.Message)
    }
}

# =====================================================================
# ESCUCHA CONTINUA (palabra de activacion)
# Motor SAPI en es-ES, offline. La gramatica es CERRADA: solo el nombre y sus
# variantes. Cuanto mas cerrada, menos falsos disparos, porque el motor no
# tiene otra cosa con la que confundirse. Verificado que rechaza "abre steam",
# "que hora es" y hasta "no va a llover", que foneticamente se le parece.
# =====================================================================
$EscuchaOn = [bool](Get-Cfg 'escucha' 'activada' $true)
$EscuchaNombre = [string](Get-Cfg 'escucha' 'nombre' 'nova')
$EscuchaConf = [double](Get-Cfg 'escucha' 'confianzaMinima' 0.65)
$EscuchaMotor = [string](Get-Cfg 'escucha' 'motor' 'vosk')
# ganancia por software: 'auto' mide el pico real y se ajusta sola
$EscuchaGanancia = [string](Get-Cfg 'escucha' 'ganancia' 'auto')
$script:wakeProc = $null
$script:vozWinProc = $null
$script:vozWinCheck = 0
$script:vozWinIntentos = 0
$script:finVoz = 0
$MarcaWake = Join-Path $TmpDir "despierta.flag"
# Mientras exista esta marca, el worker ignora el microfono. Se crea al hablar
# y al dictar: la voz del propio asistente volvia al microfono con pico 0.99 y
# hundia su ganancia automatica, dejandolo sordo.
$MarcaPausa = Join-Path $TmpDir "escucha-pausa.flag"
# --- DICTADO POR VOSK (sustituye a Win+H) ---
# Win+H era el origen de casi todos los fallos: robaba el foco -y si fallaba,
# el texto se escribia en OTRA ventana-, deformaba palabras ("steamidos",
# "little nighters 3") y obligaba a esperar el silencio desde fuera. El worker
# ya tiene el microfono abierto: dicta el tambien.
$MotorDictado = [string](Get-Cfg 'input' 'dictado' 'vosk')
# MODO DE SEGUIMIENTO: tras responder, se vuelve a escuchar durante este
# tiempo SIN palabra de activacion. Si hablas, es otra orden; si no, se cierra
# en silencio. Permite encadenar: "nova, abre steam" ... "y sube el volumen"
# ... "y avisame en veinte minutos". 0 = desactivado. Solo con el dictado del
# worker (whisper/vosk): Win+H no puede esperar sin robar el foco.
$SeguimientoMs = [int](Get-Cfg 'input' 'seguimientoMs' 2500)
# CORTAR LA CADENA (20/09). En seguimiento no hace falta decir 'nova', asi que el
# umbral de rafaga (escucha.rafagaMinima = 0.030) no filtra nada ahi: anoche 5
# activaciones falsas dieron 14 grabaciones de una conversacion privada. Con esto en
# false (lo normal) el microfono no se reabre solo detras de un final en nada. En true
# vuelve la segunda oportunidad que pidio braya el 15/09, pero UNA sola vez y nunca
# encadenando seguimiento sobre seguimiento.
$SeguimientoTrasSeco = [bool](Get-Cfg 'escucha' 'seguimientoTrasSeco' $false)
# 'vosk' y 'whisper' comparten el camino: el worker de escucha graba la orden
# y la transcribe (Whisper es mucho mas preciso; Vosk pequeno se queda para
# la palabra de activacion). 'windows' es Win+H.
$DictadoWorker = ($MotorDictado -in @('vosk', 'whisper'))
$WhisperModelo = [string](Get-Cfg 'input' 'whisperModelo' 'small')
# Modelo de repaso: el rapido dicta, y solo cuando la orden no se reconoce se
# repasa el MISMO audio con este (mas lento, bastante mas preciso con los
# nombres propios). Vacio = desactivado, se dicta solo con el rapido.
$WhisperPreciso = [string](Get-Cfg 'input' 'whisperModeloPreciso' '')
# ULTIMO RECURSO (15/09): si ni el rapido ni el preciso entienden la orden, se repasa con
# este (~12 s). Vacio = desactivado. Ver Request-UltimoRecurso.
# EL TURBO, APAGADO DESDE EL 15/09 Y CON SU CUENTA AL LADO (24/09, idea 17 de la tanda nueva).
#
# El commit 446acb1 lo apago poniendo whisperModeloUltimo a vacio, y lleva nueve dias sin
# usarse. NO se borra el codigo: esta apagado por CONFIG, asi que braya puede volver a
# encenderlo hablando, y borrarlo le quitaria esa opcion.
#
# PERO SI SE DEJA AQUI LO QUE CUESTA, porque el que lo encienda dentro de un mes no va a ir a
# buscarlo al registro. Las 29 peticiones que hubo, todas del 15/09:
#     de que entra a que sale:  25 s de mediana, 61 s el peor, 721 s (12 min) en 29 frases
#     cargas del modelo grande: 17, de las que QUINCE se soltaron sin usarse, con la VRAM a 4 GB
#
# Y la otra cara, que tambien conviene que este: no era "1 de 29". De los 27 'turbo-nada',
# solo UNO murio de verdad; en CATORCE el turbo impuso su transcripcion porque era mejor
# ("Coladojara y abre Steam" -> "Calculadora, y abre Steam"). O sea 15 de 29 (52 %).
# Es caro, no inutil.
$WhisperUltimo = [string](Get-Cfg 'input' 'whisperModeloUltimo' 'large-v3-turbo')
# OJO (15/09): vacio se le pasa a la escucha como '-'. Con un argumento vacio Start-Process
# falla y la escucha NO arranca (paso al apagar turbo en uso real).
# LO QUE DECIDIO SOLA Y AUN SE PUEDE DESHACER HABLANDO (ver Undo-DecisionPropia). Aqui si
# vale Get-Cfg: $cfg acaba de cargarse del archivo.
try {
    $dGuardada = [string](Get-Cfg 'auto' 'ultimaDecision' '')
    if ($dGuardada) {
        $pD = $dGuardada -split '\|', 4
        if ($pD.Count -eq 4) { $script:autoDecision = @{ seccion = $pD[0]; clave = $pD[1]; antes = $pD[2]; que = $pD[3] } }
    }
    # Y LO QUE BRAYA LE DEVOLVIO (23/09, idea 13). Sin esto, el "deshaz" duraba lo que durara
    # la sesion, o sea 5,8 minutos de mediana, y al siguiente arranque Nova lo volvia a apagar.
    $devG = [string](Get-Cfg 'auto' 'devueltas' '')
    if ($devG) {
        foreach ($parG in ($devG -split ';')) {
            $kvG = $parG -split '=', 2
            if ($kvG.Count -eq 2 -and $kvG[0]) { $script:decisionDevueltas[$kvG[0]] = $kvG[1] }
        }
    }
} catch {}
$MarcaDictar = Join-Path $TmpDir "dictar.flag"
# confirmacion por voz de coincidencias dudosas: el worker escucha si/no
$MarcaConfirmar = Join-Path $TmpDir "confirmar.flag"
# PARAR LIMPIO (18/09): tools\parar-nova.ps1 deja esta marca y el bucle sale por exit, que
# es lo unico que dispara PowerShell.Exiting (un Stop-Process no lo hace). Antes la unica
# forma de parar a Nova era matarla, y la linea "VoiceAssistant cerrado" no salia nunca.
$MarcaSalir = Join-Path $TmpDir "salir.flag"
$RutaConfirmacion = Join-Path $TmpDir "confirmacion.txt"
# NO ES "para que Whisper acierte los nombres" (22/09): eso es lo que ponia aqui, y hace
# once dias que no es verdad. Whisper no lee este fichero desde el 11/09 (su initial_prompt
# es PROMPT_ORDENES, sin nombres propios) y la escucha dejo de abrirlo el 19/09, cuando se
# quito leer_vocabulario(). Se sigue pasando en argv[13] y se sigue escribiendo, y el unico
# que lo lee hoy es tools\probar-audio.py, que es justo la herramienta que compara Whisper
# CON y SIN estas pistas. Por eso no se borra: borrarlo dejaria esa medicion sin la mitad
# que compara. Ver LA FIRMA DE LA ALUCINACION DE WHISPER para por que se quitaron.
$RutaVocabulario = Join-Path $TmpDir "vocabulario.txt"
$RutaDictado = Join-Path $TmpDir "dictado.txt"
$RutaParcial = Join-Path $TmpDir "dictado-parcial.txt"
# LO QUE OYO CADA MOTOR DE LA MISMA FRASE (25/09, idea de braya: "lo que entienden todos los
# modelos deberia enviarse y una IA como Claude debe armar la frase entera de ser necesario").
#
# POR QUE SALE CASI GRATIS: cuando el reconocedor local no entiende una orden, Nova YA llama a
# Claude para traducirla -SUBMIT (traducir), 1,5 s medidos el 25/09-. Hoy le manda UNA frase, y
# a veces es la peor que tenia. Darle las tres candidatas es la MISMA llamada con mas
# informacion: ni una peticion mas, ni un segundo mas.
#
# EL CASO QUE LO PIDE, del 25/09 a la 01:25: Parakeet oyo bien el nombre de un amigo de braya y
# la cobertura descarto esa transcripcion por DOS DECIMAS (3,8 letras por segundo contra un
# liston de 4,0, porque braya hablaba algo mas despacio de lo normal). Viajo la de Whisper, que
# habia convertido ese nombre en "base". Con "base" dentro, Claude no podia adivinar nada y
# Nova contesto que no sabia. Con las dos delante, si puede.
$RutaOidos = Join-Path $TmpDir "dictado-oidos.txt"
function Get-OtrosOidos([string]$principal, [string]$ruta = $RutaOidos, [switch]$Crudo) {
    # -Crudo (26/09, idea 25): devuelve el ARRAY de textos ya limpios, sin el prefijo del motor,
    # y NO borra el fichero. Es para probarlas contra la capa local antes de rendirse. Sin el
    # interruptor, todo sigue exactamente igual que siempre, borrado incluido.
    # CON -Crudo SE DEVUELVE UNA LISTA VACIA, no una cadena: quien llama hace foreach, y una
    # cadena vacia se recorreria como un elemento.
    if (-not $ruta -or -not (Test-Path -LiteralPath $ruta)) { if ($Crudo) { return @() } return '' }
    $lineas = @()
    try {
        $lineas = @(Get-Content -LiteralPath $ruta -Encoding UTF8 | Where-Object { $_.Trim() })
    } catch { return '' }
    # SE CONSUME AL LEERLA. Unas candidatas de hace tres ordenes no ayudan: harian que Nova
    # contestara a lo de antes. El oido las reescribe en cada dictado, pero si por lo que sea
    # no llegara a hacerlo, aqui se cierra la puerta igual.
    # CON -Crudo NO SE BORRA: quien pregunta va a probarlas en local y, si ninguna sirve, la
    # frase sigue su camino hasta la nube, que es quien de verdad las consume.
    if (-not $Crudo) {
        try { Remove-Item -LiteralPath $ruta -Force -ErrorAction SilentlyContinue } catch {}
    }
    $plano = (ConvertTo-Plain $principal).ToLower().Trim()
    $utiles = @()
    $limpias = @()
    foreach ($l in $lineas) {
        $t = ($l -replace '^[a-z-]+:\s*', '').Trim()
        if (-not $t) { continue }
        # la que ya se probo no es una segunda opinion
        if ((ConvertTo-Plain $t).ToLower().Trim() -eq $plano) { continue }
        if ($utiles -contains $l) { continue }
        $utiles += $l
        # EL TEXTO SIN EL PREFIJO, en el mismo bucle. Si -Crudo devolviera la linea entera
        # -'vosk: cierra los ajustes'- Test-FastCommand no aceptaria NUNCA una candidata y la
        # idea se quedaria muerta EN VERDE.
        $limpias += $t
    }
    if ($Crudo) { return @($limpias) }
    if ($utiles.Count -eq 0) { return '' }
    return ("LO QUE OYERON LOS OTROS MOTORES de esa misma frase (el microfono es imperfecto y" +
            " cada motor se equivoca en cosas distintas):`n" + ($utiles -join "`n") +
            "`nSi la frase de arriba no tiene sentido y alguna de estas si, o si juntandolas se" +
            " entiende lo que pedia, usa eso. Son la MISMA frase oida de varias maneras: no las" +
            " trates como peticiones distintas ni contestes a varias. Si la de arriba ya se" +
            " entiende sola, IGNORA esta lista entera.")
}
# YA NO TE OYE, AUNQUE LA ONDA SIGA MOVIENDOSE (22/09). La escucha crea esta marca en
# el instante en que cierra el microfono y la borra justo antes de dejar el texto:
# mientras existe, esta transcribiendo y esta sorda. Sin ella la capsula se quedaba en
# 'escuchando' -onda verde animada y ojos atentos- una media de 3,48 s por orden
# (mediana 2,0 s, p90 7,0 s, maximo 37 s; 229 de 412 por encima de dos segundos): 1.434
# segundos en total diciendo "sigue, te escucho" a alguien que ya habia terminado.
$RutaTranscribiendo = Join-Path $TmpDir "transcribiendo.flag"
# $true en cuanto se ha visto esa marca en el dictado de ahora; Start-Dictado lo baja
$script:dictaSordo = $false
# la orden ya se entiende entera: la escucha cierra la frase antes (ver SILENCIO_FIN_LOTENGO)
# CUANTOS DICTADOS VACIOS SEGUIDOS SON UNA AVERIA (1/10, idea 8 de las 20 nuevas). Uno suelto es
# normal -braya pulsa el boton y no dice nada: 10 veces en 609 ordenes- y ya esta bien tratado, que
# no cuenta como fallo de oido ni entra en la cuenta de la meta. Tres SEGUIDOS son otra cosa: el
# micro tapado por la funda, el array desactivado en Windows u otro programa con el micro cogido en
# exclusiva. Y el sintoma desde fuera es el peor de todos: suena el tic, se abre la capsula, y nada.
$DictadoVaciosAvisa = [int](Get-Cfg 'escucha' 'vaciosAvisa' 3)
$script:dictaVacios = 0
$RutaLoTengo = Join-Path $TmpDir "lotengo.txt"
$RutaEstado = Join-Path $TmpDir "escucha-estado.txt"
# EL FICHERO DEL LATIDO (24/09, idea 19): lo escribe el oido con anota_latido, y desde la idea
# 7 tambien la serie de la bateria. El nombre se calcula igual que alli -el del log con
# "-pulso" detras- para que los dos escriban en el mismo sitio sin ponerse de acuerdo.
$PulsoPath = [System.IO.Path]::ChangeExtension($EventLog, $null).TrimEnd('.') + '-pulso.log'
# --- DICTADO CON EL MOTOR DE WINDOWS (el de Win+H, sin su ventana) ---
# Convive con Whisper en vez de sustituirlo: los dos oyen la misma orden y
# se prefiere lo que diga Windows SI dice algo. Esa API escucha el microfono
# ella misma y no acepta audio amplificado, asi que puede no oir este micro,
# que entra a 0.02-0.05; por eso viene apagado y por eso hay respaldo.
$VozWindowsOn = [bool](Get-Cfg 'input' 'vozWindows' $false)
$RutaDictadoWin = Join-Path $TmpDir "dictado-winrt.txt"
# Mientras hay un juego delante, la palabra de activacion se apaga y solo vale
# el boton. Es cuando mas molesta equivocarse -el 11/09 abrio un juego solo en
# mitad de una partida- y cuando el boton del mando esta mas a mano.
$MarcaSoloBoton = Join-Path $TmpDir "solo-boton.flag"
$SoloBotonEnJuego = [bool](Get-Cfg 'escucha' 'soloBotonEnJuego' $true)
# QUE SOLO TE OBEDEZCA A TI. El tono de cada orden dictada ya se estimaba y se
# guardaba (tmp\voces.json); nadie lo usaba para nada. Si la orden viene de una
# voz que no se parece a la tuya, no se ejecuta: se pregunta. Es la defensa que
# faltaba contra el audio de un video CON VOZ HUMANA, que es el unico ruido que
# los filtros de hoy no distinguen (no es voz sintetica ni ruido: es una voz de
# verdad diciendo palabras de verdad).
# El margen es ancho a proposito: tu propia voz se mueve al susurrar, al gritar
# o resfriado, y preguntar de mas es peor que no preguntar. Con 35 Hz, una voz
# de video a 230 Hz salta y tu mismo hablando algo mas agudo no.
$SoloYoOn = [bool](Get-Cfg 'escucha' 'soloYo' $true)
$InterrumpirOn = [bool](Get-Cfg 'escucha' 'interrumpir' $true)   # ver INTERRUMPIR A NOVA
$SoloYoMargen = [double](Get-Cfg 'escucha' 'soloYoMargenHz' 35)
$SoloYoMinimo = [int](Get-Cfg 'escucha' 'soloYoMinimo' 12)
$MarcaReintento = Join-Path $TmpDir "reintentar.flag"
# una orden ESCRITA en vez de dicha (tools\decir.ps1): para probar sin hablar
$RutaOrdenEscrita = Join-Path $TmpDir "orden-escrita.txt"
$RutaReintento = Join-Path $TmpDir "reintento.txt"
# nivel de voz 0..1 que el worker escribe mientras dictas; lo lee la interfaz
# directamente (nova_ui.exe busca ui-nivel.txt junto a ui-estado.json)
$RutaNivel = Join-Path $TmpDir "ui-nivel.txt"

# MARCAS HUERFANAS. Si el asistente murio de golpe -taskkill, cierre de sesion,
# un cuelgue- sus marcas se quedan puestas y el worker nuevo las obedece como si
# fueran de ahora. La peor con diferencia es escucha-pausa.flag: el worker nace
# SORDO, tirando todo el audio, y no hay forma de sacarlo de ahi hablando,
# porque justamente no oye. Reanudar-Escucha solo la borra si pausaHasta > 0, y
# en un proceso recien arrancado vale 0, asi que se quedaba puesta para siempre.
# Una dictar.flag huerfana es mas leve pero tambien molesta: el worker se pone a
# grabar una orden que nadie esta dictando. Se limpian todas al arrancar.
# Restos de peticiones al agente que se cancelaron a mitad (manteniendo el
# boton): el runner muere antes de borrar sus in-/out-/err-/raw- y se quedan
# ahi para siempre. Se barren los de hace mas de un dia, nunca los recientes,
# que pueden estar en uso ahora mismo.
# UNA SOLA NOVA, Y ANTES DE TOCAR tmp\ (auditoria del 13/09): el candado estaba
# mas abajo, asi que una segunda copia (la clave Run mas un arranque a mano)
# borraba las marcas de la que ya funcionaba -le quitaba la pausa mientras
# hablaba- y solo despues se daba cuenta de que sobraba.
$mutex = $null
if (-not $Probar) {
    $mutex = New-Object System.Threading.Mutex($false, "Local\VoiceAssistant")
    if (-not $mutex.WaitOne(0)) {
        Write-Output "VoiceAssistant ya esta ejecutandose."
        exit 0
    }
    # workers de una sesion anterior que se quedaron huerfanos (su asistente ya
    # no existe): siguen con el microfono y al arrancar habria dos escuchando
    try {
        # OJO CON EL NOMBRE DEL PROCESO (17/09): esto filtraba Name='python.exe', pero
        # los workers se lanzan con pythonw.exe desde el 14/09 (ver $PyWorker), asi que
        # este barrido llevaba tres dias sin encontrar NI UNO. El log acumulaba 30
        # relanzamientos y 31 marcas huerfanas, y cada worker vivo se queda con el
        # microfono y con su RAM en una maquina de 8 GB. Faltaba ademas charla_worker.py,
        # que es el que mas memoria gasta de los tres.
        # Y FALTABA voz_windows.py (24/09): la lista se escribio el 17/09 a las 16:34 y el
        # worker del dictado de Windows existe desde el 11/09 a las 23:00, asi que no fue
        # un desfase sino un olvido. Es una lista cerrada que el diseno amplio: cada vez
        # que se anada un worker residente hay que anadirlo aqui Y al parar limpio.
        foreach ($wo in @(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue |
                          Where-Object { $_.Name -in @('python.exe', 'pythonw.exe') -and $_.CommandLine -and
                                         ($_.CommandLine -match 'wake_vosk\.py' -or $_.CommandLine -match 'tts_worker\.py' -or
                                          $_.CommandLine -match 'charla_worker\.py' -or $_.CommandLine -match 'voz_windows\.py') })) {
            if (-not (Get-Process -Id $wo.ProcessId -ErrorAction SilentlyContinue)) { continue }
            if (-not (Get-Process -Id $wo.ParentProcessId -ErrorAction SilentlyContinue)) {
                Stop-Process -Id $wo.ProcessId -Force -ErrorAction SilentlyContinue
            }
        }
    } catch {}
}
try {
    $limite = (Get-Date).AddDays(-1)
    $restos = @(Get-ChildItem -LiteralPath $TmpDir -File -ErrorAction SilentlyContinue |
        Where-Object { $_.Name -match '^(?:in|out|err|raw)-[0-9a-f]{16,}' -and $_.LastWriteTime -lt $limite })
    # tampoco en el banco: podrian ser los de una orden VIVA del asistente
    if ($restos.Count -gt 0 -and -not $Probar) {
        $restos | ForEach-Object { Remove-Item -LiteralPath $_.FullName -Force -ErrorAction SilentlyContinue }
        Log "limpieza: $($restos.Count) restos de ordenes canceladas"
    }
} catch {}

# NO en el banco (-Probar): tmp\ es el MISMO que usa el asistente encendido, y
# borrarle las marcas le quitaba la pausa mientras hablaba (se oia a si mismo,
# 12/09 22:20) o le cancelaba un dictado o una confirmacion en curso.
foreach ($m in $(if ($Probar) { @() } else { @($MarcaPausa, $MarcaSoloBoton, $MarcaDictar, $MarcaConfirmar, $MarcaReintento, $MarcaWake, $MarcaSalir) })) {
    if (Test-Path -LiteralPath $m) {
        Log "marca huerfana de la sesion anterior: $(Split-Path -Leaf $m)"
        try { Remove-Item -LiteralPath $m -Force -ErrorAction SilentlyContinue } catch {}
    }
}
$script:pausaHasta = 0

function Pausar-Escucha([int]$ms, [string]$voz = '') {
    try {
        # INTERRUMPIR A NOVA (M5): si la pausa es porque habla, la marca lleva lo que
        # dice. El worker escucha solo "espera", "para", "calla"... y descarta la
        # palabra si esta en la propia frase (sin eso se cortaria con su eco)
        # Y NO EN SORDINA (21/09). La sordina pone la pausa larga SIN texto -marca 'x'-,
        # pero justo despues Say dice 'me callo media hora, si me necesitas antes manten
        # el boton' y vuelve a pasar por aqui CON texto: la marca se reescribia como
        # 'voz:...' y ahi se quedaba los treinta minutos enteros, porque $pausaHasta no
        # cambia (la sordina es mas larga).
        # Con la marca en 'voz:', vigilar_corte sigue corriendo un reconocedor sobre CADA
        # bloque de audio media hora, y acepta 'nova', 'para', 'calla'... o sea que decir
        # 'nova' abria el microfono y sonaba el tic mientras escucha-pausa.flag seguia en
        # disco: la sordina rota y Nova a medio despertar. Justo lo que braya pidio que
        # NO pasara al decir 'no me escuches media hora'.
        # Lo unico que se pierde es cortar con la voz la frase 'me callo media hora', que
        # dura dos segundos y para la que esta el boton.
        # Y EN SORDINA, 'nombre:' (22/09). La marca decia 'x', que en el worker significa
        # "no escuches nada": ni siquiera su nombre la sacaba de ahi, solo el boton. braya
        # pidio lo contrario -"hasta que la vuelva a llamar"-, asi que mientras esta callada
        # la marca lleva su nombre y el worker corre un reconocedor que SOLO conoce esa
        # palabra. Las de corte ('para', 'calla') siguen fuera: son para interrumpirla
        # mientras habla, no para despertarla.
        $marcaTxt = if ($voz -and $InterrumpirOn -and $script:sordinaHasta -le $sw.ElapsedMilliseconds) { 'voz:' + (ConvertTo-Plain $voz) }
                    elseif ($script:sordinaHasta -gt $sw.ElapsedMilliseconds) { 'nombre:' + (ConvertTo-Plain $EscuchaNombre) }
                    else { 'x' }
        [System.IO.File]::WriteAllText($MarcaPausa, $marcaTxt)
        $fin = $sw.ElapsedMilliseconds + $ms
        if ($fin -gt $script:pausaHasta) { $script:pausaHasta = $fin }
    } catch {}
}

# QUE SIGNIFICA UN CORTE (24/09, idea 2 de la tanda nueva). Pura y aparte para que el
# banco pueda recorrer las seis combinaciones en un milisegundo, y sobre todo para que
# NINGUNA se quede sin rama: el fallo de los quince dias fue justo que habia dos ramas y
# tres situaciones posibles.
# LAS CINCO SALIDAS Y NINGUNA MAS:
#   en sordina + su nombre        -> vuelve entera (lo de siempre)
#   en sordina + otra palabra     -> tarde: en sordina no esta hablando
#   dictado abierto               -> se cancela el dictado   <- LO QUE FALTABA
#   hablando + su nombre          -> se calla y abre el microfono
#   hablando + otra palabra       -> se calla y NO abre el microfono
#   ni hablando ni dictando       -> tarde
function Resolve-Corte([string]$palabra, [string]$nombre, [bool]$armado, [bool]$enPausa, [bool]$enSordina) {
    $esNombre = ((ConvertTo-Plain $palabra) -eq (ConvertTo-Plain $nombre))
    if ($enSordina) {
        if ($esNombre) { return @{ accion = 'sordina-vuelve'; abreMicro = $true; estadistica = 'sordina-nombre' } }
        return @{ accion = 'tarde'; abreMicro = $false; estadistica = 'corte-tarde' }
    }
    # EL DICTADO MANDA SOBRE LA PAUSA: si hay uno abierto, lo que se pide es cancelarlo,
    # y da igual que ademas estuviera hablando.
    if ($armado) { return @{ accion = 'cancela-dictado'; abreMicro = $false; estadistica = 'corte-dictado' } }
    if ($enPausa) {
        if ($esNombre) { return @{ accion = 'corta-y-escucha'; abreMicro = $true; estadistica = 'corte-nombre' } }
        return @{ accion = 'corta-y-calla'; abreMicro = $false; estadistica = 'corte-callar' }
    }
    return @{ accion = 'tarde'; abreMicro = $false; estadistica = 'corte-tarde' }
}

function Reanudar-Escucha([switch]$Forzar) {
    # CON LA SORDINA PUESTA NO SE REANUDA (auditoria del 13/09): "no me escuches
    # media hora" se levantaba en cuanto Nova terminaba de decir "vale". Solo la
    # levanta quien lo pide a proposito (-Forzar: el dictado con el boton).
    if (-not $Forzar -and $script:sordinaHasta -gt $sw.ElapsedMilliseconds) { $script:pausaHasta = 0; return }
    try { Remove-Item -LiteralPath $MarcaPausa -Force -ErrorAction SilentlyContinue } catch {}
    $script:pausaHasta = 0
}

function Initialize-Escucha {
    if (-not $EscuchaOn) { Log "escucha continua desactivada por configuracion"; return }
    # DOS MOTORES POSIBLES:
    #  vosk (por defecto): lee el microfono en Python y AMPLIFICA por software.
    #    En esta maquina el microfono entra muy bajo (prueba de Windows: 7 %) y
    #    SAPI lo tomaba por silencio. Vosk da acceso al audio crudo, asi que la
    #    ganancia se puede corregir; SAPI no lo permitia.
    #  sapi: worker en C# (wake_worker.exe). Se conserva como alternativa.
    #    OJO: NO puede ser un script de PowerShell. PowerShell no soporta los
    #    eventos asincronos de SAPI: el manejador corre en el hilo del
    #    reconocedor y mata el proceso en silencio. Comprobado dos veces.
    try {
        Remove-Item -LiteralPath $MarcaWake -Force -ErrorAction SilentlyContinue
        if ($EscuchaMotor -eq 'vosk') {
            # el worker vigila que este proceso siga vivo: si muere, sale y suelta
            # el microfono en vez de quedarse escuchando huerfano (auditoria 13/09)
            $env:NOVA_PID_PADRE = "$PID"
            $worker = Join-Path $LogDir "wake_vosk.py"
            if (-not (Test-Path -LiteralPath $worker)) { Log "WARN: falta wake_vosk.py"; Add-FalloArranque 'no puedo oirte por la palabra, solo con el boton'; return }
            # La confianza minima va TAMBIEN aqui: hasta ahora solo la recibia el
            # wake_worker.exe viejo, asi que el ajuste del config no hacia nada.
            $conf = $EscuchaConf.ToString([System.Globalization.CultureInfo]::InvariantCulture)
            # LA RAFAGA MINIMA PARA LA PALABRA DE DESPERTAR (20/09). Ver LA RAFAGA QUE DE
            # VERDAD TE DELATA en wake_vosk.py: con 0.008 Nova se activaba sola oyendo una
            # conversacion de fondo. Se pasa como argumento 21 para poder bajarlo desde
            # config.json (escucha.rafagaMinima) si alguna vez no le oye al llamarla flojo.
            $rafagaMin = ([double](Get-Cfg 'escucha' 'rafagaMinima' 0.03)).ToString([System.Globalization.CultureInfo]::InvariantCulture)
            # EL JUEZ DE SEGUNDA ETAPA (20/09/2026). Ver EL JUEZ DEL NOMBRE en wake_vosk.py:
            # la gramatica de Vosk es CERRADA y esta OBLIGADA a devolver algo de su lista ante
            # cualquier ruido, y por eso la madrugada del 20/09 Nova grabo 70 s de una
            # conversacion privada sin que braya dijera su nombre. El juez es el mismo modelo
            # sin gramatica, escuchando en paralelo: no carga nada ni anade espera al llamarla.
            # Argumento 22. Se estrena en 'mirar' porque todavia no hay medida: la rafaga del
            # nombre no se guarda en pruebas\audio\uso, asi que el unico sitio donde se puede
            # medir es el log de un dia de uso real. Valores: 'si', 'mirar', 'no'.
            $juezNombre = [string](Get-Cfg 'escucha' 'juezNombre' 'mirar')
            if ([string]::IsNullOrWhiteSpace($juezNombre)) { $juezNombre = 'mirar' }
            # EL STDERR DEL WORKER, A UN ARCHIVO. El 12/09 murio tres veces sin
            # dejar ni una linea (se lanzaba sin redirigir nada). Y lo que dejo
            # la vez anterior se pasa al log ANTES de relanzar, porque la
            # redireccion vacia el archivo justo cuando mas falta hace.
            $rutaErrWorker = Join-Path $TmpDir 'wake-err.log'
            try {
                if ((Test-Path -LiteralPath $rutaErrWorker) -and (Get-Item -LiteralPath $rutaErrWorker).Length -gt 0) {
                    $errViejo = ([System.IO.File]::ReadAllText($rutaErrWorker)).Trim()
                    if ($errViejo) { Log ("worker de escucha, su salida de error la vez anterior: " + $errViejo.Substring([Math]::Max(0, $errViejo.Length - 2000))) }
                }
            } catch {}
            $script:wakeProc = Start-Process -FilePath $PyWorker `
                -ArgumentList @('-u', $worker, $EscuchaNombre, $MarcaWake, $EventLog, $EscuchaGanancia,
                                $MarcaPausa, $MarcaDictar, $RutaDictado, $RutaParcial, $RutaNivel,
                                $MarcaConfirmar, $RutaConfirmacion, "$MotorDictado`:$WhisperModelo", $RutaVocabulario,
                                $conf, $MarcaReintento, $RutaReintento, $(if ($WhisperPreciso) { $WhisperPreciso } else { '-' }), $(if ($WhisperUltimo) { $WhisperUltimo } else { '-' }), $rafagaMin, $juezNombre) `
                -WorkingDirectory $LogDir -WindowStyle Hidden -PassThru `
                -RedirectStandardError $rutaErrWorker
        } else {
            $worker = Join-Path $LogDir "wake_worker.exe"
            if (-not (Test-Path -LiteralPath $worker)) { Log "WARN: falta wake_worker.exe"; return }
            $conf = $EscuchaConf.ToString([System.Globalization.CultureInfo]::InvariantCulture)
            $script:wakeProc = Start-Process -FilePath $worker `
                -ArgumentList @($EscuchaNombre, $conf, $MarcaWake, $EventLog) `
                -WindowStyle Hidden -PassThru
        }
        $null = $script:wakeProc.Handle
        # el oido de Windows, si esta activado: otro proceso aparte, que mira
        # la MISMA marca de dictado y escribe en su propio archivo
        if ($VozWindowsOn) {
            $wv = Join-Path $LogDir "voz_windows.py"
            if (Test-Path -LiteralPath $wv) {
                try {
                    # DE QUIEN ES HIJO (24/09). Sin esto el worker no puede saber que se ha
                    # quedado solo: el 24/09 Nova murio a las 21:53 y media hora despues habia
                    # 44 de estos vivos comiendo 1,3 GB mientras braya jugaba.
                    # SE PONE AQUI Y NO SOLO ARRIBA A PROPOSITO: la linea de mas arriba esta
                    # dentro de "if (EscuchaMotor -eq 'vosk')", y este bloque esta fuera de esa
                    # rama. Hoy el motor es vosk y por eso la variable llegaba de casualidad;
                    # con cualquier otro motor el dictado se quedaba sin proteger.
                    $env:NOVA_PID_PADRE = "$PID"
                    $script:vozWinProc = Start-Process -FilePath $PyWorker `
                        -ArgumentList @('-u', $wv, $MarcaDictar, $RutaDictadoWin, $EventLog, 'es-ES') `
                        -WorkingDirectory $LogDir -WindowStyle Hidden -PassThru
                    $null = $script:vozWinProc.Handle
                    try { $script:vozWinProc.PriorityClass = [System.Diagnostics.ProcessPriorityClass]::BelowNormal } catch {}
                    Log "dictado de Windows ACTIVO (worker PID=$($script:vozWinProc.Id))"
                } catch { Log ("WARN: no arranco el dictado de Windows: " + $_.Exception.Message) }
            } else { Log "WARN: falta voz_windows.py" }
        }
        # Es un portatil de JUEGOS: la escucha nunca debe competir por CPU con
        # el juego en primer plano.
        try { $script:wakeProc.PriorityClass = [System.Diagnostics.ProcessPriorityClass]::BelowNormal } catch {}
        $script:wakeDesde = $sw.ElapsedMilliseconds
        # PARA MEDIR CUANTO TARDA EN OIR (23/09, idea 12): sin esto no hay forma de saber si
        # mover la carga a un hilo arreglaria algo o pagaria la primera orden por nada.
        $script:oidoMarcaPuesta = $sw.ElapsedMilliseconds
        $script:oidoApuntado = $false
        $script:oidoListoEn = 0
        $script:oidoProntoDicho = $false
        # LA MARCA LA PONE QUIEN LLEGA PRIMERO (20/09, H5m4). La escribia el worker justo
        # antes de cargar Whisper, y en el arranque de las 13:28 llego DOS SEGUNDOS tarde:
        # el saludo ya habia salido. Aqui no hay carrera posible, porque esto pasa antes
        # de lanzar nada que tarde. La borra el worker cuando ya oye de verdad.
        try { [System.IO.File]::WriteAllText((Join-Path $TmpDir 'oido-cargando.txt'), $EscuchaMotor) } catch {}
        Log "escucha continua ACTIVA [$EscuchaMotor] (worker PID=$($script:wakeProc.Id)): di '$EscuchaNombre'"
    } catch {
        Log ("WARN: escucha continua no arranco: " + $_.Exception.Message)
        $script:wakeProc = $null
    }
}

# =====================================================================
# INTERFAZ (nova_ui.exe): la cara visible del asistente
# Una capsula de cristal en la esquina inferior izquierda que vive en su
# propio proceso WPF. Aqui NO se dibuja nada: solo se escribe un JSON con el
# estado y la interfaz lo lee cada 80 ms. Mismo patron de archivos que los
# workers de voz y escucha; cero hilos compartidos con este bucle.
#
# La barra antigua de WinForms sigue existiendo porque el dictado de Windows
# necesita una ventana con foco donde escribir, pero se vuelve invisible
# (opacidad minima) cuando la interfaz nueva esta activa.
# =====================================================================
$UiNuevaOn = [bool](Get-Cfg 'ui' 'nueva' $true)
# EL MICROFONO NO SE ABRE EN SILENCIO (20/09/2026). Esa madrugada Nova se
# activo sola 5 veces en 12 minutos y grabo 70 s de una conversacion privada;
# las 5 activaciones se volvieron 14 grabaciones porque el seguimiento reabre
# la escucha solo y lo hacia SIN sonido (9 de las 14 entraron por esa puerta).
# La regla de Alexa es que el indicador suena CADA vez que se abre el micro,
# sin excepcion: si suena, se oye que esta grabando y se puede cortar. El tono
# es el sonTic que la capsula ya tiene (1320 Hz, 25 ms): corto para no pisar
# la frase. Si molesta, ui.ticMicro = false y vuelve a callar.
$TicMicroOn = [bool](Get-Cfg 'ui' 'ticMicro' $true)
$RutaUiEstado = Join-Path $TmpDir "ui-estado.json"
$script:uiProc = $null
$script:uiUltimo = ''
$script:uiHasta = 0     # cuando vence, la capsula vuelve al reposo
$script:uiCheck = 0
$script:uiIntentos = 0

# Estados: reposo | escuchando | pensando | hablando | error.
# $ms > 0: volver al reposo pasado ese tiempo (si no hay nada mas en marcha).
# Ademas del estado, el JSON lleva:
#   evento/n : animacion puntual (despierta, hecho, aviso). La interfaz la
#              dispara cuando cambia n, asi que el mismo evento puede repetirse.
#   juego    : ejecutable del juego en primer plano; su icono pasa a ser el
#              avatar de la capsula y el punto se vuelve insignia de estado.
$script:uiEstado = 'reposo'
$script:uiTexto = ''
$script:uiEvento = ''
$script:uiEventoN = 0
$script:juegoExe = ''
$script:uiAudio = ''        # mp3 que suena; la capsula busca <mp3>.env para mover la boca
$script:uiBateria = 100
$script:uiCargando = 0
$script:uiPerfil = ''       # ultimo perfil aplicado ("noche" cambia la paleta)
$script:uiCarga = 0         # % de CPU: la capsula se agita por encima del 85
$script:uiProgreso = 0      # 0..1 mientras opencode trabaja (linea del borde)
# Cuando vence el si/no, en reloj de pared: la capsula dibuja la barra que se
# vacia con su propio reloj, sin reescribir el estado en cada tic. Se declara
# AQUI y no junto a $pendiente porque Set-UI se usa mucho antes: alli valdrian
# $null y el JSON saldria roto.
$script:confirmaFin = 0
$script:confirmaTotal = 0
$script:uiVoz = 0           # indice de la voz que dicto (por tono), 0 = la habitual
$script:ultimaF0 = 0        # tono de la ultima orden dictada, en Hz (0 = no se pudo medir)
$script:ambienteUltimo = ''   # lo que sonaba antes de llamarla (solo con escucha.ambiente)
$script:uiClima = ''        # emoji del tiempo: solo unos segundos cuando se pregunta
$script:uiClimaHasta = 0
$script:uiAnimo = 0         # -1..1 segun aciertos y errores de las ultimas 24 h
$script:animoLargo = 0      # el mismo numero, pero con 7 dias de memoria (idea 34)
$script:animoBase = 0       # cuantos de esos 7 dias tenian datos suficientes para votar
# NO SE LLAMA animoLargoDias, y la razon la cazo su propio banco el 25/09: en PowerShell los
# nombres de variable NO distinguen mayusculas, asi que $script:animoLargoDias y la constante
# $AnimoLargoDias de mas abajo eran LA MISMA, y el estado le pisaba el 7 a la ventana en cuanto
# se calculaba por primera vez. Es el mismo tropiezo que $PY contra $py de esta misma semana.
$script:uiHaciendo = ''     # QUE se esta ejecutando ahora mismo (glifo en la capsula)
$script:uiRemoto = $false   # "pensando" lo lleva la IA (violeta) y no Nova sola (ambar)
$script:uiMia = $false      # idea 54: esto NO me lo pediste (una regla, un aviso de entorno, una decision propia)
$script:sinTarjeta = $false # la proxima respuesta es para oirla: sin tarjeta grande (ver Show-Popup)
$script:sinTarjetaEn = 0
$script:respuestaSinTarjeta = $false   # la respuesta del cerebro que viene es para oirla
$script:notaJuegoPendiente = $null     # la respuesta que viene es donde te quedaste en este juego
$script:notaPorGrabar = $null          # el proximo seguimiento se guarda como nota de voz
$script:grabandoNota = $null           # ...y esta en marcha (ruta del WAV)
$script:traducirPorOir = $null         # el proximo seguimiento se oye en este idioma
$script:traduciendoVoz = $null         # ...y esta en marcha
$script:huecoPendiente = $null         # a una receta le falta un valor y se ha preguntado
$script:avisosAplazados = New-Object System.Collections.ArrayList   # avisos que llegaron mientras dictabas
$script:notifCheck = 0      # ultima vez que se miraron las notificaciones
$script:uiCola = ''         # "3/2" = tres cosas en esta orden, va por la segunda; "3/2!" = esa fallo
$script:uiDescarga = 0      # 0..1 de la descarga de Steam mas avanzada (anillo)

function ConvertTo-JsonTexto([string]$s) {
    $t = (($s -replace '[\r\n\t]+', ' ') -replace '\s+', ' ').Trim()
    return $t.Replace('\', '\\').Replace('"', '\"')
}

# EL TEXTO DE LA CAPSULA, CORTADO POR DONDE SE PUEDE LEER (17/09). Cortaba a 137 letras a
# pelo, o sea a mitad de palabra: "no he podido abrir la carpeta de desc..." se quedaba en
# "desc". La VOZ ya lo hacia bien desde el 14/09 -Get-TextoVoz busca el final de una frase y
# si no el ultimo espacio-; esto es lo mismo para lo que se LEE, que es por donde pasa TODO
# el texto que ensena la capsula.
#
# Si la ultima palabra no cabe entera, se corta por el espacio anterior. Una palabra
# larguisima sin espacios utiles (una ruta, una URL) se corta a pelo a proposito: es mejor
# que ensenar tres palabras y kilometro y medio de nada.
# Aparte de Set-UI para que una prueba pueda ejecutarla sin montar media capsula.
function Get-TextoCapsula([string]$texto, [int]$tope = 140) {
    $t = (($texto -replace '[\r\n\t]+', ' ') -replace '\s+', ' ').Trim()
    if ($t.Length -le $tope) { return $t }
    $cabe = $t.Substring(0, $tope - 3).TrimEnd()
    $esp = $cabe.LastIndexOf(' ')
    if ($esp -ge [int]($tope * 0.4)) { $cabe = $cabe.Substring(0, $esp) }
    return $cabe.TrimEnd([char[]]@(' ', ',', ';', ':', '.')) + '...'
}

function Set-UI([string]$estado, [string]$texto = '', [int]$ms = 0) {
    if (-not $UiNuevaOn) { return }
    # ESCONDIDA: volver al reposo es volver a esconderse. Sin esto, la propia
    # respuesta ("me quito...") la sacaba y al callar se quedaba a la vista
    # (13/09). Hablar o escuchar si la ensenan un momento.
    if ($estado -eq 'reposo' -and $script:uiRetirada) { $estado = 'retirada' }
    $t = Get-TextoCapsula $texto
    $script:uiEstado = $estado
    $script:uiTexto = $t
    # la marca de "lo lleva la IA" dura lo que dura el pensar: cualquier otro
    # estado (respuesta, error, reposo) la quita
    if ($estado -ne 'pensando') { $script:uiRemoto = $false }
    # idea 54: la marca "mia" tambien caduca (regla 2, dos salidas + plazo): volver al reposo la apaga
    # -con el $ms que ya lleva cada Show-Popup- y que braya hable (escuchando) la apaga al instante.
    if ($estado -eq 'reposo' -or $estado -eq 'retirada' -or $estado -eq 'escuchando') { $script:uiMia = $false }
    # temporizador mas proximo, en tiempo de reloj (ms Unix) para que la
    # capsula dibuje el anillo con su propio reloj sin que haya que reescribir
    $tFin = 0; $tTotal = 0; $tTipo = ''
    if ($script:temporizadores -and $script:temporizadores.Count -gt 0) {
        $prox = $null
        # los que estan en pausa no dibujan el anillo (su vence es infinito)
        foreach ($tp in $script:temporizadores) { if ($tp.pausado) { continue }; if ($null -eq $prox -or $tp.vence -lt $prox.vence) { $prox = $tp } }
        if ($prox) {
            $tFin = [DateTimeOffset]::Now.ToUnixTimeMilliseconds() + ($prox.vence - $sw.ElapsedMilliseconds)
            $tTotal = $prox.total
            if ($prox.tipo) { $tTipo = [string]$prox.tipo }
        }
    }
    # EN QUE ESTADO ESTA EL OIDO. La capsula lo dibuja: sin esto, estar sorda y
    # estar escuchando se ven exactamente igual.
    $oido = 'palabra'
    if ($script:sordinaHasta -gt $sw.ElapsedMilliseconds) { $oido = 'sorda' }
    # "solo boton": la palabra esta apagada pero el boton sigue valiendo.
    # Pasa con un juego delante (marca solo-boton) o si el worker murio.
    elseif (Test-Path -LiteralPath $MarcaSoloBoton) { $oido = 'boton' }
    elseif ($EscuchaOn -and (-not $script:wakeProc -or $script:wakeProc.HasExited)) { $oido = 'boton' }
    $json = '{"estado":"' + $estado + '","texto":"' + (ConvertTo-JsonTexto $t) + '","nivel":0' +
            ',"evento":"' + $script:uiEvento + '","n":' + $script:uiEventoN +
            ',"juego":"' + (ConvertTo-JsonTexto $script:juegoExe) + '"' +
            # Y SI NO SE LA VE (25/09, idea 1): la propia capsula lo sabe, para poder dejar de
            # gastar en animaciones que nadie mira.
            ',"capsulaCiega":' + $(if ($script:capsulaCiega) { '1' } else { '0' }) +
            ',"audio":"' + (ConvertTo-JsonTexto $script:uiAudio) + '"' +
            ',"bateria":' + $script:uiBateria + ',"cargando":' + $script:uiCargando +
            ',"tempoFin":' + $tFin + ',"tempoTotal":' + $tTotal +
            ',"perfil":"' + $script:uiPerfil + '"' +
            ',"carga":' + $script:uiCarga + ',"clima":"' + (ConvertTo-JsonTexto $script:uiClima) + '"' +
            ',"animo":' + ([double]$script:uiAnimo).ToString('0.00', [System.Globalization.CultureInfo]::InvariantCulture) +
            ',"progreso":' + ([double]$script:uiProgreso).ToString('0.00', [System.Globalization.CultureInfo]::InvariantCulture) +
            ',"oido":"' + $oido + '","tempoTipo":"' + $tTipo + '"' +
            ',"haciendo":"' + $script:uiHaciendo + '"' +
            ',"remoto":"' + $(if ($script:uiRemoto -or $script:busy) { '1' } else { '0' }) + '"' +
            ',"mia":"' + $(if ($script:uiMia) { '1' } else { '0' }) + '"' +   # idea 54: "1" si lo hice yo sola, no me lo pediste
            ',"musica":"' + $script:uiMusica + '"' +
            ',"peligrosa":"' + $(if ($script:pendiente -and $script:pendiente.tipo -eq 'peligrosa') { '1' } else { '0' }) + '"' +
            ',"madurez":"' + $script:uiMadurez + '"' +
            ',"tiempo":"' + $script:uiTiempo + '"' +
            ',"vol":"' + $script:uiVolumen + '"' +
            ',"cola":"' + $script:uiCola + '"' +
            ',"descarga":' + ([double]$script:uiDescarga).ToString('0.000', [System.Globalization.CultureInfo]::InvariantCulture) +
            ',"escala":' + ([double]$script:uiEscala * $(if ($script:uiDock -eq 1) { 1.25 } else { 1.0 })).ToString('0.00', [System.Globalization.CultureInfo]::InvariantCulture) +
            ',"origen":"' + $script:uiOrigen + '"' +
            ',"color":"' + $script:uiColor + '"' +
            ',"confirmaFin":' + ([long]$script:confirmaFin) + ',"confirmaTotal":' + ([long]$script:confirmaTotal) +
            ',"esquina":"' + $script:esquina + '"' +
            ',"voz":' + $script:uiVoz + '}'
    if ($json -ne $script:uiUltimo) {
        # UTF-8 SIN BOM: la interfaz lo lee tal cual y el BOM colaria un caracter
        try { [System.IO.File]::WriteAllText($RutaUiEstado, $json, (New-Object System.Text.UTF8Encoding $false)) } catch {}
        $script:uiUltimo = $json
    }
    $script:uiHasta = if ($ms -gt 0) { $sw.ElapsedMilliseconds + $ms } else { 0 }
    # si se pregunto el tiempo, que el emoji dure al menos lo que la respuesta
    if ($script:uiClimaHasta -gt 0 -and $script:uiHasta -gt $script:uiClimaHasta) { $script:uiClimaHasta = $script:uiHasta + 1500 }
}

# Dispara una animacion sin cambiar el estado (el estado se reescribe igual).
function Send-UIEvento([string]$evento) {
    # ACABA DE APRENDER ALGO: el "hecho" de siempre se convierte en la
    # celebracion. Hace falta porque la capsula lee UN evento por vuelta, y el
    # "hecho" que llega justo despues de aprender pisaria el gesto. La marca
    # caduca a los 10 s, para no celebrar a destiempo algo que no toca.
    if ($script:acabaDeAprender -and ($sw.ElapsedMilliseconds - $script:acabaDeAprenderEn) -gt 10000) { $script:acabaDeAprender = $false }
    if ($evento -eq 'hecho' -and $script:acabaDeAprender) { $evento = 'gesto:aprendido' }
    if ($evento -eq 'gesto:aprendido') { $script:acabaDeAprender = $false }
    # eco en el mando: lo que la capsula celebra, el mando lo hace sentir
    switch ($evento) {
        'hecho' { Start-Vibracion @(50, 60, 50) 18000 }
        'logro' { Start-Vibracion @(80, 60, 80, 60, 160) 26000 }
        'aviso' { Start-Vibracion @(120, 80, 120) 22000 }
        'gesto:aprendido' { Start-Vibracion @(40, 50, 40, 50, 110) 22000 }
        'gesto:sinia' { Start-Vibracion @(50, 60, 50) 18000 }
    }
    if (-not $UiNuevaOn) { return }
    $script:uiEvento = $evento
    $script:uiEventoN++
    Refresh-UI
}

# Reescribe el estado actual (tras cambiar el juego o lanzar un evento) sin
# tocar el plazo de vuelta al reposo.
function Refresh-UI {
    $resta = 0
    if ($script:uiHasta -gt 0) { $resta = [Math]::Max(1, $script:uiHasta - $sw.ElapsedMilliseconds) }
    Set-UI $script:uiEstado $script:uiTexto $resta
}

# QUE VA A HACER, ANTES DE HACERLO
# Cada accion que toca el sistema enciende un glifo en la capsula JUSTO ANTES de
# ejecutarse: la app, el altavoz, la ventana. Una forma se reconoce de un
# vistazo; leer el texto tarda mas que la accion en pasar, y para entonces ya no
# hay nada que cancelar. NO anade ninguna espera: el glifo se ve durante lo que
# tarde la accion y el respiro de 250 ms que la sigue. Las ordenes que solo
# CONSULTAN (la hora, a que juegas, que modos hay) no llevan glifo: no hay nada
# que cancelar y el parpadeo solo seria ruido.
$GlifosAccion = @{
    'app' = 'app'; 'url' = 'web'; 'buscarEquipo' = 'web'
    'volumenPct' = 'sonido'; 'volumenRel' = 'sonido'; 'volumenApp' = 'sonido'
    'silencio' = 'mudo'
    'brillo' = 'brillo'
    'key' = 'tecla'; 'atajo' = 'tecla'; 'winkey' = 'tecla'; 'winaltg' = 'tecla'; 'alttab' = 'tecla'
    'escribir' = 'escribir'
    'winprt' = 'captura'
    'otroMonitor' = 'ventana'; 'siempreEncima' = 'ventana'; 'esconder' = 'ventana'
    'enfocar' = 'ventana'; 'enfocarJuego' = 'ventana'
    'cerrarApp' = 'cerrar'; 'cerrarJuego' = 'cerrar'; 'cerrarTodo' = 'cerrar'; 'zombis' = 'cerrar'
    'lock' = 'bloqueo'
    'memoria' = 'nota'; 'ocrMemoria' = 'nota'; 'apuntarCopiado' = 'nota'
    'temporizador' = 'tiempo'; 'quitarTempo' = 'tiempo'
    'copiar' = 'copia'; 'pegar' = 'copia'; 'copiarRespuesta' = 'copia'
    'ocr' = 'pantalla'; 'seguirLeyendo' = 'pantalla'
    'deshacer' = 'deshacer'; 'deshacerDesde' = 'deshacer'; 'noEraEso' = 'deshacer'; 'deshacerAuto' = 'deshacer'
}
# CUANTAS COSAS SON Y POR CUAL VA. "abre steam y pon modo juego" son dos; si
# falla la segunda, hasta ahora no habia forma de saber cual fue. Solo se manda
# cuando hay MAS DE UNA: para una sola, un punto suelto no dice nada.
function Set-UICola([int]$total, [int]$indice, [bool]$fallo = $false) {
    if (-not $UiNuevaOn) { return }
    $v = ''
    if ($total -gt 1) { $v = "$total/$indice" + $(if ($fallo) { '!' } else { '' }) }
    if ($v -eq $script:uiCola) { return }
    $script:uiCola = $v
    Refresh-UI
}

function Set-UIHaciendo([string]$kind) {
    if (-not $UiNuevaOn) { return }
    $g = ''
    if ($kind) { $g = [string]$GlifosAccion[$kind] }
    # solo se reescribe el estado si CAMBIA: dos teclas seguidas no valen dos
    # escrituras del JSON ni dos animaciones de entrada
    if ($g -eq $script:uiHaciendo) { return }
    $script:uiHaciendo = $g
    Refresh-UI
}

# AVISOS SIN VOZ
# Hasta ahora un aviso o te hablaba encima o no existia. Con un juego delante,
# que te hable es justo lo que no quieres; en sordina, le acabas de pedir
# silencio. Pero callar del todo es no enterarte. Asi que en esos casos el
# aviso se ve -tres pulsos de color en el borde de la capsula, con el texto
# puesto- y no suena.
# El aviso SIEMPRE aparece; lo unico que cambia es si ademas habla.
$AvisosSinVoz = [bool](Get-Cfg 'avisos' 'sinVoz' $true)
$AvisosSinVozEnJuego = [bool](Get-Cfg 'avisos' 'sinVozEnJuego' $true)
# SILENCIO EN LLAMADAS (13/09): si OTRA app esta usando el microfono (Discord,
# una llamada, una grabacion), Nova no habla: su voz se colaria en la llamada.
# Lo dice el registro de privacidad de Windows (LastUsedTimeStop = 0 mientras se
# usa). No cuentan el worker de escucha de Nova (python) ni el dictado de
# Windows. Se mira como mucho cada 3 s.
$script:llamadaVista = 0
$script:llamadaActiva = $false
function Test-EnLlamada {
    if (($sw.ElapsedMilliseconds - $script:llamadaVista) -lt 3000 -and $script:llamadaVista -gt 0) { return $script:llamadaActiva }
    $script:llamadaVista = $sw.ElapsedMilliseconds
    $activa = $false
    try {
        $raizM = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\CapabilityAccessManager\ConsentStore\microphone'
        $claves = @(Get-ChildItem -LiteralPath $raizM -ErrorAction SilentlyContinue) + @(Get-ChildItem -LiteralPath (Join-Path $raizM 'NonPackaged') -ErrorAction SilentlyContinue)
        foreach ($cl in $claves) {
            if ($cl.PSChildName -match '(?i)python|TextInputHost|MicrosoftWindows\.Client|voice-ctrl|^NonPackaged$') { continue }
            $pr = Get-ItemProperty -LiteralPath $cl.PSPath -ErrorAction SilentlyContinue
            if ($pr -and $null -ne $pr.LastUsedTimeStart -and [long]$pr.LastUsedTimeStop -eq 0) { $activa = $true; break }
        }
    } catch {}
    if ($activa -ne $script:llamadaActiva) { Log ("LLAMADA: " + $(if ($activa) { 'otra app usa el microfono; Nova se calla' } else { 'microfono libre; Nova vuelve a hablar' })) }
    $script:llamadaActiva = $activa
    return $activa
}
# LA CAPSULA CIEGA (25/09, idea 1).
#
# LO QUE PASO la noche del 24 con braya jugando: la capsula estaba en z=0 -por delante del
# juego-, visible, colocada y del tamano correcto, y NO SE PINTABA NI UN PIXEL. A Way Out
# estaba en pantalla completa EXCLUSIVA, y ahi ningun overlay de ventana se dibuja. Nova estuvo
# media hora ensenandole cosas a nadie, y eso choca con la regla 2 de la casa: ningun modo
# puede tener una sola salida.
#
# COMO SE SABE, y es limpio: el modo exclusivo CAMBIA LA RESOLUCION DEL ESCRITORIO. Medido esa
# noche: el panel de la Ally es 1920x1080 nativo y el escritorio estaba a 1280x720. El modo
# "ventana sin bordes" no la cambia nunca, asi que la diferencia lo delata sin preguntarle nada
# a DirectX ni inyectar nada en el juego.
#
# LA NATIVA SE PREGUNTA UNA VEZ: el panel de una consola no cambia de tamano, y la consulta WMI
# cuesta cientos de milisegundos. La actual si se mira cada vez, porque es lo que cambia.
$script:resNativa = $null
$script:resNativaMirada = $false
function Get-ResolucionNativa {
    if ($script:resNativaMirada) { return $script:resNativa }
    $script:resNativaMirada = $true
    try {
        $m = @(Get-CimInstance -Namespace 'root\wmi' -ClassName WmiMonitorListedSupportedSourceModes -ErrorAction SilentlyContinue)
        foreach ($x in $m) {
            $p = $x.MonitorSourceModes[$x.PreferredMonitorSourceModeIndex]
            if ($p.HorizontalActivePixels -gt 0) {
                $script:resNativa = @([int]$p.HorizontalActivePixels, [int]$p.VerticalActivePixels)
                break
            }
        }
    } catch { $script:resNativa = $null }
    return $script:resNativa
}
function Get-ResolucionActual {
    try {
        $v = @(Get-CimInstance Win32_VideoController -ErrorAction SilentlyContinue |
               Where-Object { $_.CurrentHorizontalResolution -gt 0 })
        if ($v.Count -gt 0) { return @([int]$v[0].CurrentHorizontalResolution, [int]$v[0].CurrentVerticalResolution) }
    } catch {}
    return $null
}
# LO DICE LA CAPSULA, NO LA RESOLUCION (27/09, idea 67). Esto comparaba la resolucion nativa con
# la actual, y esa cuenta no dio 'no se ve' NI UNA VEZ en las 58.636 lineas de los dos registros,
# con 19,9 horas de juego dentro (memoria\juegos.json, 9 dias): ni un 'CAPSULA CIEGA', y por eso
# los cinco avisos 'SIN VOZ' salieron sin vibrar. Razon: los juegos de hoy usan pantalla completa
# sin cambiar de resolucion, asi que nativa y actual coinciden y la cuenta siempre decia 'se ve'.
#
# Ahora lo dice quien lo sabe: la capsula escribe en tmp\ui-visible.txt '1|0 <hora> <cadencia ms>'
# cada 5 s (ver SeVe y AnotarVisible en nova_ui.cs), mirando su opacidad, si esta visible y
# SHQueryUserNotificationState, que es la senal que da Windows para el modo exclusivo.
#
# ANTE LA DUDA, SE VE, igual que antes: sin fichero, vacio, ilegible o viejo se supone visible.
# Dar por ciega una capsula que si se ve haria hablar a Nova encima del juego, que es peor que el
# fallo que esto arregla. Y 'viejo' no es un numero a mano: es tres veces la cadencia que la
# propia capsula acaba de declarar en el fichero.
function Get-UiVisible {
    # devuelve @{ ve = $true/$false; hace = ms desde que lo escribio; cada = su cadencia; viejo = bool }
    # o $null si no hay nada que leer
    try {
        $ruta = Join-Path $TmpDir 'ui-visible.txt'
        if (-not (Test-Path -LiteralPath $ruta)) { return $null }
        $linea = ''
        try { $linea = ([System.IO.File]::ReadAllText($ruta)).Trim() } catch { return $null }
        if (-not $linea) { return $null }
        $m = [regex]::Match($linea, '^([01])\s+(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})\s+(\d+)$')
        if (-not $m.Success) { return $null }
        $cuando = [datetime]::MinValue
        if (-not [datetime]::TryParseExact($m.Groups[2].Value, 'yyyy-MM-dd HH:mm:ss', [System.Globalization.CultureInfo]::InvariantCulture, [System.Globalization.DateTimeStyles]::None, [ref]$cuando)) { return $null }
        $hace = ((Get-Date) - $cuando).TotalMilliseconds
        $cada = [double]$m.Groups[3].Value
        # la primera linea de cada arranque lleva cada=0 (no hay anterior): entonces vale la
        # cadencia declarada del reloj de la capsula, 5 s.
        if ($cada -le 0) { $cada = 5000 }
        return @{ ve = ($m.Groups[1].Value -eq '1'); hace = $hace; cada = $cada; viejo = ($hace -gt (3 * $cada)) }
    } catch { return $null }
}

function Test-CapsulaCiega {
    if (-not $script:juegoActivo) { return $false }
    $v = Get-UiVisible
    if (-not $v -or $v.viejo) { return $false }   # ante la duda, se ve
    return (-not $v.ve)
}

function Test-AvisoSinVoz {
    if (Test-EnLlamada) { return $true }
    if (-not $AvisosSinVoz) { return $false }
    # te callaste tu: no te hablo yo
    if ($script:sordinaHasta -gt $sw.ElapsedMilliseconds) { return $true }
    # con un juego delante, hablarte encima te saca de la partida
    if ($AvisosSinVozEnJuego -and $script:juegoActivo) { return $true }
    # y el modo silencio es exactamente esto
    if ($script:uiPerfil -eq 'silencio') { return $true }
    return $false
}

# SI NO SE LA VE, QUE AL MENOS SE NOTE (25/09, idea 1). Con un juego en pantalla completa
# exclusiva la capsula no se pinta: un aviso que se calla por respeto a la partida y ademas no
# se ve no ha llegado a ninguna parte, y eso es la regla 2 rota. Se vibra, que no interrumpe
# la partida como si lo haria hablar encima.
#
# Y LA PUERTA NO SE ABRIA NUNCA (27/09, idea 77). Esto solo vibraba con $script:capsulaCiega, que
# hasta hoy se decidia comparando resoluciones: cero lineas 'CAPSULA CIEGA' en los dos registros
# (16 dias) con 4.038 segundos de nightreign en un solo dia, porque el juego corre a la resolucion
# nativa. Resultado medido: 5 avisos 'SIN VOZ' y CERO vibrados, con el canal disponible las 130
# veces que arranco ('mando: vibracion disponible'). La idea 67 arreglo la deteccion -ahora lo dice
# la propia capsula- y aqui se abre la puerta que falta: TAMBIEN se vibra con un juego delante,
# aunque la capsula se vea, porque con un juego el punto queda al 42 % de tamano y braya ya dijo el
# 24/09 que no lo veia.
#
# Y SE MIDE SI EL ZUMBIDO SIRVE, como se mide todo lo demas: si tras vibrar hay gatillo, panel o
# llamada por su nombre en los 30 s siguientes, ese aviso sirvio. La clase de aviso que no mueve
# nada cinco veces seguidas deja de vibrar sola.
$VibrarVentanaMs = 30000        # ventana para ver si el zumbido movio algo
$VibrarSeguidosMax = 5          # cinco zumbidos sin reaccion y esa clase deja de vibrar
$VibrarSeparacionMs = 60000     # nunca dos zumbidos en menos de un minuto
$script:vibroEn = -100000       # cuando se vibro por ultima vez
$script:vibroClave = ''         # por que aviso (para apuntar si sirvio)
$script:vibroVence = 0          # hasta cuando se mira la reaccion

function Get-VibradoSeguidosSinNada([string]$clave) {
    # cuantos zumbidos seguidos de esta clase no movieron nada, de las estadisticas de siempre
    if (-not $clave) { return 0 }
    try {
        $s = Get-Estadisticas
        $si = 0; $no = 0
        foreach ($d in @($s.dias.Keys)) {
            if ($s.dias[$d].ContainsKey("vibro-sirvio:$clave")) { $si += [int]$s.dias[$d]["vibro-sirvio:$clave"] }
            if ($s.dias[$d].ContainsKey("vibro-nada:$clave")) { $no += [int]$s.dias[$d]["vibro-nada:$clave"] }
        }
        if ($si -gt 0) { return 0 }    # si alguna vez sirvio, no se corta
        return $no
    } catch { return 0 }
}

function Send-AvisoVibrado([string]$clave = '') {
    # LAS DOS RAZONES PARA VIBRAR: que no se vea la capsula, o que haya un juego delante (donde el
    # punto es diminuto). Sin ninguna de las dos, el aviso se ve y vibrar solo molesta.
    if (-not $script:capsulaCiega -and -not $script:juegoActivo) { return $false }
    $ahoraV = $sw.ElapsedMilliseconds
    # ni dos zumbidos pegados, ni uno encima de otro que aun suena
    if (($ahoraV - $script:vibroEn) -lt $VibrarSeparacionMs) { return $false }
    # LA CLASE QUE NUNCA MUEVE NADA SE CORTA SOLA (la regla de la casa: lo que no sirve, fuera)
    if ($clave -and (Get-VibradoSeguidosSinNada $clave) -ge $VibrarSeguidosMax) {
        Log ("VIBRAR: '" + $clave + "' llevaba " + $VibrarSeguidosMax + " zumbidos sin que movieras nada; dejo de vibrar por eso")
        return $false
    }
    try {
        Start-Vibracion @(90, 60, 90) 16000
        $script:vibroEn = $ahoraV
        $script:vibroClave = [string]$clave
        $script:vibroVence = $ahoraV + $VibrarVentanaMs
        return $true
    } catch { return $false }
}

# ¿Movio algo el zumbido? Lo llama el bucle cuando ve gatillo, panel o llamada por el nombre, y
# tambien cuando se pasa la ventana sin nada. Aqui no se decide nada: solo se apunta.
function Set-VibradoReaccion([bool]$reacciono) {
    if (-not $script:vibroVence) { return $false }
    $cl = $script:vibroClave
    $script:vibroVence = 0
    $script:vibroClave = ''
    if (-not $cl) { return $false }
    try {
        Add-Estadistica $(if ($reacciono) { "vibro-sirvio:$cl" } else { "vibro-nada:$cl" }) $cl
        if (-not $reacciono) { Log ("VIBRAR: el zumbido de '" + $cl + "' no movio nada en " + [int]($VibrarVentanaMs / 1000) + " s") }
    } catch {}
    return $true
}

# LOS ERRORES QUE NOVA SE TRAGA, GRATIS (27/09, idea 80)
#
# EL DATO: 470 de los 897 catch de este fichero estan COMPLETAMENTE VACIOS -el 52,4 %-: cuando algo
# revienta, se lo traga y sigue, y no habia ni un dato de cuales disparan de verdad. Solo 171 catch
# escriben algo en el registro.
#
# Y NO HACE FALTA TOCAR NINGUNO para enterarse: PowerShell mete TODA excepcion capturada en la
# variable automatica $Error, con su numero de linea. No aparecia ni una vez en las 31.000 lineas
# del script (los aciertos del grep eran todos $ErrorActionPreference). Aqui se lee lo nuevo una vez
# por minuto, se agrupa por linea y se cuenta como 'pete:<linea>'.
#
# EL TOPE DE $Error SON 256 ($MaximumErrorCount), asi que la resta con lo ya visto no vale cuando se
# llena: en ese caso se leen los 256 y se dice que hay mas.
$PetesPorVez = 60               # como mucho se leen 60 por pasada: esto corre en el bucle
$script:erroresVistos = 0
$script:petePeor = $null        # @{ linea; veces; que } para el parte
$script:peteTabla = @{}         # linea -> veces en esta sesion

# APUNTARLO NO SERVIA DE NADA: HAY QUE DECIRLO (1/10/2026, idea 1 de las 20 nuevas).
#
# Esto de arriba lleva desde el 27/09 contando los errores que se tragan los catch vacios, CON SU
# NUMERO DE LINEA, y funcionaba perfectamente. El 1/10, mirando otra cosa, aparecio esto en
# estadisticas.json:
#
#     pete:979   -> 987 veces
#     pete:1002  -> 100 veces
#
# Y las dos eran EL MISMO FALLO: en el commit 5e63f34 el File::Replace de Write-Atomico estaba en
# la linea 979 y en 15db768 en la 1002. O sea MIL OCHENTA Y SIETE errores tragados, todos iguales,
# apuntados con nombre y numero durante cuatro dias, y nadie los leyo nunca. El fallo era gordo
# -la escritura "atomica" no era atomica, ver Write-Atomico- y el dato estaba ahi desde el principio.
#
# APUNTAR ALGO QUE NADIE LEE CUESTA LO MISMO QUE NO APUNTARLO, y encima da la sensacion contraria.
# Asi que ahora se dice. Y se dice del ACUMULADO DE TODOS LOS DIAS, no del de esta sesion: lo que
# convierte un pete en noticia es que lleve 987 veces, no que haya salido 3 veces hoy.
#
# EL LISTON ES ALTO A PROPOSITO: un catch vacio que salta veinte veces puede ser un fichero que
# todavia no existe en el arranque. Doscientas veces ya no es eso, es algo que lleva roto dias.
$PeteAvisaDesde = [int](Get-Cfg 'registro' 'peteAvisaDesde' 200)
$script:peteDicho = ''          # 'linea:veces' del ultimo avisado: no se repite la misma noticia

# LO QUE LLEVA ROTO MAS TIEMPO, sumando TODOS los dias del fichero. Devuelve @{ linea; veces; dias }
# o $null. Se usa para la frase y para el aviso, asi que la cuenta vive en UN solo sitio.
function Get-PeorPeteHistorico {
    try {
        $s = Get-Estadisticas
        if (-not $s -or -not $s.dias) { return $null }
        $porLinea = @{}
        $diasDe = @{}
        foreach ($d in @($s.dias.Keys)) {
            foreach ($k in @($s.dias[$d].Keys)) {
                if (-not ([string]$k).StartsWith('pete:')) { continue }
                $ln = ([string]$k).Substring(5)
                if (-not $porLinea.ContainsKey($ln)) { $porLinea[$ln] = 0; $diasDe[$ln] = 0 }
                $porLinea[$ln] += [int]$s.dias[$d][$k]
                $diasDe[$ln]++
            }
        }
        if ($porLinea.Count -eq 0) { return $null }
        # EL MAXIMO A MANO Y NO CON Sort-Object: son cuatro claves y esto lo llama el bucle.
        $mejor = ''; $max = -1
        foreach ($ln in @($porLinea.Keys)) {
            if ([int]$porLinea[$ln] -gt $max) { $max = [int]$porLinea[$ln]; $mejor = [string]$ln }
        }
        if (-not $mejor) { return $null }
        return @{ linea = $mejor; veces = $max; dias = [int]$diasDe[$mejor] }
    } catch { return $null }
}

# LA FRASE, para cuando braya pregunta "que se te esta rompiendo". Dice la linea A PROPOSITO:
# braya lee el codigo conmigo, y "la linea 979" es lo unico que convierte la queja en algo que se
# puede arreglar. Sin el numero seria "tengo un error", que no sirve para nada.
function Get-FrasePetes {
    $h = Get-PeorPeteHistorico
    if (-not $h) { return 'Por dentro no se me ha roto nada que yo sepa.' }
    if ([int]$h.veces -lt 10) { return 'Por dentro voy bien: lo poco que falla no se repite.' }
    $t = 'Llevo ' + [string]$h.veces + ' veces el mismo error tragado, en la linea ' + [string]$h.linea
    if ([int]$h.dias -gt 1) { $t += ', repartidas en ' + [string]$h.dias + ' dias' }
    $t += '.'
    # Y SI ADEMAS ESTA PASANDO AHORA, se dice: una cosa es un fallo viejo y otra uno vivo.
    $ahora = Get-PeorPete
    if ($ahora -and [int]$ahora.veces -ge 2) {
        $t += ' Y en esta sesion va por ' + [string]$ahora.veces + ': ' + [string]$ahora.que
    }
    return $t
}

function Watch-ErroresTragados {
    # devuelve cuantos errores nuevos ha visto. NO usa Log para cada uno: serian cientos de lineas.
    try {
        $n = @($Error).Count
        if ($n -le 0) { $script:erroresVistos = 0; return 0 }
        $nuevos = $n - $script:erroresVistos
        if ($nuevos -le 0) {
            # o se limpio la lista, o no hay nada nuevo. Si esta topada, siempre hay 'nuevos'
            # aunque el Count no se mueva, asi que se leen los primeros de todas formas.
            if ($n -lt 256) { $script:erroresVistos = $n; return 0 }
            $nuevos = $PetesPorVez
        }
        if ($nuevos -gt $PetesPorVez) { $nuevos = $PetesPorVez }
        $script:erroresVistos = $n
        for ($i = 0; $i -lt $nuevos; $i++) {
            $e = $Error[$i]
            if ($null -eq $e) { continue }
            $linea = 0
            $que = ''
            try { $linea = [int]$e.InvocationInfo.ScriptLineNumber } catch {}
            try { $que = [string]$e.Exception.Message } catch {}
            if ($linea -le 0) { continue }
            if (-not $script:peteTabla.ContainsKey($linea)) { $script:peteTabla[$linea] = 0 }
            $script:peteTabla[$linea]++
            if ($null -eq $script:petePeor -or $script:peteTabla[$linea] -gt [int]$script:petePeor.veces) {
                $script:petePeor = @{ linea = $linea; veces = $script:peteTabla[$linea]; que = $que.Substring(0, [Math]::Min(120, $que.Length)) }
            }
        }
        return $nuevos
    } catch { return 0 }
}

# Lo que mas ha petado en esta sesion, para el parte. $null si nada ha petado.
function Get-PeorPete {
    if ($null -eq $script:petePeor) { return $null }
    if ([int]$script:petePeor.veces -lt 2) { return $null }   # una vez no es noticia
    return $script:petePeor
}
# UN SOLO ESTADO DE RED, EN VEZ DE DIECISEIS PLAZOS SUELTOS (27/09, idea 84)
#
# EL PROBLEMA: cada pieza descubre por su cuenta que no hay red y paga su propio plazo. En este
# fichero hay siete: la tienda de Steam 3 s, YouTube 6 s, ip-api 4 s, open-meteo 4 s, los amigos
# 10 s, el correo 25 s y el correo de la manana 30 s. En el worker de la charla hay nueve mas. Y un
# grep de Test-Connection, NetworkAvailability, Test-Red, hayRed y sinRed sobre los cuatro fuentes
# da CERO: no existia ninguna funcion que supiera si hay red.
#
# LO QUE HACE ESTO: un solo sitio donde se apunta cuando contesto algo de fuera por ultima vez y
# cuantos fallos seguidos lleva. Las llamadas DE FONDO preguntan y se saltan si esta caido; lo que
# pide braya en voz alta NO se bloquea nunca, solo se le acorta el plazo.
#
# LA GUARDA QUE IMPORTA: hace falta que fallen DOS SERVICIOS DISTINTOS seguidos para darlo por
# caido. Con uno solo, la tienda de Steam en mantenimiento apagaria el clima, el correo y los
# amigos, que es peor que el problema. Y cualquier exito lo borra al instante.
$RedJson = Join-Path $TmpDir 'red.json'          # una linea; el worker de la charla lo lee tambien
$RedFallosParaCaida = 2                          # dos servicios DISTINTOS
$RedCaidaViejaMs = 300000                        # a los 5 min sin noticias, se vuelve a intentar
$script:redUltimoOk = 0                          # ms del bucle del ultimo exito
$script:redFallosSeguidos = 0
$script:redQuienFallo = @()                      # los servicios distintos que llevan fallando
$script:redCaidaDesde = 0
# ¿SE LE DIJO QUE NO HABIA RED? (27/09, idea 92). El aviso de que ya volvio solo sale si el de ida
# llego a decirse de verdad: si braya no oyo que no habia internet, contarle que "ya volvio" es
# hablarle de algo que nunca le contaron.
$script:redAvisada = $false

function Set-RedOk([string]$quien) {
    # CUALQUIER exito borra la caida al instante: si algo de fuera contesta, hay red y punto.
    $script:redUltimoOk = $sw.ElapsedMilliseconds
    if ($script:redFallosSeguidos -gt 0 -or $script:redCaidaDesde -gt 0) {
        Log ('RED: ' + $quien + ' contesta; vuelvo a contar con la red')
        # Y SI EL DE IDA SE DIJO, ESTE TAMBIEN (idea 92). Corto, que lo unico que aporta es que
        # braya sepa que ya puede volver a pedir lo que la red necesitaba.
        if ($script:redAvisada) {
            $script:redAvisada = $false
            [void](Send-AvisoEntorno 'red-vuelve' 'Ya hay internet otra vez.' 'medio' 60)
        }
    }
    $script:redFallosSeguidos = 0
    $script:redQuienFallo = @()
    $script:redCaidaDesde = 0
    try { Write-Atomico $RedJson (ConvertTo-Json @{ ok = (Get-Date).ToString('s'); caida = 0 } -Compress) } catch {}
}

function Set-RedFallo([string]$quien) {
    $script:redFallosSeguidos++
    if ($quien -and $script:redQuienFallo -notcontains $quien) { $script:redQuienFallo += $quien }
    # DOS DISTINTOS, no dos veces el mismo: ver LA GUARDA QUE IMPORTA
    if (@($script:redQuienFallo).Count -ge $RedFallosParaCaida -and $script:redCaidaDesde -le 0) {
        $script:redCaidaDesde = $sw.ElapsedMilliseconds
        Log ('RED: doy la red por caida (' + (@($script:redQuienFallo) -join ', ') + ' no contestan); las cosas de fondo se esperan')
        try { Write-Atomico $RedJson (ConvertTo-Json @{ ok = ''; caida = 1; quien = (@($script:redQuienFallo) -join ',') } -Compress) } catch {}
        # Y SE LO DICE, UNA VEZ (27/09, idea 92 de las 121). Hasta hoy Nova se quedaba sin clima,
        # sin resumen del dia y sin voz en linea, contestaba a medias y no explicaba por que: un
        # grep de 'sin-red' en las 32.900 lineas del fichero daba CERO.
        #
        # ES UN AVISO, NO UN MODO: caduca solo, y toda la maquinaria de frenos ya existe. Send-
        # AvisoEntorno se calla entero con un juego delante, tiene el tope por hora, el "no
        # repetir lo mismo" y la espera aprendida. Aqui no se anade ni un freno nuevo.
        #
        # Y NO PUEDE SALTAR POR UN SERVICIO LOCAL CAIDO, que es lo que de verdad pasa en el
        # registro: las 756 lineas 'no pude resumir' del 26/09 son WinError 10061 -conexion
        # denegada- contra Ollama en localhost, una por minuto durante todo el dia. Eso no es
        # falta de red. Set-RedFallo solo lo llaman ip-api y el clima, que si salen a internet,
        # y ademas hacen falta DOS servicios distintos.
        $script:redAvisada = [bool](Send-AvisoEntorno 'sin-red' 'Parece que no hay internet. Lo que necesite la red va a esperar.' 'medio' 60)
    }
}

# ¿Merece la pena intentar algo DE FONDO ahora? Lo que pide braya no pregunta esto nunca.
function Test-RedParaFondo {
    if ($script:redCaidaDesde -le 0) { return $true }
    # A LOS CINCO MINUTOS SE VUELVE A PROBAR: un modo sin salida no puede existir (regla 2). Se
    # deja caducar la caida y que el siguiente intento decida, en vez de quedarse esperando para
    # siempre a que alguien traiga un exito que nadie va a pedir.
    if (($sw.ElapsedMilliseconds - $script:redCaidaDesde) -ge $RedCaidaViejaMs) {
        $script:redCaidaDesde = 0
        $script:redQuienFallo = @()
        $script:redFallosSeguidos = 0
        Log 'RED: han pasado cinco minutos de la caida; vuelvo a probar'
        return $true
    }
    return $false
}

# El plazo que le toca a una llamada: el escrito si todo va bien, y la mitad si la red esta
# sospechosa -uno de los dos fallos ya cayo-, para no regalar segundos cuando ya se sabe.
function Get-PlazoRed([int]$escrito) {
    if ($escrito -le 0) { return 1 }
    if ($script:redCaidaDesde -gt 0 -or $script:redFallosSeguidos -gt 0) {
        return [Math]::Max(1, [int]($escrito / 2))
    }
    return $escrito
}
# Un aviso, por la puerta que toque. $tipo da el color del pulso: bateria,
# tiempo, descarga, recordatorio.
function Send-Aviso([string]$texto, [string]$tipo = '') {
    # MIENTRAS DICTAS, ESPERA (auditoria del 13/09): hablar encima de un dictado
    # pone la pausa y el worker tira tu audio. Se guarda y suena al terminar.
    if ($script:armed) {
        [void]$script:avisosAplazados.Add(@{ texto = $texto; tipo = $tipo })
        Log "aviso aplazado hasta que termines de dictar: $texto"
        return
    }
    Show-Popup $texto
    if (Test-AvisoSinVoz) {
        Send-UIEvento ("pulso:" + $tipo)
        # Y SI LA CAPSULA NO SE VE, QUE AL MENOS SE NOTE (25/09, idea 1): con el juego en
        # pantalla completa exclusiva ese pulso no lo pinta nadie. Vibrar no saca a braya de la
        # partida, que es lo que se evitaba callandose.
        # la clase de aviso viaja al vibrado para poder medir por clase cual sirve (idea 77)
        $vib = Send-AvisoVibrado $(if ($tipo) { [string]$tipo } else { 'aviso' })
        $porQueVib = if ($script:capsulaCiega) { 'no se ve la capsula' } else { 'hay un juego delante' }
        Log ("aviso SIN VOZ ($tipo)" + $(if ($vib) { ', vibrado: ' + $porQueVib }) + ": $texto")
    } else {
        Say $texto
        # una descarga terminada tiene su propio gesto: el salto con chispas (13/09)
        Send-UIEvento $(if ($tipo -eq 'descarga') { 'gesto:descargado' } else { 'aviso' })
    }
}

function Initialize-UI {
    if (-not $UiNuevaOn) { Log "interfaz nueva desactivada por configuracion"; return }
    $exe = Join-Path $LogDir "nova_ui.exe"
    if (-not (Test-Path -LiteralPath $exe)) { Log "WARN: falta nova_ui.exe (compilar con tools\compilar-ui.ps1); sigue la barra antigua"; Add-FalloArranque 'me falta la capsula'; $script:UiNuevaOn = $false; return }
    try {
        # arrancar siempre en reposo: un JSON viejo de otra sesion dejaria la
        # capsula abierta con un texto rancio
        $script:uiUltimo = ''
        Set-UI 'reposo'
        # se le pasa nuestro PID: si este proceso muere, la capsula se cierra sola
        $script:uiProc = Start-Process -FilePath $exe -ArgumentList @((ConvertTo-CmdArg $RutaUiEstado), "$PID") `
            -WorkingDirectory $LogDir -PassThru
        $null = $script:uiProc.Handle
        try { $script:uiProc.PriorityClass = [System.Diagnostics.ProcessPriorityClass]::BelowNormal } catch {}
        Log "interfaz ACTIVA (PID=$($script:uiProc.Id))"
    } catch {
        Log ("WARN: la interfaz no arranco: " + $_.Exception.Message)
        $script:uiProc = $null
    }
}

# Win + Alt + <tecla>: atajos de la barra de juego (grabar, captura)
function Send-WinAlt([int]$vk) {
    [AX]::keybd_event([byte]$VK_LWIN, 0, 0, [UIntPtr]::Zero)
    [AX]::keybd_event([byte]$VK_MENU, 0, 0, [UIntPtr]::Zero)
    Start-Sleep -Milliseconds 60
    [AX]::keybd_event([byte]$vk, 0, 0, [UIntPtr]::Zero)
    Start-Sleep -Milliseconds 40
    [AX]::keybd_event([byte]$vk, 0, $KEYUP, [UIntPtr]::Zero)
    Start-Sleep -Milliseconds 60
    [AX]::keybd_event([byte]$VK_MENU, 0, $KEYUP, [UIntPtr]::Zero)
    [AX]::keybd_event([byte]$VK_LWIN, 0, $KEYUP, [UIntPtr]::Zero)
}

# --- QUE ESTA EN PRIMER PLANO ---
# Saber a que juegas desbloquea frases naturales ("cuanto llevo jugando",
# "busca una guia de esto") sin tener que nombrarlo cada vez.
$script:juegoActivo = $null
# Si el juego esta en pantalla completa exclusiva, la capsula no se pinta (ver LA CAPSULA
# CIEGA). Se recalcula junto al juego, no en cada aviso: la consulta cuesta milisegundos.
$script:capsulaCiega = $false
$script:juegoDesde = 0
$script:juegoPid = 0             # PID del proceso que tiene la ventana del juego (C4, 19/09)
$script:juegoPidCandidato = 0
# La ultima entrada a cada juego: con que proceso y cuando. Sirve para no decir "Modo juego"
# treinta veces por los alt-tabs (26/09, idea 4). Ver Enter-Juego.
$script:juegoEntradas = @{}
# El respaldo de reloj para cuando no hay PID. Es la MISMA hora que usa Show-RecuerdoJuego
# (8920) desde siempre, a proposito: dos guardas hermanas con dos numeros distintos son dos
# numeros que mantener. Medido el 26/09: de las 45 vueltas a un juego ya visto, 30 caen por
# debajo de esta hora -los alt-tabs- y las 15 que la pasan son partidas nuevas de verdad.
$JuegoVueltaMs = 3600000
# LA DECISION, EN SU PROPIA FUNCION Y CON TODO POR PARAMETRO, para que el banco la corra DE
# VERDAD en vez de reimplementarla al lado: un banco que prueba su propia copia de la logica
# se queda verde el dia que el codigo cambia y la copia no. Ver Enter-Juego.
# Devuelve $true cuando NO hay que anunciar nada porque no has salido del juego.
function Test-VuelveAlMismoJuego([string]$nombre, [int]$proc, [double]$ahora) {
    $v = $false
    $ant = $null
    if ($script:juegoEntradas.ContainsKey($nombre)) { $ant = $script:juegoEntradas[$nombre] }
    if ($ant) {
        # EL PROCESO MANDA: si es el mismo, no has salido, pasen veinte segundos o tres horas.
        if ($proc -gt 0 -and [int]$ant.proc -eq $proc) { $v = $true }
        # y el reloj solo cuando no hay proceso con el que comparar
        elseif ([int]$ant.proc -le 0 -and ($ahora - [double]$ant.cuando) -lt $JuegoVueltaMs) { $v = $true }
    }
    $script:juegoEntradas[$nombre] = @{ proc = $proc; cuando = $ahora }
    return $v
}
# EL JUEGO QUE SE ABRE Y SE MUERE A LOS DIEZ SEGUNDOS (26/09, idea 47 de las 121). Cuenta las
# muertes CONSECUTIVAS del mismo juego; la racha se rompe si pasa mas de $JuegoVueltaMs desde la
# ultima (la misma hora que Test-VuelveAlMismoJuego usa para "es la misma sesion"). MEDIDO: el
# 25/09 NIGHTREIGN murio 6 veces en una hora; con esto, al 3er intento Nova ofrece 'cierra steam'.
# Vive en RAM (regla 5): un reinicio empieza de cero, que es lo correcto.
function Test-MuereAlArrancar([string]$nombre, [double]$ahora) {
    $ant = $null
    if ($script:juegoMuertesSeguidas.ContainsKey($nombre)) { $ant = $script:juegoMuertesSeguidas[$nombre] }
    $n = 1
    if ($ant -and ($ahora - [double]$ant.cuando) -lt $JuegoVueltaMs) { $n = ([int]$ant.n) + 1 }
    $script:juegoMuertesSeguidas[$nombre] = @{ n = $n; cuando = $ahora }
    return $n
}
function Clear-MuereAlArrancar([string]$nombre) {
    # una partida que pasa del minimo limpia el contador de ESE juego: no era una racha de muerte
    if ($script:juegoMuertesSeguidas.ContainsKey($nombre)) { [void]$script:juegoMuertesSeguidas.Remove($nombre) }
}
$script:juegoSalida = $null      # salida EN DUDA: @{nombre; exe; proc; desdeMs} (C4, 19/09)
$script:soloBotonPuesto = $false   # idea 108: para no repetir la linea del registro
$script:juegoSesionMin = 0       # minutos de primer plano de la partida de ahora (C4, 19/09)
$script:juegoSesionSeg = 0       # segundos de la sentada, solo para la frase (idea 47)
$script:juegoMuertesSeguidas = @{}   # nombre -> @{ n; cuando }; muertes seguidas al arrancar (idea 47), en RAM

# EL PID DE LA VENTANA, NO SU MainWindowHandle (24/09, idea 8 de la tanda nueva).
#
# Esto recorria los ~200 procesos buscando uno cuyo MainWindowHandle fuera EXACTAMENTE la
# ventana de delante. Con un juego en pantalla completa exclusiva eso no casa, y devolvia
# $null: Nova se quedaba ciega con el juego delante.
#
# ESTA MEDIDO Y CON SUS PALABRAS. El 20/09 el registro de Steam dice que ELDEN RING corrio de
# 18:59:53 a 19:07:57; Nova lo vio ONCE SEGUNDOS y a las 19:01:22 contesto "ELDEN RING no esta
# abierto". A las 19:02:27 braya le dijo al microfono -y esta en el registro-: "Elden Ring si
# esta abierto... el juego sigue abierto". Se quedo ciega los 7 min 49 s restantes, unas 47
# vueltas del bucle. Lo mismo el 19/09 (13 s de 272) y el 18/09 (11 s de 185). En total, el
# 5,5 % de lo que jugo a ese juego con Nova viva.
#
# (El otro 90 % de lo que se pierde no es esto: es que Nova no estaba encendida. Eso no se
# arregla aqui, y no se finge que si.)
#
# LA SOLUCION YA ESTABA ESCRITA TREINTA LINEAS MAS ABAJO, en el comentario del 23/09: "se pide
# el handle de delante, su PID, y UN solo Get-Process -Id", con su medicion -de 500 a 740 ms
# recorriendo los 200 procesos, frente a 20 ms-. Mas barato y mas certero, y Get-PidDeVentana
# ya se usa en la primera linea de Get-JuegoEnPrimerPlano.
#
# Y NO LA VUELVE PERMISIVA: esto solo devuelve el PROCESO. Quien decide si eso es un juego es
# Get-JuegoEnPrimerPlano con sus $CARPETAS_JUEGO, $EXES_JUEGO, $CARPETA_NO_JUEGO y el filtro
# de instaladores, y eso no se toca.
function Get-ProcesoEnPrimerPlano {
    try {
        $h = [AX]::GetForegroundWindow()
        if ($h -eq [IntPtr]::Zero) { return $null }
        $pidFg = Get-PidDeVentana $h
        if ($pidFg -gt 0) {
            $pr = Get-Process -Id $pidFg -ErrorAction SilentlyContinue
            if ($pr) { return $pr }
        }
        # DE RESPALDO, lo de siempre: si el PID no se puede resolver o el proceso ya murio
        # entre una linea y otra, se busca por ventana principal como hasta hoy.
        foreach ($p in (Get-Process -ErrorAction SilentlyContinue)) {
            if ($p.MainWindowHandle -eq $h) { return $p }
        }
    } catch {}
    return $null
}

# QUE VENTANA TENGO DELANTE, BARATO (23/09, idea 2). Hace falta para resolver "esto", y el
# coste manda: el comentario de Get-RamResumen, medido el 21/09, dice que leer
# MainWindowTitle de los 200 y pico procesos cuesta de 500 a 740 ms frente a 20 ms. Por eso
# aqui NO se usa Get-ProcesoEnPrimerPlano, que recorre todos: se pide el handle de delante,
# su PID, y UN solo Get-Process -Id.
# No corre en el bucle: solo cuando llega una frase con deictico. Y cachea 800 ms, que es
# menos de lo que tarda braya en decir dos frases seguidas.
$script:ventanaDelante = $null
$script:ventanaDelanteMs = 0
function Get-VentanaDelante {
    if ($script:ventanaDelanteMs -gt 0 -and ($sw.ElapsedMilliseconds - $script:ventanaDelanteMs) -lt 800) {
        return $script:ventanaDelante
    }
    $script:ventanaDelanteMs = $sw.ElapsedMilliseconds
    $script:ventanaDelante = $null
    try {
        $h = [AX]::GetForegroundWindow()
        if ($h -eq [IntPtr]::Zero) { return $null }
        $duenoV = Get-PidDeVentana $h
        if ($duenoV -le 0) { return $null }
        # MI PROPIA VENTANA NO CUENTA, la misma guarda que Get-JuegoEnPrimerPlano: ni esta
        # consola ni la capsula. Con la capsula delante no se sabe que hay detras, y
        # adivinarlo seria inventarse el referente.
        if ($duenoV -eq $PID) { return $null }
        if ($script:uiProc -and -not $script:uiProc.HasExited -and $duenoV -eq $script:uiProc.Id) { return $null }
        $p = Get-Process -Id $duenoV -ErrorAction SilentlyContinue
        if (-not $p) { return $null }
        $nomP = [string]$p.ProcessName
        if ($PROCESOS_INTOCABLES -contains $nomP) { return $null }
        $tit = ''
        try { $tit = [string]$p.MainWindowTitle } catch { $tit = '' }
        $script:ventanaDelante = @{ titulo = $tit; proceso = $nomP; nombre = (Get-NombreDeTitulo $tit $nomP) }
    } catch { $script:ventanaDelante = $null }
    return $script:ventanaDelante
}

# EL NOMBRE QUE SE DICE EN VOZ ALTA, sacado del titulo. Pura: no llama a Windows, asi que una
# prueba puede ejecutarla con titulos de verdad.
# El tope de 40 es el mismo criterio que ya usa el listado de "cierra todo": un titulo largo
# es una frase ("Documento1 - Word - 3 paginas sin guardar"), no un nombre, y decirlo entero
# en mitad de una pregunta no ayuda a nadie. La lista de contenedores es CERRADA: quitar "lo
# que va detras del ultimo guion" se llevaria por delante los nombres con guion.
function Get-NombreDeTitulo([string]$titulo, [string]$proceso) {
    $t = ([string]$titulo).Trim()
    if (-not $t) { return $proceso }
    $t = $t -replace '^\(\d+\)\s*', ''          # el "(3) " de los contadores de mensajes
    foreach ($suf in @(' - google chrome', ' - mozilla firefox', ' - microsoft edge', ' - brave',
                       ' - opera', ' - visual studio code', ' - bloc de notas', ' and 1 more page - personal')) {
        if ($t.ToLowerInvariant().EndsWith($suf)) { $t = $t.Substring(0, $t.Length - $suf.Length).Trim(); break }
    }
    if (-not $t -or $t.Length -gt 40) { return $proceso }
    return $t
}

# Devuelve el juego de Steam que esta en primer plano, o $null.
# DE DONDE SALE ESTA LISTA (21/09): la noche del 20 al 21 braya jugo DOS HORAS a
# Roblox y para Nova no estaba jugando. Aqui solo valia steamapps\\common, asi que
# $script:juegoActivo se quedo en $null las dos horas y con el se quedaron fuera: el
# tiempo de juego, el avatar de la capsula, el freno de los avisos, el limite de
# tiempo, la nota semanal y -lo que mas se noto- el 'braya esta jugando a X' que va
# en el prompt del cerebro y le pide contestar en UNA frase. Sin el, se enrollaba.
# Su Roblox es el de Game Pass: C:\\XboxGames\\Roblox\\Content\\RobloxPlayerBeta.exe.
#
# CADA PATRON EXIGE UNA BARRA DETRAS DEL NOMBRE a proposito: es lo que distingue la
# carpeta de un juego del ejecutable de la tienda. Sin ella, Epic Games\\algo.exe o el
# propio GalaxyClient.exe entrarian como si fueran juegos.
# EL NOMBRE QUE SE DICE EN VOZ ALTA. Las carpetas se llaman como les da la gana:
# '.minecraft' es la de datos y 'Minecraft Launcher' la del lanzador. Lo usan
# Get-JuegoEnPrimerPlano y Get-JuegosXbox, y tiene que ser LA MISMA limpieza en las
# dos: si no, el tiempo de juego se apunta a nombre de una y se lee a nombre de otra.
function Get-NombreJuegoLimpio([string]$n) {
    if (-not $n) { return $n }
    $n = $n.TrimStart('.')
    $n = ($n -replace '\s+(?:Launcher|Game Preview Edition)$', '')
    return $n.Trim()
}

$CARPETAS_JUEGO = @(
    '(?i)steamapps\\common\\([^\\]+)\\'   # Steam
    '(?i)\\XboxGames\\([^\\]+)\\'   # Xbox / Game Pass
    '(?i)\\Epic Games\\([^\\]+)\\'   # Epic
    '(?i)\\GOG Galaxy\\Games\\([^\\]+)\\'   # GOG
    '(?i)\\Ubisoft Game Launcher\\games\\([^\\]+)\\'   # Ubisoft
    '(?i)\\(?:Origin|EA) Games\\([^\\]+)\\'   # EA
    '(?i)\\Riot Games\\([^\\]+)\\'   # Riot
    '(?i)\\itch\\apps\\([^\\]+)\\'   # itch.io
    '(?i)\\(Roblox)\\Versions\\'   # Roblox de la web
    '(?i)\\\.(minecraft)\\'   # Minecraft
)
# lo que vive en esas carpetas y no es un juego
$CARPETA_NO_JUEGO = @('launcher', 'epic games launcher', 'gamesave', 'directxredist',
                      'redistributables', '_commonredist', 'support', 'epic online services')
# SI NO SE PUEDE LEER LA RUTA, POR EL NOMBRE DEL PROCESO. Las apps de la Store corren
# protegidas y $p.Path puede saltar por permisos; antes eso era un 'no hay juego'.
$EXES_JUEGO = @{ 'robloxplayerbeta' = 'Roblox'; 'minecraft' = 'Minecraft'
                 'minecraftlauncher' = 'Minecraft'; 'fortniteclient-win64-shipping' = 'Fortnite' }
function Get-JuegoEnPrimerPlano {
    # MI PROPIA VENTANA DELANTE NO ES SALIR DEL JUEGO (21/09). Esto solo miraba si la
    # ventana de delante era de un juego; si no, devolvia $null y el bucle daba la
    # partida por terminada: Exit-Juego, las reglas de 'juegoCierra', el brillo
    # restaurado, vuelve la palabra de activacion y a cero el tiempo jugado. Y al dictar,
    # la capsula se pone delante un momento.
    # ESTA EN EL LOG DESDE EL 11/09, siempre igual y siempre con un dictado por medio:
    #   15:43:46  dictado: escuchando la orden
    #   15:43:49  JUEGO: brillo restaurado a 100 al salir de Little Nightmares III
    #   15:44:0x  juego en primer plano: Little Nightmares III   (volvia una vuelta despues)
    # Start-Dictado ya lo tenia resuelto para lo suyo, y lo dice: 'NINGUNA ventana del
    # asistente cuenta como tuya: ni la de captura ni la CAPSULA'. Aqui faltaba.
    # Se devuelve el juego que YA habia, no $null: con la capsula delante no se sabe que
    # hay detras, y lo ultimo que se supo sigue siendo lo mas probable.
    try {
        $hFg = [AX]::GetForegroundWindow()
        if ($hFg -ne [IntPtr]::Zero) {
            $duenoFg = Get-PidDeVentana $hFg
            $mio = ($duenoFg -eq $PID)
            if (-not $mio -and $script:uiProc -and -not $script:uiProc.HasExited -and $duenoFg -eq $script:uiProc.Id) { $mio = $true }
            if ($mio) { return $script:juegoActivo }
        }
    } catch {}
    $p = Get-ProcesoEnPrimerPlano
    if (-not $p) { return $null }
    $ruta = ''
    try { $ruta = $p.Path } catch { $ruta = '' }
    $carpeta = ''
    if ($ruta) {
        foreach ($reJ in $CARPETAS_JUEGO) {
            if ($ruta -match $reJ) { $carpeta = $Matches[1]; break }
        }
    }
    if (-not $carpeta) {
        $nomP = ''
        try { $nomP = ([string]$p.Name).ToLowerInvariant() } catch {}
        if ($nomP -and $EXES_JUEGO.ContainsKey($nomP)) { $carpeta = [string]$EXES_JUEGO[$nomP] }
        # Y DESPUES, lo aprendido (26/09, idea 26). Lo escrito a mano manda: si el proceso esta
        # en las dos, gana la lista de arriba. Y lo aprendido pasa por los MISMOS filtros de
        # abajo -carpeta que no es juego, redistribuibles, limpieza del nombre-, no se salta
        # ninguno.
        if (-not $carpeta -and $nomP) {
            $aprE = Get-ExesJuego
            if ($aprE.ContainsKey($nomP)) { $carpeta = [string]$aprE[$nomP].juego }
        }
    }
    if (-not $carpeta) { return $null }
    if ($CARPETA_NO_JUEGO -contains $carpeta.ToLowerInvariant()) { return $null }
    # UN INSTALADOR DENTRO DE LA CARPETA DEL JUEGO NO ES JUGAR. Al instalar,
    # .../Fortnite/Engine/Extras/Redist/_CommonRedist/vcredist.exe pasa por delante
    # un momento y capturaba 'Fortnite': Nova diria que estas jugando mientras
    # esperas la descarga, y con eso se callaria los avisos que si querias.
    if ($ruta -match '(?i)\\(?:_CommonRedist|Redist|DirectX|vcredist|DotNetFX|Installers?)\\') { return $null }
    $carpeta = Get-NombreJuegoLimpio $carpeta
    # el ejecutable se guarda aparte: la capsula saca de el el icono del juego
    $script:juegoExeCandidato = $ruta
    # C4 (19/09): y el PID, para poder preguntar luego si ese proceso sigue vivo sin
    # tener que enumerar todos los procesos de la maquina (4 nucleos)
    $script:juegoPidCandidato = [int]$p.Id
    # PRIMERO POR LA CARPETA EXACTA (idea 38): si el installdir casa, ese es el nombre de verdad,
    # sin pasar por la distancia de Find-Juego (que ademas deja $script:dudosa puesta cada 10 s).
    $jc = Get-JuegoPorCarpeta $carpeta
    if ($jc) { return $jc.nombre }
    # la carpeta de instalacion suele parecerse al titulo (respaldo: ELDEN RING, Little Nightmares
    # y REANIMAL no tienen appmanifest, o sea que no estan en la tabla y salen por aqui)
    $j = Find-Juego $carpeta
    if ($j) { return $j.nombre }
    return $carpeta
}


# EL SITIO NO ES CAPRICHO: esto va DESPUES de Get-JuegoEnPrimerPlano, no antes.
# probar-juego-primer-plano saca $EXES_JUEGO con un regex que llega hasta la primera llave en
# COLUMNA CERO, o sea hasta el final de esa funcion. Metido en medio, el banco se tragaba este
# bloque entero y moria intentando un Join-Path con un $MemoriaDir que alli no existe.
# Y LA TABLA QUE SE APRENDE SOLA (26/09, idea 26 de las 121). La lista de arriba tiene CUATRO
# entradas escritas a mano, y todo juego que no arranque desde una carpeta reconocible y no este
# en esas cuatro es invisible para Nova.
# EL CASO, con numeros: el 25/09 braya jugo 4.038 segundos seguidos a ELDEN RING NIGHTREIGN -una
# hora y siete minutos- y Nova apunto SETENTA Y CINCO. El 1,86 %: se perdio el 98,14 % de la
# partida. Y no es solo la cuenta: en esa hora con el microfono abierto porque "no habia juego"
# hay 45 lineas de llamadas descartadas en el registro.
# COMO SE APRENDE: si un proceso lleva mucho rato delante sin que Nova lo reconozca como juego,
# se le pregunta a Steam. Steam sella LastPlayed en el appmanifest de lo que se acaba de jugar;
# si en esa ventana se movio EXACTAMENTE UN appmanifest, ese es el juego. Si se movieron cero o
# dos, no se aprende nada: adivinar entre dos seria inventarse el dato.
# Comprobado con el caso real: LastPlayed de nightreign cayo a las 23:53:48, dentro de la
# ventana, y ningun otro appmanifest se movio en ella.
$ExesJuegoPath = Join-Path $MemoriaDir 'juegos-exes.json'
# EL TOPE ES EL MISMO QUE EL DEL CUADERNO DE LA ALLY, y por lo mismo. En dos dias de cuaderno han
# salido nueve procesos distintos: cuarenta sobra.
$ExesJuegoMax = 40
# Y LOS DIEZ MINUTOS TAMPOCO SON A OJO. Medido sobre memoria\uso-ally.json: el proceso NO-juego
# con mas tiempo delante en un DIA ENTERO es explorer, 350 s (26/09) y 321 s (25/09); detras van
# EADesktop 30, steamwebhelper 20 y 19, SearchHost 10, Discord 10. Ninguno ha juntado 350 s en
# veinticuatro horas, asi que no puede juntar 600 SEGUIDOS. Y el caso bueno sobra: nightreign
# 4.038 s, Spider-Man 2.351 s. El liston cae en el hueco vacio entre 350 y 2.351.
# LOS 300 s QUE PEDIA LA IDEA NO SE SOSTIENEN: explorer ya pasa de 300 en un dia y quedaria a
# tiro. Por eso 600 y no 300.
$ExesJuegoMinSeg = 600
$script:exesJuego = $null
$script:exeSinJuego = ''
# el exe que quedo sin aclarar, esperando a que Steam selle su LastPlayed al cerrarse (28/09)
$script:exePendiente = $null
$script:exeSinJuegoDesde = 0
function Get-ExesJuego {
    if ($null -ne $script:exesJuego) { return $script:exesJuego }
    $script:exesJuego = @{}
    if (Test-Path -LiteralPath $ExesJuegoPath) {
        try {
            $jE = Get-Content -LiteralPath $ExesJuegoPath -Raw -Encoding UTF8 | ConvertFrom-Json
            foreach ($pe in $jE.PSObject.Properties) {
                $script:exesJuego[$pe.Name] = @{
                    juego = [string]$pe.Value.juego; desde = [string]$pe.Value.desde
                    veces = [int]$pe.Value.veces
                }
            }
        } catch { Save-Corrupto $ExesJuegoPath 'juegos-exes' }
    }
    return $script:exesJuego
}
function Save-ExeJuego([string]$proc, [string]$juego) {
    # LO QUE HAGA OTRO NO SE APRENDE (modo invitado).
    if ($script:invitado) { return $false }
    if (-not $proc -or -not $juego) { return $false }
    $k = $proc.ToLowerInvariant()
    try {
        $tb = Get-ExesJuego
        if ($tb.ContainsKey($k)) { $tb[$k].veces = [int]$tb[$k].veces + 1; $tb[$k].juego = $juego }
        else { $tb[$k] = @{ juego = $juego; desde = (Get-Date).ToString('yyyy-MM-dd'); veces = 1 } }
        # el tope se aplica por las MAS VIEJAS, que es lo que sobra cuando se desinstala algo
        while ($tb.Count -gt $ExesJuegoMax) {
            $vieja = ($tb.GetEnumerator() | Sort-Object { [string]$_.Value.desde } | Select-Object -First 1)
            if (-not $vieja) { break }
            [void]$tb.Remove($vieja.Key)
        }
        $o = [ordered]@{}
        foreach ($kk in ($tb.Keys | Sort-Object)) { $o[$kk] = $tb[$kk] }
        Write-Atomico $ExesJuegoPath (ConvertTo-Json -InputObject $o -Depth 4)
        Log "EXE DE JUEGO: '$k' es $juego"
        return $true
    } catch { Log ('exes de juego: no pude guardarlo: ' + $_.Exception.Message); return $false }
}
function Remove-ExeJuego([string]$proc) {
    if (-not $proc) { return $false }
    $k = $proc.ToLowerInvariant()
    try {
        $tb = Get-ExesJuego
        if (-not $tb.ContainsKey($k)) { return $false }
        [void]$tb.Remove($k)
        $o = [ordered]@{}
        foreach ($kk in ($tb.Keys | Sort-Object)) { $o[$kk] = $tb[$kk] }
        Write-Atomico $ExesJuegoPath (ConvertTo-Json -InputObject $o -Depth 4)
        Log "EXE DE JUEGO: olvido que '$k' era un juego"
        return $true
    } catch { return $false }
}
# Y QUIEN DECIDE: se le pregunta a Steam cual fue el ultimo juego que se toco.
# UN SOLO CANDIDATO O NINGUNO. Steam sella LastPlayed en el appmanifest de lo que se acaba de
# jugar; si en la ventana en que ese proceso estuvo delante se movio EXACTAMENTE UNO, ese es. Si
# se movieron dos, adivinar entre ellos seria inventarse el dato, y lo que se aprende aqui hace
# que Nova cierre el microfono: equivocarse deja a braya sin voz mientras no juega.
# LA HOLGURA NO ES UN NUMERO NUEVO: el +120 s es el MISMO tope que ya usan Add-TiempoJuego y
# Add-UsoAlly para decidir que un hueco entre dos miradas no es tiempo de verdad. El -60 s es
# porque Steam puede sellar al arrancar y no al salir.
function Find-JuegoPorUltimoJugado([datetime]$desde, [datetime]$hasta, $antes) {
    # PURA en lo que importa: recibe la foto del ANTES, asi el banco la prueba sin Steam.
    $ini = $desde.AddSeconds(-60)
    $fin = $hasta.AddSeconds(120)
    $cands = @()
    foreach ($jj in @($script:Juegos)) {
        $lp = 0
        try { $lp = [long]$jj.ultimo } catch { $lp = 0 }
        if ($lp -le 0) { continue }
        $antesLp = 0
        $cl = [string]$jj.nombre
        if ($antes -and $antes.ContainsKey($cl)) { $antesLp = [long]$antes[$cl] }
        # tiene que haber SUBIDO: uno que ya estaba sellado de ayer no dice nada de ahora
        if ($lp -le $antesLp) { continue }
        $cuando = [DateTimeOffset]::FromUnixTimeSeconds($lp).LocalDateTime
        if ($cuando -lt $ini -or $cuando -gt $fin) { continue }
        $cands += $cl
    }
    $cands = @($cands | Select-Object -Unique)
    if ($cands.Count -eq 1) { return [string]$cands[0] }
    return ''
}

# QUE NOVA SE MIDA A SI MISMA CONTRA STEAM, EN FRIO, UNA VEZ AL DIA (27/09, idea 113 de las 121)
#
# EL AGUJERO QUE DEJA EL APRENDIZAJE DE AQUI ARRIBA: ese aprende EN VIVO y necesita que un proceso
# desconocido junte 600 segundos SEGUIDOS delante. Un juego que se alterna con el escritorio, o uno
# que ya se jugo antes de que ese codigo existiera, no lo dispara nunca. Y el dato ya esta en casa:
#
# EL 25/09, MEDIDO EN LOS DOS CUADERNOS DE NOVA:
#   memoria\juegos.json     'ELDEN RING NIGHTREIGN' -> 75 segundos
#   memoria\uso-ally.json   'nightreign'            -> 4.038 segundos con alguien delante
#                            'ELDEN RING NIGHTREIGN' ->    10 segundos
# O sea que Nova SI vio la partida entera: la apunto en el otro cuaderno y con el nombre del
# ejecutable, y nunca cruzo las dos cuentas. La ficha de esta idea creia que el dato se perdia; lo
# que pasa es que esta partido en dos ficheros que no se hablan.
#
# Y STEAM ES EL ARBITRO QUE FALTABA: sella LastPlayed en el appmanifest sin que nadie se lo pida, y
# el de nightreign cayo el 25/09 a las 23:53. Con eso se puede decir que ese 'nightreign' de 4.038
# segundos era ELDEN RING NIGHTREIGN, y aprenderlo en juegos-exes.json, que es el fichero del
# aprendizaje en vivo: esto no estrena cuaderno para nadie, alimenta el que ya hay.
#
# SOLO LA COLUMNA 'con' DEL CUADERNO, Y ESTO ES LO MAS FINO DE TODO: el cuaderno separa los
# segundos con alguien delante de los segundos sin nadie. Medido, el 26/09: explorer con=2.797 y
# sin=64.083. Sumando las dos columnas, el escritorio de Windows gana a cualquier juego por un
# factor de diez y seria el 'candidato' de todos los dias. Jugar es estar delante, asi que solo
# cuenta 'con'.
#
# EL LISTON DE 600 s NO SEPARA NADA EN FRIO, Y HAY QUE DECIRLO: el de arriba son 600 segundos
# SEGUIDOS, y para eso esta medido. En el total de un dia entero los no-juegos llegan mucho mas
# lejos: el 26/09, EmuDeck 1.850 s y msedge 1.260 s con alguien delante. Aqui 600 solo hace de
# suelo de ruido -por debajo de diez minutos nadie es candidato a ser un juego-. Lo que de verdad
# decide es la UNICIDAD, igual que arriba: un solo desconocido y un solo juego de Steam ese dia, o
# no se aprende nada. Comprobado con los dos dias que hay: el 25/09 queda nightreign solo; el
# 26/09 quedan EmuDeck y msedge, o sea dos, y no se aprende nada. Que es lo que se quiere.
#
# LA LISTA DEL SHELL NO ES UN UMBRAL, ES UN HECHO: explorer.exe ES el escritorio de Windows, y los
# demas son las ventanas del propio sistema. No pueden ser un juego por definicion, no por un
# numero que haya que revisar.
#
# Y LA GUARDA DE LA FICHA SALE GRATIS: solo se juzgan los dias que estan en el cuaderno de la Ally,
# y ese cuaderno SOLO se escribe cuando Nova esta viva. Un dia que se jugo con Nova apagada no
# tiene entrada y no se acusa a nadie.
$JuegosCiegosPath = Join-Path $MemoriaDir 'juegos-ciegos.json'
$CiegosMax = 40                  # el mismo tope que juegos-exes.json, y por lo mismo
$CiegoFraccion = 3               # 'menos de un tercio de lo que dice la otra cuenta'
# Los dos casos reales estan en los extremos y no en la frontera: NIGHTREIGN apunto el 1,9 % de lo
# que vio el otro cuaderno (75 de 4.038), y Spider-Man y Black Myth el 100,0 % (5.485 de 5.486 y
# 860 de 860). Con datos asi de partidos, cualquier corte entre el 10 % y el 90 % da el mismo
# resultado: el numero no esta decidiendo nada, y por eso se deja el tercio que pedia la ficha.
$CiegoShell = @('explorer', 'dwm', 'shellexperiencehost', 'searchhost', 'startmenuexperiencehost',
                'applicationframehost', 'pickerhost', 'textinputhost', 'systemsettings',
                'lockapp', 'searchapp', 'widgets', 'sihost', 'taskmgr')
$script:juegosCiegos = $null

function Get-JuegosCiegos {
    if ($null -ne $script:juegosCiegos) { return $script:juegosCiegos }
    $script:juegosCiegos = @{}
    if (Test-Path -LiteralPath $JuegosCiegosPath) {
        try {
            $jC = Get-Content -LiteralPath $JuegosCiegosPath -Raw -Encoding UTF8 | ConvertFrom-Json
            foreach ($pc in $jC.PSObject.Properties) {
                $script:juegosCiegos[$pc.Name] = @{
                    dia = [string]$pc.Value.dia; visto = [int]$pc.Value.visto
                    podria = [int]$pc.Value.podria; proceso = [string]$pc.Value.proceso
                }
            }
        } catch { Save-Corrupto $JuegosCiegosPath 'juegos-ciegos' }
    }
    return $script:juegosCiegos
}

function Save-JuegoCiego([string]$juego, [string]$dia, [int]$visto, [int]$podria, [string]$proceso) {
    if ($script:invitado) { return $false }     # lo que haga otro no es su cuenta
    if (-not $juego -or -not $dia) { return $false }
    try {
        $tb = Get-JuegosCiegos
        $tb[$juego] = @{ dia = $dia; visto = $visto; podria = $podria; proceso = $proceso }
        while ($tb.Count -gt $CiegosMax) {
            $vieja = ($tb.GetEnumerator() | Sort-Object { [string]$_.Value.dia } | Select-Object -First 1)
            if (-not $vieja) { break }
            [void]$tb.Remove($vieja.Key)
        }
        $o = [ordered]@{}
        foreach ($kk in ($tb.Keys | Sort-Object)) { $o[$kk] = $tb[$kk] }
        Write-Atomico $JuegosCiegosPath (ConvertTo-Json -InputObject $o -Depth 4)
        return $true
    } catch { Log ('juegos ciegos: no pude guardarlo: ' + $_.Exception.Message); return $false }
}

# PURA, y por eso se puede probar con los dos dias de verdad que hay en disco.
#   $cuaderno : clave -> @{ con; sin }, tal cual lo guarda uso-ally.json
#   $conocidos: los nombres de juego que Nova sabe reconocer
#   $deSteam  : los juegos que Steam dice que se jugaron ESE dia
#   $apuntado : juego -> segundos que juegos.json tiene de ese dia
# Devuelve @{ candidatos; mayor; aprende; ciegos }, y 'aprende' solo lleva nombre cuando no hay
# ninguna duda posible.
function Find-CiegosDeUnDia($cuaderno, $conocidos, $deSteam, $apuntado) {
    $res = @{ candidatos = @(); mayor = @{ proc = ''; seg = 0 }; aprende = ''; ciegos = @() }
    if (-not $cuaderno) { return $res }
    $conoce = @{}
    foreach ($c in @($conocidos)) { if ($c) { $conoce[([string]$c).ToLowerInvariant()] = $true } }
    $cands = @()
    $mejorJuego = 0
    foreach ($k in @($cuaderno.Keys)) {
        $seg = 0
        # SOLO 'con': ver arriba por que. El escritorio tiene 64.083 en 'sin' y 2.797 en 'con'.
        try { $seg = [int]$cuaderno[$k].con } catch { $seg = 0 }
        if ($seg -le 0) { continue }
        $kb = ([string]$k).ToLowerInvariant()
        if ($conoce.ContainsKey($kb)) { if ($seg -gt $mejorJuego) { $mejorJuego = $seg }; continue }
        if ($CiegoShell -contains $kb) { continue }        # el escritorio no es un juego
        if ($seg -lt $ExesJuegoMinSeg) { continue }        # suelo de ruido, no frontera
        $cands += @(@{ proc = [string]$k; seg = $seg })
    }
    $cands = @($cands | Sort-Object { -[int]$_.seg })
    $res.candidatos = $cands
    if ($cands.Count -gt 0) { $res.mayor = $cands[0] }
    # QUIEN ES: un solo desconocido y un solo juego de Steam ese dia. Con dos de cualquiera,
    # adivinar seria inventarse el dato, y esto acaba cerrando el microfono.
    $st = @(@($deSteam) | Where-Object { $_ })
    if ($cands.Count -eq 1 -and $st.Count -eq 1) {
        # Y TIENE QUE GANARLE AL JUEGO MEJOR VISTO DE ESE DIA: si Nova reconocio algo durante mas
        # tiempo que el desconocido, el desconocido era lo de menos y no se le atribuye la partida.
        if ([int]$cands[0].seg -gt $mejorJuego) { $res.aprende = [string]$st[0] }
    }
    # Y LOS CIEGOS: un juego que Steam dice que se jugo y del que Nova apunto menos de un tercio
    # de lo que el mayor desconocido estuvo delante.
    if ([int]$res.mayor.seg -gt 0) {
        $techo = [int][Math]::Floor([double]$res.mayor.seg / [double]$CiegoFraccion)
        foreach ($g in $st) {
            $v = 0
            if ($apuntado -and $apuntado.ContainsKey([string]$g)) { $v = [int]$apuntado[[string]$g] }
            if ($v -lt $techo) {
                $res.ciegos += @(@{ juego = [string]$g; visto = $v; podria = [int]$res.mayor.seg
                                    proceso = [string]$res.mayor.proc })
            }
        }
    }
    return $res
}

# Los juegos que Steam dice que se jugaron un dia, leyendo el LastPlayed que ya esta en memoria.
function Get-JuegosDeSteamDelDia([string]$dia) {
    $l = New-Object System.Collections.ArrayList
    foreach ($jj in @($script:Juegos)) {
        $lp = 0
        try { $lp = [long]$jj.ultimo } catch { $lp = 0 }
        if ($lp -le 0) { continue }
        $cuando = ''
        try { $cuando = [DateTimeOffset]::FromUnixTimeSeconds($lp).LocalDateTime.ToString('yyyy-MM-dd') } catch { continue }
        if ($cuando -eq $dia) { [void]$l.Add([string]$jj.nombre) }
    }
    return ,@($l)
}

# EL REPASO, UNA VEZ AL DIA Y SOLO DE AYER. No de dias antiguos a proposito: LastPlayed es el
# ULTIMO jugado, asi que en cuanto pasan dos dias ya no dice lo que paso el dia que se repasa.
function Test-JuegosCiegos([string]$dia = '') {
    try {
        if (-not $dia) { $dia = (Get-Date).AddDays(-1).ToString('yyyy-MM-dd') }
        $hb = Get-Habitos
        if ([string]$hb.ciegosVisto -eq $dia) { return 0 }
        $cuad = Get-UsoAlly
        if (-not $cuad.ContainsKey($dia)) {
            # LA GUARDA DE LA FICHA: sin cuaderno de ese dia, Nova no estuvo viva y no juzga a nadie
            Log ("CIEGOS: del $dia no tengo cuaderno de uso, asi que no puedo juzgar lo que vi")
            $hb.ciegosVisto = $dia; Save-Habitos
            return 0
        }
        $conocidos = @(@($script:Juegos) | ForEach-Object { [string]$_.nombre })
        # SIN @(), Y AQUI ES DONDE MAS DOLIA: Get-JuegosDeSteamDelDia acaba en 'return ,@($l)', asi
        # que un @() encima da un array de UNO con la lista dentro. Con DOS juegos de Steam el mismo
        # dia -el 25/09 hubo CUATRO- la guarda '$st.Count -eq 1' pasaba igual, y Nova aprendia
        # 'ELDEN RING NIGHTREIGN The Past Within' como nombre de juego: lo escribia en
        # juegos-exes.json, lo metia de clave en juegos-ciegos.json y lo decia por el altavoz.
        # Reproducido ejecutando Find-CiegosDeUnDia con las dos formas. Cuarta vez de este patron:
        # por eso ahora hay un banco que lo vigila en todo el fichero (probar-listas-envueltas.ps1).
        $deSteam = Get-JuegosDeSteamDelDia $dia
        $apuntado = @{}
        $mem = Get-JuegosMem
        foreach ($k in @($mem.Keys)) {
            $h = Get-DiasJuego $mem[$k]['dias']
            if ($h.ContainsKey($dia)) { $apuntado[[string]$k] = [int]$h[$dia] }
        }
        $r = Find-CiegosDeUnDia $cuad[$dia] $conocidos $deSteam $apuntado
        $hb.ciegosVisto = $dia; Save-Habitos
        if (@($r.candidatos).Count -eq 0) { return 0 }
        Log ("CIEGOS: el $dia hubo " + @($r.candidatos).Count + " proceso(s) delante que no supe reconocer; el mayor es '" +
             [string]$r.mayor.proc + "' con " + [int]$r.mayor.seg + " s. Steam dice que ese dia se jugo a: " +
             $(if (@($deSteam).Count -gt 0) { (@($deSteam) -join ', ') } else { 'nada' }))
        $n = 0
        foreach ($c in @($r.ciegos)) {
            if (Save-JuegoCiego $c.juego $dia $c.visto $c.podria $c.proceso) { $n++ }
            Log ("CIEGOS: de " + $c.juego + " apunte " + $c.visto + " s el " + $dia +
                 " y hubo " + $c.podria + " s de '" + $c.proceso + "' delante: a ese juego lo veo mal")
        }
        # Y SE APRENDE, que es lo que cierra el bucle: va al MISMO juegos-exes.json que usa el
        # aprendizaje en vivo, con un criterio mas estricto que el suyo (uno y uno, y ganandole al
        # juego mejor visto del dia).
        if ($r.aprende) {
            Log ("CIEGOS: solo hubo un proceso sin reconocer y un juego de Steam el $dia; '" +
                 [string]$r.mayor.proc + "' es " + [string]$r.aprende)
            [void](Save-ExeJuego ([string]$r.mayor.proc) ([string]$r.aprende))
        }
        return $n
    } catch {
        Log ('CIEGOS: no pude repasarlo (' + $_.Exception.Message + ')')
        return 0
    }
}

# Y QUE ALGUIEN LO LEA: la coletilla para cuando braya pregunta cuanto ha jugado. Sin esto la lista
# seria otro cuaderno que nadie mira, el pecado que las ideas 99 y 100 tuvieron que arreglar.
function Get-ColaCiegos {
    try {
        $tb = Get-JuegosCiegos
        if ($tb.Count -eq 0) { return '' }
        if ($tb.Count -eq 1) {
            $k = @($tb.Keys)[0]
            return (' Y ojo, que a ' + $k + ' lo veo mal: lo que yo cuento de el se queda corto.')
        }
        return (' Y ojo, que hay ' + $tb.Count + ' juegos que veo mal y de esos mi cuenta se queda corta.')
    } catch { return '' }
}

# --- RUTINAS DE JUEGO (config.json -> juego) ---
# Al entrar en un juego se aplica un perfil (por defecto "juego"); al salir se
# restaura el brillo que habia. El volumen no se puede leer sin librerias
# externas, asi que no se restaura: se avisa en vez de fingir.
$JuegoPerfilEntrar = [string](Get-Cfg 'juego' 'perfilAlEntrar' 'juego')
$JuegoRestaurar = [bool](Get-Cfg 'juego' 'restaurarAlSalir' $true)
$JuegoAvisoMin = [int](Get-Cfg 'juego' 'avisoMinutos' 120)
# C4 (19/09): CUANTO TIENE QUE DURAR UNA PARTIDA PARA QUE CONTESTE AL CERRARLA.
# Sale del log del 10 al 19/09, de las 11 salidas con rastro completo:
#   falsas (alt-tab o juego recien lanzado): 4 s, 10 s, 11 s, 83 s y 100 s
#   partidas de verdad: 3 min 31 s, 4 min 10 s, 12 min 50 s, 33 min 55 s, 59 min 39 s, 6 h 14 min
# El hueco esta entre 1 min 40 s y 3 min 31 s, asi que el corte va en 3 minutos: deja
# fuera las cinco falsas con casi el doble de margen y no se come ninguna partida real.
# OJO AL NOMBRE (20/09). Esto se llamaba $JuegoSesionMin, y PowerShell NO distingue
# mayusculas en los nombres de variable: era LA MISMA que $script:juegoSesionMin, el
# acumulador de minutos de tres lineas mas arriba. Se pisaban. El umbral de 3 minutos
# que se puso el 19/09 -justo para no cantar cierres falsos de ELDEN RING- no ha
# funcionado NUNCA: nacio roto en el commit c714970 y la linea 'sin aviso' no aparece
# ni una vez en todo el log. El 20/09 a las 19:00:08 anuncio 'cerraste ELDEN RING' con
# 0 minutos de partida, once segundos despues de abrirlo, y de ahi salio media hora de
# lio con braya. El nombre nuevo no colisiona con nada.
$JuegoMinimoPartida = [int](Get-Cfg 'juego' 'sesionMinima' 3)
$script:juegoBrilloAntes = $null
# EL ESTADO DEL AVISO VIVE EN habitos.json (23/09), no en memoria. Con 16,3 arranques al
# dia, un aviso que solo se acuerda en RAM se repetiria en el primer chequeo despues de
# cada reinicio: dieciseis veces al dia, que es peor que no avisar.
$script:juegoAvisoDia = ''     # el dia del ultimo aviso
$script:juegoAvisoUlt = 0      # minutos de hoy cuando se aviso
$script:juegoAvisoCada = 0     # 0 = una vez al dia; >0 = cada N minutos
$script:ultimaRegla = $null    # la ultima regla creada, para que 'siempre' sepa cual es
$script:juegoAvisoNo = ''      # el dia en que dijo hoy no me avises

$script:juegoHoras = 0

# --- EL TIEMPO (config.json -> clima) ---
# Una consulta por hora a Open-Meteo (sin clave). Si no hay coordenadas en la
# configuracion se piden UNA vez a ip-api.com por la IP publica: eso manda la
# IP a un tercero; con clima.lat/lon en config.json no hace falta.
$ClimaOn = [bool](Get-Cfg 'clima' 'activada' $true)
$ClimaLat = Get-Cfg 'clima' 'lat' $null
$ClimaLon = Get-Cfg 'clima' 'lon' $null
$script:clima = $null
$script:climaCheck = -3600000        # lo restaura Restore-Clima (idea 6), no la lista de relojes
# =====================================================================
# EL TIEMPO NO SE PIDE OTRA VEZ EN CADA ARRANQUE (26/09, idea 6 de las 121)
# =====================================================================
# El clima se guarda una hora... pero solo dentro del proceso. Cada arranque nace con
# $script:clima vacio y $script:climaCheck en -3600000 -o sea, "hace una hora"-, asi que a los
# veinte segundos de vivir Nova sale a internet otra vez aunque el dato de hace cuatro minutos
# siguiera siendo bueno. Y Nova arranca MUCHO.
#
# MEDIDO sobre los dos registros: 258 arranques y 504 consultas de clima, de las cuales 334
# -el 66 %- caen en los TRES MINUTOS siguientes a un arranque. Dos de cada tres viajes a
# internet eran el mismo dato que ya se sabia.
#
# LA VENTANA ES LA MISMA QUE YA HABIA, una hora: no se alarga nada. Lo unico que cambia es que
# ahora sobrevive al reinicio. Si el fichero es mas viejo, se ignora y se pregunta como siempre.
$ClimaFrescoMs = 3600000
function Save-Clima([int]$codigo) {
    if (-not $script:clima) { return $false }
    try {
        $o = [ordered]@{
            emoji = [string]$script:clima.emoji; desc = [string]$script:clima.desc
            temp = [int]$script:clima.temp; codigo = $codigo
            ui = [string]$script:uiTiempo; cuando = (Get-Date).ToString('o')
        }
        Write-Atomico (Join-Path $MemoriaDir 'clima.json') (ConvertTo-Json -InputObject $o -Depth 3)
        return $true
    } catch { Log ('clima: no pude guardarlo: ' + $_.Exception.Message); return $false }
}
function Restore-Clima([datetime]$ahora = (Get-Date)) {
    # Devuelve los minutos de antiguedad si lo ha cargado, o -1 si no habia nada usable.
    try {
        $ruta = Join-Path $MemoriaDir 'clima.json'
        if (-not (Test-Path -LiteralPath $ruta)) { return -1 }
        $g = Get-Content -LiteralPath $ruta -Raw -Encoding UTF8 | ConvertFrom-Json
        if (-not $g -or -not $g.cuando) { return -1 }
        $c = [datetime]::MinValue
        if (-not [datetime]::TryParse([string]$g.cuando, [ref]$c)) { return -1 }
        $ms = ($ahora - $c).TotalMilliseconds
        # NI DEL FUTURO NI RANCIO: un reloj movido hacia atras dejaria un fichero "del futuro"
        # que parecia fresco para siempre.
        if ($ms -lt 0 -or $ms -ge $ClimaFrescoMs) { return -1 }
        $script:clima = @{ emoji = [string]$g.emoji; desc = [string]$g.desc; temp = [int]$g.temp }
        $script:uiTiempo = [string]$g.ui
        # Y EL RELOJ SE PONE COMO SI ACABARA DE MIRARLO, descontando lo que ya ha envejecido:
        # asi la proxima consulta cae cuando le tocaba, no una hora mas tarde.
        $script:climaCheck = $sw.ElapsedMilliseconds - $ms
        return [int]($ms / 60000)
    } catch { Log ('clima: no pude leer el guardado: ' + $_.Exception.Message); return -1 }
}

# lluvia / nieve / tormenta / '' : lo dibuja la capsula, muy de vez en cuando
$script:uiTiempo = ''
# el volumen que Nova acaba de poner: la capsula ensancha el halo al cambiar (13/09)
$script:uiVolumen = -1
function Update-Clima {
    if (-not $ClimaOn) { return }
    try {
        if ($null -eq $ClimaLat -or $null -eq $ClimaLon) {
            # LA UBICACION, UNA VEZ AL DIA (18/09). Se pedia por IP en CADA arranque: 126
            # llamadas en el registro, siempre el mismo resultado. Es red repetida para nada.
            # OJO, y esto corrige a quien escribio la idea: NO son "20 s del arranque".
            # Update-Clima se llama desde el bucle con "una vez por hora, la primera a los 20 s
            # de arrancar", asi que esos 20 s son la espera de diseño, no lo que tarda esto.
            # Lo que se gana es la red y no quedarse sin clima el dia que ip-api no conteste.
            $rutaU = Join-Path $MemoriaDir 'ubicacion.json'
            $hoyU = (Get-Date).ToString('yyyy-MM-dd')
            $cacheU = $null
            if (Test-Path -LiteralPath $rutaU) {
                try { $cacheU = Get-Content -LiteralPath $rutaU -Raw -Encoding UTF8 | ConvertFrom-Json } catch {}
            }
            if ($cacheU -and $cacheU.lat -and [string]$cacheU.dia -eq $hoyU) {
                $script:ClimaLat = [double]$cacheU.lat; $script:ClimaLon = [double]$cacheU.lon
            } else {
                $g = $null
                # IDEA 57: HTTPS, no http. Era el UNICO destino externo en claro (los otros siete
                # van por https); en esa peticion viajaba la IP publica de braya sin cifrar. ip-api
                # sirve https. Si https falla, el catch deja $g a $null y mas abajo se usa la
                # ubicacion guardada: NUNCA se vuelve a http.
                # idea 84: esto es de fondo, asi que se salta si la red esta caida, y con plazo recortado
                $g = $null
                if (Test-RedParaFondo) {
                    try { $g = Invoke-RestMethod -Uri 'https://ip-api.com/json/?fields=lat,lon,city' -TimeoutSec (Get-PlazoRed 4); Set-RedOk 'ip-api' } catch { $g = $null; Set-RedFallo 'ip-api' }
                }
                if ($g -and $g.lat) {
                    $script:ClimaLat = [double]$g.lat; $script:ClimaLon = [double]$g.lon
                    # IDEA 57: dias seguidos con la MISMA ciudad. Es la medicion (medir con uso real)
                    # para poder dejar de preguntar mas adelante; AUN NO se actua: fijar el numero de
                    # racha sin medirlo romperia la regla 3, y antes hay que detectar el viaje (SSID)
                    # -si no, con la consola de viaje Nova daria el clima de Tampa para siempre-.
                    $igualesU = 1
                    if ($cacheU -and [string]$cacheU.ciudad -eq [string]$g.city) { $igualesU = [int]$cacheU.iguales + 1 }
                    Log "clima: ubicacion por IP ($($g.city)); $igualesU dia(s) seguidos igual"
                    try {
                        Write-Atomico $rutaU (ConvertTo-Json -InputObject ([ordered]@{ lat = [double]$g.lat; lon = [double]$g.lon; ciudad = [string]$g.city; dia = $hoyU; iguales = $igualesU }) -Depth 3)
                    } catch {}
                } elseif ($cacheU -and $cacheU.lat) {
                    # sin red: mejor el sitio de ayer que quedarse sin tiempo
                    $script:ClimaLat = [double]$cacheU.lat; $script:ClimaLon = [double]$cacheU.lon
                    Log "clima: sin respuesta de ip-api; uso la ubicacion guardada ($([string]$cacheU.ciudad))"
                } else { return }
            }
        }
        $cul = [System.Globalization.CultureInfo]::InvariantCulture
        $u = 'https://api.open-meteo.com/v1/forecast?latitude=' + ([double]$ClimaLat).ToString($cul) + '&longitude=' + ([double]$ClimaLon).ToString($cul) + '&current_weather=true'
        if (-not (Test-RedParaFondo)) { return }   # idea 84: el clima es de fondo
        $r = $null
        try { $r = Invoke-RestMethod -Uri $u -TimeoutSec (Get-PlazoRed 4); Set-RedOk 'clima' } catch { Set-RedFallo 'clima'; throw }
        $cw = $r.current_weather
        if (-not $cw) { return }
        $codigo = [int]$cw.weathercode
        $noche = ($cw.is_day -eq 0)
        # codigos WMO -> emoji + descripcion hablada
        $emoji = '☀️'; $desc = 'esta despejado'
        if ($codigo -ge 1 -and $codigo -le 2) { $emoji = '⛅'; $desc = 'hay algunas nubes' }
        elseif ($codigo -eq 3) { $emoji = '☁️'; $desc = 'esta nublado' }
        elseif ($codigo -ge 45 -and $codigo -le 48) { $emoji = '🌫️'; $desc = 'hay niebla' }
        elseif ($codigo -ge 51 -and $codigo -le 67) { $emoji = '🌧️'; $desc = 'esta lloviendo' }
        # 85 Y 86 SON CHUBASCOS DE NIEVE, Y FALTABAN (21/09). Esta cadena saltaba de 77 a
        # 80, asi que un codigo 85 u 86 no encajaba en ninguna rama y se quedaba con el
        # valor de arriba: 'esta despejado'. Y la linea de la capsula, doce lineas mas
        # abajo, SI los cuenta como nieve: Nova decia que estaba despejado mientras su
        # propia cara dejaba caer copos.
        elseif (($codigo -ge 71 -and $codigo -le 77) -or ($codigo -ge 85 -and $codigo -le 86)) { $emoji = '🌨️'; $desc = 'esta nevando' }
        elseif ($codigo -ge 80 -and $codigo -le 82) { $emoji = '🌦️'; $desc = 'hay chubascos' }
        elseif ($codigo -ge 95) { $emoji = '⛈️'; $desc = 'hay tormenta' }
        elseif ($noche) { $emoji = '🌙'; $desc = 'esta despejado' }
        $temp = [int][Math]::Round([double]$cw.temperature)
        $script:clima = @{ emoji = $emoji; desc = $desc; temp = $temp }
        # EL CLIMA VIVO: la capsula deja caer una gota (o un copo) de vez en cuando
        $tiempoAntes = $script:uiTiempo
        $script:uiTiempo = if (($codigo -ge 51 -and $codigo -le 67) -or ($codigo -ge 80 -and $codigo -le 82)) { 'lluvia' }
                           elseif (($codigo -ge 71 -and $codigo -le 77) -or ($codigo -ge 85 -and $codigo -le 86)) { 'nieve' }
                           elseif ($codigo -ge 95) { 'tormenta' }
                           elseif ($codigo -le 1 -and -not $noche) { 'sol' } else { '' }
        if ($script:uiTiempo -ne $tiempoAntes) { Refresh-UI }
        # el avatar NO cambia solo: la carita manda. El tiempo se ensena solo
        # cuando se pregunta (Resolve-Fragment) y unos segundos.
        Log "clima: $desc, $temp grados (codigo $codigo)"
        # Y AL DISCO, PARA NO VOLVER A PREGUNTARLO EN EL PROXIMO ARRANQUE (26/09, idea 6 de las
        # 121). Ver Restore-Clima.
        try { Save-Clima $codigo } catch {}
    } catch { Log ("clima: no disponible (" + $_.Exception.Message + ")") }
}

# =====================================================================
# REGLAS POR VOZ: "cuando abra elden ring pon modo noche", "cuando la bateria
# baje del 20 bloquea", "todos los dias a las 9 pon el brillo al 60", "cada
# 45 minutos avisame en 0 minutos que descanse". Se guardan en reglas.json y
# se evaluan desde el bucle principal. La accion es una orden LOCAL (se
# valida con Test-FastCommand al crearla): nada de texto libre al modelo.
# =====================================================================
# --- COPIA DE SEGURIDAD DE LO APRENDIDO (idea 8) ---
# Traducciones, reglas, modos, alias, rechazos, listas, fechas, recordatorios,
# el diario y la voz del dueno: meses de ajustes repartidos en una docena de
# JSON que se reescriben enteros cada vez. Uno que se corte a medias (un
# apagon, la bateria a cero en mitad de un Set-Content) se lleva todo lo suyo
# sin avisar. Una copia al dia, sola, y otra cuando se pida; se guardan las 14
# ultimas, que con ~40 KB cada una no ocupan nada.
$CopiasDir = Join-Path $LogDir 'copias'
$CopiasMax = 14
# LAS COPIAS TAMBIEN SE PODAN (27/09, idea 65). El perfil vivo se limpia solo -la poda tira los
# estados pasajeros y lo que ya no toca- pero cada zip guarda intacto el perfil de SU dia, asi
# que lo borrado sigue vivo en catorce sitios. Medido: juntando el perfil.md de los 13 zips
# salen 94 datos distintos frente a los 38 del vivo; 73 huerfanos, entre ellos 'Braya considera
# que Nova se equivoca frecuentemente' y 'A braya no le gusta la musica electronica'.
#
# UNA POR DIA, NO LAS CATORCE DE GOLPE: se poda el zip MAS VIEJO que aun tenga huerfanos, asi
# que un fallo nunca se lleva mas de una copia, y no hace falta guardar por donde iba: en cuanto
# un zip queda limpio, deja de ser el elegido y le toca al siguiente.
#
# LA GUARDA QUE NO PIDE LA IDEA Y HACE FALTA: si el perfil vivo estuviera vacio -un fichero que
# se corta a medias, justo lo que estas copias vienen a arreglar- 'quitar lo que no este en el
# vivo' vaciaria las catorce. Con cero datos vivos no se toca ni un zip.
#
# Y LO QUE NO SE PODA, dicho aqui para que nadie lo 'arregle': memoria/perfil-todo.md. Es la
# memoria que braya pidio que no se borre nunca; en los zips desde el 25/09 el dato sigue ahi
# aunque salga de perfil.md, y eso es lo correcto, no un olvido.
# Poda UN zip: deja en su memoria/perfil.md solo las lineas que sigan en el vivo. Devuelve
# cuantas quito, o -1 si no habia nada que hacer. ATOMICO: se trabaja sobre una copia .tmp y
# solo al final se pone en el sitio del original, igual que Write-Atomico con los json.
function Update-CopiaPodada([string]$zip, $vivosPlano) {
    $tmp = $zip + '.tmp'
    $entrada = 'memoria/perfil.md'
    try {
        Copy-Item -LiteralPath $zip -Destination $tmp -Force -ErrorAction Stop
        $quitadas = 0
        $za = [System.IO.Compression.ZipFile]::Open($tmp, 'Update')
        try {
            $e = @($za.Entries | Where-Object { $_.FullName.Replace('\', '/') -eq $entrada })[0]
            if (-not $e) { $za.Dispose(); Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue; return -1 }
            $sr = New-Object System.IO.StreamReader($e.Open(), (New-Object System.Text.UTF8Encoding($false)))
            $texto = $sr.ReadToEnd(); $sr.Close()
            $lineas = @(($texto -split "`r?`n"))
            $quedan = New-Object System.Collections.Generic.List[string]
            foreach ($l in $lineas) {
                if ($l -match '^\s*-\s+\S') {
                    $plano = (ConvertTo-Plain (Get-DatoSinCola $l)).ToLower()
                    if ($vivosPlano -notcontains $plano) { $quitadas++; continue }
                }
                $quedan.Add($l)
            }
            if ($quitadas -eq 0) { $za.Dispose(); Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue; return 0 }
            $nombre = $e.FullName
            $e.Delete()
            $nueva = $za.CreateEntry($nombre)
            $sw = New-Object System.IO.StreamWriter($nueva.Open(), (New-Object System.Text.UTF8Encoding($false)))
            $sw.Write(($quedan -join "`r`n")); $sw.Flush(); $sw.Close()
        } finally { $za.Dispose() }
        # DESDE AQUI, UN FALLO ES DE LOS QUE PARAN LA PASADA: ya se ha reescrito la entrada
        # dentro del .tmp y lo unico que queda es ponerlo en su sitio. Si esto falla, algo va mal
        # de verdad (disco lleno, permisos) y seguir con los otros trece seria repetir el fallo.
        $paso = $false
        try {
            # el cambio de sitio, al final y de una vez: si algo se rompio arriba, el zip de
            # verdad sigue entero y lo unico que sobra es un .tmp.
            Move-Item -LiteralPath $tmp -Destination $zip -Force -ErrorAction Stop
            $paso = $true
        } catch {
            Log ('COPIA poda: no pude poner en su sitio ' + (Split-Path -Leaf $zip) + ': ' + $_.Exception.Message)
            Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue
            return -2
        }
        if (-not $paso) { return -2 }
        return $quitadas
    } catch {
        # LEER no salio: un zip que no se abre (cortado a medias en su dia, o que no es un zip).
        # No es un fallo de la poda y no debe bloquearla: se apunta, se salta y a por el siguiente.
        Log ('COPIA poda: no pude leer ' + (Split-Path -Leaf $zip) + ': ' + $_.Exception.Message)
        Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue
        return -1
    }
}

# TODAS LAS QUE HAGA FALTA EN UNA PASADA, pero cortando en el primer fallo de escritura. La idea
# pedia "una por dia" por miedo a corromper catorce de golpe, y con eso no llegaba nunca: solo
# se guardan las 14 ultimas copias, asi que a una por dia las viejas salen de la rotacion antes
# de que les toque el turno y la poda no serviria para lo que se hizo. El miedo se cubre igual:
# cada zip se reescribe en su propio .tmp -un fallo deja el original entero- y en cuanto uno
# falla AL ESCRIBIR se para la pasada, asi que un problema de verdad se lleva una copia como
# mucho. Un zip que no se puede leer no para nada: se salta.
# LA TABLA DE CORRECCIONES ESCRITA A MANO: 96 DE 110 NUNCA SE HAN OIDO (27/09, idea 109 de las 121)
#
# EL DATO: commands.json lleva 110 correcciones de palabras mal oidas ('yutub', 'espotifai',
# 'guasap'...), escritas a mano una por una. Cruzadas contra las 1.449 frases unicas de
# pruebas\audio\uso -once dias de uso real, todos los campos de destinos.jsonl y registro.jsonl-
# solo CATORCE se han oido alguna vez: bril, descagando, discor, escagando, "este estado es
# cargando", estin, navegado, painterest, pinteres, serra, sting, team, temporizado y youtub. Las
# otras 96 son peso muerto que nadie habia medido nunca. (La ficha decia 8 de 110; contando la clave
# como subcadena en el corpus entero salen 14. El orden de magnitud es el mismo.)
#
# Y NO ES SOLO PESO: Repair-Words hace UN [regex]::Replace POR ENTRADA en cada dictado. MEDIDO con
# una frase de 54 caracteres, 200 repeticiones: 1,125 ms con las 110 y 0,145 ms con las 14. SIETE
# VECES Y MEDIA mas, en el camino de cada orden. La velocidad es la primera preferencia de braya.
#
# SOLO RETIRA, NUNCA ANADE, y ese es el nucleo de la guarda: buscando candidatos por parecido
# fonetico salen 'esta' (235 veces en el corpus), 'este' (123) y 'estas' (56) como parecidos a
# 'steam'. Meter cualquiera convertiria "esta bien" en "steam bien" y rompe la regla 1 en cada frase.
# Proponer entradas nuevas es cosa de braya, no de Nova.
#
# Y RETIRAR ES REVERSIBLE: las entradas se MUEVEN a una seccion 'correccionesDormidas' del propio
# commands.json, no se borran. Volver a usar una es moverla de sitio a mano.
#
# CERO APARICIONES Y NO "POCAS": asi no hay ningun corte que escribir a mano. Lo unico que se exige
# es que haya corpus suficiente para que ese cero signifique algo.
$CorreccionesDiasMin = 7        # una semana de uso real antes de retirar nada
$script:corpusUsoCache = $null
$script:corpusUsoSello = ''

# Todas las frases del uso real, en plano y en una sola cadena para poder buscar dentro.
# Con cache por tamano, como Get-FalsasAlarmas: los dos ficheros solo crecen por el final.
#
# EL CORPUS NO SON SOLO LOS ONCE DIAS (30/09). Medido: de las 96 que esta poda durmio, DOS
# -'sirra'->cierra y 'programan'->programas- se habian dicho de verdad, y se perdio la orden
# "SIRRA, LOS PROGRAMAN" (cerrar los programas), que la seccion 3 del banco cazo bajando de 88 a 87.
# La causa es el alcance del corpus: 'pruebas\audio\uso' empieza el 15/09, y
# 'ordenes-que-funcionaban.txt' esta SACADO DEL LOG de antes de esa fecha (asi lo dice
# pruebas\LEEME.md). O sea que el cero significaba "no en los once dias", no "nunca".
# Por eso entra aqui, y SOLO ese: 'destinos.txt' y 'casos-nuevos.txt' se escriben a mano junto a
# las correcciones, asi que usarlos seria preguntarle a la pieza que se prueba. Las otras 94 siguen
# dormidas y el oido sigue costando 16 regex en vez de 110.
function Get-CorpusUso([string]$dirUso = '') {
    if (-not $dirUso) { $dirUso = Join-Path $LogDir 'pruebas\audio\uso' }
    $rD = Join-Path $dirUso 'destinos.jsonl'
    $rR = Join-Path $dirUso 'registro.jsonl'
    $rL = Join-Path $LogDir 'pruebas\ordenes-que-funcionaban.txt'
    # Y LO QUE EL OIDO ENTIENDE DE SUS VEINTE GRABACIONES (30/09). Lo escribe
    # tools\probar-audio.py cada vez que corre: es la voz de braya de verdad, transcrita por el
    # mismo motor que usa Nova. Hasta hoy ese dato se recalculaba y se tiraba -'esperado.json'
    # guarda lo que DIJO, no lo que se oyo-, asi que la poda durmio cuatro correcciones que salen
    # justo ahi: 'si arra'->cierra, 'moldo'->modo, 'descacando'->descargando y 'medio de hora'->
    # media hora. Son veinte lineas: no cuesta nada y cierra el agujero de raiz, porque sin esto
    # despertarlas a mano no duraria ni un arranque.
    $rG = Join-Path $dirUso 'oido-grabaciones.jsonl'
    $sello = ''
    try {
        $sello = $dirUso + '|' + $(if (Test-Path -LiteralPath $rD) { (Get-Item -LiteralPath $rD).Length } else { 0 }) +
                 '|' + $(if (Test-Path -LiteralPath $rR) { (Get-Item -LiteralPath $rR).Length } else { 0 }) +
                 '|' + $(if (Test-Path -LiteralPath $rL) { (Get-Item -LiteralPath $rL).Length } else { 0 }) +
                 '|' + $(if (Test-Path -LiteralPath $rG) { (Get-Item -LiteralPath $rG).Length } else { 0 })
    } catch { $sello = '' }
    if ($sello -and $sello -eq $script:corpusUsoSello -and $null -ne $script:corpusUsoCache) { return $script:corpusUsoCache }
    $frases = @{}
    $dias = @{}
    # El log viejo, linea a linea: no es jsonl, es una frase por linea con comentarios y marcas.
    # NO SUMA DIAS a proposito: la guarda de los 7 dias mide uso GRABADO, y esto es historico.
    if (Test-Path -LiteralPath $rL) {
        try {
            foreach ($l in [System.IO.File]::ReadAllLines($rL, [System.Text.Encoding]::UTF8)) {
                if (-not $l) { continue }
                $t = $l.Trim()
                if (-not $t -or $t.StartsWith('#')) { continue }
                $t = ($t -replace '@si-tienes:.*$', '').Trim()
                if ($t.Length -lt 2) { continue }
                $pl = ConvertTo-Plain $t
                if ($pl) { $frases[$pl] = $true }
            }
        } catch { }
    }
    foreach ($r in @($rD, $rR)) {
        if (-not (Test-Path -LiteralPath $r)) { continue }
        try {
            foreach ($l in [System.IO.File]::ReadAllLines($r, [System.Text.Encoding]::UTF8)) {
                if (-not $l -or $l.Length -lt 10) { continue }
                # EL DIA SALE DEL id, que ES la fecha: el mismo truco de Get-FalsasAlarmas
                if ($l -match '"id"\s*:\s*"(\d{8})') { $dias[$Matches[1]] = $true }
                $o = $null
                try { $o = $l | ConvertFrom-Json } catch { continue }
                foreach ($c in @('texto', 'detalle', 'frase', 'orden', 'entregado', 'parakeet', 'whisper', 'vosk')) {
                    $v = ''
                    try { $v = [string]$o.$c } catch { $v = '' }
                    if (-not $v -or $v.Trim().Length -lt 2) { continue }
                    $pl = ConvertTo-Plain $v
                    if ($pl) { $frases[$pl] = $true }
                }
            }
        } catch { continue }
    }
    # LAS VEINTE GRABACIONES, SIN SUMAR DIAS. Van aparte del bucle de arriba justo por eso: su 'id'
    # lleva la fecha del dia que se corrio el banco y casaria con el mismo regex, metiendo dias que
    # NO son de uso real en la guarda de los siete. Un corpus de banco no puede dar permiso para
    # podar: el permiso lo dan los dias que braya hablo de verdad.
    if (Test-Path -LiteralPath $rG) {
        try {
            foreach ($l in [System.IO.File]::ReadAllLines($rG, [System.Text.Encoding]::UTF8)) {
                if (-not $l -or $l.Length -lt 10) { continue }
                $o = $null
                try { $o = $l | ConvertFrom-Json } catch { continue }
                foreach ($c in @('texto', 'frase')) {
                    $v = ''
                    try { $v = [string]$o.$c } catch { $v = '' }
                    if (-not $v -or $v.Trim().Length -lt 2) { continue }
                    $pl = ConvertTo-Plain $v
                    if ($pl) { $frases[$pl] = $true }
                }
            }
        } catch { }
    }
    $res = @{ texto = (' || ' + (@($frases.Keys) -join ' || ') + ' || '); frases = $frases.Count; dias = $dias.Count }
    if ($sello) { $script:corpusUsoSello = $sello; $script:corpusUsoCache = $res }
    return $res
}

# PURA: dado el corpus en plano y las claves, dice cuales no aparecen NUNCA.
function Get-CorreccionesDormidas([string]$corpus, $claves) {
    $fuera = New-Object System.Collections.ArrayList
    foreach ($k in @($claves)) {
        $pl = ConvertTo-Plain ([string]$k)
        if (-not $pl) { continue }
        if (-not $corpus.Contains(' ' + $pl + ' ') -and -not $corpus.Contains($pl)) { [void]$fuera.Add([string]$k) }
    }
    return $fuera
}

function Invoke-CorreccionesDormidas {
    try {
        if (-not $cmds -or -not $cmds.correcciones) { return 0 }
        $co = Get-CorpusUso
        if ([int]$co.dias -lt $CorreccionesDiasMin) {
            Log ("CORRECCIONES: solo " + [int]$co.dias + " dias de uso grabado, hacen falta " + $CorreccionesDiasMin + "; no retiro nada")
            return 0
        }
        $claves = @($cmds.correcciones.PSObject.Properties.Name)
        if ($claves.Count -eq 0) { return 0 }
        $dormir = @(Get-CorreccionesDormidas ([string]$co.texto) $claves)
        if ($dormir.Count -eq 0) { return 0 }
        # NUNCA TODAS: si el corpus estuviera vacio o roto, esto se llevaria la tabla entera. Con
        # menos de la mitad viva se para y lo dice, que es lo que hace toda decision de la casa
        # cuando el dato huele raro.
        if ($dormir.Count -ge $claves.Count) {
            Log ("CORRECCIONES: el corpus dice que NINGUNA de las " + $claves.Count + " se ha oido; eso huele a corpus roto, no toco nada")
            return 0
        }
        $j = Get-Content -LiteralPath $cmdsPath -Raw -Encoding UTF8 | ConvertFrom-Json
        if (-not $j.PSObject.Properties['correccionesDormidas']) {
            $j | Add-Member -NotePropertyName correccionesDormidas -NotePropertyValue (New-Object PSObject)
        }
        foreach ($k in $dormir) {
            $v = [string]$j.correcciones.$k
            $j.correccionesDormidas | Add-Member -NotePropertyName $k -NotePropertyValue $v -Force
            $j.correcciones.PSObject.Properties.Remove($k)
        }
        Write-Atomico $cmdsPath ($j | ConvertTo-Json -Depth 8)
        # y la tabla viva de ESTA sesion, para que Repair-Words deje de pagarlas ya
        $script:cmds = Get-Content -LiteralPath $cmdsPath -Raw -Encoding UTF8 | ConvertFrom-Json
        Log ("CORRECCIONES: " + $dormir.Count + " de " + $claves.Count + " no se han oido en " + [int]$co.dias +
             " dias de uso (" + [int]$co.frases + " frases); a dormir. Quedan " +
             @($script:cmds.correcciones.PSObject.Properties).Count)
        Add-Estadistica 'auto-ajuste' ("correcciones dormidas: " + $dormir.Count + " de " + $claves.Count)
        return $dormir.Count
    } catch {
        Log ('CORRECCIONES: no pude repasarlas (' + $_.Exception.Message + ')')
        return 0
    }
}

function Invoke-PodaCopias {
    try {
        Add-Type -AssemblyName System.IO.Compression.FileSystem -ErrorAction SilentlyContinue
        $vivos = @(Get-DatosPerfil)
        if ($vivos.Count -eq 0) { Log 'COPIA poda: el perfil vivo esta vacio; no se toca ninguna copia'; return $null }
        $vivosPlano = @($vivos | ForEach-Object { (ConvertTo-Plain (Get-DatoSinCola $_)).ToLower() })
        $zips = @(Get-ChildItem -LiteralPath $CopiasDir -Filter 'lo-aprendido_*.zip' -File -ErrorAction SilentlyContinue | Sort-Object Name)
        $podadas = 0; $quitadasTot = 0; $corto = ''
        foreach ($z in $zips) {
            $q = Update-CopiaPodada $z.FullName $vivosPlano
            if ($q -eq -2) { $corto = $z.Name; break }   # fallo al escribir: se para aqui
            if ($q -gt 0) {
                Log ("COPIA poda: " + $q + " datos que el perfil ya no tiene, fuera de " + $z.Name)
                Add-Estadistica 'copia-podada' $z.Name
                $podadas++; $quitadasTot += $q
            }
        }
        if ($corto) { Log ("COPIA poda: parada en " + $corto + "; las demas se quedan como estaban") }
        if ($podadas -eq 0) { return $null }
        return @{ copias = $podadas; quitadas = $quitadasTot; parada = $corto }
    } catch { Log ('COPIA poda: ' + $_.Exception.Message); return $null }
}
function New-CopiaSeguridad([string]$motivo = 'a mano') {
    try {
        $origen = @($TraduccionesPath, (Join-Path $LogDir 'reglas.json'), $cmdsPath, $cfgPath, $MemoriaDir,
                    (Join-Path $TmpDir 'mi-voz.json')) | Where-Object { $_ -and (Test-Path -LiteralPath $_) }
        if ($origen.Count -eq 0) { Log "COPIA: no hay nada que copiar"; return $null }
        if (-not (Test-Path -LiteralPath $CopiasDir)) { New-Item -ItemType Directory -Path $CopiasDir -Force | Out-Null }
        $zip = Join-Path $CopiasDir ('lo-aprendido_' + (Get-Date -Format 'yyyy-MM-dd_HHmm') + '.zip')
        Compress-Archive -LiteralPath $origen -DestinationPath $zip -Force -ErrorAction Stop
        # las viejas fuera: el nombre lleva la fecha, asi que ordenar por nombre es ordenar por fecha
        Get-ChildItem -LiteralPath $CopiasDir -Filter 'lo-aprendido_*.zip' | Sort-Object Name -Descending |
            Select-Object -Skip $CopiasMax | Remove-Item -Force -ErrorAction SilentlyContinue
        # LA PODA DE LAS VIEJAS (27/09, idea 65). Va DESPUES de escribir la de hoy: si algo se
        # rompiera aqui, la copia de hoy ya esta hecha y entera. Una por dia, la mas vieja con
        # huerfanos; la de hoy nace ya limpia porque su perfil.md ES el vivo.
        # LAS SIETE TAREAS DEL DIA YA NO CUELGAN DE AQUI: ver Invoke-TareasDelDia, mas abajo.
        $n = @($origen | ForEach-Object { if (Test-Path -LiteralPath $_ -PathType Container) { Get-ChildItem -LiteralPath $_ -Recurse -File } else { Get-Item -LiteralPath $_ } }).Count
        $kb = [int][Math]::Ceiling((Get-Item -LiteralPath $zip).Length / 1KB)
        Log "COPIA ($motivo): $n archivos, $kb KB -> $zip"
        # TAMBIEN EN ONEDRIVE (13/09): si el equipo tiene OneDrive, la misma copia
        # se deja en OneDrive\Nova\copias (las 14 ultimas), para no perderla si se
        # pierde la Ally. Si no hay OneDrive, no pasa nada.
        try {
            $odN = $env:OneDrive
            if ($odN -and (Test-Path -LiteralPath $odN)) {
                $destOD = Join-Path $odN 'Nova\copias'
                if (-not (Test-Path -LiteralPath $destOD)) { New-Item -ItemType Directory -Force -Path $destOD | Out-Null }
                Copy-Item -LiteralPath $zip -Destination $destOD -Force
                @(Get-ChildItem -LiteralPath $destOD -Filter 'lo-aprendido_*.zip' -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -Skip 14) |
                    ForEach-Object { Remove-Item -LiteralPath $_.FullName -Force -ErrorAction SilentlyContinue }
                Log "COPIA: tambien en OneDrive ($destOD)"
            }
        } catch { Log ("COPIA: no pude dejarla en OneDrive: " + $_.Exception.Message) }
        return @{ ruta = $zip; archivos = $n; kb = $kb }
    } catch {
        Log ("COPIA fallida ($motivo): " + $_.Exception.Message)
        return $null
    }
}

# LAS SIETE TAREAS DEL DIA, FUERA DEL try DE LA COPIA (27/09, arreglado tras la revision)
#
# EL FALLO: las siete colgaban DENTRO de New-CopiaSeguridad y DESPUES de su
# 'Compress-Archive ... -ErrorAction Stop'. O sea que si el zip fallaba, las siete se saltaban de
# golpe y el registro solo decia "COPIA fallida": nada decia que ademas se habian quedado sin correr
# el repaso contra Steam, los ajustes propios, los cuadernos parados, la frase del oido y lo de la
# pantalla. Y el disparador mas probable de que el zip falle es EL DISCO LLENO, que es justo lo que
# Nova vigila -843 avisos de 'disco-poco' aparcados en el registro-: el dia que de verdad importa
# que estas tareas corran es el dia en que no corrian.
#
# HABIA UN SEGUNDO CAMINO, ademas: el 'if ($origen.Count -eq 0) { return $null }' de mas arriba las
# saltaba igual, sin que nada fallara.
#
# Y UN TERCERO, al reves: pedir una copia a mano -"hazme una copia"- disparaba las siete tareas
# diarias de propina. Ahora no: la copia es la copia y las tareas son las tareas.
#
# CADA UNA EN SU try, como estaban, para que la que pete no se lleve a las seis siguientes (regla 7).
function Invoke-TareasDelDia {
    # UNA VEZ AL DIA DE VERDAD, NO EN CADA ARRANQUE (28/09, visto con Nova delante). El 27/09 estas
    # siete salieron del try de la copia -eso estaba bien- pero salieron TAMBIEN del
    # 'if (Test-CopiaPendiente)', y ahi perdieron lo unico que las limitaba a una vez al dia. Nova
    # arranca mucho -235 veces en catorce dias- y cada arranque repetia las siete enteras: la poda
    # de las 28 copias, las correcciones, los juegos ciegos... MEDIDO EN VIVO el 28/09: de las
    # 00:18 a las 00:35 y subiendo, mas de media hora con el bucle bloqueado y Nova sin escuchar.
    # El sello va en config.json como el de la vuelta (entorno.vueltaMedidoDia), y se pone ANTES de
    # empezar: si una tarea revienta, se hara manana. Perder un dia de mantenimiento es barato;
    # repetirlo en cada arranque, no.
    $hoyT = Get-Date -Format 'yyyy-MM-dd'
    if ([string](Get-Cfg 'auto' 'tareasDelDia' '') -eq $hoyT) { return 0 }
    Set-Cfg 'auto' 'tareasDelDia' $hoyT
    $hechas = 0
    foreach ($t in @(
        @{ n = 'COPIA poda';    f = { Invoke-PodaCopias } }
        @{ n = 'CORRECCIONES';  f = { Invoke-CorreccionesDormidas } }
        @{ n = 'CIEGOS';        f = { Test-JuegosCiegos } }
        @{ n = 'AJUSTES';       f = { Test-AjustesDelDia } }
        @{ n = 'FICHEROS';      f = { Test-FicherosMemoria } }
        @{ n = 'OIDO frase';    f = { Update-PromptOrdenes } }
        @{ n = 'PANTALLA';      f = { Test-DecirPantalla } }
    )) {
        try { [void](& $t.f); $hechas++ }
        catch { Log ([string]$t.n + ': ' + $_.Exception.Message) }
    }
    # Y SE DICE CUANTAS CORRIERON, que es lo que faltaba: con las siete dentro del try de la copia,
    # "no corrio ninguna" y "corrieron todas" se escribian igual, o sea nada.
    if ($hechas -lt 7) { Log ('DIA: corrieron ' + $hechas + ' de 7 tareas del dia') }
    return $hechas
}
# ¿Hace falta la copia del dia? Solo si la ultima tiene mas de 20 horas: asi
# reiniciar el asistente cinco veces no deja cinco copias iguales.
function Test-CopiaPendiente {
    if (-not (Test-Path -LiteralPath $CopiasDir)) { return $true }
    $ultima = Get-ChildItem -LiteralPath $CopiasDir -Filter 'lo-aprendido_*.zip' | Sort-Object LastWriteTime -Descending | Select-Object -First 1
    if (-not $ultima) { return $true }
    return (((Get-Date) - $ultima.LastWriteTime).TotalHours -ge 20)
}

# TRABAJAR CUANDO NO MOLESTA (25/09, idea 27 de las 50)
#
# LO MEDIDO: de 2.166 ordenes en dieciseis dias, CERO caen entre las 02 y las 08. Seis horas
# muertas cada dia. Y Nova esta despierta en esa franja -6.027 lineas de registro, en nueve
# noches distintas-: lo unico que hace es escuchar a nadie y aparcar avisos.
#
# Mientras tanto, la copia de lo aprendido se ha hecho TRECE veces y las trece entre las 17 y
# las 22 h, que son justo las horas de mas uso (235 ordenes a las 18h, 198 a las 19h). No es
# casualidad ni mala suerte: la copia se intenta EN EL PRIMER MINUTO TRAS ARRANCAR, y braya
# arranca Nova cuando se pone a usarla. O sea que la tarea mas pesada del dia -comprimir 40
# archivos y copiarlos a OneDrive- cae siempre en el peor momento posible.
#
# LO QUE NO SE HACE: mirar el reloj. La franja de 02 a 08 es lo que braya hace HOY, y atarse a
# eso seria un numero inventado el dia que cambie de horario. Lo que se mira es si esta
# DELANTE, que es lo que de verdad importa: si una noche esta despierto a las cuatro, tampoco
# conviene ponerse a comprimir.
#
# Y LLEVA PLAZO, que es la regla 2 de la casa: aplazar sin tope convertiria "cuando no moleste"
# en "nunca". Pasadas TrabajoEsperaMaxHoras se hace igual, estorbe o no. Una copia tarde es un
# incordio; una copia que no se hace nunca es perder lo aprendido.
$TrabajoAusenciaMin = 15       # minutos sin nadie delante para considerar que no molesta
$TrabajoEsperaMaxHoras = 30    # y pasado esto se hace igual, aunque estorbe
function Test-BuenRatoParaTrabajo([int]$ausenciaMin, [bool]$hayJuego, [double]$horasEsperando) {
    # EL PLAZO MANDA SOBRE TODO LO DEMAS, incluso sobre el juego: si lleva mas de un dia sin
    # copia, el riesgo de perderla pesa mas que la molestia de hacerla ahora.
    if ($horasEsperando -ge $TrabajoEsperaMaxHoras) { return $true }
    if ($hayJuego) { return $false }
    return ($ausenciaMin -ge $TrabajoAusenciaMin)
}
# LA RONDA DE FONDO NO MIRABA SI HAY ALGUIEN DELANTE (27/09, idea 112 de las 121)
#
# EL DATO, contado en los dos registros: entre las 02:00 y las 08:59 no hay NI UNA de las 170
# ordenes -cero, hora por hora- y en esa misma franja Nova consulto el tiempo 62 veces y salio a
# mirar el correo 9 (de 14 en total: el 64 % de las miradas al correo caen cuando no hay nadie).
# Mientras, escribia 4.187 lineas 'ENTORNO aparcado', que es ella misma diciendo que no hay nadie
# a quien contarselo.
#
# LA GUARDA YA EXISTIA Y ERA DE OTRO: Test-BuenRatoParaTrabajo, aqui arriba, con $TrabajoAusenciaMin.
# La copia de seguridad si preguntaba si molestaba; la ronda de red, no.
#
# LA CADENCIA LARGA NO ES UN NUMERO NUEVO: es lo que lleva sin nadie. Con dos horas sola mira cada
# dos horas, con diez cada diez. Se ajusta sola, nunca deja de mirar -que seria un modo sin salida,
# la regla 2- y no hay ni un numero escrito a mano que revisar el mes que viene.
#
# Y EL REFRESCO INMEDIATO AL VOLVER SALE GRATIS, sin una linea para el: en cuanto la ausencia baja
# del liston, la condicion vuelve a ser la de siempre y el plazo ya esta vencido hace horas, asi que
# la siguiente vuelta del bucle -30 ms- hace la ronda. No hace falta un evento de vuelta.
#
# EL FRENO DE UN MINUTO NO ES OPCIONAL, Y ESTA MEDIDO: Get-InactividadMin cuesta 0,364 ms por
# llamada (200 llamadas cronometradas aqui) y es la parte BARATA de Get-NadieMin, que ademas lee
# habitos, el mando y el acelerometro. Sin freno, una vez vencido el plazo esto se preguntaria en
# cada vuelta del bucle: 712.800 llamadas en seis horas sin nadie, 259 segundos de CPU solo por
# preguntar si hay alguien. Justo lo que la regla 5 prohibe.
#
# EL OIDO QUEDA FUERA, y el disco y la biblioteca de Steam TAMBIEN, aunque la ficha los pedia:
# ninguno de los dos es red. El disco es un DriveInfo local y la biblioteca lee el vdf del disco
# (Get-JuegosSteam cuesta 67 ms, esta medido en su comentario). Dormirlos no ahorraria ni un viaje
# a internet y solo serviria para contestar con datos viejos.
$script:nadieCache = -1
$script:nadieCacheEn = -100000
$script:fondoSaltadas = 0

# La misma pregunta que Get-NadieMin, con freno de un minuto. Ver arriba por que hace falta.
function Get-NadieMinFrenado {
    if (($sw.ElapsedMilliseconds - $script:nadieCacheEn) -lt 60000) { return $script:nadieCache }
    $script:nadieCacheEn = $sw.ElapsedMilliseconds
    try { $script:nadieCache = [int](Get-NadieMin) } catch { $script:nadieCache = -1 }
    return $script:nadieCache
}

# NO SABER NO ES 'NO HAY NADIE': Get-NadieMin devuelve -1 cuando no puede saberlo, y un -1 tratado
# como ausencia dejaria a Nova sin mirar nada por una averia de user32. Con duda, se hace lo de
# siempre. Es la misma regla que la idea 30 escribio para el aparcado de avisos.
function Test-HayAlguien {
    $n = [int](Get-NadieMinFrenado)
    if ($n -lt 0) { return $true }
    return ($n -lt $TrabajoAusenciaMin)
}

# PURA: dado lo que lleva sin hacerse, su cadencia y lo que lleva sin nadie, dice si toca ahora.
#
# AQUI HABIA UN SUELO -'la cadencia larga nunca menor que la normal'- Y ERA CODIGO MUERTO. Lo canto
# su propia rotura: quitarlo no ponia rojo ni un caso. La razon es la primera linea: a partir de
# ella llevaMs >= cadaMs SIEMPRE, asi que si la ausencia es mas corta que la cadencia se cumple
# llevaMs >= cadaMs > ausencia y el resultado es el mismo con suelo que sin el; y si es mas larga,
# el suelo no elegia nada. Codigo que no cambia ningun resultado es codigo que engaña al que lo lee.
# La propiedad que el suelo pretendia dar -que esto nunca se mire mas a menudo que su cadencia- la
# da la primera linea, y ahi si hay casos que la vigilan.
function Test-TocaRonda([double]$llevaMs, [double]$cadaMs, [int]$nadieMin) {
    # NUNCA ANTES DE SU CADENCIA NORMAL, pase lo que pase con la presencia
    if ($llevaMs -lt $cadaMs) { return $false }
    # HAY ALGUIEN: lo de siempre. Y el -1 de 'no lo se' cae aqui solo, porque -1 es menor que
    # cualquier liston; se deja dicho aparte por lo que significa, no porque haga falta.
    if ($nadieMin -lt 0) { return $true }
    if ($nadieMin -lt $TrabajoAusenciaMin) { return $true }
    # SIN NADIE, LA CADENCIA ES LO QUE LLEVA SIN NADIE: dos horas sola, mira cada dos horas.
    return ($llevaMs -ge ([double]$nadieMin * 60000.0))
}

# Lo que se pregunta desde el bucle. Y APUNTA LO QUE SE AHORRA, que si no, dentro de un mes no
# habria forma de saber si esto sirvio para algo: la casa mide con uso real, no con la intencion.
function Test-RondaDeFondo([double]$desdeMs, [double]$cadaMs, [string]$que) {
    $lleva = [double]$sw.ElapsedMilliseconds - $desdeMs
    if ($lleva -lt $cadaMs) { return $false }
    if (-not (Test-RedParaFondo)) { return $false }
    $nadie = [int](Get-NadieMinFrenado)
    if (Test-TocaRonda $lleva $cadaMs $nadie) {
        if ($script:fondoSaltadas -gt 0) {
            Log ("FONDO: vuelvo a mirar " + $que + " (me ahorre " + $script:fondoSaltadas +
                 " salida(s) a internet sin nadie delante)")
            $script:fondoSaltadas = 0
        }
        return $true
    }
    $script:fondoSaltadas++
    return $false
}

# Cuanto lleva esperando la copia, en horas. Aparte para poder probar las dos cosas sueltas.
function Get-CopiaHorasEsperando {
    try {
        if (-not (Test-Path -LiteralPath $CopiasDir)) { return 999.0 }
        $u = Get-ChildItem -LiteralPath $CopiasDir -Filter 'lo-aprendido_*.zip' | Sort-Object LastWriteTime -Descending | Select-Object -First 1
        if (-not $u) { return 999.0 }
        return [double]((Get-Date) - $u.LastWriteTime).TotalHours
    } catch { return 999.0 }
}

$ReglasPath = Join-Path $LogDir 'reglas.json'
$script:reglas = $null
$HORAS_PALABRA = @{ 'una' = 1; 'dos' = 2; 'tres' = 3; 'cuatro' = 4; 'cinco' = 5; 'seis' = 6; 'siete' = 7; 'ocho' = 8; 'nueve' = 9; 'diez' = 10; 'once' = 11; 'doce' = 12 }

function Get-Reglas {
    if ($null -ne $script:reglas) { return ,$script:reglas }
    $script:reglas = New-Object System.Collections.ArrayList
    if (Test-Path -LiteralPath $ReglasPath) {
        try {
            # sin @(): ver el comentario de Get-Recordatorios
            $crudoReglas = Get-Content -LiteralPath $ReglasPath -Raw -Encoding UTF8 | ConvertFrom-Json
            foreach ($r in $crudoReglas) {
                if ($null -eq $r -or -not [string]$r.tipo) { continue }
                # 'hasta' (23/09, idea 4): dia en que caduca la regla, 'yyyy-MM-dd'. Vacio = sin
                # plazo, que es como se leen las reglas de antes: se portan igual que siempre.
                [void]$script:reglas.Add(@{ id = [int]$r.id; tipo = [string]$r.tipo; valor = [string]$r.valor; accion = [string]$r.accion; ultima = [string]$r.ultima; cond = [string]$r.cond; hasta = [string]$r.hasta })
            }
        } catch { Save-Corrupto $ReglasPath 'reglas' }
    }
    # la coma evita que PowerShell "desenrolle" la lista vacia en $null
    return ,$script:reglas
}

function Save-Reglas {
    try {
        # foreach sobre la variable, no por tuberia: la lista llega como UN
        # objeto (por la coma de Get-Reglas) y la tuberia no la desenrollaria
        $g = Get-Reglas
        $lista = @()
        foreach ($x in $g) {
            $o = New-Object PSObject
            foreach ($k in 'id', 'tipo', 'valor', 'accion', 'ultima', 'cond', 'hasta') { $o | Add-Member -NotePropertyName $k -NotePropertyValue $x[$k] }
            $lista += $o
        }
        $json = if ($lista.Count -eq 0) { '[]' } else { ConvertTo-Json -InputObject @($lista) -Depth 4 }
        Write-Atomico $ReglasPath $json
    } catch { Log ("reglas: no pude guardar: " + $_.Exception.Message) }
}

# --- REGLAS SOBRE CUALQUIER APP (idea 5) ---
# Antes "cuando abra X" solo entendia juegos de Steam: "cuando abra Spotify,
# baja el juego al 40" contestaba "no conozco el juego". Ahora X puede ser
# cualquier app de commands.json. Si el nombre es EXACTAMENTE una app, gana la
# app (Spotify no debe acabar emparejado por parecido con un juego); si no, se
# prueba como juego y, por ultimo, como app por parecido.
function Resolve-SujetoRegla([string]$obj) {
    if ($cmds -and (Test-Prop $cmds.apps $obj)) { return @{ app = $true; nombre = $obj } }
    $j = Find-Juego $obj
    if ($j) { return @{ app = $false; nombre = $j.nombre } }
    $pr = Resolve-Proceso $obj
    if ($pr -and $pr.proceso -ne '*juego*') { return @{ app = $true; nombre = $pr.nombre } }
    return $null
}

# Vigila las apps que salen en alguna regla y dispara al CAMBIAR: de cerrada a
# abierta (appAbre) y al reves (appCierra). La primera mirada solo toma nota:
# si al arrancar el asistente Spotify ya estaba abierto, eso no es "abrirlo".
# Lo mismo con una regla recien creada: su app se apunta y dispara a la
# siguiente vez que cambie.
$script:appsCheck = 0
$script:appsVivas = @{}
function Watch-AppsReglas {
    $g = Get-Reglas
    $nombres = @($g | Where-Object { $_.tipo -eq 'appAbre' -or $_.tipo -eq 'appCierra' } | ForEach-Object { $_.valor } | Select-Object -Unique)
    if ($nombres.Count -eq 0) { $script:appsVivas = @{}; return }
    foreach ($n in $nombres) {
        $pr = Resolve-Proceso $n
        if (-not $pr -or $pr.proceso -eq '*juego*') { continue }
        $viva = [bool](Get-Process -Name $pr.proceso -ErrorAction SilentlyContinue)
        $antes = $script:appsVivas[$n]
        $script:appsVivas[$n] = $viva
        if ($null -eq $antes) { continue }
        if ($viva -and -not $antes) { Log "APP abierta: $n"; Invoke-Reglas 'appAbre' $n }
        elseif ($antes -and -not $viva) { Log "APP cerrada: $n"; Invoke-Reglas 'appCierra' $n }
    }
}

function Describe-Regla($r) {
    $cuando = switch ($r.tipo) {
        'juegoAbre' { if ($r.valor) { "cuando abras $($r.valor)" } else { 'cuando abras un juego' } }
        'juegoCierra' { if ($r.valor) { "cuando cierres $($r.valor)" } else { 'cuando cierres el juego' } }
        'appAbre' { "cuando abras $($r.valor)" }
        'appCierra' { "cuando cierres $($r.valor)" }
        'bateria' { "cuando la bateria baje del $($r.valor) por ciento" }
        'cargadorQuita' { 'cuando quites el cargador' }
        'cargadorPone' { 'cuando enchufes el cargador' }
        'dockPone' { 'cuando conectes el dock o una pantalla' }
        'cascosPone' { 'cuando te pongas los cascos' }
        'dockQuita' { 'cuando quites la pantalla' }
        'cascosQuita' { 'cuando te quites los cascos' }
        'bateriaLlena' { 'cuando termine de cargar' }
        'discoJuegos' { if ($r.valor -eq 'quita') { 'cuando quites el disco de los juegos' } else { 'cuando conectes el disco de los juegos' } }
        'mandoCoge' { 'cuando cojas el mando' }
        # idea 78: la costumbre anclada a cuando braya EMPIEZA a hablarle, no a una hora de reloj
        'empiezas' { 'cuando empieces a hablarme' }
        # el nombre, no el steamid: la regla se lee en voz alta y un 76561198... no se entiende
        'amigoConecta' { $nomD = ([string]$r.valor).Split('|'); if ($nomD.Count -ge 2 -and $nomD[1]) { "cuando se conecte $($nomD[1])" } else { 'cuando se conecte' } }
        'disco' { "cuando queden menos de $($r.valor) gigas" }
        'descarga' { if ($r.valor) { "cuando termine de descargarse $($r.valor)" } else { 'cuando termine una descarga' } }
        'hora' { "todos los dias a las $($r.valor)" }
        'cada' { "cada $($r.valor) minutos" }
        default { $r.tipo }
    }
    return "$cuando" + $(if ($r.cond -eq 'noche') { ' y sea de noche' } elseif ($r.cond -eq 'dia') { ' y sea de dia' } else { '' }) + ", $($r.accion)" + $(if ($r.ultima -eq 'unavez') { ' (una sola vez)' } else { '' }) + $(if ($r.hasta) { ' (solo por hoy)' } else { '' })
}

# CADA CUANTO TOCA, CONTADO CON EL RELOJ DE PARED (23/09, idea 4).
# Antes esto se contaba con $sw.ElapsedMilliseconds, que es el cronometro DEL PROCESO, y se
# persistia en reglas.json. Dos fallos en uno:
#  - al reiniciar, $sw vuelve a cero y $r.ultima sigue valiendo, por ejemplo, 7200000: la
#    resta sale NEGATIVA y la regla no vuelve a hablar NUNCA. Con 244 arranques en 15 dias
#    -16,3 al dia- eso le pasa el primer dia;
#  - y aunque estuviera a cero, la cuenta empezaba de cero en cada arranque, asi que "cada
#    dos horas" casi nunca llegaba a las dos horas: la sesion media no llega a hora y media.
# El $ahora es parametro para que una prueba pueda mover el reloj en vez de esperar dos horas.
# NADA DE AVISOS ATRASADOS (regla 1): tras nueve horas apagado con periodo de dos, se dispara
# UNA vez y se rearma; no se sueltan de golpe las cuatro que "tocaban".
function Test-CadaDispara($r, [datetime]$ahora = (Get-Date)) {
    $per = [int]$r.valor
    if ($per -lt 1) { return $false }
    # MIGRACION DEL FORMATO VIEJO, sin fichero nuevo ni una linea de mas: un 'ultima' que son
    # TODO digitos son los milisegundos del cronometro de otra sesion, y un [datetime] de
    # "7200000" NUNCA parsea (comprobado, tambien con "20260923" y "1200"). Asi que el catch
    # ya hace la migracion entera: lo viejo se lee como "no ha disparado nunca" y la cuenta
    # arranca hoy. Se probo poner ademas un -notmatch de digitos y no cambiaba nada: rompiendo
    # esa linea a proposito, el banco seguia en verde.
    $ult = $null
    if ($r.ultima) { try { $ult = [datetime]$r.ultima } catch { $ult = $null } }
    if (-not $ult) { $r.ultima = $ahora.ToString('s'); return $false }
    if (($ahora - $ult).TotalMinutes -lt $per) { return $false }
    $r.ultima = $ahora.ToString('s')
    return $true
}

# SE ACABO EL PLAZO? (23/09, idea 4). Una regla que habla sola cada dos horas y sobrevive
# semanas es justo la fabrica de las 101 frases (de 232) que Nova arranco sola y cayeron en
# el vacio. Por eso una regla 'cada' nace con plazo de hoy, salvo que braya diga 'siempre'.
function Test-ReglaCaducada($r, [datetime]$ahora = (Get-Date)) {
    if (-not $r.hasta) { return $false }
    try { return ($ahora.Date -gt [datetime]::ParseExact([string]$r.hasta, 'yyyy-MM-dd', $null)) } catch { return $false }
}

# Intenta interpretar la frase como regla. Devuelve la respuesta hablada, o
# $null si no es una regla.
function Invoke-ReglaVoz([string]$text) {
    $p = ConvertTo-Plain $text
    $g = Get-Reglas
    # REGLAS COMBINADAS (13/09): "cuando abra hades y sea de noche, pon modo noche".
    # La condicion se quita de la frase (el resto se entiende como siempre) y se
    # guarda aparte; al dispararse, se mira la hora (noche = de 20:00 a 7:00).
    $condR = ''
    if ($p -match '^cuando\s' -and $p -match '\s+(?:y\s+)?(?:solo\s+)?(?:(?:sea|es|este|estemos)\s+)?(?:de|por la|en la)\s+(noche|dia)\b') {
        $condR = $Matches[1]
        $p = ($p -replace '\s+(?:y\s+)?(?:solo\s+)?(?:(?:sea|es|este|estemos)\s+)?(?:de|por la|en la)\s+(?:noche|dia)\b', '').Trim()
    }
    # "SIEMPRE", QUE NOVA OFRECIA Y NO EXISTIA (24/09, repaso). Al crear una regla 'cada' Nova
    # dice literalmente "Di 'siempre' si quieres que se quede", y NO habia ni un patron que
    # entendiera esa palabra: la frase se iba al modelo y la regla se moria a medianoche
    # creyendo braya que la habia dejado fija. Anunciar una salida que no existe es peor que
    # no anunciarla.
    # La ventana es la misma que la de las otras respuestas cortas de la casa: si no se dice
    # en dos minutos, "siempre" vuelve a ser una palabra cualquiera.
    if ($p -match '^(?:siempre|que se quede|dejala|dejalo|todos los dias|cada dia|para siempre)$' -and
        $script:ultimaRegla -and ($sw.ElapsedMilliseconds - [double]$script:ultimaRegla.en) -lt 120000) {
        $idS = [int]$script:ultimaRegla.id
        $script:ultimaRegla = $null
        $qS = @(); foreach ($xS in @($g)) { if ($xS.id -eq $idS) { $qS += $xS } }
        if ($qS.Count -eq 0) { return "Esa regla ya no esta." }
        if (-not $qS[0].hasta) { return "La regla $idS ya se queda puesta." }
        $qS[0].hasta = ''
        Save-Reglas
        Log "REGLA ${idS}: se queda sin plazo (lo pediste diciendo 'siempre')"
        return ("Vale, la regla $idS se queda. Di 'borra la regla $idS' cuando te canse.")
    }
    if ($p -match '^(?:borra|elimina|quita|olvida)\s+(?:todas\s+)?(?:las\s+)?reglas$') {
        $g.Clear(); Save-Reglas; return "Listo, sin reglas."
    }
    if ($p -match '^(?:borra|elimina|quita|olvida)\s+la\s+regla\s+(\d+)$') {
        $id = [int]$Matches[1]
        $q = @($g | Where-Object { $_.id -eq $id })
        if ($q.Count -eq 0) { return "No hay ninguna regla $id" }
        foreach ($x in $q) { $g.Remove($x) }
        Save-Reglas; return "Regla $id borrada."
    }
    # LA SEGUNDA SALIDA, POR TEXTO (23/09, idea 4). La de numero -"borra la regla 3"- es lista
    # cerrada y aguanta el 70,4 % del oido, pero exige acordarse del numero que Nova canto
    # hace horas. Las dos NO SE PISAN, y no por el orden: esta exige la palabra "recordatorio",
    # "aviso" o "recordarme", que la de numero no lleva. Se probo cambiandolas de sitio a
    # proposito y no pasaba nada, asi que el orden aqui no es lo que las separa.
    # SI HAY MAS DE UNA QUE ENCAJE NO SE BORRA NINGUNA: se leen con su numero y se pregunta.
    # Borrar la que no era es exactamente la regla 1 al reves.
    # EL AVISO DEL TIEMPO DE JUEGO NO ES UN RECORDATORIO (23/09). "quita el aviso de cada
    # hora" es de Resolve-Fragment, y esta funcion se mira ANTES, asi que sin esta salvedad
    # aquel patron se quedaba en codigo muerto. Lo canto probar-tiempo-juego, que es justo
    # para lo que esta. La lista es cerrada y es LA MISMA que la de alli.
    if ($p -match '^(?:deja\s+de\s+(?:recordarme|avisarme|decirme)|quita(?:me)?\s+(?:el\s+)?(?:recordatorio|aviso)|borra\s+(?:el\s+)?(?:recordatorio|aviso))\s+(?!(?:de\s+|del\s+)?(?:cada\s+)?(?:hora|rato|tiempo|tiempo de juego|juego)$)(?:lo\s+)?(?:de\s+|del\s+|que\s+|sobre\s+)?(.+)$') {
        $busca = (ConvertTo-Suave ($Matches[1].Trim()))
        $cand = @($g | Where-Object { $_.tipo -in @('cada', 'hora') -and (ConvertTo-Suave ([string]$_.accion)).Contains($busca) })
        if ($cand.Count -eq 0) { return "No tengo ningun recordatorio de eso." }
        if ($cand.Count -gt 1) {
            return ("Tengo " + $cand.Count + " que encajan: " + (($cand | ForEach-Object { "regla $($_.id), " + (Describe-Regla $_) }) -join '. ') + ". Dime cual borro.")
        }
        $qR = $cand[0]
        [void]$g.Remove($qR); Save-Reglas
        Log ("REGLA $($qR.id) borrada por texto: " + (Describe-Regla $qR))
        return "Listo, ya no te lo recuerdo. Era la regla $($qR.id)."
    }
    if ($p -match '^(?:que reglas hay|que reglas tengo|mis reglas|cuales son las reglas|lista las reglas|dime las reglas)$') {
        if ($g.Count -eq 0) { return "No tienes reglas. Puedes decir: cuando abra un juego, pon modo juego." }
        return ("Tienes " + $g.Count + ": " + (($g | ForEach-Object { "regla $($_.id), " + (Describe-Regla $_) }) -join '. '))
    }
    # RECORDATORIO DE UN SOLO USO LIGADO A UNA APP (13/09): "recuerdame comprar la
    # expansion cuando abra hades" o "cuando abra hades recuerdame...". Es una regla
    # que lo dice la primera vez que abres eso, y se borra sola.
    # y el recordatorio de un solo uso al conectar el dock o ponerse los cascos (F8)
    $recDisp = $null; $recTxtD = $null
    $RE_DISP = '((?:conecte|conectes|enchufe|ponga)\s+(?:el\s+|la\s+)?(?:dock|base|tele|television|monitor|pantalla)|(?:me\s+)?(?:conecte|ponga)\s+(?:los\s+|mis\s+)?(?:cascos|auriculares|audifonos))'
    if ($p -match ('^(?:recuerdame|avisame)\s+(?:que\s+|de\s+)?(.+?)\s+cuando\s+' + $RE_DISP + '$')) { $recTxtD = $Matches[1]; $recDisp = $Matches[2] }
    elseif ($p -match ('^cuando\s+' + $RE_DISP + '\s*,?\s*(?:recuerdame|avisame)\s+(?:que\s+|de\s+)?(.+)$')) { $recDisp = $Matches[1]; $recTxtD = $Matches[2] }
    if ($recDisp -and $recTxtD) {
        $esCascos = ($recDisp -match 'cascos|auriculares|audifonos')
        $idD = 1; foreach ($x in $g) { if ($x.id -ge $idD) { $idD = $x.id + 1 } }
        $rDisp = @{ id = $idD; tipo = $(if ($esCascos) { 'cascosPone' } else { 'dockPone' }); valor = ''; accion = "di " + $recTxtD.Trim(); ultima = 'unavez' }
        [void]$g.Add($rDisp); Save-Reglas
        Log ("REGLA $idD guardada: " + (Describe-Regla $rDisp))
        return "Vale, te lo recuerdo cuando " + $(if ($esCascos) { 'te pongas los cascos.' } else { 'conectes el dock.' })
    }
    $recApp = $null; $recTexto = $null
    if ($p -match '^(?:recuerdame|avisame)\s+(?:que\s+|de\s+)?(.+?)\s+cuando\s+(?:abra|abras|abro|inicie|arranque|entre en|entre a|juegue a|juegue al|juegue)\s+(?:el\s+|la\s+|al\s+|a\s+)?(.+)$') {
        $recTexto = $Matches[1]; $recApp = $Matches[2]
    } elseif ($p -match '^cuando\s+(?:abra|abras|abro|inicie|arranque|entre en|entre a|juegue a|juegue al|juegue)\s+(?:el\s+|la\s+|al\s+|a\s+)?(.+?)\s*,?\s*(?:recuerdame|avisame)\s+(?:que\s+|de\s+)?(.+)$') {
        $recApp = $Matches[1]; $recTexto = $Matches[2]
    }
    if ($recApp -and $recTexto) {
        $sujR = Resolve-SujetoRegla $recApp.Trim()
        if (-not $sujR) { return "No conozco '$($recApp.Trim())': no es un juego instalado ni una app de las que se abrir." }
        $idR = 1; foreach ($x in $g) { if ($x.id -ge $idR) { $idR = $x.id + 1 } }
        $rR = @{ id = $idR; tipo = $(if ($sujR.app) { 'appAbre' } else { 'juegoAbre' }); valor = $sujR.nombre; accion = "di " + $recTexto.Trim(); ultima = 'unavez' }
        [void]$g.Add($rR); Save-Reglas
        Log ("REGLA $idR guardada: " + (Describe-Regla $rR))
        return "Vale, te lo recuerdo cuando abras $($sujR.nombre)."
    }
    $tipo = $null; $valor = ''; $accion = ''
    # LAS PALABRAS TAMBIEN SON NUMEROS (23/09, idea 4). El patron de 'cada' pide digitos y
    # ConvertTo-Plain no los convierte, asi que "cada DOS horas di que estire la espalda" no
    # casaba con nada y se iba al modelo. ConvertTo-Digitos ya existia y no la llamaba nadie
    # desde aqui. Se guarda APARTE y solo la usan los dos patrones de 'cada': los doce de
    # arriba dependen de las palabras tal cual ("cuando abra hades" tiene que seguir entrando).
    $pCada = ConvertTo-Digitos $p
    if ($p -match '^cuando\s+(?:se\s+)?(?:abra|abras|abro|inicie|arranque|empiece|entre a|entre en)\s+(?:el\s+|un\s+|cualquier\s+)?(.+?)\s*,?\s*(?:entonces\s+)?((?:' + $VERBOS + '|modo|activa|desactiva|bloquea|di|avisa|avisame)\b.*)$') {
        $tipo = 'juegoAbre'; $obj = $Matches[1].Trim(); $accion = $Matches[2].Trim()
        if ($obj -notmatch '^(?:juego|videojuego|algo|cualquier cosa)$') {
            $sujeto = Resolve-SujetoRegla $obj
            if (-not $sujeto) { return "No conozco '$obj': no es un juego instalado ni una app de las que se abrir." }
            if ($sujeto.app) { $tipo = 'appAbre' }
            $valor = $sujeto.nombre
        }
    }
    # "AVISAME CUANDO LA DESCARGA DE STEAM TERMINE" (21/09 noche, del uso real). braya lo
    # dijo asi y le costo 46 SEGUNDOS para acabar oyendo que no se podia: parakeet ->
    # canary -> omni -> whisper -> la nube -> la API, y la API contesto 'No puedo completar
    # esta orden porque falta especificar que accion quieres'. La orden era perfecta; lo que
    # faltaba era el patron. El de abajo solo entiende el orden inverso -'cuando termine de
    # descargarse X, avisame'-, que nadie dice asi.
    # AQUI LA ACCION ES AVISAR, y por eso no hace falta que diga que hacer: 'avisame' YA es
    # lo que quiere. Va DELANTE del patron de abajo porque es mas especifico (pide el verbo
    # de avisar al principio) y no le quita ninguna frase.
    # LA VOCAL FINAL SE LA COME EL OIDO (22/09, minando los descartes). En la lista de
    # frases tiradas estaba 'avisame cuando la descarga de Steam TERMINO' dos veces, con
    # 'termino' donde braya dijo 'termine'. No es que lo dijera mal: es que Whisper y
    # Parakeet fallan la vocal atona del final constantemente, que es de lo mas dificil
    # de oir. Aceptar termine/termino/termina -y acabe/acabo/acaba, etc.- no abre la
    # puerta a nada: 'la descarga termino' y 'cuando la descarga termine' piden lo mismo,
    # y el patron ya exige el 'avisame cuando' delante.
    if ($p -match '^(?:avisa|avisame|avisas|dime|me dices|me avisas)\s+(?:cuando|en cuanto)\s+(?:(?:se\s+)?(?:termin[eoa]|acab[eoa]|complet[eoa]|descargue|baj[eoa]|instal[eoa])\s+(?:de\s+)?(?:descargar|bajar|instalar)?(?:se)?\s*(?:el\s+|la\s+|un\s+)?(?:descarga\s+de\s+)?(.*?)|(?:la\s+)?descarga(?:\s+de\s+(.*?))?\s+(?:termin[eoa]|acab[eoa]|se\s+complet[eoa]))\s*$') {
        # los dos grupos se copian YA: el -match de Find-Juego pisaria $Matches
        $objA = ([string]$Matches[1]).Trim()
        if (-not $objA) { $objA = ([string]$Matches[2]).Trim() }
        $tipo = 'descarga'; $accion = 'avisame'
        $valor = ''
        # 'avisame cuando termine la descarga' sin decir cual: vale cualquiera, que es lo que
        # hace el patron de abajo con 'algo'. Y 'de steam' no es un juego: es de donde baja.
        if ($objA -and $objA -notmatch '^(?:algo|cualquier cosa|lo que sea|juego|videojuego|el juego|descarga|la descarga|steam|de steam|el steam)$') {
            $jA = Find-Juego $objA
            if ($jA) { $valor = $jA.nombre } else { return "No conozco el juego '$objA'" }
        }
    }
    # DESCARGAS: "cuando termine de descargarse elden ring, abrelo"
    # Ojo con el orden: esta va ANTES que la de "cuando termine X" (cerrar un
    # juego), porque "cuando termine de descargarse X" tambien encaja alli y
    # se quedaria con ella.
    elseif ($p -match '^cuando\s+(?:se\s+)?(?:termine|acabe|complete)\s+(?:de\s+)?(?:descargar|bajar|instalar)(?:se)?\s*(?:el\s+|la\s+|un\s+)?(.*?)\s*,?\s*(?:entonces\s+)?((?:' + $VERBOS + '|modo|activa|desactiva|bloquea|di|avisa|avisame|abrelo|abrela|ejecutalo|lanzalo|inicialo|arrancalo|juegalo)\b.*)$') {
        $tipo = 'descarga'; $obj = $Matches[1].Trim(); $accion = $Matches[2].Trim()
        $valor = ''
        if ($obj -and $obj -notmatch '^(?:algo|cualquier cosa|lo que sea|juego|videojuego|el juego|descarga|la descarga)$') {
            $j = Find-Juego $obj
            if ($j) { $valor = $j.nombre } else { return "No conozco el juego '$obj'" }
        }
        # "abrelo" es la forma NATURAL aqui y no vale en ninguna otra regla, porque
        # en las demas no hay un "lo" evidente. Aqui si lo hay: el juego que acaba
        # de bajarse. Se traduce ya, que la accion se guarda como texto y luego la
        # ejecuta Invoke-FastCommand sin saber de que regla vino.
        if ($accion -match '^(?:abrelo|abrela|ejecutalo|lanzalo|inicialo|arrancalo|juegalo)$') {
            if (-not $valor) { return "Dime que juego: 'abrelo' no se a que se refiere si no nombras uno." }
            $accion = "abre $valor"
        }
    }
    # LA BATERIA LLENA: "cuando termine de cargar, avisame" (16/09).
    # OJO CON EL ORDEN, y esto lo cazo el banco: tiene que ir ANTES que la de cerrar un
    # juego ("cuando termine X"), porque esa se comia "cuando termine DE CARGAR" tomando
    # "de cargar" como nombre de juego, y contestaba "no conozco 'de cargar'". Es la
    # misma trampa que ya obligo a subir la de las descargas, unas lineas mas arriba.
    elseif ($p -match '^cuando\s+(?:(?:se\s+)?(?:termine|acabe)\s+de\s+cargar(?:se)?|(?:la\s+)?(?:bateria|pila)\s+(?:este|se\s+ponga)\s+(?:llena|cargada|al\s+(?:cien|100)(?:\s*(?:por ciento|%))?))\s*,?\s*(?:entonces\s+)?((?:' + $VERBOS + '|modo|activa|desactiva|bloquea|di|avisa|avisame)\b.*)$') {
        $tipo = 'bateriaLlena'; $valor = ''; $accion = $Matches[1].Trim()
    }
    elseif ($p -match '^cuando\s+(?:se\s+)?(?:cierre|cierres|cierro|termine|acabe|salga de|salga del)\s+(?:el\s+|un\s+|cualquier\s+)?(.+?)\s*,?\s*(?:entonces\s+)?((?:' + $VERBOS + '|modo|activa|desactiva|bloquea|di|avisa|avisame)\b.*)$') {
        $tipo = 'juegoCierra'; $obj = $Matches[1].Trim(); $accion = $Matches[2].Trim()
        if ($obj -notmatch '^(?:juego|videojuego|algo|cualquier cosa)$') {
            $sujeto = Resolve-SujetoRegla $obj
            if (-not $sujeto) { return "No conozco '$obj': no es un juego instalado ni una app de las que se abrir." }
            if ($sujeto.app) { $tipo = 'appCierra' }
            $valor = $sujeto.nombre
        }
    }
    elseif ($p -match '^cuando\s+la\s+(?:bateria|pila)\s+(?:baje|este|llegue|caiga)\s+(?:del|al|a|por debajo del|por debajo de|de|menos del)\s+(\d{1,3})\s*(?:por ciento|%)?\s*,?\s*(?:entonces\s+)?((?:' + $VERBOS + '|modo|activa|desactiva|bloquea|di|avisa|avisame)\b.*)$') {
        $tipo = 'bateria'; $valor = [string][int]$Matches[1]; $accion = $Matches[2].Trim()
    }
    # CARGADOR: "cuando quite el cargador pon el brillo al 30"
    elseif ($p -match '^cuando\s+(?:lo\s+|la\s+)?(?:quite|quites|desenchufe|desenchufes|saque|saques|desconecte|desconectes)\s+(?:el\s+)?(?:cargador|cable|corriente|enchufe)\s*,?\s*(?:entonces\s+)?((?:' + $VERBOS + '|modo|activa|desactiva|bloquea|di|avisa|avisame)\b.*)$') {
        $tipo = 'cargadorQuita'; $valor = ''; $accion = $Matches[1].Trim()
    }
    elseif ($p -match '^cuando\s+(?:lo\s+|la\s+)?(?:enchufe|enchufes|conecte|conectes|ponga|pongas)\s+(?:el\s+)?(?:cargador|cable|corriente|enchufe|a cargar)\s*,?\s*(?:entonces\s+)?((?:' + $VERBOS + '|modo|activa|desactiva|bloquea|di|avisa|avisame)\b.*)$') {
        $tipo = 'cargadorPone'; $valor = ''; $accion = $Matches[1].Trim()
    }
    # DOCK Y CASCOS (F8): "cuando conecte el dock pon modo tele", "cuando me ponga los cascos sube el volumen"
    elseif ($p -match '^cuando\s+(?:conecte|conectes|enchufe|enchufes|ponga|pongas)\s+(?:el\s+|la\s+)?(?:dock|base|tele|television|monitor|pantalla)\s*,?\s*(?:entonces\s+)?((?:' + $VERBOS + '|modo|activa|desactiva|bloquea|di|avisa|avisame)\b.*)$') {
        $tipo = 'dockPone'; $valor = ''; $accion = $Matches[1].Trim()
    }
    elseif ($p -match '^cuando\s+(?:me\s+)?(?:conecte|conectes|ponga|pongas)\s+(?:los\s+|mis\s+)?(?:cascos|auriculares|audifonos)\s*,?\s*(?:entonces\s+)?((?:' + $VERBOS + '|modo|activa|desactiva|bloquea|di|avisa|avisame)\b.*)$') {
        $tipo = 'cascosPone'; $valor = ''; $accion = $Matches[1].Trim()
    }
    # LOS SENSORES DE LAS 31 IDEAS, YA ENGANCHABLES (16/09). Hasta ahora Nova se
    # enteraba de todo esto y solo lo decia; no se podia colgar nada de ello.
    # "cuando quite el dock, pon el modo bateria"
    elseif ($p -match '^cuando\s+(?:lo\s+|la\s+)?(?:quite|quites|desconecte|desconectes|saque|saques|desenchufe|desenchufes)\s+(?:el\s+|la\s+)?(?:dock|base|tele|television|monitor|pantalla)\s*,?\s*(?:entonces\s+)?((?:' + $VERBOS + '|modo|activa|desactiva|bloquea|di|avisa|avisame)\b.*)$') {
        $tipo = 'dockQuita'; $valor = ''; $accion = $Matches[1].Trim()
    }
    # "cuando me quite los cascos, pausa"
    elseif ($p -match '^cuando\s+(?:me\s+)?(?:quite|quites|saque|saques)\s+(?:los\s+|mis\s+)?(?:cascos|auriculares|audifonos)\s*,?\s*(?:entonces\s+)?((?:' + $VERBOS + '|modo|activa|desactiva|bloquea|di|avisa|avisame)\b.*)$') {
        $tipo = 'cascosQuita'; $valor = ''; $accion = $Matches[1].Trim()
    }
    # "cuando conecte el disco de los juegos, di ya estan" (y al quitarlo).
    # El verbo decide: el mismo patron sirve para las dos, y el valor guarda cual.
    elseif ($p -match '^cuando\s+(conecte|conectes|enchufe|enchufes|ponga|pongas|quite|quites|desconecte|desconectes|saque|saques)\s+(?:el\s+)?disco(?:\s+(?:de\s+(?:los\s+)?juegos|externo|duro|de\s+fuera))?\s*,?\s*(?:entonces\s+)?((?:' + $VERBOS + '|modo|activa|desactiva|bloquea|di|avisa|avisame)\b.*)$') {
        $tipo = 'discoJuegos'; $accion = $Matches[2].Trim()
        $valor = if ($Matches[1] -match '^(?:quite|quites|desconecte|desconectes|saque|saques)$') { 'quita' } else { 'pone' }
    }
    # "cuando coja el mando, pon el modo juego"
    elseif ($p -match '^cuando\s+(?:coja|cojas|agarre|agarres|use|uses|toque|toques|encienda|enciendas)\s+(?:el\s+)?(?:mando|control|joystick|gamepad|mandito)\s*,?\s*(?:entonces\s+)?((?:' + $VERBOS + '|modo|activa|desactiva|bloquea|di|avisa|avisame)\b.*)$') {
        $tipo = 'mandoCoge'; $valor = ''; $accion = $Matches[1].Trim()
    }
    # DISCO: "cuando queden menos de 20 gigas avisame"
    elseif ($p -match '^cuando\s+(?:queden|quede|haya|tenga)\s+menos\s+de\s+(\d{1,4})\s*(?:gigas?|gb|g)\b\s*,?\s*(?:entonces\s+)?((?:' + $VERBOS + '|modo|activa|desactiva|bloquea|di|avisa|avisame)\b.*)$') {
        $tipo = 'disco'; $valor = [string][int]$Matches[1]; $accion = $Matches[2].Trim()
    }
    elseif ($p -match '^(?:todos los dias|cada dia|diariamente|siempre)?\s*a\s+las?\s+(\d{1,2}|una|dos|tres|cuatro|cinco|seis|siete|ocho|nueve|diez|once|doce)(?::(\d{2})|\s+y\s+media|\s+y\s+cuarto)?\s*(de la manana|de la tarde|de la noche|de la madrugada|am|pm)?\s*,?\s*(?:entonces\s+)?((?:' + $VERBOS + '|modo|activa|desactiva|bloquea|di|avisa|avisame)\b.*)$') {
        # Los grupos, COPIADOS antes de nada: el primer -match de las lineas de
        # abajo (la franja) reescribe $Matches entero y $Matches[4] desaparecia.
        # 'a las 10 de la noche pon modo noche' reventaba con una excepcion que
        # se tragaba el catch de Invoke-FastCommand, asi que la regla no se
        # creaba y nadie se enteraba. Lo mismo con 'y media' y 'y cuarto': el
        # ejemplo de la documentacion llevaba roto desde que se escribio.
        $g0 = $Matches[0]; $g1 = $Matches[1]; $g2 = $Matches[2]; $g3 = $Matches[3]; $g4 = $Matches[4]
        $h = $g1; if ($HORAS_PALABRA.ContainsKey($h)) { $h = $HORAS_PALABRA[$h] }; $h = [int]$h
        $m = 0
        if ($g2) { $m = [int]$g2 } elseif ($g0 -match 'y media') { $m = 30 } elseif ($g0 -match 'y cuarto') { $m = 15 }
        $franja = $g3
        if ($franja -match 'tarde|noche|pm' -and $h -lt 12) { $h += 12 }
        # LAS DOCE ES EL UNICO NUMERO QUE NO SIGUE LA REGLA (21/09). La linea de arriba
        # suma 12 solo si la hora es MENOR que 12, asi que el 12 no lo tocaba; y esta
        # miraba 'manana|am', que es justo al reves de como se dice en espanol:
        #   las doce de la NOCHE son las 00:00   (se guardaba 12:00, el mediodia)
        #   las doce de la MANANA son las 12:00  (se guardaba 00:00, la medianoche)
        # Error de doce horas exactas, y no solo en un aviso: 'a las doce de la noche pon
        # modo noche' le bajaba el brillo al MEDIODIA, jugando.
        # 'manana' y 'madrugada' no contienen 'am' (comprobado), asi que la alternancia
        # no se pisa a si misma.
        if ($franja -match 'noche|madrugada|am' -and $h -eq 12) { $h = 0 }
        $tipo = 'hora'; $valor = ('{0:00}:{1:00}' -f $h, $m); $accion = $g4.Trim()
    }
    # COMO LO DICE EL DE VERDAD (23/09, idea 4): "recuerdame cada dos horas que estire la
    # espalda". Va DELANTE del de '^cada' de abajo, que ancla al principio de la frase, asi
    # que no le quita ni una. Y no le roba nada al aviso del tiempo de juego, que exige que la
    # frase ACABE ahi ("avisame cada hora"): este pide una accion detras.
    # 'media', 'un' y 'una' se admiten a mano porque ConvertTo-Digitos los deja fuera a
    # proposito -son articulos muchas mas veces que numeros-.
    # EL AVISO DEL TIEMPO DE JUEGO NO ES UN RECORDATORIO (24/09, repaso). "avisame cada 2 horas
    # que llevo jugando" caia aqui -esta funcion se mira antes que Resolve-Fragment- y creaba
    # una regla cuya accion era "di llevo jugando": Nova decia literalmente eso cada dos horas.
    # La cola es la MISMA lista que la del patron de alla, y por eso esta escrita igual.
    elseif ($pCada -match '^(?:recuerdame|avisame|recuerda|dime)\s+cada\s+(?:\d{1,4}|media|un|una)\s*(?:minutos?|horas?)\b\s*(?:que\s+)?(?:llevo\s+)?(?:jugando|de juego|del juego|con el juego)$') {
        return $null
    }
    elseif ($pCada -match '^(?:recuerdame|avisame|recuerda|dime)\s+cada\s+(\d{1,4}|media|un|una)\s*(minutos?|horas?)\b\s*(?:,\s*)?(?:que\s+|de\s+que\s+)?(.+)$') {
        $nR = [string]$Matches[1]; $unidadR = [string]$Matches[2]; $accionR = [string]$Matches[3]
        $n = if ($nR -eq 'media') { 1 } elseif ($nR -in @('un', 'una')) { 1 } else { [int]$nR }
        if ($unidadR -match '^hora') { $n *= 60 }
        if ($nR -eq 'media') { $n = [int]($n / 2) }
        if ($n -lt 1) { return "Cada cuanto tiempo? Necesito al menos un minuto." }
        $tipo = 'cada'; $valor = [string]$n
        # "recuerdame cada dos horas que estire la espalda" -> la accion es hablar
        $accion = $accionR.Trim()
        if ($accion -notmatch '(?i)^(?:' + $VERBOS + '|modo|activa|desactiva|bloquea|di|avisa|avisame)\b') { $accion = 'di ' + $accion }
    }
    # 'media', 'un' y 'una' entran aqui tambien (23/09, idea 4): ConvertTo-Digitos los deja
    # fuera a proposito -son articulos muchas mas veces que numeros- y sin esto "cada media
    # hora avisame" se iba al modelo.
    elseif ($pCada -match '^cada\s+(\d+|media|un|una)\s*(minutos?|horas?)\b\s*,?\s*((?:' + $VERBOS + '|modo|activa|desactiva|bloquea|di|avisa|avisame)\b.*)$') {
        # los grupos se copian ANTES del -match de la unidad, que pisa $Matches:
        # con "horas" la accion salia $null y la regla no se creaba (auditoria 13/09)
        $crudoC = [string]$Matches[1]; $unidadC = [string]$Matches[2]; $accionC = [string]$Matches[3]
        $n = if ($crudoC -match '^\d+$') { [int]$crudoC } else { 1 }
        if ($unidadC -match '^hora') { $n *= 60 }
        if ($crudoC -eq 'media') { $n = [int]($n / 2) }
        if ($n -lt 1) { return "Cada cuanto tiempo? Necesito al menos un minuto." }
        $tipo = 'cada'; $valor = [string]$n; $accion = $accionC.Trim()
    }
    if (-not $tipo) { return $null }
    # "avisame" a secas no es una accion ejecutable, pero es lo que se dice.
    # Se convierte en un aviso hablado con el texto del propio disparador.
    if ($accion -match '^(?:avisa|avisame)$') {
        $queDecir = switch ($tipo) {
            'disco' { "queda poco espacio en el disco, menos de $valor gigas" }
            'descarga' { if ($valor) { "$valor ha terminado de descargarse" } else { 'ha terminado una descarga' } }
            'bateria' { "te queda poca bateria, menos del $valor por ciento" }
            'cargadorQuita' { 'has quitado el cargador' }
            'cargadorPone' { 'ya esta cargando' }
            'dockPone' { 'has conectado una pantalla' }
            'cascosPone' { 'te has puesto los cascos' }
            'dockQuita' { 'has quitado la pantalla' }
            'cascosQuita' { 'te has quitado los cascos' }
            'bateriaLlena' { 'ya esta cargada del todo' }
            'discoJuegos' { if ($valor -eq 'quita') { 'has quitado el disco de los juegos' } else { 'ya esta el disco de los juegos' } }
            'mandoCoge' { 'has cogido el mando' }
            'juegoAbre' { 'ya abriste el juego' }
            'juegoCierra' { 'ya cerraste el juego' }
            'appAbre' { "se abrio $valor" }
            'appCierra' { "se cerro $valor" }
            default { 'aviso' }
        }
        $accion = "di $queDecir"
    }
    if (-not (Test-FastCommand $accion)) { return "Entendi la condicion, pero no reconozco la accion '$accion'. Tiene que ser una orden que yo sepa hacer." }
    # NADA DESTRUCTIVO EN ALGO QUE SE VA A EJECUTAR SOLO (17/09). Este mismo filtro ya
    # existia para las propuestas de costumbres ("que no se cuele nada destructivo en una
    # regla que corre sola"), pero el camino HABLADO se lo habia saltado: se podia decir
    # "cuando abra steam cierra todos los programas" y quedaba guardado. Es el MISMO
    # criterio a proposito; dos listas distintas acabarian separandose.
    # OJO CON LO QUE SOLO HABLA: "di ..." nunca es destructivo. Sin esta excepcion el
    # banco cazo -bien cazado- que "cuando termine de cargar avisame", que se convierte
    # en "di ya esta cargada del TODO", quedaba rechazada por la palabra "todo". El
    # filtro es para lo que HACE, no para lo que dice.
    if ((ConvertTo-Plain $accion) -notmatch '^di\s' -and
        (ConvertTo-Plain $accion) -match '^(?:cierra|apaga|reinicia|bloquea|borra|elimina)\b|\b(?:todo|todos|todas)\b') {
        Log "REGLA rechazada: '$accion' es demasiado gorda para dispararse sola"
        Add-Estadistica 'regla-peligrosa' $accion
        return "Eso prefiero que me lo pidas tu en el momento: no lo dejo en una regla que se dispara sola."
    }
    $id = 1; foreach ($x in $g) { if ($x.id -ge $id) { $id = $x.id + 1 } }
    # TODA REGLA QUE HABLA SOLA NACE CON PLAZO (23/09, idea 4; regla 2: ningun modo sin
    # salida). De 232 frases que Nova arranco sola, 101 -el 43,5 %- cayeron en el vacio: una
    # regla que habla cada dos horas y sobrevive semanas es la fabrica de esas 101. Asi que
    # una 'cada' dura hasta el final del dia salvo que braya diga 'siempre' o 'todos los
    # dias'. Solo las 'cada': las demas cuelgan de un suceso suyo -abrir un juego, quitar el
    # cargador- y no hablan por su cuenta.
    $hastaR = ''
    if ($tipo -eq 'cada' -and $p -notmatch '\b(?:siempre|todos los dias|cada dia|para siempre)\b') {
        $hastaR = (Get-Date).ToString('yyyy-MM-dd')
    }
    $r = @{ id = $id; tipo = $tipo; valor = $valor; accion = $accion; ultima = ''; cond = $condR; hasta = $hastaR }
    [void]$g.Add($r); Save-Reglas
    # LA QUE ACABA DE NACER, para que "siempre" sepa a cual se refiere (24/09, repaso)
    $script:ultimaRegla = @{ id = $id; en = $sw.ElapsedMilliseconds }
    Log ("REGLA $id guardada: " + (Describe-Regla $r))
    Add-Estadistica 'local' "regla: $text"
    # LAS DOS SALIDAS SE DICEN EN VOZ ALTA, que es lo unico que las hace salidas de verdad.
    $colaR = if ($hastaR) { " Di 'siempre' si quieres que se quede, o 'borra la regla $id'." } else { " Di 'borra la regla $id' cuando te canse." }
    return ("Regla $id guardada: " + (Describe-Regla $r) + "." + $colaR)
}

# Ejecuta las reglas de un tipo cuyo valor encaje.
function Invoke-Reglas([string]$tipo, [string]$dato = '') {
    # CUANTAS DISPARARON EN ESTA LLAMADA (21/09). No se devuelve con 'return' a
    # proposito: esta funcion se llama desde treinta sitios sin [void], y cualquier
    # cosa que devuelva se colaria en la salida de la funcion que la llama. Con un
    # $script: lo lee quien lo necesite y nadie mas se entera.
    $script:reglasDisparadas = 0
    $script:reglasCaducadas = 0
    $g = Get-Reglas
    if ($g.Count -eq 0) { return }
    $hoy = Get-Date -Format 'yyyy-MM-dd'
    foreach ($r in @($g)) {
        if ($r.tipo -ne $tipo) { continue }
        $dispara = $false
        switch ($tipo) {
            'juegoAbre' { $dispara = (-not $r.valor -or $r.valor -eq $dato) }
            'juegoCierra' { $dispara = (-not $r.valor -or $r.valor -eq $dato) }
            'appAbre' { $dispara = ($r.valor -eq $dato) }
            'appCierra' { $dispara = ($r.valor -eq $dato) }
            'bateria' {
                $pct = [int]$dato
                if ($pct -le [int]$r.valor) { if ($r.ultima -ne 'baja') { $dispara = $true; $r.ultima = 'baja' } }
                elseif ($pct -gt ([int]$r.valor + 10)) { $r.ultima = '' }
            }
            'cargadorQuita' { $dispara = ($dato -eq 'quita') }
            'cargadorPone' { $dispara = ($dato -eq 'pone') }
            'dockPone' { $dispara = ($dato -eq 'pone') }
            'cascosPone' { $dispara = ($dato -eq 'pone') }
            'dockQuita' { $dispara = ($dato -eq 'quita') }
            'cascosQuita' { $dispara = ($dato -eq 'quita') }
            'bateriaLlena' { $dispara = ($dato -eq 'llena') }
            # sin valor vale cualquiera de las dos, por si alguien dice solo "el disco"
            'discoJuegos' { $dispara = (-not $r.valor -or $r.valor -eq $dato) }
            'mandoCoge' { $dispara = ($dato -eq 'coge') }
            'empiezas' { $dispara = ($dato -eq 'empieza') }
            # el dato que llega es el steamid, que es lo unico que no cambia: el nick se puede
            # cambiar en Steam en cualquier momento
            'amigoConecta' { $dispara = (([string]$r.valor).Split('|')[0] -eq $dato) }
            'disco' {
                # igual que la bateria: solo al cruzar el umbral, y se rearma
                # cuando vuelve a haber holgura (5 gigas de margen)
                $gb = [double]$dato
                if ($gb -le [double]$r.valor) { if ($r.ultima -ne 'poco') { $dispara = $true; $r.ultima = 'poco' } }
                elseif ($gb -gt ([double]$r.valor + 5)) { $r.ultima = '' }
            }
            'descarga' { $dispara = (-not $r.valor -or $r.valor -eq $dato) }
            'hora' { if ($dato -eq $r.valor -and $r.ultima -ne $hoy) { $dispara = $true; $r.ultima = $hoy } }
            'cada' {
                # ver Test-CadaDispara: el reloj de pared, no el cronometro del proceso
                # NI 'continue' NI 'break' AQUI DENTRO: dentro de un switch los dos salen del
                # switch, no del foreach, y eso se lee como si saltara la regla cuando en
                # realidad hace otra cosa. Se apaga $dispara y lo recoge el if de abajo.
                if (Test-ReglaCaducada $r) {
                    Log "REGLA $($r.id): se acabo el plazo de hoy, la quito"
                    [void]$g.Remove($r); $script:reglasCaducadas++
                    $dispara = $false
                } else {
                    $dispara = Test-CadaDispara $r
                }
            }
        }
        if (-not $dispara) { continue }
        # la condicion de una regla combinada (ver REGLAS COMBINADAS)
        if ($r.cond) {
            $horaC = (Get-Date).Hour
            $esNocheC = ($horaC -ge 20 -or $horaC -lt 7)
            if (($r.cond -eq 'noche' -and -not $esNocheC) -or ($r.cond -eq 'dia' -and $esNocheC)) { continue }
        }
        # LA SEGUNDA PUERTA (17/09). Al crear ya no se admite nada destructivo, pero una
        # regla guardada ANTES de ese filtro -o escrita a mano en reglas.json- llegaba
        # aqui igual, y $script:confirmado = $true le daba carta blanca: "cierra todos
        # los programas" se ejecutaba sin preguntar y sin que nadie pudiera pararlo.
        # Mismo criterio que al crearla, a proposito.
        # misma excepcion que al crearla: "di ..." solo habla, y "di ya esta cargada del
        # TODO" no puede quedarse sin dispararse por llevar esa palabra
        if ((ConvertTo-Plain $r.accion) -notmatch '^di\s' -and
            (ConvertTo-Plain $r.accion) -match '^(?:cierra|apaga|reinicia|bloquea|borra|elimina)\b|\b(?:todo|todos|todas)\b') {
            Log "REGLA $($r.id) NO se dispara: '$($r.accion)' es demasiado gorda para hacerla sola"
            Add-Estadistica 'regla-peligrosa' $r.accion
            continue
        }
        Log ("REGLA $($r.id) dispara: " + (Describe-Regla $r))
        $script:reglasDisparadas++
        $script:confirmado = $true
        $script:uiMia = $true   # idea 54: una regla dispara sola, no me lo pediste (la apaga el vuelta-a-reposo)
        $res = $null
        try { $res = Invoke-FastCommand $r.accion } catch { $res = $null } finally { $script:confirmado = $false }
        # 'amigoConecta' entra aqui (23/09, idea 10): la vigilancia se borra sola en cuanto
        # avisa una vez. Es la primera de sus tres salidas y no cuesta una linea de codigo
        # nueva, solo estar en esta lista.
        $unaVez = ($r.ultima -eq 'unavez' -and $tipo -in @('appAbre', 'juegoAbre', 'dockPone', 'cascosPone', 'amigoConecta'))
        # POR LA PUERTA DE LOS AVISOS, NO POR Say (24/09). Esto llamaba a Say directamente, y
        # Say no pasa por NINGUNA de las cuatro guardas que Nova tiene para no hablar cuando
        # no debe: ni la llamada, ni la sordina -que braya puede pedir para media hora-, ni el
        # juego delante (avisos.sinVozEnJuego esta a true en config.json), ni el modo silencio.
        # O sea que una regla que venciera dentro de la sordina que el mismo pidio se la
        # saltaba, y jugando le hablaba encima de la partida.
        #
        # Send-Aviso es la misma puerta que usa el aviso de descarga terminada, cinco lineas
        # mas arriba en este bucle: jugando deja capsula y pulso y se calla; sin juego lo dice
        # igual que antes. Y ademas APLAZA si braya esta dictando, que es otra cosa que Say no
        # hacia: "hablar encima de un dictado pone la pausa y el worker tira tu audio"
        # (auditoria del 13/09). Una regla que venciera en mitad de una orden se la comia.
        #
        # EN QUINCE DIAS NO HA DISPARADO NI UNA REGLA, asi que el dano hasta hoy es cero; pero
        # el ciclo entero se probo hoy de punta a punta, y en cuanto haya una regla viva pasa.
        if ($res) {
            Send-UIEvento 'hecho'
            Send-Aviso ($(if ($unaVez) { 'Recuerda' } else { "Regla $($r.id)" }) + ": $res") 'regla'
        } else { Log "REGLA $($r.id): la accion no se pudo ejecutar" }
        # un recordatorio de un solo uso se borra al cumplirse (ver Invoke-ReglaVoz)
        if ($unaVez) { [void]$g.Remove($r); Save-Reglas; Log "REGLA $($r.id): era de un solo uso, borrada" }
    }
    if ($tipo -in @('bateria', 'hora', 'cada', 'disco') -or $script:reglasCaducadas -gt 0) { Save-Reglas }
}

# =====================================================================
# FECHAS: "recuerda que el 3 de octubre es el cumple de Ana" -> ademas del
# diario, se guarda en memoria\fechas.json y ese dia lo celebra al arrancar.
# =====================================================================
$FechasPath = Join-Path $MemoriaDir 'fechas.json'
$MESES = @{ 'enero' = 1; 'febrero' = 2; 'marzo' = 3; 'abril' = 4; 'mayo' = 5; 'junio' = 6; 'julio' = 7; 'agosto' = 8; 'septiembre' = 9; 'setiembre' = 9; 'octubre' = 10; 'noviembre' = 11; 'diciembre' = 12 }

function Get-Fechas {
    $lista = @()
    if (Test-Path -LiteralPath $FechasPath) {
        # mismo fantasma que en los recordatorios: ver Get-Recordatorios
        try {
            $crudo = Get-Content -LiteralPath $FechasPath -Raw -Encoding UTF8 | ConvertFrom-Json
            foreach ($x in $crudo) { if ($null -ne $x -and [string]$x.texto) { $lista += $x } }
        } catch { $lista = @(); Save-Corrupto $FechasPath 'fechas' }
    }
    return $lista
}

function Add-Fecha([string]$frase) {
    if ($script:invitado) { return $null }   # MODO INVITADO: lo que diga otro no se queda (17/09)
    $p = ConvertTo-Plain $frase
    if ($p -notmatch '\b(?:el\s+)?(\d{1,2})\s+de\s+(enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|setiembre|octubre|noviembre|diciembre)\b') { return $null }
    $d = [int]$Matches[1]; $m = $MESES[$Matches[2]]
    if ($d -lt 1 -or $d -gt 31) { return $null }
    $md = '{0:00}-{1:00}' -f $m, $d
    $lista = @(Get-Fechas | Where-Object { -not ($_.md -eq $md -and $_.texto -eq $frase) })
    $lista += New-Object PSObject -Property @{ md = $md; texto = $frase }
    try {
        Write-Atomico $FechasPath (ConvertTo-Json -InputObject @($lista) -Depth 3)
        Log "FECHA guardada ($md): $frase"
    } catch {}
    return $md
}

function Test-FechasHoy {
    $hoy = Get-Date -Format 'MM-dd'
    $de = @(Get-Fechas | Where-Object { $_.md -eq $hoy })
    if ($de.Count -eq 0) { return }
    foreach ($f in $de) {
        Log "FECHA de hoy: $($f.texto)"
        Say ("Hoy es un dia especial: " + $f.texto)
        Send-UIEvento 'logro'
    }
}

# =====================================================================
# RECORDATORIOS CON FECHA Y HORA: "recuerdame manana a las 10 que llame al
# medico", "avisame el viernes a las cinco de la tarde que...", "recuerdame
# a las 3 revisar el horno" (hoy si aun no ha pasado; si no, manana). Se
# guardan en memoria\recordatorios.json y sobreviven a los reinicios.
# =====================================================================
$RecordatoriosPath = Join-Path $MemoriaDir 'recordatorios.json'
$DIAS_SEMANA = @{ 'lunes' = 1; 'martes' = 2; 'miercoles' = 3; 'jueves' = 4; 'viernes' = 5; 'sabado' = 6; 'domingo' = 0 }

function Get-Recordatorios {
    $lista = @()
    if (Test-Path -LiteralPath $RecordatoriosPath) {
        # OJO con @(...) alrededor de ConvertFrom-Json: con un "[]" en el
        # archivo, PowerShell 5.1 no devuelve una lista vacia sino una lista de
        # UN elemento que contiene la lista vacia. Ese fantasma se guardaba
        # luego como {"value":[],"Count":0} dentro del json y contaba como un
        # recordatorio de verdad. El foreach sobre el resultado crudo si da 0.
        try {
            $crudo = Get-Content -LiteralPath $RecordatoriosPath -Raw -Encoding UTF8 | ConvertFrom-Json
            foreach ($x in $crudo) { if ($null -ne $x -and [string]$x.texto) { $lista += $x } }
        } catch { $lista = @(); Save-Corrupto $RecordatoriosPath 'recordatorios' }
    }
    return $lista
}

function Save-Recordatorios($lista) {
    $json = if (@($lista).Count -eq 0) { '[]' } else { ConvertTo-Json -InputObject @($lista) -Depth 3 }
    Write-Atomico $RecordatoriosPath $json
}

function Invoke-RecordatorioVoz([string]$text) {
    $p = ConvertTo-Plain $text
    # LA MULETILLA DE DELANTE COSTO 49 SEGUNDOS (21/09). 'Mira, recuerdame manana
    # instalarme el juego el que esta guardado en mi lista' (20/09 23:08:04): sin el
    # 'Mira,' se resuelve aqui al momento; con el, el log dice 'LOCAL descarta: no
    # reconozco mira recuerdame manana...' (23:08:14) y la frase se fue a traducir
    # (haiku, 4277 c.), a plan (haiku, 4734 c.) y AL AGENTE ENTERO (sonnet, 28,4 s,
    # 3 pasos, 19534 B) para contestar a las 23:08:53, con Roblox delante.
    # Remove-Filler ya quita estas palabras, pero se llama DESPUES: los recordatorios
    # y las reglas se resuelven sobre la frase entera, antes de partirla en
    # fragmentos. Por eso hay que quitarlas tambien aqui.
    # EL LOOKAHEAD ES LA GUARDA: solo se borra si detras viene de verdad un verbo de
    # recordatorio. 'mira que tengo apuntado' o 'bueno, pues nada' no se tocan.
    $p = [regex]::Replace($p, '^(?:(?:oye|mira|escucha|hey|ey|hola|nova|ok|okey|okay|vale|bueno|pues|luego|despues|ahora|entonces)\s+)+(?=(?:recuerdame|avisame|recordatorio|ponme|pon)\b)', '')
    # "REVISA MI CALENDARIO PARA MAÑANA" (18/09). braya lo pidio tres veces y acabo en el agente
    # (23 s) o en la charla. Nova no tiene calendario -el correo va por IMAP y por ahi no se
    # llega a Google Calendar-, pero tiene SUS recordatorios, que es justo lo que el agente
    # acabo contestando. Aqui se contesta en local, filtrando por dia si lo dice. Lo que
    # empieza por recuerdame/avisame/pon es CREAR uno y sigue su camino.
    if ($p -notmatch '^(?:recuerdame|avisame|recordatorio|ponme|pon)\b' -and
        # SU FRASE NO ENTRABA (23/09). El dijo "dime si tengo algo anotado para manana" y el
        # patron del tema exige que la frase EMPIECE por "tengo algo anotado": la suya empieza
        # por "dime si". La otra mitad de la condicion -la del verbo de cabeza- si la aceptaba,
        # asi que faltaba media puerta. La alternativa sin ancla pide las DOS palabras juntas
        # ('tengo algo anotado'), que no aparecen por casualidad en otra orden.
        ($p -match '\b(?:calendario|agenda)\b' -or $p -match '\btengo\s+algo\s+(?:apuntado|anotado|programado|pendiente)\b' -or $p -match '^que\s+tengo\s+(?:apuntado|anotado|programado)\b') -and
        $p -match '^(?:(?:puedes?\s+|podrias\s+)?(?:revisa|revisar|mira|mirar|consulta|consultar|dime|decirme|ver|que)\b.*|(?:que\s+)?tengo\s+algo\b.*)$') {
        # EL RANGO, Y EL ORDEN IMPORTA (23/09, idea 5): 'pasado manana' antes que 'manana', y
        # 'fin de semana' antes que 'semana', porque "este fin de semana" lleva 'semana'
        # dentro y se lo comeria.
        $hoyC = (Get-Date).Date
        $desdeC = $hoyC; $hastaC = $hoyC.AddDays(30); $cuandoC = ''
        if ($p -match '\bpasado\s+manana\b') { $desdeC = $hoyC.AddDays(2); $hastaC = $desdeC; $cuandoC = ' para pasado manana' }
        elseif ($p -match '\bmanana\b') { $desdeC = $hoyC.AddDays(1); $hastaC = $desdeC; $cuandoC = ' para manana' }
        elseif ($p -match '\bhoy\b') { $hastaC = $hoyC; $cuandoC = ' para hoy' }
        # 'el fin de LA semana' tambien se dice, y ESA si choca con la rama de abajo: lleva
        # 'la semana' dentro. Por eso esta va primero. (Con solo 'fin de semana' el orden no
        # cambiaba nada: se probo cambiandolas de sitio y el banco seguia en verde.)
        elseif ($p -match '\b(?:este\s+|el\s+)?fin\s+de\s+(?:la\s+)?semana\b') {
            $aSab = (6 - [int]$hoyC.DayOfWeek + 7) % 7
            $desdeC = $hoyC.AddDays($aSab); $hastaC = $desdeC.AddDays(1); $cuandoC = ' para el fin de semana'
        }
        elseif ($p -match '\b(?:esta|la)\s+semana\b') { $hastaC = $hoyC.AddDays(6); $cuandoC = ' de hoy a siete dias' }
        elseif ($p -match '\bel\s+(lunes|martes|miercoles|jueves|viernes|sabado|domingo)\b') {
            # el mismo calculo que al crear un recordatorio: "el viernes" dicho un viernes es
            # el que viene, no hoy
            $dC = $DIAS_SEMANA[$Matches[1]]
            $deltaC = ($dC - [int]$hoyC.DayOfWeek + 7) % 7
            if ($deltaC -eq 0) { $deltaC = 7 }
            $desdeC = $hoyC.AddDays($deltaC); $hastaC = $desdeC; $cuandoC = " para el $($Matches[1])"
        }
        # SUS CITAS NO VAN AL REGISTRO (24/09, repaso): esta funcion devuelve la frase ya
        # montada, y la linea de "LOCAL: ... -> ..." la escribia entera.
        $script:respuestaPrivada = $true
        $rsC = @(Get-AgendaDe $desdeC $hastaC)
        if ($rsC.Count -eq 0) { return "No tienes nada apuntado$cuandoC. Si quieres, di: recuerdame manana a las diez que llame al medico." }
        $culC = New-Object System.Globalization.CultureInfo('es-MX')
        $listaC = @($rsC | ForEach-Object {
            if ($_.origen -eq 'fecha') { ([datetime]$_.cuando).ToString('dddd d', $culC) + ', ' + $_.texto }
            else { ([datetime]$_.cuando).ToString('dddd d "a las" H:mm', $culC) + ', ' + $_.texto }
        })
        return ("Tienes " + $(if ($rsC.Count -eq 1) { 'una cosa' } else { "$($rsC.Count) cosas" }) + "$cuandoC`: " + ($listaC -join '. ') + '.')
    }
    if ($p -match '^(?:que recordatorios (?:tengo|hay)|mis recordatorios|que tengo pendiente|que me tienes que recordar)$') {
        $rs = @(Get-Recordatorios | Sort-Object cuando)
        if ($rs.Count -eq 0) { return "No tienes recordatorios. Di, por ejemplo: recuerdame manana a las diez que llame al medico." }
        $cul = New-Object System.Globalization.CultureInfo('es-MX')
        return ("Tienes " + $rs.Count + ": " + (($rs | ForEach-Object { ([DateTime]$_.cuando).ToString('dddd d "a las" H:mm', $cul) + ", " + $_.texto }) -join '. '))
    }
    if ($p -match '^(?:borra|elimina|quita|olvida)\s+(?:todos\s+)?(?:los\s+)?recordatorios$') { Save-Recordatorios @(); return "Listo, sin recordatorios." }
    # BORRAR UNA CITA HABLANDO (23/09, idea 5). Va DETRAS del 'todos', que es mas especifico y
    # sigue ganando, y EXIGE el sustantivo delante ('recordatorio', 'aviso' o 'cita'): sin eso
    # se comeria "borra la carpeta descargas", que es otra cosa y ademas destructiva de verdad.
    # EL AVISO DEL TIEMPO DE JUEGO NO ES UNA CITA. Es la tercera vez hoy con la misma
    # familia de frases: "quita el aviso de cada hora" es de Resolve-Fragment, y esta
    # funcion se mira ANTES, asi que sin la salvedad aquel patron se queda en codigo
    # muerto. La lista de palabras es la MISMA que alli y que en los recordatorios
    # repetidos: tres sitios, una lista.
    if ($p -match '^(?!(?:borra|elimina|quita|olvida|cancela)\s+(?:el\s+|la\s+|mi\s+)?(?:aviso|avisos)\s+(?:de\s+|del\s+)?(?:cada\s+)?(?:hora|rato|tiempo|tiempo de juego|juego)$)(?:borra|elimina|quita|olvida|cancela)\s+(?:el\s+|la\s+|mi\s+)?(?:recordatorio|aviso|cita)\s*(?:de\s+|del\s+|sobre\s+|que\s+)?(.+)$') {
        $qR = [string]$Matches[1]
        # LA SEGUNDA VIA, POR NUMERO (regla 7, oido al 70,4 %): Nova acaba de leer la lista
        # numerada, asi que "borra el recordatorio dos" es una lista cerrada de una palabra.
        $nR = switch -Regex ($qR.Trim()) { '^(?:uno|1)$' { 1 } '^(?:dos|2)$' { 2 } '^(?:tres|3)$' { 3 } '^(?:cuatro|4)$' { 4 } '^(?:cinco|5)$' { 5 } default { 0 } }
        if ($nR -gt 0) {
            $todosR = @(Get-Recordatorios | Sort-Object cuando)
            if ($nR -gt $todosR.Count) { return "Solo tienes $($todosR.Count)." }
            $elR = $todosR[$nR - 1]
            # SE FILTRA LA LISTA QUE YA SE LEYO, no otra lectura: leer dos veces crea objetos
            # nuevos y "-ne" compara por referencia, asi que no se iba ninguno y Nova decia
            # "Listo, quitado" sin quitar nada.
            $quedanR = @()
            for ($iR = 0; $iR -lt $todosR.Count; $iR++) { if ($iR -ne ($nR - 1)) { $quedanR += $todosR[$iR] } }
            Save-Recordatorios $quedanR
            Log ("RECORDATORIO borrado por numero: " + ([string]$elR.texto).Length + " caracteres")
            return "Listo, quitado: $($elR.texto)."
        }
        $rq = Remove-RecordatorioTexto $qR
        if ($rq.estado -eq 'ninguno') { return "No tengo nada apuntado de eso." }
        if ($rq.estado -eq 'varios') {
            $nn = 0
            $lR = @($rq.lista | ForEach-Object { $nn++; "$nn, $($_.texto)" })
            return ("Tengo " + $rq.lista.Count + " que hablan de eso: " + ($lR -join '. ') + ". Cual borro? Di: borra el recordatorio uno.")
        }
        return "Listo, quitado: $($rq.borrado.texto)."
    }
    if ($p -notmatch '^(?:recuerdame|avisame|recordatorio|ponme un recordatorio|pon un recordatorio)\s+(?!que\b)(.+)$') { return $null }
    $resto = $Matches[1]
    $hoy = (Get-Date).Date
    $fecha = $null; $hora = -1; $min = 0
    # dia
    if ($resto -match '^(?:para\s+)?hoy\b\s*(.*)$') { $fecha = $hoy; $resto = $Matches[1] }
    elseif ($resto -match '^(?:para\s+)?pasado manana\b\s*(.*)$') { $fecha = $hoy.AddDays(2); $resto = $Matches[1] }
    elseif ($resto -match '^(?:para\s+)?manana\b\s*(.*)$') { $fecha = $hoy.AddDays(1); $resto = $Matches[1] }
    elseif ($resto -match '^(?:para\s+)?el\s+(lunes|martes|miercoles|jueves|viernes|sabado|domingo)\b\s*(.*)$') {
        $d = $DIAS_SEMANA[$Matches[1]]; $resto = $Matches[2]
        $delta = ($d - [int]$hoy.DayOfWeek + 7) % 7
        if ($delta -eq 0) { $delta = 7 }   # "el viernes" dicho un viernes = el que viene
        $fecha = $hoy.AddDays($delta)
    }
    elseif ($resto -match '^(?:para\s+)?el\s+(\d{1,2})\s+de\s+(enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|setiembre|octubre|noviembre|diciembre)\b\s*(.*)$') {
        $dd = [int]$Matches[1]; $mm = $MESES[$Matches[2]]; $resto = $Matches[3]
        try { $fecha = Get-Date -Year $hoy.Year -Month $mm -Day $dd -Hour 0 -Minute 0 -Second 0 } catch { return "Esa fecha no existe." }
        if ($fecha.Date -lt $hoy) { $fecha = $fecha.AddYears(1) }
    }
    # AVISO ANTES DE UNA HORA (idea 6): "avisame diez minutos antes de las
    # diez", "recuerdame media hora antes de las ocho que empieza la partida".
    # Habia "a las diez" y habia "en veinte minutos", pero no lo que de verdad
    # se pide antes de una partida. Va DESPUES del dia ("manana diez minutos
    # antes de las diez") y ANTES de la hora, que se lee igual que siempre.
    $antesMin = 0
    if ($resto -match '^(.+?)\s+(minutos?|horas?)(\s+y\s+media)?\s+antes(?:\s+(?:de\s+)?(.+))?$') {
        $cantA = $Matches[1].Trim(); $unidadA = $Matches[2]; $yMediaA = [bool]$Matches[3]; $trasA = $Matches[4]
        if ($cantA -match '^(?:un\s+)?cuarto\s+de$') { $antesMin = 15 }
        elseif ($cantA -match '^medi[ao]$') { if ($unidadA -like 'hora*') { $antesMin = 30 } }
        elseif ($cantA -match '^(?:un|una)$') { $antesMin = if ($unidadA -like 'hora*') { 60 } else { 1 } }
        else {
            $cantA = (ConvertTo-Digitos $cantA).Trim()
            if ($cantA -match '^\d{1,3}$') { $antesMin = if ($unidadA -like 'hora*') { [int]$cantA * 60 } else { [int]$cantA } }
        }
        # "una hora y media antes", "dos horas y media antes"
        if ($antesMin -gt 0 -and $yMediaA -and $unidadA -like 'hora*') { $antesMin += 30 }
        if ($antesMin -gt 0) {
            $resto = $trasA
            # "antes de las diez": el patron de la hora espera "a las"
            if ($resto -match '^las?\s') { $resto = 'a ' + $resto }
        }
    }
    # hora
    # "11:30" llega como "11 30": ConvertTo-Plain cambia los dos puntos por un
    # espacio, y con solo ':' el patron se quedaba con las 11 y guardaba "30 de
    # la noche que apague el horno" como texto del recordatorio (12/09).
    if ($resto -match '^(?:a\s+las?\s+)(\d{1,2}|una|dos|tres|cuatro|cinco|seis|siete|ocho|nueve|diez|once|doce)(?:(?::|\s+)(\d{2})\b|\s+y\s+media|\s+y\s+cuarto|\s+menos\s+cuarto)?\s*(de la manana|de la tarde|de la noche|de la madrugada|am|pm)?\s*(.*)$') {
        # mismos cuidados que en las reglas: copiar ANTES de volver a usar
        # -match. Aqui el fallo era mudo: $resto quedaba vacio y contestaba
        # '¿Que te recuerdo?', asi que creias haber puesto el recordatorio y no
        # existia. Pasaba con 'y media', 'y cuarto' y 'menos cuarto'.
        $g0 = $Matches[0]; $g1 = $Matches[1]; $g2 = $Matches[2]; $g3 = $Matches[3]; $g4 = $Matches[4]
        $h = $g1; if ($HORAS_PALABRA.ContainsKey($h)) { $h = $HORAS_PALABRA[$h] }; $hora = [int]$h
        if ($g2) { $min = [int]$g2 } elseif ($g0 -match 'y media') { $min = 30 } elseif ($g0 -match 'y cuarto') { $min = 15 } elseif ($g0 -match 'menos cuarto') { $min = 45; $hora-- }
        $franja = $g3; $resto = $g4
        if ($franja -match 'tarde|noche|pm' -and $hora -lt 12) { $hora += 12 }
        # LAS DOCE ES EL UNICO NUMERO QUE NO SIGUE LA REGLA (21/09). La linea de arriba
        # suma 12 solo si la hora es MENOR que 12, asi que el 12 no lo tocaba; y esta
        # miraba 'manana|am', que es justo al reves de como se dice en espanol:
        #   las doce de la NOCHE son las 00:00   (se guardaba 12:00, el mediodia)
        #   las doce de la MANANA son las 12:00  (se guardaba 00:00, la medianoche)
        # Error de doce horas exactas, y no solo en un aviso: 'a las doce de la noche pon
        # modo noche' le bajaba el brillo al MEDIODIA, jugando.
        # 'manana' y 'madrugada' no contienen 'am' (comprobado), asi que la alternancia
        # no se pisa a si misma.
        if ($franja -match 'noche|madrugada|am' -and $hora -eq 12) { $hora = 0 }
        # sin franja y hora "pequena": si ya paso, sera de tarde.
        # PERO DE MADRUGADA NO (21/09). Esto sumaba 12 SIEMPRE que la hora fuera de 1 a 7
        # y no se dijera la franja, y a las tres de la madrugada eso es justo al reves de
        # lo que quiere decir: 'recuerdame a las siete que desayune', dicho a las 3:00, se
        # guardaba para las 19:00 -cuando lo que queda son cuatro horas para las 7 de la
        # manana-. Y braya juega de madrugada, que es cuando mas lo dice.
        # La razon de sumar 12 es 'esa hora ya paso hoy', asi que se mira eso y no un
        # numero fijo: si la hora pedida AUN NO HA LLEGADO, se toma tal cual.
        $horaAhora = (Get-Date).Hour
        if (-not $franja -and $hora -le 7 -and $hora -ge 1 -and $null -eq $fecha -and
            $horaAhora -ge $hora) { $hora += 12 }
    }
    # no es un recordatorio con fecha... salvo que haya antelacion sin hora, que
    # se pregunta justo debajo
    if ($null -eq $fecha -and $hora -lt 0 -and $antesMin -le 0) { return $null }
    # "avisame veinte minutos antes" sin decir de que: mejor preguntar que
    # dejar que la frase se vaya al agente
    if ($antesMin -gt 0 -and $hora -lt 0) { return "¿Antes de que hora? Di, por ejemplo: avisame diez minutos antes de las nueve." }
    $texto = ($resto -replace '^(?:que|de que|de|para|a)\s+', '').Trim()
    # con antelacion no hace falta decir que: el aviso ya dice cuanto falta
    if (-not $texto -and $antesMin -le 0) { return "¿Que te recuerdo?" }
    if ($hora -lt 0) { $hora = 9 }   # solo dia: a las 9 de la manana
    if ($null -eq $fecha) {
        $fecha = $hoy
        if ($hoy.AddHours($hora).AddMinutes($min) -le (Get-Date)) { $fecha = $hoy.AddDays(1) }
    }
    $cuando = $fecha.Date.AddHours($hora).AddMinutes($min)
    if ($cuando -le (Get-Date)) { return "Esa hora ya paso." }
    $antesDicho = ''
    if ($antesMin -gt 0) {
        $evento = $cuando
        $cuando = $evento.AddMinutes(-$antesMin)
        $cul0 = New-Object System.Globalization.CultureInfo('es-MX')
        $margen = if ($antesMin % 60 -eq 0) { $hh = $antesMin / 60; if ($hh -eq 1) { 'una hora' } else { "$hh horas" } } elseif ($antesMin -eq 30) { 'media hora' } elseif ($antesMin -eq 90) { 'una hora y media' } elseif ($antesMin % 60 -eq 30) { "$([int][Math]::Floor($antesMin / 60)) horas y media" } elseif ($antesMin -eq 1) { 'un minuto' } else { "$antesMin minutos" }
        # "falta una hora", "faltan diez minutos": se lee en voz alta
        $falta = if ($margen -match '^(?:una hora|media hora|una hora y media|un minuto)$') { 'falta' } else { 'faltan' }
        if ($cuando -le (Get-Date)) { return "Ya $falta menos de $margen para las " + $evento.ToString('H:mm', $cul0) + "." }
        $texto = if ($texto) { "$texto. Es a las " + $evento.ToString('H:mm', $cul0) } else { "$falta $margen para las " + $evento.ToString('H:mm', $cul0) }
        $antesDicho = ", $margen antes"
    }
    $lista = @(Get-Recordatorios) + @(New-Object PSObject -Property @{ cuando = $cuando.ToString('s'); texto = $texto })
    Save-Recordatorios $lista
    $cul = New-Object System.Globalization.CultureInfo('es-MX')
    $dicho = if ($cuando.Date -eq $hoy) { "hoy a las " + $cuando.ToString('H:mm', $cul) } elseif ($cuando.Date -eq $hoy.AddDays(1)) { "manana a las " + $cuando.ToString('H:mm', $cul) } else { $cuando.ToString('dddd d "de" MMMM "a las" H:mm', $cul) }
    Log "RECORDATORIO ($cuando): $texto"
    Add-Estadistica 'local' "recordatorio: $text"
    return "Listo, te lo recuerdo $dicho$antesDicho."
}

# LA AGENDA MIRA LOS TRES SITIOS (23/09, idea 5). Nova apunta cosas con fecha en TRES sitios
# y el alias del calendario solo leia uno:
#   - recordatorios.json, con fecha y hora exactas;
#   - fechas.json, lo anual ("el 15 de septiembre es el cumple de Ana"), que hoy tiene una
#     entrada de verdad en el disco y que Test-FechasHoy solo mira EL MISMO DIA;
#   - las reglas de tipo 'hora', que es donde vive "todos los dias a las ocho di que me tome
#     la pastilla".
# NO se crea un cuarto fichero: eso es exactamente la leccion que ya esta escrita en el
# codigo ("dos listas distintas acabarian separandose"). Cero migracion, cero formato nuevo.
# De las reglas solo entran las que HABLAN ('di ...'): un modo nocturno no es una cita.
function Get-AgendaDe([datetime]$desde, [datetime]$hasta) {
    $out = @()
    foreach ($r in @(Get-Recordatorios)) {
        $c = $null
        try { $c = [datetime]$r.cuando } catch { $c = $null }
        if ($c -and $c.Date -ge $desde.Date -and $c.Date -le $hasta.Date) {
            $out += @{ cuando = $c; texto = [string]$r.texto; origen = 'recordatorio' }
        }
    }
    $fechas = @(Get-Fechas)
    # SE ASIGNA PRIMERO Y LUEGO foreach, que es como lo hace Invoke-Reglas, y no por tuberia.
    # Get-Reglas devuelve ",$script:reglas" para que una lista vacia no se vuelva $null, y eso
    # hace que @(Get-Reglas) sea un array de UN elemento que ES la lista. Con Where-Object
    # pasaba lo peor: $_.tipo sobre una coleccion devuelve la lista de tipos, comparada con
    # 'hora' da algo no vacio -o sea verdadero- y la lista ENTERA se colaba como si fuera una
    # regla; despues [string]$g.valor salia "08:00 23:00" y se descartaba sola, en silencio.
    # Con una sola regla el fallo no se ve: hacen falta dos para que aparezca.
    $reglas = @()
    try {
        $todasR = Get-Reglas
        foreach ($rr in @($todasR)) {
            if ([string]$rr.tipo -eq 'hora' -and (ConvertTo-Plain ([string]$rr.accion)) -match '^di\s') { $reglas += $rr }
        }
    } catch { $reglas = @() }
    if ($fechas.Count -gt 0 -or $reglas.Count -gt 0) {
        for ($d = $desde.Date; $d -le $hasta.Date; $d = $d.AddDays(1)) {
            $md = $d.ToString('MM-dd')
            foreach ($f in $fechas) {
                # UN CUMPLEANOS NO TIENE HORA: se le pone una para poder ordenar, y al leerlo
                # se dice sin ella.
                if ([string]$f.md -eq $md) { $out += @{ cuando = $d.AddHours(9); texto = [string]$f.texto; origen = 'fecha' } }
            }
            foreach ($g in $reglas) {
                $hh = 0; $mm = 0
                if ([string]$g.valor -match '^(\d{1,2}):(\d{2})$') { $hh = [int]$Matches[1]; $mm = [int]$Matches[2] } else { continue }
                $out += @{ cuando = $d.AddHours($hh).AddMinutes($mm)
                           texto = (([string]$g.accion) -replace '(?i)^\s*di\s+', '')
                           origen = 'regla' }
            }
        }
    }
    return @($out | Sort-Object { $_.cuando })
}

# BORRAR UNA CITA HABLANDO (23/09, idea 5). Antes solo existia "borra todos los
# recordatorios", que es todo o nada.
# CON MAS DE UNA COINCIDENCIA NO BORRA NINGUNA: borrar la que no era es la regla 1 al reves,
# y encima sobre algo que no se puede recuperar. Se leen numeradas y decide el.
function Remove-RecordatorioTexto([string]$q) {
    # borrar un recordatorio de braya no tiene vuelta atras.
    if ($script:invitado) { return $null }   # MODO INVITADO: lo que borre otro tampoco se queda (24/09)
    $todos = @(Get-Recordatorios)
    $qs = ConvertTo-Plain ([string]$q).Trim()
    # SUELO DE TRES LETRAS (regla 7, oido al 70,4 %). Con menos, un trozo mal oido borra lo
    # que pille: "borra el recordatorio de la" se llevaba "sacar la basura" porque 'la' esta
    # dentro, y un recordatorio borrado no se recupera. Tres letras es lo mismo que ya pide
    # Remove-DatoPerfil para no emparejar por una palabra vacia.
    if ($qs.Length -lt 3) { return @{ estado = 'ninguno' } }
    $hit = @($todos | Where-Object { (ConvertTo-Plain ([string]$_.texto)).Contains($qs) })
    if ($hit.Count -eq 0) { return @{ estado = 'ninguno' } }
    if ($hit.Count -gt 1) { return @{ estado = 'varios'; lista = $hit } }
    Save-Recordatorios @($todos | Where-Object { $_ -ne $hit[0] })
    Log ("RECORDATORIO borrado a mano: " + ([string]$hit[0].texto).Length + " caracteres")
    return @{ estado = 'uno'; borrado = $hit[0] }
}

# Los que ya se apuntaron como ilegibles en ESTE arranque, para no repetir la linea en cada
# vuelta del bucle. En memoria y no en disco a proposito: si al reiniciar sigue rota, merece
# una linea nueva -es informacion de que el problema no se ha arreglado solo-.
$script:recordatorioIlegible = New-Object System.Collections.ArrayList
function Test-Recordatorios {
    $lista = @(Get-Recordatorios)
    if ($lista.Count -eq 0) { return }
    $ahora = Get-Date
    $quedan = @()
    foreach ($r in $lista) {
        $c = $null
        try { $c = [DateTime]$r.cuando } catch {
            # UNA FECHA ILEGIBLE NO BORRA EL RECORDATORIO (24/09). Aqui habia un 'continue'
            # que saltaba el 'else { $quedan += $r }' de abajo, y el Save de dos lineas mas
            # alla guardaba la lista SIN esta entrada: la fecha rota no aplazaba nada, borraba
            # el recordatorio del disco y sin escribir una linea.
            # Se apunta UNA vez por arranque y no en cada vuelta: el bucle pasa por aqui
            # constantemente, y repetirlo seria el fallo de los 25 avisos identicos del 22/09.
            # Y no se adivina la fecha: se conserva para que braya pueda preguntar por el.
            if (-not $script:recordatorioIlegible.Contains([string]$r.texto)) {
                [void]$script:recordatorioIlegible.Add([string]$r.texto)
                Log "RECORDATORIO con fecha ilegible ('$($r.cuando)'): lo dejo donde esta, no lo borro"
                Add-Estadistica 'recordatorio-ilegible' ([string]$r.texto)
            }
            $quedan += $r
            continue
        }
        if ($c -le $ahora) {
            # el despertador no es un aviso: suena (ver DESPERTADOR)
            if ($r.texto -eq 'despertador') { try { Invoke-Despertador } catch { Log ("despertador: " + $_.Exception.Message) }; continue }
            Log "RECORDATORIO vence: $($r.texto)"
            Send-Aviso ("Te recuerdo: " + $r.texto) 'recordatorio'
            Start-Vibracion @(120, 80, 120)
        } else { $quedan += $r }
    }
    if ($quedan.Count -ne $lista.Count) { Save-Recordatorios $quedan }
}

# =====================================================================
# MICRO-CHARLA: un comentario espontaneo al dia, y solo si viene a cuento.
# =====================================================================
$CharlaOn = [bool](Get-Cfg 'charla' 'activada' $true)
$script:charlaAgua = ''
$script:charlaTarde = ''

# =====================================================================
# LOGROS DE STEAM: Steam reescribe appcache\stats\UserGameStats_<usuario>_<app>.bin
# cuando cambian los logros del juego que esta corriendo. Se vigila la fecha
# del archivo del juego activo: si cambia, medalla. (Tambien cambia con otras
# estadisticas: puede haber algun falso positivo; una medalla de mas no duele.)
# =====================================================================
$script:logroArchivo = ''
$script:logroStamp = [DateTime]::MinValue
$script:logroUltimo = 0
$script:logroClave = ''     # el appid del juego que se esta vigilando, para la fecha en disco

# LOS LOGROS QUE NADIE VE (25/09)
#
# LO MEDIDO: "LOGRO (stats de Steam cambiaron)" sale CINCO veces en dieciseis dias -tres el
# 15/09, una el 19 y una el 20-, y ninguna desde entonces. Y no es que el mecanismo este roto:
# los .bin que vigila SIGUEN cambiando, el mas reciente el 24/09 a las 22:41 (A Way Out).
#
# POR QUE NO LO VE, y son dos agujeros del mismo sitio:
#   1. $script:logroStamp vive SOLO EN RAM. Nova se apaga, y la fecha del fichero se olvida:
#      lo que pasara mientras no estaba no existio. El 24/09 a las 22:41 cambio el .bin y en el
#      registro no hay ni una linea entre las 21 y las 23 de ese dia. Nova estaba apagada.
#   2. Cada vez que el juego sale del primer plano se hace "$script:logroArchivo = ''", y al
#      volver la primera pasada SOLO apunta la fecha y se va con un return. O sea que un logro
#      conseguido entre salir y volver tampoco se ve. El 23/09 hubo dos alt-tab en 70 segundos.
#
# EL ARREGLO es guardar la fecha en disco por juego, que es lo unico que faltaba: al volver -o
# al arrancar- se compara contra lo GUARDADO en vez de contra lo que se acaba de leer.
#
# Y LA PRIMERA VEZ NO CANTA, a proposito: sin nada guardado no se sabe si el fichero cambio
# ayer o hace un mes, y una medalla por instalar Nova seria justo el falso positivo que
# quitaria credito a los de verdad. La primera vez se apunta y se calla.
$LogrosStampPath = Join-Path $MemoriaDir 'logros-stamp.json'
$script:logrosStamp = $null

function Get-LogrosStamp {
    if ($null -ne $script:logrosStamp) { return $script:logrosStamp }
    $script:logrosStamp = @{}
    if (Test-Path -LiteralPath $LogrosStampPath) {
        try {
            $cL = Get-Content -LiteralPath $LogrosStampPath -Raw -Encoding UTF8 | ConvertFrom-Json
            foreach ($pL in @($cL.PSObject.Properties)) { $script:logrosStamp[$pL.Name] = [string]$pL.Value }
        } catch { Log ('logros: no pude leer las fechas guardadas: ' + $_.Exception.Message) }
    }
    return $script:logrosStamp
}

function Save-LogrosStamp {
    try {
        $hL = Get-LogrosStamp
        $oL = [ordered]@{}
        foreach ($kL in @($hL.Keys | Sort-Object)) { $oL[$kL] = [string]$hL[$kL] }
        [System.IO.File]::WriteAllText($LogrosStampPath + '.tmp', (ConvertTo-Json -InputObject $oL -Depth 3), (New-Object System.Text.UTF8Encoding($false)))
        Move-Item -LiteralPath ($LogrosStampPath + '.tmp') -Destination $LogrosStampPath -Force
    } catch { Log ('logros: no pude guardar las fechas: ' + $_.Exception.Message) }
}

# SI ESTA FECHA ES UN LOGRO NUEVO. Aparte para poderla probar sin Steam delante.
# Se compara con -gt y no con -ne (que es lo que hacia antes): si algun dia se restaura una
# copia de seguridad de Steam, el .bin puede quedarse con una fecha ANTERIOR a la guardada, y
# eso no es un logro, es un retroceso. Con -ne se cantaria igual.
function Test-LogroNuevo([string]$guardado, [datetime]$ahora) {
    if (-not $guardado) { return $false }     # primera vez: se apunta y se calla
    try {
        $gL = [datetime]::Parse($guardado, [Globalization.CultureInfo]::InvariantCulture,
                                [Globalization.DateTimeStyles]::RoundtripKind)
    } catch {
        # QUE NO SE CALLE (25/09, lo cazo una rotura). $false es TAMBIEN la respuesta buena
        # -"esto no es un logro"-, asi que una fecha corrupta en el fichero dejaria de dar
        # medallas para siempre y por fuera pareceria que braya no consigue ninguna. Es la
        # manera 10 de que un banco salga verde mintiendo. Con la linea, se ve.
        Log ("logros: no entiendo la fecha guardada ('" + $guardado + "'): " + $_.Exception.Message)
        return $false
    }
    return ($ahora -gt $gL)
}

function Watch-LogrosSteam {
    if (-not $script:juegoActivo) { $script:logroArchivo = ''; return }
    try {
        if (-not $script:logroArchivo) {
            $j = @($script:Juegos | Where-Object { $_.nombre -eq $script:juegoActivo }) | Select-Object -First 1
            if (-not $j) { return }
            $sp = (Get-ItemProperty 'HKCU:\Software\Valve\Steam' -ErrorAction SilentlyContinue).SteamPath -replace '/', '\'
            $f = Get-ChildItem -LiteralPath (Join-Path $sp 'appcache\stats') -Filter "UserGameStats_*_$($j.id).bin" -ErrorAction SilentlyContinue | Select-Object -First 1
            if (-not $f) { $script:logroArchivo = '-'; return }
            $script:logroArchivo = $f.FullName
            $script:logroStamp = $f.LastWriteTimeUtc
            $script:logroClave = [string]$j.id
            # AQUI ESTABA EL AGUJERO: antes se apuntaba la fecha y se volvia con un return, o
            # sea que lo que hubiera pasado con Nova apagada -o entre dos alt-tab- no se veia
            # nunca. Ahora se compara contra lo que quedo GUARDADO la ultima vez.
            $hL = Get-LogrosStamp
            $antesL = [string]$hL[$script:logroClave]
            $hL[$script:logroClave] = $script:logroStamp.ToString('o')
            Save-LogrosStamp
            if (Test-LogroNuevo $antesL $script:logroStamp) {
                $script:logroUltimo = $sw.ElapsedMilliseconds
                Log "LOGRO (stats de Steam cambiaron mientras no miraba) en $($script:juegoActivo)"
                # y se cuenta para el resumen de la sesion (1/10, la 20 de las 20)
                $script:logrosSesion = [int]$script:logrosSesion + 1
                Send-UIEvento 'logro'
            }
            return
        }
        if ($script:logroArchivo -eq '-') { return }
        $st = [System.IO.File]::GetLastWriteTimeUtc($script:logroArchivo)
        if ($st -ne $script:logroStamp) {
            $script:logroStamp = $st
            # Y QUE SOBREVIVA AL PROXIMO APAGON: se guarda en cuanto cambia, no al salir.
            # Nova no siempre se apaga por las buenas -el 24/09 hay catorce arranques- y una
            # fecha que solo se escribe al cerrar limpiamente es una fecha que se pierde.
            try {
                if ($script:logroClave) {
                    (Get-LogrosStamp)[$script:logroClave] = $st.ToString('o')
                    Save-LogrosStamp
                }
            } catch {}
            if (($sw.ElapsedMilliseconds - $script:logroUltimo) -ge 120000) {
                $script:logroUltimo = $sw.ElapsedMilliseconds
                Log "LOGRO (stats de Steam cambiaron) en $($script:juegoActivo)"
                # y se cuenta para el resumen de la sesion (1/10, la 20 de las 20)
                $script:logrosSesion = [int]$script:logrosSesion + 1
                Send-UIEvento 'logro'
            }
        }
    } catch {}
}

# =====================================================================
# ACELEROMETRO (WinRT): un golpe o sacudida de la consola sobresalta a la
# capsula. Si el sensor no existe, no se hace nada.
# =====================================================================
$script:acelerometro = $null
$script:acelCheck = 0
$script:acelUltimo = 0
# ESO YA NO ES VERDAD EN ESTA CONSOLA (27/09, idea 83). El comentario de arriba decia que
# GetCurrentReading() "tarda 5 s y devuelve null SIEMPRE", y por eso config.json lo tenia apagado.
# Medido hoy con el MISMO camino que usa este codigo -ReportInterval fijado antes de leer-: la
# primera lectura tarda 33,1 ms (la guarda corta en 150), y de 30 lecturas seguidas CERO son nulas,
# con media 2,94 ms y maximo 17,1. O sea que el sensor funciona y llevaba apagado por una medicion
# vieja. Por defecto se enciende; la guarda de Watch-Acelerometro sigue ahi para la consola donde
# esto no sea cierto, y lo apaga para siempre en la primera lectura.
#
# PARA QUE SIRVE, y es lo que lo justifica: 4.153 lineas "ENTORNO aparcado (no hay nadie...)" en el
# registro actual, que tiene 7.924: el 52 % de lo que Nova escribe es apuntar que no hay nadie a
# quien hablar, y siete de esos avisos caducaron sin decirse nunca. Con el acelerometro sabe que
# braya la tiene en la mano aunque no haya tocado un boton, y suelta ahi lo que lleva guardado.
if ([bool](Get-Cfg 'sensores' 'acelerometro' $true)) {
    try {
        $null = [Windows.Devices.Sensors.Accelerometer, Windows.Devices.Sensors, ContentType = WindowsRuntime]
        $script:acelerometro = [Windows.Devices.Sensors.Accelerometer]::GetDefault()
        if ($script:acelerometro) { Log "acelerometro: disponible (se probara la primera lectura)" } else { Log "acelerometro: no hay sensor" }
    } catch { $script:acelerometro = $null; Log "acelerometro: no disponible" }
}

# LA ORIENTACION (27/09, idea 69). SimpleOrientationSensor dice si la consola esta tumbada boca
# arriba sin cuestas: medido hoy en esta Ally, PRESENTE, devuelve Faceup y cuesta 0,157 ms por
# lectura (200 llamadas). El acelerometro, que daria lo mismo, cuesta 15,52 ms medidos -99 veces
# mas- y por eso sigue apagado: nunca por GetCurrentReading dentro del bucle.
#
# NO HACE FALTA INTERRUPTOR EN config.json y es a proposito: a diferencia del acelerometro, este
# sensor no bloquea, y ademas lleva la MISMA guarda -si la primera lectura tarda o viene vacia, se
# apaga para siempre-. Un interruptor apagado por defecto lo dejaria muerto como esta el otro.
$script:orientacion = $null
$script:orientaProbado = $false
$script:orientaCheck = 0
$script:orientacionPlana = $false      # Faceup o Facedown: la consola esta tumbada
$script:orientaPlanaEn = 0             # ms del bucle desde que esta asi
try {
    $null = [Windows.Devices.Sensors.SimpleOrientationSensor, Windows.Devices.Sensors, ContentType = WindowsRuntime]
    $script:orientacion = [Windows.Devices.Sensors.SimpleOrientationSensor]::GetDefault()
    if ($script:orientacion) { Log 'orientacion: sensor disponible (se probara la primera lectura)' } else { Log 'orientacion: no hay sensor' }
} catch { $script:orientacion = $null; Log 'orientacion: no disponible' }

function Watch-Orientacion {
    if (-not $script:orientacion) { return }
    try {
        if (-not $script:orientaProbado) {
            $script:orientaProbado = $true
            # LA PRIMERA LECTURA NO VALE PARA MEDIR, y por poco mata el sensor: cazado por el
            # banco el 27/09, cuesta 11,96 ms de estreno y 1,86 ms en caliente. Midiendo la
            # primera, la guarda de abajo lo habria desactivado para siempre en la unica
            # consola donde funciona. Se calienta con una lectura que no se mide -igual que se
            # calento la medicion de 0,157 ms de la que sale el numero- y se juzga la segunda.
            $o0 = $script:orientacion.GetCurrentOrientation()
            $t = [System.Diagnostics.Stopwatch]::StartNew()
            $o0 = $script:orientacion.GetCurrentOrientation()
            # 5 ms es mas de treinta veces lo medido en caliente: si tarda eso, este sensor no
            # es el que se midio y no se paga en cada vuelta. La misma guarda que el acelerometro.
            if ($t.Elapsed.TotalMilliseconds -gt 5 -or $null -eq $o0) {
                Log ('orientacion: lectura lenta o vacia (' + [Math]::Round($t.Elapsed.TotalMilliseconds, 2) + ' ms, nulo=' + ($null -eq $o0) + '); desactivada')
                $script:orientacion = $null
                return
            }
            Log ('orientacion: lecturas OK (' + [Math]::Round($t.Elapsed.TotalMilliseconds, 3) + ' ms, ' + [string]$o0 + ')')
        }
        $o = $script:orientacion.GetCurrentOrientation()
        if ($null -eq $o) { return }
        $plana = ([string]$o -eq 'Faceup' -or [string]$o -eq 'Facedown')
        if ($plana -ne $script:orientacionPlana) {
            $script:orientacionPlana = $plana
            $script:orientaPlanaEn = $sw.ElapsedMilliseconds
            Log ('orientacion: ' + $(if ($plana) { 'tumbada (' + [string]$o + ')' } else { 'en la mano (' + [string]$o + ')' }))
        }
    } catch { $script:orientacion = $null }
}
$script:acelProbado = $false
# EL MOVIMIENTO, ADEMAS DEL SOBRESALTO (27/09, idea 83). El mismo sensor que ya detecta el golpe
# sirve para saber si la consola esta en la mano: se compara la magnitud con la de la lectura
# anterior y, si la diferencia pasa del ruido de su propio reposo, hay alguien moviendola.
#
# EL UMBRAL SALE DE SU PROPIO REPOSO, no de un numero: es el p90 de las diferencias que ve, por
# tres. En reposo esas diferencias son minusculas, asi que el liston se pone solo justo encima del
# ruido de esta consola y de esta mesa.
#
# Y SE EXIGE QUE SE REPITA: dos lecturas seguidas por encima del liston. Un pico suelto es la mesa
# al recibir un golpe, no braya cogiendo la consola.
$AcelDeltasMemoria = 200
$AcelDeltasMin = 40             # menos que esto y no se opina de movimiento
$AcelUmbralMin = 0.02           # suelo: por debajo de esto es ruido en cualquier maquina
# OJO CON EL NOMBRE: PowerShell NO distingue mayusculas en las variables, asi que esta
# constante y el contador $script:acelRacha serian LA MISMA si se llamaran igual -y el
# contador la machacaba, dejando el minimo en 1: un golpe en la mesa contaba como braya.
# Lo cazo el banco de esta idea. Nombres distintos a proposito.
$AcelRachaMin = 2               # lecturas seguidas para llamarlo movimiento
# LO QUE CUENTA COMO "LECTURA LENTA", EN UN SOLO SITIO (30/09). Este numero ya estaba escrito a
# pelo dentro de Watch-Acelerometro para la primera lectura, y ahora lo usan las dos guardas: la
# de la primera y la de todas las demas. Escrito dos veces se separarian el dia que alguien tocara
# una, que es la manera 4 de salir verde mintiendo.
# NO ES UN NUMERO QUE NOVA DEBA AJUSTAR: es el corte entre "el sensor responde" y "el sensor tarda
# cinco segundos", y entre esas dos cosas no hay medio camino que aprender. En la Ally la lectura
# buena tarda menos de 10 ms y la mala 5.015: cualquier corte entre medias vale igual.
$AcelLecturaLentaMs = 150
$AcelLentasMax = 2              # lentas o vacias SEGUIDAS antes de apagarlo; con 2 ya van 10 s
$script:acelLentas = 0
$script:acelMagAntes = 0.0
$script:acelDeltas = New-Object System.Collections.ArrayList
$script:acelRacha = 0
$script:movidoEn = 0            # ms del bucle de la ultima vez que se movio de verdad

function Get-AcelUmbral {
    if ($script:acelDeltas.Count -lt $AcelDeltasMin) { return 0.0 }   # 0 = todavia no lo se
    return [Math]::Max($AcelUmbralMin, (Get-PercentilLista $script:acelDeltas 90) * 3.0)
}

# Minutos desde que la consola se movio, hermana de Get-InactividadMin. -1 si no se sabe (sensor
# apagado, sin umbral aun, o sin haberla visto moverse en esta sesion): eso NO es "no hay nadie".
# LA PANTALLA LLEVA HORAS ENCENDIDA Y LA CONSOLA ESTA PUESTA PARA NO APAGARLA NUNCA
# (27/09, idea 121 de las 121, la ultima de la tanda)
#
# EL DATO, medido ahora mismo en esta consola:
#   powercfg /query SCHEME_CURRENT SUB_VIDEO VIDEOIDLE -> indice 0x00000000 en corriente ALTERNA y
#   en CONTINUA, o sea "apagar la pantalla tras: nunca" en las dos. Y WmiMonitorBrightness marca
#   CurrentBrightness = 100.
# Con eso, los 4.187 avisos aparcados por no haber nadie no son ratos cortos: son noches enteras con
# la pantalla encendida a tope.
#
# Y NOVA NO SABE NADA DE ESTO: cero apariciones de LastBootUpTime, de uptime y de SendMessage en todo
# el archivo. El plan de energia activo tampoco lo ve, porque Get-ModoEnergia lee el deslizador de
# Windows, que es otra cosa.
#
# UN DATO DE LA FICHA YA NO ES CIERTO, Y SE DICE: hablaba de 158,9 horas encendida desde el 19/09.
# Medido hoy, la consola arranco a las 02:57 y lleva 11,6 horas: braya la ha reiniciado. El argumento
# de "seis dias sin apagarse" se ha caido solo, asi que lo que queda en pie es lo otro, que sigue
# siendo verdad: la pantalla no se apaga NUNCA por si sola, ni enchufada ni con bateria.
#
# POR ESO ESTO SE MIDE Y SE DICE, Y NO SE HACE SOLO. Apagarle la pantalla es una accion sobre su
# maquina, inmediata y visible, y el riesgo que la propia ficha nombra es real: que se la apague
# mientras mira un video o una guia sin tocar nada. Asi que la maquinaria queda escrita y probada, el
# dato se le cuenta -que es lo que hoy no tiene-, y el interruptor nace APAGADO en config.json. El
# dia que braya lo encienda, las tres guardas de abajo estan puestas. Es el mismo criterio que la
# idea 110 y la 111: primero se mide, y la decision espera a tener con que tomarse.
$PantallaApagarOn = [bool](Get-Cfg 'entorno' 'apagarPantalla' $false)
# EL PLAZO VA EN CONFIG Y NO SALE DE UN DATO SUYO, y hay que decir por que: la pantalla de braya no
# se ha apagado NUNCA -powercfg da 0 en alterna y en continua-, asi que no hay ni una medicion de
# cuanto tarda el en volver despues de dejarla sola. Sin historial no se inventa un percentil: el
# numero se escribe, se dice que esta escrito, y queda donde braya lo pueda tocar. Media hora es lo
# que Windows trae de fabrica en un portatil, que es el unico punto de partida que hay.
$PantallaApagarMin = [int](Get-Cfg 'entorno' 'apagarPantallaMin' 30)
$PantallaAltavozMin = 0.01       # el mismo suelo de nivel que usa el aviso de cascos
$script:pantallaApagadaEn = 0
$script:pantallaDichoDia = ''

# Lo que Windows tiene puesto: cuantos segundos tarda en apagar la pantalla, o 0 si nunca.
# Cuesta 34 ms medidos, asi que se pregunta UNA VEZ AL DIA y no en el bucle.
function Get-PantallaApagaTras {
    $r = @{ alterna = -1; continua = -1 }
    try {
        $sal = @(powercfg /query SCHEME_CURRENT SUB_VIDEO VIDEOIDLE 2>$null)
        foreach ($l in $sal) {
            # el texto de powercfg esta traducido, asi que se busca el numero, no la palabra
            $m = [regex]::Match([string]$l, '(?i)(alterna|continua|\bAC\b|\bDC\b)[^:]*:\s*0x([0-9a-f]{8})')
            if (-not $m.Success) { continue }
            $seg = [Convert]::ToInt64($m.Groups[2].Value, 16)
            if ($m.Groups[1].Value -match '(?i)alterna|AC') { $r.alterna = [int]$seg } else { $r.continua = [int]$seg }
        }
    } catch {}
    return $r
}

# Cuantas horas lleva la consola encendida. -1 si no se puede saber.
function Get-HorasEncendida([datetime]$ahora = (Get-Date)) {
    try {
        $b = (Get-CimInstance Win32_OperatingSystem -ErrorAction Stop).LastBootUpTime
        if (-not $b) { return -1.0 }
        $h = ($ahora - $b).TotalHours
        if ($h -lt 0 -or $h -gt 8760) { return -1.0 }   # un reloj movido no es un dato
        return [Math]::Round($h, 1)
    } catch { return -1.0 }
}

# El nivel que el worker deja en el TERCER campo de escucha-estado.txt. -1 si no se sabe, que NO es
# cero: un -1 tratado como silencio apagaria la pantalla con un video sonando.
function Get-NivelAltavoces {
    if (-not (Test-Path -LiteralPath $RutaEstado)) { return -1.0 }
    if (-not (Test-EstadoFresco)) { return -1.0 }
    try {
        $st = ([System.IO.File]::ReadAllText($RutaEstado).Trim()) -split '\|'
        if ($st.Count -lt 3) { return -1.0 }
        $d = 0.0
        if ([double]::TryParse($st[2].Trim(), [System.Globalization.NumberStyles]::Float, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$d)) { return $d }
    } catch {}
    return -1.0
}

# PURA: dice si toca apagar la pantalla, y si no, por que no. Las tres guardas de la ficha, y una
# cuarta que ella no pide: no saber algo NUNCA cuenta a favor de apagar.
function Test-ApagarPantalla([int]$nadieMin, [int]$movidoMin, [double]$nivel, [bool]$hayJuego,
                             [int]$plazoMin, [bool]$encendido = $true) {
    if (-not $encendido) { return @{ apagar = $false; porque = 'no me has dicho que lo haga' } }
    if ($hayJuego) { return @{ apagar = $false; porque = 'hay un juego delante' } }
    # LOS ALTAVOCES: si estan dando nivel, hay algo sonando y eso es alguien viendo algo. Y si no se
    # sabe -el -1-, tampoco se apaga: es el riesgo que la ficha nombra.
    if ($nivel -lt 0) { return @{ apagar = $false; porque = 'no se si suena algo' } }
    if ($nivel -gt $PantallaAltavozMin) { return @{ apagar = $false; porque = 'algo esta sonando' } }
    # EL MOVIMIENTO, que es la senal que la ficha pide: no basta el teclado. Si el acelerometro dice
    # que la consola se movio hace poco, hay alguien. Y si no lo sabe (-1), no decide nada: manda la
    # otra senal.
    if ($movidoMin -ge 0 -and $movidoMin -lt $plazoMin) { return @{ apagar = $false; porque = 'la has movido hace ' + $movidoMin + ' min' } }
    if ($nadieMin -lt 0) { return @{ apagar = $false; porque = 'no se si hay alguien' } }
    if ($nadieMin -lt $plazoMin) { return @{ apagar = $false; porque = 'hace ' + $nadieMin + ' min que habia alguien' } }
    # EL [string] NO SOBRA: con el int delante, PowerShell intenta SUMAR la cadena y peta
    return @{ apagar = $true; porque = [string]$nadieMin + ' min sin nadie y sin nada sonando' }
}

# LA MANDA A DORMIR. Una linea, y nada queda puesto: cualquier tecla, el raton, el mando o la propia
# Nova al ver movimiento la encienden.
function Set-PantallaApagada([bool]$apagar = $true) {
    try {
        # HWND_BROADCAST = 0xffff, WM_SYSCOMMAND = 0x0112, SC_MONITORPOWER = 0xF170
        # lParam: 2 = apagar, -1 = encender
        $lp = if ($apagar) { [IntPtr]2 } else { [IntPtr](-1) }
        [void][Nova.Win]::SendMessage([IntPtr]0xffff, 0x0112, [IntPtr]0xF170, $lp)
        return $true
    } catch { Log ('pantalla: no pude ' + $(if ($apagar) { 'apagarla' } else { 'encenderla' }) + ' (' + $_.Exception.Message + ')'); return $false }
}

# Y QUIEN LA MANDA A DORMIR DE VERDAD (cableado tras la revision del 27/09)
#
# EL FALLO QUE ESTO ARREGLA ERA MIO Y DE HONESTIDAD: Test-ApagarPantalla, Set-PantallaApagada y
# Get-NivelAltavoces se escribieron con sus guardas y sus bancos... y NO LAS LLAMABA NADIE. Cada una
# aparecia UNA vez en el fichero: su propia definicion. Y el comentario decia "el dia que braya lo
# encienda, las tres guardas de abajo estan puestas", que se lee como "enciendelo y funciona": poner
# entorno.apagarPantalla = true no hacia absolutamente nada. Noventa lineas muertas y un interruptor
# de pega. Ahora esta cableado de verdad, y sigue naciendo APAGADO.
#
# EL PLAZO SE MIRA UNA VEZ POR MINUTO, no en cada vuelta: la decision necesita Get-NadieMin, que lee
# habitos, el ocio de Windows, el mando y el acelerometro. Y la enciende Nova en cuanto ve a alguien,
# que es la segunda salida que la regla 2 pide (la primera es cualquier tecla, raton o mando, que la
# enciende sin que Nova haga nada).
function Watch-PantallaDormida([datetime]$ahora = (Get-Date)) {
    if (-not $PantallaApagarOn) { return $false }
    $nadie = -1
    try { $nadie = [int](Get-NadieMinFrenado) } catch { $nadie = -1 }
    $movido = -1
    try { $movido = [int](Get-MovimientoMin) } catch { $movido = -1 }
    $nivel = -1.0
    try { $nivel = [double](Get-NivelAltavoces) } catch { $nivel = -1.0 }
    $d = Test-ApagarPantalla $nadie $movido $nivel ([bool]$script:juegoActivo) $PantallaApagarMin $true
    if ($d.apagar) {
        # UNA VEZ, NO EN CADA MINUTO: si ya la apago y sigue sin haber nadie, Windows la tiene
        # apagada y repetir el mensaje no hace nada. Se vuelve a permitir cuando alguien aparece.
        if ($script:pantallaApagadaEn -gt 0) { return $false }
        if (Set-PantallaApagada $true) {
            $script:pantallaApagadaEn = $sw.ElapsedMilliseconds
            Log ('PANTALLA: la apago, ' + [string]$d.porque)
            try { Add-Estadistica 'pantalla-off' ([string]$d.porque) } catch {}
            return $true
        }
        return $false
    }
    # Y LA ENCIENDE EN CUANTO HAY ALGUIEN, sin esperar a que braya toque nada: es la salida que
    # convierte esto en algo que no se queda puesto.
    if ($script:pantallaApagadaEn -gt 0) {
        $script:pantallaApagadaEn = 0
        [void](Set-PantallaApagada $false)
        Log ('PANTALLA: la enciendo, ' + [string]$d.porque)
    }
    return $false
}

# Y LO QUE SI SE HACE HOY: contarselo. Una vez al dia, y solo si de verdad esta puesta para no
# apagarse nunca; si Windows ya la apaga solo, aqui no hay noticia.
function Test-DecirPantalla([datetime]$ahora = (Get-Date)) {
    $dia = $ahora.ToString('yyyy-MM-dd')
    if ($script:pantallaDichoDia -eq $dia) { return $false }
    $script:pantallaDichoDia = $dia
    try {
        $c = Get-PantallaApagaTras
        if ([int]$c.alterna -ne 0 -and [int]$c.continua -ne 0) { return $false }
        $h = Get-HorasEncendida $ahora
        # NI "NUNCA" A SECAS CUANDO SOLO ES UNO DE LOS DOS (arreglado tras la revision): el texto
        # decia "Windows esta puesto para no apagarla nunca (alterna 0, continua 600)", y eso es
        # mentir en la primera mitad y desmentirse en la segunda, con los dos numeros al lado. Hoy
        # en la Ally las dos valen 0 y acertaba por suerte; el dia que braya ponga un apagado solo
        # con bateria, diria lo contrario de lo que ella misma imprime.
        $quien = if ([int]$c.alterna -eq 0 -and [int]$c.continua -eq 0) { 'ni enchufada ni con bateria' }
                 elseif ([int]$c.alterna -eq 0) { 'estando enchufada' }
                 else { 'con bateria' }
        Log ('PANTALLA: Windows no la apaga sola ' + $quien + ' (alterna ' + $c.alterna + ', continua ' +
             $c.continua + ')' + $(if ($h -ge 0) { '; la consola lleva ' + $h + ' h encendida' } else { '' }) +
             '; yo puedo apagarla a los ' + $PantallaApagarMin + ' min sin nadie con entorno.apagarPantalla, hoy en ' + $PantallaApagarOn)
        return $true
    } catch { return $false }
}

function Get-MovimientoMin {
    if (-not $script:acelerometro) { return -1 }
    if ($script:movidoEn -le 0) { return -1 }
    return [int](($sw.ElapsedMilliseconds - $script:movidoEn) / 60000)
}
function Watch-Acelerometro {
    if (-not $script:acelerometro) { return }
    try {
        # GUARDA: en la Ally el sensor "existe" pero GetCurrentReading tarda
        # 5 s y devuelve null. Llamado cada 250 ms bloqueaba el asistente
        # entero (se descubrio porque las ordenes tardaban 30 s en leerse).
        # Si la primera lectura es lenta o vacia, se apaga para siempre.
        if (-not $script:acelProbado) {
            $script:acelProbado = $true
            try { $script:acelerometro.ReportInterval = [Math]::Max(100, $script:acelerometro.MinimumReportInterval) } catch {}
            $t = [System.Diagnostics.Stopwatch]::StartNew()
            $r0 = $script:acelerometro.GetCurrentReading()
            if ($t.ElapsedMilliseconds -gt $AcelLecturaLentaMs -or -not $r0) {
                Log ("acelerometro: sin lecturas utiles (" + $t.ElapsedMilliseconds + " ms, nulo=" + ($null -eq $r0) + "); desactivado")
                $script:acelerometro = $null
                return
            }
            Log "acelerometro: lecturas OK"
        }
        # Y LA GUARDA VALE PARA TODAS, NO SOLO PARA LA PRIMERA (30/09). Medido en esta consola con
        # el banco de 2n236: la primera lectura pasa -"lecturas OK"- y las VEINTE siguientes tardan
        # 5.015 ms de media y devuelven null, o sea exactamente el fallo que este comentario
        # describe, pero por la puerta que la guarda no miraba. Se colaba entero: el 'if (-not $r)
        # { return }' se lo tragaba en silencio, sin un delta y sin una linea de log, y el bucle se
        # comia CINCO SEGUNDOS por vuelta. Es la misma forma del 41 -algo que cuesta lo que nadie
        # midio porque nadie lo estaba mirando-.
        # NO SE APAGA POR UN HIPO: hace falta una racha, porque una lectura lenta suelta puede ser
        # el sistema ocupado y apagar el sensor es para siempre. Con dos seguidas ya van 10 s
        # perdidos, asi que la racha es corta a proposito.
        $tL = [System.Diagnostics.Stopwatch]::StartNew()
        $r = $script:acelerometro.GetCurrentReading()
        $tL.Stop()
        if ($tL.ElapsedMilliseconds -gt $AcelLecturaLentaMs -or -not $r) {
            $script:acelLentas++
            if ($script:acelLentas -ge $AcelLentasMax) {
                Log ("acelerometro: " + $script:acelLentas + " lecturas seguidas lentas o vacias (la ultima, " +
                     $tL.ElapsedMilliseconds + " ms, nulo=" + ($null -eq $r) + "); desactivado para no frenar el bucle")
                $script:acelerometro = $null
            }
            return
        }
        $script:acelLentas = 0
        $mag = [Math]::Sqrt($r.AccelerationX * $r.AccelerationX + $r.AccelerationY * $r.AccelerationY + $r.AccelerationZ * $r.AccelerationZ)
        # ¿SE ESTA MOVIENDO? (idea 83). Ver EL MOVIMIENTO, ADEMAS DEL SOBRESALTO.
        if ($script:acelMagAntes -gt 0) {
            $delta = [Math]::Abs($mag - $script:acelMagAntes)
            [void]$script:acelDeltas.Add([double]$delta)
            while ($script:acelDeltas.Count -gt $AcelDeltasMemoria) { $script:acelDeltas.RemoveAt(0) }
            $umbral = Get-AcelUmbral
            if ($umbral -gt 0 -and $delta -gt $umbral) {
                $script:acelRacha++
                if ($script:acelRacha -ge $AcelRachaMin) { $script:movidoEn = $sw.ElapsedMilliseconds }
            } else {
                $script:acelRacha = 0
            }
        }
        $script:acelMagAntes = $mag
        if ([Math]::Abs($mag - 1.0) -gt 0.7 -and ($sw.ElapsedMilliseconds - $script:acelUltimo) -ge 5000) {
            $script:acelUltimo = $sw.ElapsedMilliseconds
            Log ("SACUDIDA: {0:0.00} g" -f $mag)
            Send-UIEvento 'gesto:sobresalto'
        }
    } catch { $script:acelerometro = $null }
}

# =====================================================================
# NOTA SEMANAL: memoria\semanas\AAAA-Www.md, escrita en lenguaje hablado a
# partir de las estadisticas y del diario de gestos. Una por semana vencida.
# =====================================================================
# LO QUE DECIDI YO SOLA, en el parte semanal (17/09). La nota ya contaba cuantas cosas
# pediste, cuantas se resolvieron al instante y que no entendi... pero hablaba solo de ti.
# Desde esta tanda Nova toma decisiones propias (apagar la nube, el oido fino o el ultimo
# recurso, avisar de que su idea de tu voz se movio), y no estaban en ninguna parte que
# leyeras: solo en el log.
#
# La regla de la lista: si no puede explicar una decision con un numero, es que no deberia
# haberla tomado. Aqui se cumple sola, porque el detalle que se guarda YA trae el numero
# ("ultimo recurso off: 1 de 29").
#
# Si esa semana no decidio nada, no escribe ninguna linea: un parte que dice "no hice nada
# especial" cansa mas de lo que informa.
# LEER EL FICHERO DE LO IMPORTANTE (27/09, idea 79)
#
# EL AGUJERO: desde el 25/09 el worker copia a memoria\cerebro\importante.jsonl cada turno en que
# braya corrige y cada turno en que Nova admite que no sabe algo. Se escribia en modo 'a' y NO LO
# LEIA NADIE: cero lectores en todo el repositorio fuera de dos bancos. Es el inventario de sus
# agujeros y estaba muerto en el disco.
#
# EL REPARTO DEL TRABAJO: el worker agrupa (usa fichas(), que vive en su lado) y deja el resultado
# en agujeros.json; aqui se hace lo que el worker NO puede hacer: probar EN SECO si eso que Nova
# dijo que no sabia es algo que SI sabe. De los 8 agujeros contados en el registro, TRES eran
# falsos: dos veces '¿que hora es?' -contesto 'no tengo acceso a la hora actual de tu consola'- y
# una el clima, que se arreglo a mano el 15/09.
#
# EN SECO DE VERDAD: Test-FastCommand dice si la frase tiene una orden que Nova resuelve, y no
# ejecuta nada. Nunca se llama a Invoke-FastCommand desde aqui.
$AgujerosJson = Join-Path $MemoriaDir 'cerebro\agujeros.json'
function Get-AgujerosSemana {
    # devuelve @{ total; repetidos = @(@{ veces; frase; falso }) } o $null si no hay nada que leer
    try {
        if (-not (Test-Path -LiteralPath $AgujerosJson)) { return $null }
        $j = Get-Content -LiteralPath $AgujerosJson -Raw -Encoding UTF8 | ConvertFrom-Json
        $tot = [int]$j.total
        if ($tot -le 0) { return $null }
        $rep = New-Object System.Collections.ArrayList
        foreach ($g in @($j.grupos)) {
            if ([int]$g.veces -lt 2) { continue }          # lo que paso una vez no es un agujero suyo
            $fr = [string]$g.frase
            $falso = $false
            # LA PRUEBA EN SECO: ¿sabria resolverlo hoy? Si si, el agujero es mentira.
            try { $falso = [bool](Test-FastCommand $fr) } catch { $falso = $false }
            [void]$rep.Add(@{ veces = [int]$g.veces; frase = $fr; falso = $falso })
        }
        return @{ total = $tot; repetidos = @($rep) }
    } catch { return $null }
}

# LA FRASE DE EJEMPLO DE WHISPER, ESCRITA CON SUS PROPIAS ORDENES (27/09, idea 118 de las 121)
#
# EL DATO: a Whisper se le pasa siempre la misma frase, escrita a mano el 14/09 -"Nova, abre Steam.
# Sube el volumen. Pon el modo noche. Que hora es? Baja el brillo."- y no se ha movido desde
# entonces. Contadas las primeras palabras de las 226 ordenes utiles de destinos.jsonl:
#     abre 23, cierra 18, que 12, mira 10, dime 6, pon 4, sube 1
# La frase lleva 'sube' (UNA orden real en todo el historial) y 'baja' (tres), y NO lleva 'cierra',
# que son dieciocho.
#
# Y 'CIERRA' ES JUSTO EL QUE PEOR SE OYE: 21 veces salio deformado en el registro, y no de milagro:
#     'Tierra Steam y pon un tempon'   'Tierra el navegador'   'Sierra Gul'   'Sierra and the Ring'
#     'Si es Steam'                    'Si es el navegador'    'Sierra Paint' 'Si es a los ajutos'
# Veintiuna ordenes de cerrar que acabaron en otra parte, con el verbo mas usado despues de 'abre'
# fuera del unico sitio donde se le puede dar una pista al reconocedor.
#
# LAS DOS GUARDAS DEL 14/09 SE RESPETAN ENTERAS, porque estan medidas y son lo unico que sostiene
# que esta frase funcione: sin numeros -"al treinta" dentro hacia que "pon el juego al ochenta" se
# oyera "al treinta"- y sin nombres de juegos -"Abre Little Nightmares III" se inventaba ese juego
# en frases que no lo decian-. Por eso NO se usan las ordenes reales de braya, que traen las dos
# cosas: de cada verbo se coge una PLANTILLA fija escrita aqui. El dato de su uso elige QUE verbos
# entran; el texto de cada frase no sale de sus grabaciones.
#
# Y es_eco_del_ejemplo no se toca: parte la frase por puntuacion, asi que sigue valiendo para
# cualquier frase que se genere.
$PromptOrdenesPath = Join-Path $TmpDir 'prompt-ordenes.txt'
$PromptOrdenesMax = 5            # las mismas cinco frases que tiene la de hoy
$PromptOrdenesMin = 20           # el liston de la casa: sin historial no se cambia nada
# VERBO -> FRASE, y las frases son de aqui, no de sus grabaciones: ni un numero ni un nombre propio.
# El orden de la tabla no importa; lo que manda es cuanto usa cada verbo.
$PromptFrases = [ordered]@{
    'abre'     = 'Abre el navegador.'
    'cierra'   = 'Cierra la ventana.'
    'pon'      = 'Pon el modo noche.'
    'que'      = '¿Qué hora es?'
    'dime'     = 'Dime la hora.'
    'mira'     = 'Mira el correo.'
    'revisa'   = 'Revisa el correo.'
    'baja'     = 'Baja el brillo.'
    'sube'     = 'Sube el volumen.'
    'busca'    = 'Busca en internet.'
    'silencia' = 'Silencia el sonido.'
    'muevete'  = 'Muévete a la derecha.'
    'activa'   = 'Activa el modo juego.'
    'apaga'    = 'Apaga la pantalla.'
    'lanza'    = 'Lanza el programa.'
}

# PURA: cuenta las primeras palabras de lo que braya pidio de verdad.
# Solo las filas que Nova ATENDIO: una charla o un descarte no es una orden.
function Get-VerbosUsados($filas) {
    $c = @{}
    foreach ($f in @($filas)) {
        if (-not $f) { continue }
        $hizo = [string]$f.hizo
        if ($hizo -notin @('local', 'accion', 'traducir', 'traducida')) { continue }
        $t = ([string]$f.detalle).Trim()
        if (-not $t) { continue }
        $w = @($t -split '\s+')[0]
        $w = (ConvertTo-Plain $w).Trim('.', ',', '?', '!', ';', ':')
        if (-not $w) { continue }
        if (-not $c.ContainsKey($w)) { $c[$w] = 0 }
        $c[$w]++
    }
    return $c
}

# PURA: monta la frase con los verbos que mas usa y que tienen plantilla. Devuelve '' si no hay
# bastante historial, y entonces el worker se queda con la frase de siempre.
function Get-PromptOrdenes($cuenta, [int]$minTotal = 0) {
    if ($minTotal -le 0) { $minTotal = $PromptOrdenesMin }
    $tot = 0
    foreach ($v in @($cuenta.Values)) { $tot += [int]$v }
    if ($tot -lt $minTotal) { return '' }
    $con = @()
    foreach ($k in @($cuenta.Keys)) {
        if (-not $PromptFrases.Contains([string]$k)) { continue }   # sin plantilla no entra
        $con += @(@{ verbo = [string]$k; veces = [int]$cuenta[$k] })
    }
    if ($con.Count -eq 0) { return '' }
    # de mas usado a menos, y con el verbo como desempate para que la frase no baile entre dos
    # arranques con los mismos datos
    $con = @($con | Sort-Object @{ Expression = { -[int]$_.veces } }, @{ Expression = { [string]$_.verbo } })
    $frases = @()
    foreach ($x in @($con | Select-Object -First $PromptOrdenesMax)) {
        $frases += @([string]$PromptFrases[[string]$x.verbo])
    }
    # 'Nova, ' delante de la primera, como la de hoy: es la palabra con la que empieza cada orden
    $primera = [string]$frases[0]
    if ($primera.Length -gt 1) { $primera = 'Nova, ' + $primera.Substring(0, 1).ToLowerInvariant() + $primera.Substring(1) }
    $frases[0] = $primera
    return ($frases -join ' ')
}

# Lo escribe en tmp para que el oido lo lea al arrancar. Devuelve $true si cambio algo.
function Update-PromptOrdenes {
    try {
        $ruta = Join-Path $LogDir 'pruebas\audio\uso\destinos.jsonl'
        if (-not (Test-Path -LiteralPath $ruta)) { return $false }
        $filas = New-Object System.Collections.ArrayList
        foreach ($ln in [System.IO.File]::ReadAllLines($ruta, [System.Text.Encoding]::UTF8)) {
            if (-not $ln -or $ln.Length -lt 10) { continue }
            try { [void]$filas.Add(($ln | ConvertFrom-Json)) } catch { continue }
        }
        $fr = Get-PromptOrdenes (Get-VerbosUsados $filas)
        if (-not $fr) { return $false }
        $antes = ''
        if (Test-Path -LiteralPath $PromptOrdenesPath) {
            try { $antes = ([System.IO.File]::ReadAllText($PromptOrdenesPath, [System.Text.Encoding]::UTF8)).Trim() } catch { $antes = '' }
        }
        if ($antes -eq $fr) { return $false }
        if (-not (Test-Path -LiteralPath $TmpDir)) { New-Item -ItemType Directory -Force -Path $TmpDir | Out-Null }
        [System.IO.File]::WriteAllText($PromptOrdenesPath, $fr, (New-Object System.Text.UTF8Encoding $false))
        Log ('OIDO: la frase de ejemplo pasa a ser «' + $fr + '»')
        return $true
    } catch { Log ('prompt de ordenes: ' + $_.Exception.Message); return $false }
}

# LEER EL FICHERO DE LAS CORRECCIONES (27/09, idea 117 de las 121)
#
# EL AGUJERO QUE QUEDABA: la idea 79 ya lee los AGUJEROS, que el worker agrupa en agujeros.json. Lo
# que seguia sin lector es el fichero de donde salen: memoria\cerebro\importante.jsonl, que el
# worker escribe en modo 'a' y que su propio comentario dice que "NO se poda nunca".
#
# Y AL ABRIRLO, LA SORPRESA: cinco lineas, las cinco con por='correccion', y ninguna es una
# correccion. Son frases que el oido entendio mal en mitad de una charla -"No, porque se destilada
# la camera con anadir con la contable"-, y entran porque empiezan por "no" y tienen cinco palabras.
# Por eso agujeros.json no existia todavia: todo se etiquetaba de correccion y nada llegaba a ser un
# agujero.
#
# LO QUE LA FICHA PEDIA Y NO SE HACE: meter esas correcciones en el prompt de la charla. Con cinco
# de cinco siendo ruido de reconocimiento, eso es exactamente el riesgo que la propia ficha nombra
# -"que ensucie el prompt"-, y no hay ni una correccion de verdad con la que probar que ayuda.
# Primero que haya correcciones; el dia que las haya, la decision tendra con que tomarse.
#
# LO QUE SI SE HACE, que es el nucleo de la idea: leerlo y decir lo que de verdad dice. Con el
# motivo nuevo 'no-entendi' que el worker estrena hoy, el fichero pasa a medir algo que no se media
# en ningun sitio: cuantos turnos de charla se pierden porque Nova no entendio la frase.
$ImportanteJsonl = Join-Path $MemoriaDir 'cerebro\importante.jsonl'
function Get-Importante([int]$dias = 7, [datetime]$hoy = (Get-Date)) {
    # Una linea por objeto, asi que se lee suelta y una linea rota no se lleva el fichero.
    $l = New-Object System.Collections.ArrayList
    try {
        if (-not (Test-Path -LiteralPath $ImportanteJsonl)) { return ,@($l) }
        $desde = $hoy.Date.AddDays(-$dias).ToString('yyyy-MM-dd')
        foreach ($ln in [System.IO.File]::ReadAllLines($ImportanteJsonl, [System.Text.Encoding]::UTF8)) {
            if (-not $ln -or $ln.Length -lt 10) { continue }
            $o = $null
            try { $o = $ln | ConvertFrom-Json } catch { continue }
            if (-not $o) { continue }
            $d = [string]$o.d
            if ($d -and $d -lt $desde) { continue }
            [void]$l.Add(@{ dia = $d; hora = [string]$o.h; por = [string]$o.por
                            braya = [string]$o.braya; nova = [string]$o.nova })
        }
    } catch { Log ('lo importante: no pude leerlo (' + $_.Exception.Message + ')') }
    return ,@($l)
}

# PURA: dada la lista, los cuenta por motivo. Aparte para que su banco le pase las cinco de verdad.
function Get-ImportanteResumen($lineas) {
    $r = @{ total = 0; correccion = 0; agujero = 0; noEntendi = 0; ultima = '' }
    foreach ($x in @($lineas)) {
        if (-not $x) { continue }
        $r.total++
        switch ([string]$x.por) {
            'correccion' { $r.correccion++ }
            'agujero'    { $r.agujero++ }
            'no-entendi' { $r.noEntendi++ }
        }
        if ([string]$x.dia -gt [string]$r.ultima) { $r.ultima = [string]$x.dia }
    }
    return $r
}

# La frase para el parte semanal. Vacia si no hay nada: un parte que dice "no paso nada" cansa.
function Get-ParrafoImportante {
    try {
        $rs = Get-ImportanteResumen (Get-Importante 7)
        # SALIDA TEMPRANA, NO UNA GUARDA, y se dice para que nadie la confunda: quitarla no cambia
        # ninguna respuesta -el '$partes.Count -eq 0' de abajo tambien devuelve vacio- y su banco lo
        # comprobo. Vale para no montar frases cuando no hay ni una linea.
        if ([int]$rs.total -eq 0) { return '' }
        $partes = @()
        # LO QUE MAS IMPORTA VA PRIMERO: los turnos que se perdieron por el oido, que es lo que
        # nadie medía. Y se dice en turnos de charla, no en porcentajes, que es como se nota.
        if ([int]$rs.noEntendi -gt 0) {
            $v = [int]$rs.noEntendi
            $partes += ('Esta semana hubo ' + $v + ' ' + $(if ($v -eq 1) { 'rato' } else { 'ratos' }) +
                        ' en que me hablaste y no te entendi, y ' +
                        $(if ($v -eq 1) { 'se quedo' } else { 'se quedaron' }) + ' sin contestar de verdad.')
        }
        if ([int]$rs.correccion -gt 0) {
            $v = [int]$rs.correccion
            $partes += ('Y me corregiste ' + $v + ' ' + $(if ($v -eq 1) { 'vez' } else { 'veces' }) + '.')
        }
        if ($partes.Count -eq 0) { return '' }
        return ($partes -join ' ')
    } catch { return '' }
}

# La frase para el resumen semanal. Vacia si no hay agujeros repetidos: sin eso no hay noticia.
function Get-ParrafoAgujeros {
    $ag = Get-AgujerosSemana
    if (-not $ag) { return '' }
    $reps = @($ag.repetidos)
    if ($reps.Count -eq 0) { return '' }
    $falsos = @($reps | Where-Object { $_.falso })
    $deVerdad = @($reps | Where-Object { -not $_.falso })
    $lineas = @()
    $cosas = if ($ag.total -eq 1) { 'cosa' } else { 'cosas' }
    $eran = if ($reps.Count -eq 1) { 'era' } else { 'eran' }
    $lineas += ('Esta semana no supe contestarte ' + $ag.total + ' ' + $cosas + ', y ' + $reps.Count + ' ' + $eran + ' de lo mismo.')
    if ($deVerdad.Count -gt 0) {
        $lineas += ('Lo que mas me faltó: ' + (@($deVerdad | Select-Object -First 3 | ForEach-Object { '«' + $_.frase + '» (' + $_.veces + ' veces)' }) -join ', ') + '.')
    }
    if ($falsos.Count -gt 0) {
        # LO QUE SI SABIA Y DIJE QUE NO: esto es lo mas util del fichero, porque es arreglable hoy
        $lineas += ('Y ' + $(if ($falsos.Count -eq 1) { 'una' } else { $falsos.Count }) + ' de esas si la sé y te dije que no: ' +
                    (@($falsos | Select-Object -First 3 | ForEach-Object { '«' + $_.frase + '»' }) -join ', ') + '.')
    }
    return ($lineas -join ' ')
}
function Get-ParrafoDecisiones($stats, [datetime]$ini, [datetime]$fin) {
    $hechas = @(); $deshechas = 0; $medias = 0
    try {
        # DE "decisiones", QUE PARA ESO SE HIZO (22/09). Esto leia "recientes", que tiene 40
        # filas y se las lleva cualquier racha: medido hoy, 28 de esas 40 eran aviso-entorno
        # y las decisiones dentro de la ventana eran CERO, asi que este parrafo -que es
        # SEMANAL- salia vacio siempre. Se sigue mirando "recientes" si la lista nueva esta
        # vacia, que es lo que pasa con un estadisticas.json de antes de hoy: asi el primer
        # resumen despues del cambio no se queda sin lo que ya habia.
        # EL Where-Object NO SOBRA, y me costo ocho rojos de un banco que ya existia: si
        # $stats no trae la clave 'decisiones' -un objeto de antes de hoy-, $stats.decisiones
        # es $null, y en PowerShell @($null).Count es UNO, no cero. O sea que el respaldo no
        # entraba nunca y el foreach corria sobre un $null: el parrafo seguia saliendo vacio,
        # que es justo lo que se venia a arreglar. Filtrando, una lista ausente y una vacia
        # se parecen por fin.
        $deDonde = @($stats.decisiones | Where-Object { $_ })
        if ($deDonde.Count -eq 0) { $deDonde = @($stats.recientes | Where-Object { $_ }) }
        foreach ($r in $deDonde) {
            if ($r -notmatch '^(\d{4}-\d{2}-\d{2})\s+\S+\s+\[([a-z-]+)\]\s+(.*)$') { continue }
            $f = $null
            try { $f = [DateTime]::ParseExact($Matches[1], 'yyyy-MM-dd', $null) } catch { continue }
            if ($f -lt $ini -or $f -gt $fin) { continue }
            switch ($Matches[2]) {
                'auto-ajuste'     { $hechas += [string]$Matches[3] }
                'auto-deshecho'   { $deshechas++ }
                'arranque-medias' { $medias++ }
            }
        }
    } catch { return '' }
    if ($hechas.Count -eq 0 -and $deshechas -eq 0 -and $medias -eq 0) {
        # SI NO DECIDI NADA, AL MENOS DE QUE MURIERON LAS ORDENES (27/09, idea 99 de las 121).
        #
        # Este parrafo es SEMANAL y sale vacio siempre: 'auto-ajuste' vale cero en 14 dias y la
        # lista 'decisiones' esta vacia. Mientras tanto, senales-fallo.jsonl lleva 33 lineas de
        # cinco dias diciendo exactamente QUE frase fallo y por que, y no lo leia NADIE -el
        # fichero aparece dos veces en todo el proyecto: quien lo escribe y quien lo borra-.
        #
        # LOS PESOS NO SE SUMAN: se nombra la senal que mas veces salio en la ventana y se dice
        # si es de las que no hicieron nada ('alto') o de las que hicieron algo que quiza no era
        # ('bajo'). Sumarlos daria 63 fallos de 114 ordenes el 18/09, y no es verdad.
        try {
            $sfP = Get-SenalFallePeor 7 $fin
            if ($null -eq $sfP) { return '' }
            $comoP = switch ([string]$sfP.senal) {
                'ruido'             { 'restos del microfono que no eran una orden' }
                'descarte'          { 'frases que no llegue a entender' }
                'no-orden-a-charla' { 'frases que mande a la charla sin ser charla' }
                'me-disculpe'       { 'veces que acabe disculpandome' }
                'error'             { 'dictados que llegaron vacios' }
                'recitado'          { 'frases que se invento el oido con el silencio' }
                default             { [string]$sfP.senal }
            }
            $vecesP = if ([int]$sfP.veces -eq 1) { 'una vez' } else { ([string][int]$sfP.veces + ' veces') }
            $colaP = if ($sfP.alto) { ', y ahi no hice nada con lo que dijiste' } else { ', y ahi hice algo que quiza no era lo que querias' }
            return ('Esta semana no decidi nada por mi cuenta. Lo que mas se me murio: ' + $comoP + ', ' + $vecesP + $colaP + '.')
        } catch { return '' }
    }
    $lineas = @()
    if ($hechas.Count -gt 0) {
        $lineas += "Esta semana decidi " + $(if ($hechas.Count -eq 1) { 'una cosa' } else { "$($hechas.Count) cosas" }) + " por mi cuenta: " + (($hechas | Select-Object -First 4) -join '; ') + "."
    }
    if ($deshechas -gt 0) {
        $lineas += "Me pediste deshacer " + $(if ($deshechas -eq 1) { 'una de ellas' } else { "$deshechas de ellas" }) + ", asi que ahi me equivoque."
    }
    if ($medias -gt 0) {
        $lineas += "Y arranque a medias " + $(if ($medias -eq 1) { 'una vez' } else { "$medias veces" }) + "."
    }
    return ($lineas -join ' ')
}

function Write-NotaSemanal {
    try {
        $hoy = (Get-Date).Date
        # lunes de ESTA semana; la semana a resumir es la anterior
        $lunes = $hoy.AddDays(-(([int]$hoy.DayOfWeek + 6) % 7))
        $ini = $lunes.AddDays(-7); $fin = $lunes.AddDays(-1)
        $cal = [System.Globalization.CultureInfo]::InvariantCulture.Calendar
        $semana = $cal.GetWeekOfYear($ini, [System.Globalization.CalendarWeekRule]::FirstFourDayWeek, [DayOfWeek]::Monday)
        $dir = Join-Path $MemoriaDir 'semanas'
        $ruta = Join-Path $dir ('{0}-W{1:00}.md' -f $ini.Year, $semana)
        if (Test-Path -LiteralPath $ruta) { return }
        $s = Get-Estadisticas
        $tot = @{}; $dias = 0
        for ($d = $ini; $d -le $fin; $d = $d.AddDays(1)) {
            $k = $d.ToString('yyyy-MM-dd')
            if (-not $s.dias.ContainsKey($k)) { continue }
            $dias++
            foreach ($r in $s.dias[$k].Keys) { if (-not $tot.ContainsKey($r)) { $tot[$r] = 0 }; $tot[$r] += $s.dias[$k][$r] }
        }
        if ($dias -eq 0) { return }   # semana sin uso: no hay nada que contar
        # LO QUE ME DIJISTE ES SOLO LO QUE DIJISTE TU (27/09, idea 101 de las 121)
        #
        # ESTO ESTABA ESCRITO EN memoria\semanas\2026-W37.md: "Lo que mas me dijiste, segun mis
        # gestos: grito x148, confuso x143, orgullo x123, perdida x59". De esos cuatro, TRES son de
        # Nova: confuso, orgullo y perdida los dispara lo que ELLA dice o los manda el asistente por
        # la puerta de eventos. Y W38 dice "duda x256, grito x235, confuso x119, negar x80", con
        # confuso otra vez y 'duda' que pueden disparar los dos.
        #
        # MEDIDO sobre el diario entero: solo 87 lineas (el 4,3 %) son de gestos que UNICAMENTE
        # braya puede disparar, 681 (33,3 %) son solo de Nova y 792 (38,8 %) llevan un nombre que
        # pueden ser de cualquiera de los dos.
        #
        # AHORA SOLO ENTRAN LOS 't'. Las lineas sin letra -todas las de antes de hoy- van a '?' y NO
        # entran: es mejor que la primera semana esta frase salga corta que seguir afirmando que
        # braya dijo cosas que dijo ella.
        $gestos = @{}
        $gestosSinMarca = 0
        $gl = Join-Path $TmpDir 'gestos.log'
        if (Test-Path -LiteralPath $gl) {
            foreach ($l in [System.IO.File]::ReadAllLines($gl, [System.Text.Encoding]::UTF8)) {
                if ($l -match '^(\d{4}-\d{2}-\d{2}) \S+ (\S+?)(?: ([tyn?]))?$') {
                    $dd = [DateTime]::ParseExact($Matches[1], 'yyyy-MM-dd', $null)
                    if ($dd -lt $ini -or $dd -gt $fin) { continue }
                    if ($Matches[2] -in @('escucho', 'lotengo', 'atencion')) { continue }
                    if (-not $Matches[3]) { $gestosSinMarca++; continue }
                    if ([string]$Matches[3] -ne 't') { continue }
                    if (-not $gestos.ContainsKey($Matches[2])) { $gestos[$Matches[2]] = 0 }
                    $gestos[$Matches[2]]++
                }
            }
        }
        $cul = New-Object System.Globalization.CultureInfo('es-MX')
        $n = 0; foreach ($k in 'local', 'aprendida', 'memoria', 'pregunta', 'traducida', 'accion', 'charla') { if ($tot.ContainsKey($k)) { $n += $tot[$k] } }
        $rapidas = 0; foreach ($k in 'local', 'aprendida', 'memoria') { if ($rapidas -ne $null -and $tot.ContainsKey($k)) { $rapidas += $tot[$k] } }
        $errores = if ($tot.ContainsKey('error')) { $tot['error'] } else { 0 }
        $desc = @($s.descartes | Where-Object { $_ -match '^(\d{4}-\d{2}-\d{2})' -and ([DateTime]::ParseExact($Matches[1], 'yyyy-MM-dd', $null) -ge $ini) -and ([DateTime]::ParseExact($Matches[1], 'yyyy-MM-dd', $null) -le $fin) } | ForEach-Object { $_ -replace '^\S+\s+', '' } | Select-Object -First 5)
        $sb = New-Object System.Text.StringBuilder
        [void]$sb.AppendLine("# Semana del " + $ini.ToString('d "de" MMMM', $cul) + " al " + $fin.ToString('d "de" MMMM "de" yyyy', $cul))
        [void]$sb.AppendLine("")
        [void]$sb.AppendLine("Esta semana hablamos $dias " + $(if ($dias -eq 1) { 'día' } else { 'días' }) + ". Me pediste $n " + $(if ($n -eq 1) { 'cosa' } else { 'cosas' }) + $(if ($n -gt 0) { ", y $rapidas de ellas las resolví al instante sin pasar por el modelo" } else { '' }) + ".")
        if ($errores -gt 0) { [void]$sb.AppendLine("Hubo $errores " + $(if ($errores -eq 1) { 'tropiezo' } else { 'tropiezos' }) + " (cancelaciones, dictados vacíos o esperas que se pasaron de tiempo).") }
        if ($desc.Count -gt 0) { [void]$sb.AppendLine(""); [void]$sb.AppendLine("Cosas que no entendí a la primera y que podrías enseñarme en commands.json: " + (($desc | ForEach-Object { "«$_»" }) -join ', ') + ".") }
        $parrafoYo = Get-ParrafoDecisiones $s $ini $fin
        if ($parrafoYo) { [void]$sb.AppendLine(""); [void]$sb.AppendLine($parrafoYo) }
        # y lo que mas se le ha roto por dentro sin decirlo (idea 80)
        try {
            $peorP = Get-PeorPete
            if ($peorP) {
                [void]$sb.AppendLine('')
                [void]$sb.AppendLine('Por dentro se me rompio algo ' + $peorP.veces + ' veces en el mismo sitio (linea ' + $peorP.linea + ') y no te lo dije: ' + $peorP.que)
            }
        } catch {}
        # los agujeros de la semana, leidos del fichero que nadie abria (idea 79)
        $parrafoAg = ''
        try { $parrafoAg = Get-ParrafoAgujeros } catch { $parrafoAg = '' }
        if ($parrafoAg) { [void]$sb.AppendLine(""); [void]$sb.AppendLine($parrafoAg) }
        # Y LO QUE APUNTA EN importante.jsonl (27/09, idea 117). Aqui al lado del de los agujeros
        # porque salen del mismo fichero: aquel lee los agrupados y este el bruto.
        try { $parrafoIm = Get-ParrafoImportante } catch { $parrafoIm = '' }
        if ($parrafoIm) { [void]$sb.AppendLine(""); [void]$sb.AppendLine($parrafoIm) }
        if ($gestos.Count -gt 0) {
            $top = @($gestos.GetEnumerator() | Sort-Object -Property Value -Descending | Select-Object -First 4 | ForEach-Object { "$($_.Key) ×$($_.Value)" })
            [void]$sb.AppendLine(""); [void]$sb.AppendLine("Lo que más me dijiste, según mis gestos: " + ($top -join ', ') + ".")
        } elseif ($gestosSinMarca -gt 0) {
            # LA REGLA 2 DE LA CASA: lo que no se sabe se dice, no se calla. Si toda la semana es de
            # antes de que el diario supiera de quién era cada gesto, esta frase lo cuenta en vez de
            # desaparecer sin explicación.
            [void]$sb.AppendLine("")
            [void]$sb.AppendLine("De los gestos de esta semana no sé cuáles fueron cosa tuya: $gestosSinMarca son de antes de que empezara a apuntarlo.")
            if ($gestos.ContainsKey('carino') -and $gestos['carino'] -ge 3) { [void]$sb.AppendLine("Gracias por los cariños, se notaron.") }
            if ($gestos.ContainsKey('negar') -and $gestos['negar'] -gt ($n / 3)) { [void]$sb.AppendLine("Hubo bastantes «no»: si algo hago mal a menudo, apúntamelo en la lista de descartes y lo aprendo.") }
        }
        if (-not (Test-Path -LiteralPath $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
        [System.IO.File]::WriteAllText($ruta, $sb.ToString(), (New-Object System.Text.UTF8Encoding($false)))
        Log "nota semanal escrita: $ruta"
    } catch { Log ("nota semanal: " + $_.Exception.Message) }
}

# =====================================================================
# PREGUNTARLE OTRAS COSAS A STEAM, SIN PISAR A LOS AMIGOS (1/10, funciones 14 y 15 de las 20)
# =====================================================================
# EL CANAL DE RED DE STEAM ES UNO SOLO: $script:steamTask, y Start-SteamAsync se va en su primera
# linea si ya hay una peticion en vuelo. Lo usa la vigilancia de amigos, que FUNCIONA, y lo ultimo
# que conviene hacer es meter mano ahi de cualquier manera.
# ASI QUE SE RESPETA SU PROTOCOLO, que ya estaba inventado: una variable propia dice de quien es la
# respuesta que viene ($script:amigoPide para los amigos, $script:steamPide para esto), el canal lo
# coge quien llega primero, y NADIE recoge una respuesta que no ha pedido. Si el canal esta ocupado,
# estas preguntas lo dicen y no insisten: son preguntas de braya, no vigilancias, y un segundo de
# espera se nota menos que una vigilancia muda.
$script:steamPide = $null

function Start-SteamPregunta([string]$que, [string]$appid, [string]$comoSeLlama) {
    if ($script:amigoPide -or $script:steamPide -or $script:steamTask) {
        return 'Estoy preguntandole otra cosa a Steam, dame un segundo y repitelo.'
    }
    $url = switch ($que) {
        # NI CLAVE NI STEAMID: estos dos endpoints son del juego, no tuyos, asi que no hay nada que
        # tapar en el registro ni nada privado que viaje.
        'deck'   { 'https://store.steampowered.com/saleaction/ajaxgetdeckappcompatibilityreport?nAppID=' + $appid + '&l=spanish' }
        'logros' { 'https://api.steampowered.com/ISteamUserStats/GetGlobalAchievementPercentagesForApp/v2/?gameid=' + $appid }
        # LA LISTA DE DESEOS SI LLEVA SU STEAMID, que es publico y esta en la carpeta de Steam del
        # disco; la clave de la API no hace falta para este.
        'wishlist' { $y = Get-YoSteam; if (-not $y) { '' } else { 'https://api.steampowered.com/IWishlistService/GetWishlist/v1/?steamid=' + $y } }
        default  { '' }
    }
    if (-not $url) { return 'No se preguntarle eso a Steam.' }
    if (-not (Start-SteamAsync $url)) { return 'No he podido preguntarle a Steam.' }
    $script:steamPide = @{ que = $que; appid = [string]$appid; juego = [string]$comoSeLlama
                           paso = 'uno'; en = $sw.ElapsedMilliseconds }
    return ''      # vacio = la respuesta se dice cuando llegue, no ahora
}

# Una vuelta del bucle = un IsCompleted, cero espera. Y NO toca el canal si la respuesta que viene
# es de los amigos: ese es el acuerdo que hace que los dos puedan compartirlo.
function Receive-SteamPregunta {
    if (-not $script:steamPide) { return }
    if ($script:amigoPide) { return }
    if (($sw.ElapsedMilliseconds - [double]$script:steamPide.en) -gt $AmigoRedMs) {
        $script:steamPide = $null
        try { [void](Complete-SteamAsync) } catch {}
        Say 'Steam no me ha contestado.'
        return
    }
    $json = Complete-SteamAsync
    if (-not $json) { return }
    $pide = $script:steamPide
    $script:steamPide = $null
    $o = $null
    try { $o = $json | ConvertFrom-Json } catch { $o = $null }
    if (-not $o) { Say 'Steam me ha contestado algo que no entiendo.'; return }
    if ($pide.que -eq 'deck') { Say (Format-DeckVerified $o ([string]$pide.juego)); return }
    if ($pide.que -eq 'logros') { Say (Format-LogrosFaciles $o ([string]$pide.juego)); return }
    # LA LISTA DE DESEOS SON DOS PASOS: primero los appids, despues sus precios. Igual que la maquina
    # de los amigos, avanza UNA vuelta del bucle cada vez y nunca espera a nada.
    if ($pide.que -eq 'wishlist') {
        if ($pide.paso -eq 'uno') {
            $ids = @()
            try { $ids = @($o.response.items | ForEach-Object { [string]$_.appid }) } catch {}
            if ($ids.Count -eq 0) { Say 'No veo nada en tu lista de deseos.'; return }
            # SOLO LOS PRIMEROS: appdetails acepta varios de golpe, pero pedir treinta y tres de una
            # vez es una respuesta enorme para una frase hablada. Con doce ya se ve si hay ofertas.
            $trozo = @($ids | Select-Object -First $WishlistMiraMax)
            $url2 = 'https://store.steampowered.com/api/appdetails?appids=' + ($trozo -join ',') + '&filters=price_overview'
            # OJO: el filtro NO puede ir junto con 'cc' ni 'l'. Medido: appdetails devuelve 400.
            if (-not (Start-SteamAsync $url2)) { Say 'No he podido mirar los precios.'; return }
            $script:steamPide = @{ que = 'wishlist'; paso = 'dos'; ids = $trozo; total = $ids.Count
                                   en = $sw.ElapsedMilliseconds }
            return
        }
        Say (Format-WishlistPrecios $o ([string[]]$pide.ids) ([int]$pide.total))
        return
    }
}

# ¿ESTE JUEGO VA BIEN EN LA ALLY? (1/10, la 15 de las 20)
# Las categorias de Steam para portatiles: 0 sin probar, 1 no soportado, 2 jugable, 3 verificado.
# MEDIDO al escribirla: Black Myth: Wukong sale 1, "no soportado", con sus 139,57 GB instalados.
function Format-DeckVerified($o, [string]$juego) {
    # "NO HAY CATEGORIA" NO ES "CATEGORIA 0" (1/10, lo cazo su banco). '[int]$null' vale 0, asi que
    # una respuesta sin el campo caia en la rama de "todavia no le han hecho la prueba", que es una
    # afirmacion sobre Valve. Son dos cosas distintas: una es que Steam no me contesto.
    $cat = -1
    try {
        $v = $o.results.resolved_category
        if ($null -ne $v -and "$v" -ne '') { $cat = [int]$v }
    } catch { $cat = -1 }
    $comoSeLlama = if ($juego) { $juego } else { 'ese juego' }
    switch ($cat) {
        3 { return $comoSeLlama + ' esta verificado para portatiles: mandos y letra pensados para una pantalla asi.' }
        2 { return $comoSeLlama + ' es jugable en portatil, pero con pegas: suele ser texto pequeno o que hay que tocar algo a mano.' }
        1 { return $comoSeLlama + ' sale como NO soportado en portatiles. Puede tirar igual, pero Valve avisa de que algo no va bien.' }
        0 { return 'A ' + $comoSeLlama + ' todavia no le han hecho la prueba de portatiles.' }
        default { return 'Steam no me dice como va ' + $comoSeLlama + ' en portatil.' }
    }
}

# QUE LOGRO ES EL MAS FACIL (1/10, la 14 de las 20) — LA MITAD QUE SE PUEDE
# LO QUE NO SE PUEDE, medido: GetPlayerAchievements devuelve 403 porque el perfil de Steam de braya
# esta PRIVADO, asi que Nova no puede saber cuales tiene ya. Lo que si responde sin permisos es el
# porcentaje GLOBAL de cada logro, o sea cual tiene mas gente: ese es el atajo de verdad para quien
# persigue el 100 %, y es informacion util aunque no sepamos cuales le faltan a el.
# Y SE DICE QUE NO SE SABEN LOS SUYOS: si no, pareceria que le esta recomendando los que le quedan.
function Format-LogrosFaciles($o, [string]$juego) {
    $l = @()
    try { $l = @($o.achievementpercentages.achievements) } catch {}
    if ($l.Count -eq 0) { return 'Ese juego no tiene logros, o Steam no me los da.' }
    $comoSeLlama = if ($juego) { $juego } else { 'ese juego' }
    $faciles = @($l | Sort-Object -Property @{ Expression = { [double]$_.percent }; Descending = $true } | Select-Object -First 3)
    $t = $comoSeLlama + ' tiene ' + $l.Count + ' logros. Los que mas gente consigue: '
    $t += (($faciles | ForEach-Object { [string]$_.name + ' (el ' + [Math]::Round([double]$_.percent, 0) + ' por ciento)' }) -join ', ')
    $t += '. No se cuales tienes tu: tu perfil de Steam esta en privado y no me deja verlos.'
    return $t
}

# =====================================================================
# LA LISTA DE DESEOS, Y CUANDO BAJA DE PRECIO (1/10, la 12 de las 20 funciones)
# =====================================================================
# MEDIDO al escribirla: la lista de braya tiene 33 juegos, y los precios salen de
# 'appdetails?appids=A,B&filters=price_overview'. OJO con una trampa que costo un 400: ese filtro NO
# se puede combinar con 'cc' ni con 'l'; con el filtro solo, funciona.
# LO QUE DE VERDAD HACIA FALTA no es la lista -eso ya lo ve en Steam- es que avise CUANDO ALGO BAJA,
# que es lo que no se puede mirar a mano todos los dias. Asi que se guarda lo que costaba cada uno la
# ultima vez y se compara: lo que baja se dice, lo que no, se calla.
$WishlistMiraMax = 12            # cuantos precios se piden de una vez
$WishlistBajaMin = 10            # por debajo de este % de rebaja no es noticia
$WishlistPath = Join-Path $MemoriaDir 'wishlist-precios.json'

function Get-WishlistPrecios {
    try {
        if (Test-Path -LiteralPath $WishlistPath) {
            $j = Get-Content -LiteralPath $WishlistPath -Raw -Encoding UTF8 | ConvertFrom-Json
            $h = @{}
            foreach ($p in $j.PSObject.Properties) { $h[$p.Name] = [double]$p.Value }
            return $h
        }
    } catch {}
    return @{}
}

function Format-WishlistPrecios($o, [string[]]$ids, [int]$total) {
    $antes = Get-WishlistPrecios
    $ahora = @{}
    $bajadas = @()
    $ofertas = @()
    foreach ($id in @($ids)) {
        $d = $null
        try { $d = $o.$id } catch { $d = $null }
        if (-not $d -or -not $d.success) { continue }
        $po = $null
        try { $po = $d.data.price_overview } catch {}
        if (-not $po) { continue }                      # gratis, o sin precio en esta region
        $final = 0.0
        try { $final = [double]$po.final / 100.0 } catch {}
        if ($final -le 0) { continue }
        $desc = 0
        try { $desc = [int]$po.discount_percent } catch {}
        $txt = [string]$po.final_formatted
        $ahora[$id] = $final
        # ¿BAJO DESDE LA ULTIMA VEZ? Eso es lo que no se puede mirar a mano todos los dias.
        if ($antes.ContainsKey($id) -and $antes[$id] -gt 0) {
            $baja = [int][Math]::Round(((($antes[$id] - $final) / $antes[$id]) * 100))
            if ($baja -ge $WishlistBajaMin) { $bajadas += @{ id = $id; txt = $txt; baja = $baja } }
        }
        if ($desc -ge $WishlistBajaMin) { $ofertas += @{ id = $id; txt = $txt; desc = $desc } }
    }
    # SE GUARDA SIEMPRE QUE HAYA ALGO, tambien la primera vez: sin la foto de hoy no hay con que
    # comparar manana, y entonces esta funcion no sirve para nada.
    if ($ahora.Count -gt 0) {
        try {
            $oG = New-Object PSObject
            foreach ($k in $ahora.Keys) { $oG | Add-Member -NotePropertyName $k -NotePropertyValue $ahora[$k] -Force }
            Write-Atomico $WishlistPath ($oG | ConvertTo-Json -Depth 3)
        } catch {}
    }
    if ($ahora.Count -eq 0) { return 'Steam no me ha dado los precios de tu lista.' }
    $mirados = $ahora.Count
    $deCuantos = if ($total -gt $mirados) { ' He mirado ' + $mirados + ' de los ' + $total + ' de tu lista.' } else { '' }
    # NO SE DICEN LOS APPID, Y NO ES POR GUSTO (1/10, medido): 'appdetails' solo acepta VARIOS juegos
    # de golpe si se le pone 'filters=price_overview', y con ese filtro NO devuelve el nombre; sin
    # filtro acepta UNO solo -con seis ids y sin filtro, 400-. Pedir doce nombres serian doce
    # llamadas, y el canal de Steam es uno.
    # ASI QUE SE DICE LO QUE IMPORTA -que algo bajo y cuanto- y se ABRE LA LISTA en Steam, que es
    # donde estan los nombres y las caratulas. Recitar "el appid 39210" en voz alta no sirve a nadie.
    if ($bajadas.Count -gt 0) {
        $b = @($bajadas | Sort-Object -Property @{ Expression = { $_.baja }; Descending = $true } | Select-Object -First 3)
        $t = if ($bajadas.Count -eq 1) { 'Ha bajado uno de tu lista de deseos' } else { 'Han bajado ' + $bajadas.Count + ' de tu lista de deseos' }
        $t += ': ' + (($b | ForEach-Object { 'un ' + $_.baja + ' por ciento, a ' + $_.txt }) -join '; ')
        $t += '. Te abro la lista para que veas cuales.' + $deCuantos
        try { Start-Process 'steam://url/WishlistPage' | Out-Null } catch {}
        return $t
    }
    if ($ofertas.Count -gt 0) {
        $f = @($ofertas | Sort-Object -Property @{ Expression = { $_.desc }; Descending = $true } | Select-Object -First 1)
        return ('No ha bajado nada desde la ultima vez, pero tienes ' + $ofertas.Count +
                ' en oferta, el mejor al ' + $f[0].desc + ' por ciento, a ' + $f[0].txt + '.' + $deCuantos)
    }
    return 'Nada de tu lista ha bajado de precio desde la ultima vez.' + $deCuantos
}

# El appid de un juego por su nombre, del indice que Nova ya tiene del disco.
function Get-AppIdDeJuego([string]$juego) {
    if (-not $juego) { return @{ id = ''; nombre = '' } }
    $q = (ConvertTo-Plain $juego) -replace '[^a-z0-9]', ''
    if ($q.Length -lt 3) { return @{ id = ''; nombre = '' } }
    foreach ($j in @($script:Juegos)) {
        if (-not $j.appid) { continue }
        $c = (ConvertTo-Plain ([string]$j.nombre)) -replace '[^a-z0-9]', ''
        if ($c -eq $q -or $c.StartsWith($q)) { return @{ id = [string]$j.appid; nombre = [string]$j.nombre } }
    }
    return @{ id = ''; nombre = '' }
}

# =====================================================================
# SUBTITULOS DEL AUDIO DEL JUEGO (1/10, la 17 de las 20 funciones)
# =====================================================================
# La mas cara de las veinte, y la unica que lleva un numero medido delante de cada decision,
# porque aqui es facil prometer algo que se come la consola. Todo esto es del 1/10 en esta
# maquina, y con la bateria de pruebas encima (o sea, numeros pesimistas):
#
#   capturar el audio del sistema (WASAPI loopback) ......  8,7 % de un nucleo
#   Whisper tiny int8 sobre trozos de 6 s, 1 hilo .......  x0,30 real, 1,8 s, 99 % de UN nucleo
#                                           2 hilos ....  x0,20 real, 1,2 s, 197 %
#                                           4 hilos ....  x0,20 real, 1,2 s, 385 %
#
# Cuatro hilos es dinero tirado: igual de rapido que dos y el doble de nucleos. Va con UN hilo
# (regla 5: el juego necesita los nucleos). Y con nada sonando el pico de amplitud es
# EXACTAMENTE 0,00000, asi que la puerta de "no hay nada que subtitular" es gratis.
#
# NO TRADUCE, Y ES LA PARTE QUE MAS DOLIO: Whisper solo traduce HACIA ingles. Para el espanol
# hay que pasar por el modelo local, y eso tambien se midio: 4,13 s con llama3.2:1b y 5,04 s
# con qwen2.5:3b. Encima de los 1,8 s de transcribir son SIETE SEGUNDOS de retraso, y encima
# traducia mal ("the top of the tower" -> "el topo del castillo", "the bridge is out" -> "El
# puente esta fuera"). Un subtitulo que llega siete segundos tarde y mal no es un subtitulo.
# Asi que los subtitulos salen EN EL IDIOMA DEL JUEGO, y para el espanol esta la otra mitad,
# que SI puede pagar los 5 s porque braya la pide y espera: "que ha dicho".
#
# Y UN HALLAZGO QUE MEJORA LA FUNCION (medido con el volumen a 12 %): el loopback coge el
# sonido ANTES del volumen maestro, asi que el pico capturado es el mismo a todo volumen que
# casi callado. Los subtitulos funcionan con el sonido bajado, que es como se juega de noche.
#
# SE CORTA SOLA (regla 2, y no es negociable con algo que gasta un nucleo): por plazo, al
# cerrarse el juego, y si la CPU ya va ahogada.
$SubtitulosModelo = [string](Get-Cfg 'subtitulos' 'modelo' 'tiny')
$SubtitulosTrozoSeg = [double](Get-Cfg 'subtitulos' 'trozoSeg' 6)
# EL PLAZO: veinte minutos de dialogo es mucho mas de lo que dura una cinematica, y a los
# veinte minutos ya no se esta "leyendo una escena", se esta gastando un nucleo por inercia.
$SubtitulosMaxMin = [int](Get-Cfg 'subtitulos' 'maxMin' 20)
# SI LA CPU YA VA AHOGADA, NO. Subtitular cuesta un nucleo entero mientras transcribe: con el
# juego ya al 90 % lo unico que consigue es estropear la partida que se queria entender.
$SubtitulosCpuMax = [int](Get-Cfg 'subtitulos' 'cpuMax' 88)
$script:subProc = $null
$script:subLectura = $null
$script:subDesde = 0          # cuando se encendieron (reloj del bucle)
$script:subIdioma = ''        # lo que habla el juego, ya fijado por el worker
$script:subUltimo = ''        # el ultimo subtitulo que se pinto
$script:subPideUltimo = $false   # hay un "que ha dicho" esperando la respuesta del worker
$script:subPideEn = 0            # ...y desde cuando, para que no se quede esperando para siempre
$script:subMsPeor = 0         # lo que mas tardo un subtitulo, para poder decirlo

# QUE HACE FALTA PARA SUBTITULAR, dicho de una vez y en voz de persona. Se mira ANTES de
# arrancar nada: prometer subtitulos y que luego el worker muera callado es lo peor de todo.
function Get-EstorboSubtitulos {
    if (-not (Test-Path -LiteralPath $PyExe)) { return 'me falta Python para eso' }
    $w = Join-Path $LogDir 'subtitulos.py'
    if (-not (Test-Path -LiteralPath $w)) { return 'me falta el trozo que oye el juego' }
    return ''
}

function Start-Subtitulos {
    if ($script:subProc -and -not $script:subProc.HasExited) {
        return 'Ya los tengo puestos.'
    }
    $est = Get-EstorboSubtitulos
    if ($est) { return "No puedo subtitular: $est." }
    # LA CPU PRIMERO, Y LEIDA AHORA. $script:uiCarga valdria, pero el bucle solo lo actualiza
    # cada 30 s y solo cuando se mueve diez puntos: aqui se decide si gastar un nucleo entero,
    # y decidirlo con un numero de hace medio minuto no es decidir. Get-CargaCPU es un
    # NextValue del contador de rendimiento, o sea gratis, y esto no corre en el bucle sino
    # cuando braya lo pide (regla 4 intacta). Si la sonda esta apagada se usa lo que haya.
    $cargaAhora = $null
    try { $cargaAhora = Get-CargaCPU } catch {}
    if ($null -eq $cargaAhora) { $cargaAhora = [int]$script:uiCarga }
    if ([int]$cargaAhora -ge $SubtitulosCpuMax) {
        return "Ahora no: la consola va al $([int]$cargaAhora) por ciento y subtitular se come un nucleo entero. Te estropearia la partida."
    }
    try {
        $psi = New-Object System.Diagnostics.ProcessStartInfo
        $psi.FileName = $PyWorker
        $psi.Arguments = "-u `"$(Join-Path $LogDir 'subtitulos.py')`" $SubtitulosModelo $SubtitulosTrozoSeg"
        $psi.UseShellExecute = $false
        $psi.RedirectStandardInput = $true
        $psi.RedirectStandardOutput = $true
        $psi.CreateNoWindow = $true
        $psi.WorkingDirectory = $LogDir
        # DE QUIEN ES HIJO, igual que el oido y la voz desde el 13/09. Lo que quedaria huerfano
        # aqui es un Whisper comiendose un nucleo entero (regla 5), asi que no basta con confiar
        # en que al morir Nova se cierre la tuberia: el worker lo comprueba por su cuenta.
        [void]$psi.EnvironmentVariables.Remove('NOVA_PID_PADRE')
        [void]$psi.EnvironmentVariables.Add('NOVA_PID_PADRE', [string]$PID)
        $script:subProc = [System.Diagnostics.Process]::Start($psi)
        $script:subLectura = $null
        $script:subDesde = $sw.ElapsedMilliseconds
        $script:subIdioma = ''
        $script:subUltimo = ''
        $script:subMsPeor = 0
        Log "subtitulos: worker PID=$($script:subProc.Id) ($SubtitulosModelo, trozos de $SubtitulosTrozoSeg s, 1 hilo)"
    } catch {
        $script:subProc = $null
        Log ('subtitulos: no arranco: ' + $_.Exception.Message)
        return 'No he podido ponerme a oir el juego.'
    }
    # SE DICE EL PRECIO Y EL PLAZO, las dos cosas: es la unica funcion de las veinte que gasta
    # un nucleo, y braya tiene derecho a saberlo sin mirar el log.
    return "Voy. Salen en pantalla en el idioma del juego, con un segundo y medio de retraso; traducir tardaria siete y lo haria mal. Me callo sola en $SubtitulosMaxMin minutos o cuando me digas."
}

# LA TUBERIA NO ES UTF-8 POR DEFECTO, y esto me costo una prueba colgada el 1/10: con
# StandardInput.WriteLine, PowerShell cuela su preambulo delante del PRIMER mensaje, el worker
# recibe "﻿{" en vez de "{", json.loads falla y el pedido se pierde EN SILENCIO. El "que
# ha dicho" no contestaba nunca. Send-CharlaPedido ya lo resolvio el 13/09 escribiendo bytes
# UTF-8 directos al BaseStream; aqui se hace igual, y por el mismo motivo.
function Send-SubPedido([string]$json) {
    if (-not $script:subProc -or $script:subProc.HasExited) { return $false }
    try {
        $bytes = [System.Text.Encoding]::UTF8.GetBytes($json + "`n")
        $flujo = $script:subProc.StandardInput.BaseStream
        $flujo.Write($bytes, 0, $bytes.Length)
        $flujo.Flush()
        return $true
    } catch { Log ('subtitulos: no pude escribir al worker: ' + $_.Exception.Message); return $false }
}

function Stop-Subtitulos([string]$porque = '') {
    if (-not $script:subProc) { return $false }
    # SE LE PIDE QUE SE VAYA Y SE LE ESPERA UN POCO; si no se va, se cierra la tuberia, que es
    # lo que el worker mira para morirse solo. Matar a lo bruto dejaria el modelo a medio
    # descargar y la grabadora del altavoz abierta.
    [void](Send-SubPedido '{"op":"fin"}')
    # 1,5 s Y NO 0,7: medido el 1/10, el cierre limpio tarda 0,71 s -lee el sonido a medio segundo
    # y luego suelta el modelo-, asi que con 700 ms se le mataba justo en la raya. Matarlo deja la
    # grabadora del altavoz abierta y el modelo a medio soltar.
    try { [void]$script:subProc.WaitForExit(1500) } catch {}
    try { if (-not $script:subProc.HasExited) { $script:subProc.StandardInput.Close() } } catch {}
    try { if (-not $script:subProc.WaitForExit(500)) { $script:subProc.Kill() } } catch {}
    try { $script:subProc.Dispose() } catch {}
    $script:subProc = $null
    $script:subLectura = $null
    $script:subPideUltimo = $false
    Log ("subtitulos: fuera" + $(if ($porque) { " ($porque)" } else { '' }))
    return $true
}

# LO QUE VA DICIENDO EL WORKER, SIN BLOQUEAR EL BUCLE. Mismo patron que Receive-Charla:
# ReadLineAsync y si no esta lista se vuelve en la siguiente vuelta.
function Receive-Subtitulos {
    if (-not $script:subProc) { return }
    if ($script:subProc.HasExited) {
        Log 'subtitulos: el worker se cerro'
        $script:subProc = $null
        $script:subLectura = $null
        $script:subPideUltimo = $false
        return
    }
    # Y EL "QUE HA DICHO" TAMPOCO SE QUEDA ESPERANDO PARA SIEMPRE (regla 2): el worker contesta
    # en menos de un trozo -6 s-, asi que a los 15 ya no va a contestar y hay que decirlo en vez
    # de contestar "ya voy con eso" el resto de la tarde.
    if ($script:subPideUltimo -and ($sw.ElapsedMilliseconds - $script:subPideEn) -gt 15000) {
        $script:subPideUltimo = $false
        Say 'No he conseguido recuperar lo que dijo.'
    }
    # EL PLAZO, Y AQUI DENTRO a proposito: asi no hace falta acordarse de mirarlo en el bucle,
    # y no hay forma de que los subtitulos se queden puestos si alguien olvida la guarda.
    if (($sw.ElapsedMilliseconds - $script:subDesde) -gt ($SubtitulosMaxMin * 60000)) {
        [void](Stop-Subtitulos 'se paso el plazo')
        Say "Quito los subtitulos, que llevan $SubtitulosMaxMin minutos puestos. Dime y los vuelvo a poner."
        return
    }
    # Y SI SE CIERRA EL JUEGO, tampoco hay nada que subtitular: subtitular el escritorio es
    # gastar un nucleo en el silencio.
    if (-not $script:juegoActivo -and ($sw.ElapsedMilliseconds - $script:subDesde) -gt 30000) {
        [void](Stop-Subtitulos 'ya no hay juego delante')
        return
    }
    for ($n = 0; $n -lt 12; $n++) {
        if (-not $script:subLectura) { $script:subLectura = $script:subProc.StandardOutput.ReadLineAsync() }
        if (-not $script:subLectura.IsCompleted) { return }
        $linea = $script:subLectura.Result
        $script:subLectura = $null
        if ($null -eq $linea) { return }
        $ev = $null
        try { $ev = $linea | ConvertFrom-Json } catch { $ev = $null }
        if (-not $ev) { continue }
        switch ([string]$ev.ev) {
            'listo' { Log 'subtitulos: oyendo' }
            'idioma' {
                $script:subIdioma = [string]$ev.idioma
                Log ("subtitulos: el juego habla " + $script:subIdioma + " (al " + ([int]([double]$ev.conf * 100)) + ' %)')
            }
            'sub' {
                $t = [string]$ev.texto
                if (-not $t) { continue }
                $script:subUltimo = $t
                if ([int]$ev.ms -gt $script:subMsPeor) { $script:subMsPeor = [int]$ev.ms }
                # SE LEE, NO SE OYE: repetir en voz alta lo que el juego acaba de decir, encima
                # del juego, es absurdo. Van a la capsula y se van solas.
                # Y EL ESTADO ES 'atenta', NO 'hablando': con 'hablando' la capsula se pinta del
                # azul de "estoy contestando" y el subtitulo pareceria suyo. 'atenta' es el verde
                # apagado de "sigo aqui, oyendo", que es exactamente lo que esta haciendo.
                # 6,5 s y no 5: un trozo de 6 s con 1 s de solape trae subtitulo cada ~5 s, y con
                # 5000 la capsula se quedaba en blanco justo antes del siguiente.
                Set-UI 'atenta' $t 6500
            }
            'ultimo' {
                $script:subPideUltimo = $false
                $t = [string]$ev.texto
                if (-not $t) { Say 'No he oido nada en los ultimos segundos.'; continue }
                # AQUI SI SE TRADUCE, porque braya lo ha pedido y esta esperando: los cinco
                # segundos del modelo local se pagan a gusto. Mismo camino que el traductor de
                # conversacion, que ya existe desde el 16/09.
                $script:respuestaSinTarjeta = $false
                Submit-Command ("Traduce al espanol esto que acaba de decir un videojuego. Contesta SOLO con la traduccion, sin comillas ni comentarios: " + $t) 'pregunta'
            }
            'err' { Log ('subtitulos: ' + [string]$ev.texto) }
            'info' { Log ('subtitulos: ' + [string]$ev.texto) }
        }
    }
}

# "QUE HA DICHO": la otra mitad de la 17, la que SI va en espanol.
function Request-UltimoSubtitulo {
    if (-not $script:subProc -or $script:subProc.HasExited) {
        return 'No estoy oyendo el juego. Dime "subtitula" y luego te lo traduzco.'
    }
    if ($script:subPideUltimo) { return 'Ya voy con eso.' }
    if (-not (Send-SubPedido '{"op":"ultimo"}')) { return 'No he podido preguntarle a mi propio oido.' }
    $script:subPideUltimo = $true
    $script:subPideEn = $sw.ElapsedMilliseconds
    return ''
}

# EL PARTE, cuando se pregunta "estas subtitulando" o "como va eso"
function Get-FraseSubtitulos {
    if (-not $script:subProc -or $script:subProc.HasExited) {
        $est = Get-EstorboSubtitulos
        if ($est) { return "No estoy subtitulando, y no podria: $est." }
        return 'No estoy subtitulando. Dime "subtitula" y me pongo.'
    }
    $min = [Math]::Floor(($sw.ElapsedMilliseconds - $script:subDesde) / 60000.0)
    $t = 'Llevo ' + $(if ($min -lt 1) { 'menos de un minuto' } elseif ($min -eq 1) { 'un minuto' } else { "$min minutos" }) + ' subtitulando'
    if ($script:subIdioma) { $t += ', y el juego habla ' + (Get-NombreIdioma $script:subIdioma) }
    if ($script:subMsPeor -gt 0) { $t += '. Lo que mas ha tardado un subtitulo son ' + [Math]::Round($script:subMsPeor / 1000.0, 1) + ' segundos' }
    $quedan = $SubtitulosMaxMin - $min
    if ($quedan -gt 0) { $t += ". Me callo sola en $quedan" + $(if ($quedan -eq 1) { ' minuto' } else { ' minutos' }) }
    return $t + '.'
}

# EL IDIOMA, EN CRISTIANO: "el juego habla en" y luego "en" no sirve de nada.
$IDIOMAS_SUB = @{
    'en' = 'ingles'; 'es' = 'espanol'; 'fr' = 'frances'; 'de' = 'aleman'; 'it' = 'italiano'
    'pt' = 'portugues'; 'ja' = 'japones'; 'ko' = 'coreano'; 'zh' = 'chino'; 'ru' = 'ruso'
    'pl' = 'polaco'; 'nl' = 'holandes'; 'sv' = 'sueco'; 'tr' = 'turco'; 'ar' = 'arabe'
}
function Get-NombreIdioma([string]$cod) {
    $c = ([string]$cod).ToLowerInvariant()
    if ($IDIOMAS_SUB.ContainsKey($c)) { return [string]$IDIOMAS_SUB[$c] }
    return 'otro idioma'
}

# =====================================================================
# EL RELOJ DEL REEMBOLSO (1/10, la 11 de las 20 funciones) — LA MITAD QUE SE PUEDE
# =====================================================================
# STEAM DEVUELVE EL DINERO con menos de DOS HORAS jugadas y menos de CATORCE DIAS desde la compra.
# MEDIDO: la fecha de compra NO EXISTE en ningun sitio al que Nova pueda llegar. 'PurchaseTime',
# 'Licenses' y 'rt_purchase' dan CERO apariciones en localconfig.vdf; el appmanifest solo trae
# 'LastPlayed'; y la API publica no la expone. Asi que los catorce dias no se pueden contar.
# LAS DOS HORAS SI, y son el limite que de verdad se pasa por alto: Nova lleva los segundos jugados
# por juego en memoria\juegos.json desde el 19/09. Medido ahi: It Takes Two 12,86 h, Spider-Man 3,38,
# Unravel Two 0,16, ELDEN RING 0,10. Asi que avisa al acercarse a las dos horas y DICE lo que no
# sabe, en vez de prometer un plazo que no puede calcular.
$ReembolsoHoras = 2.0
$ReembolsoAvisaMin = 95           # a hora y media y pico: da tiempo a decidir sin cortar la partida
$script:reembolsoDicho = @{}

function Get-HorasJugadas([string]$juego) {
    try {
        $clave = (ConvertTo-Plain $juego) -replace '[^a-z0-9]', ''
        foreach ($p in (Get-JuegosMem).PSObject.Properties) {
            if (((ConvertTo-Plain $p.Name) -replace '[^a-z0-9]', '') -ne $clave) { continue }
            $seg = 0.0
            try { foreach ($d in $p.Value.dias.PSObject.Properties) { $seg += [double]$d.Value } } catch {}
            return [Math]::Round($seg / 3600.0, 2)
        }
    } catch {}
    return -1
}

function Get-FraseReembolso([string]$juego) {
    if (-not $juego) { return 'Dime de que juego.' }
    $h = Get-HorasJugadas $juego
    if ($h -lt 0) { return "No tengo apuntado tiempo de juego de $juego." }
    $min = [int][Math]::Round($h * 60)
    if ($h -ge $ReembolsoHoras) {
        return ('En ' + $juego + ' llevas ' + [Math]::Round($h, 1) + ' horas, o sea que ya pasaste de las dos: ' +
                'Steam ya no lo devuelve por el limite de tiempo.')
    }
    $quedan = [int][Math]::Round(($ReembolsoHoras * 60) - $min)
    # Y SE DICE LO QUE NO SE SABE: sin la fecha de compra, la mitad de los catorce dias no se puede
    # calcular, y callarselo haria creer que el plazo esta entero.
    return ('En ' + $juego + ' llevas ' + $min + ' minutos, asi que te quedan ' + $quedan +
            ' antes de pasar de las dos horas. Lo de los catorce dias desde la compra no lo se: ' +
            'Steam no guarda esa fecha donde yo pueda verla.')
}

# Y EL AVISO, que es lo que hace que sirva: la ventana se pasa sola mientras juegas.
function Watch-Reembolso([string]$juego) {
    if (-not $juego) { return }
    try {
        $clave = (ConvertTo-Plain $juego) -replace '[^a-z0-9]', ''
        if ($script:reembolsoDicho.ContainsKey($clave)) { return }
        $h = Get-HorasJugadas $juego
        if ($h -lt 0) { return }
        $min = [int][Math]::Round($h * 60)
        # SOLO EN LA VENTANA: por debajo no viene a cuento, y pasadas las dos horas ya no sirve de
        # nada decirlo -el dinero ya no vuelve- y seria recordarle algo que no puede arreglar.
        if ($min -lt $ReembolsoAvisaMin -or $min -ge ($ReembolsoHoras * 60)) { return }
        $script:reembolsoDicho[$clave] = $true
        $quedan = [int][Math]::Round(($ReembolsoHoras * 60) - $min)
        [void](Send-AvisoEntorno ('reembolso-' + $clave) ('Llevas ' + $min + ' minutos en ' + $juego +
              ' y a las dos horas Steam ya no te lo devuelve: te quedan ' + $quedan +
              '. Si no te esta gustando, es ahora.') 'medio' 1440)
    } catch {}
}

# =====================================================================
# EL RESUMEN DE LA PARTIDA QUE ACABA (1/10, la 20 de las 20 funciones)
# =====================================================================
# Nova escribe el parte del dia y el resumen de la semana, pero de LA SESION QUE SE CIERRA no decia
# nada, y es el momento en que apetece oirlo: acabas de soltar el mando.
# TODO SALE DE LO QUE YA MIDE, sin apuntar nada nuevo: los minutos de la partida (juegoSesionMin), lo
# jugado hoy (juegos.json), la bateria que se fue (el tramo de Update-BateriaJuego) y los logros que
# cayeron (Nova ya los vigila). Si de algo no hay dato, esa parte no se dice en vez de rellenarse.
# Y NO SE DICE NADA SI LA PARTIDA FUE CORTA: por debajo del minimo ni se llega aqui, y una frase por
# cada rato de diez minutos acabaria siendo ruido.
$script:sesionBatDesde = -1

function Get-FraseResumenSesion([string]$juego, [int]$minutos, [int]$segundos) {
    if (-not $juego -or $minutos -le 0) { return '' }
    $piezas = @()
    # 1. lo que ha durado, dicho como se dice
    $dur = if ($minutos -ge 60) {
        $h = [int][Math]::Floor($minutos / 60); $m = $minutos % 60
        '' + $h + ' ' + $(if ($h -eq 1) { 'hora' } else { 'horas' }) + $(if ($m -gt 0) { ' y ' + $m + ' minutos' } else { '' })
    } else { '' + $minutos + ' minutos' }
    $piezas += ('Has jugado ' + $dur + ' a ' + $juego)
    # 2. y cuanto llevas hoy EN TOTAL, que es el dato que no se tiene en la cabeza
    try {
        $hoyMin = [int](Get-MinutosJuegoHoy)
        if ($hoyMin -gt $minutos + 5) {
            $durH = if ($hoyMin -ge 60) {
                $h2 = [int][Math]::Floor($hoyMin / 60); $m2 = $hoyMin % 60
                '' + $h2 + ' h' + $(if ($m2 -gt 0) { ' ' + $m2 + ' min' } else { '' })
            } else { '' + $hoyMin + ' min' }
            $piezas += ('hoy llevas ' + $durH + ' en total')
        }
    } catch {}
    # 3. la bateria que se ha ido, si se jugo sin cargador
    try {
        if ($script:sesionBatDesde -ge 0) {
            $b = Get-CimInstance Win32_Battery -ErrorAction SilentlyContinue | Select-Object -First 1
            if ($b) {
                $ahoraB = [int]$b.EstimatedChargeRemaining
                $gasto = $script:sesionBatDesde - $ahoraB
                if ($gasto -ge 3) { $piezas += ('se han ido ' + $gasto + ' puntos de bateria') }
            }
        }
    } catch {}
    $script:sesionBatDesde = -1
    # 4. y los logros que cayeron en esta partida, si los hubo
    try {
        $nL = [int]$script:logrosSesion
        if ($nL -gt 0) { $piezas += ('y ' + $nL + ' ' + $(if ($nL -eq 1) { 'logro' } else { 'logros' })) }
        $script:logrosSesion = 0
    } catch {}
    return (($piezas -join ', ') + '.')
}

# =====================================================================
# EL VOLUMEN DEL MICROFONO (1/10, la 19 de las 20 funciones)
# =====================================================================
# Nova controlaba el volumen de SALIDA y el de cada app, pero no el del micro, que es justo el que se
# toca cuando entras a hablar con alguien y te dicen que no se te oye. El microfono es otro endpoint
# de Windows -eCapture en vez de eRender-, asi que son dos funciones nuevas en el .cs y nada mas.
# MEDIDO al anadirlo: salida al 70 %, micro al 54 %, y PonerVolumenMicro devuelve true.
# OJO CON LA GANANCIA DEL OIDO, QUE NO ES ESTO: Nova lleva su propia ganancia de software (x9,5,
# x26,4...) que multiplica lo que ya le llega. Esta funcion mueve el volumen del aparato en Windows,
# que es lo que oyen los demas en Discord. Son dos cosas distintas y conviene no mezclarlas: subir
# una no arregla lo que la otra estropea.
function Get-FraseVolumenMicro {
    $v = -1
    try { $v = [int][AX]::LeerVolumenMicro() } catch {}
    if ($v -lt 0) { return 'No puedo leer el volumen del microfono.' }
    $t = 'El microfono esta al ' + $v + ' por ciento'
    if ($v -eq 0) { $t += ': asi no te oye nadie' }
    elseif ($v -lt 30) { $t += ', que es bajito' }
    return $t + '.'
}

function Set-VolumenMicro([int]$pct, [string]$como = '') {
    $antes = -1
    try { $antes = [int][AX]::LeerVolumenMicro() } catch {}
    if ($antes -lt 0) { return 'No puedo tocar el volumen del microfono.' }
    # SUBIR Y BAJAR SON RELATIVOS AL DE AHORA, como en el volumen de salida: "sube el micro" no es
    # "pon el micro al 100".
    $nuevo = $pct
    if ($como -eq 'sube') { $nuevo = [Math]::Min(100, $antes + 15) }
    elseif ($como -eq 'baja') { $nuevo = [Math]::Max(0, $antes - 15) }
    if ($nuevo -lt 0) { $nuevo = 0 }
    if ($nuevo -gt 100) { $nuevo = 100 }
    if ($nuevo -eq $antes) { return 'El microfono ya estaba al ' + $antes + ' por ciento.' }
    $ok = $false
    try { $ok = [bool][AX]::PonerVolumenMicro($nuevo) } catch {}
    if (-not $ok) { return 'He pedido ' + $nuevo + ' y no me ha dejado.' }
    # SE COMPRUEBA, no se presume (regla 1): el endpoint puede aceptar la llamada y no moverse.
    $despues = -1
    try { $despues = [int][AX]::LeerVolumenMicro() } catch {}
    Log ('MICRO: volumen ' + $antes + ' -> ' + $despues)
    if ([Math]::Abs($despues - $nuevo) -gt 2) {
        return 'He pedido ' + $nuevo + ' y se ha quedado en ' + $despues + '.'
    }
    return 'Microfono al ' + $despues + ' por ciento.'
}

# =====================================================================
# LA CACHE DE SHADERS, QUE NADIE VACIA (1/10, la 10 de las 20 funciones)
# =====================================================================
# MEDIDO EN ESTA CONSOLA: 902 MB en DxcCache, 74,7 en DxCache, 3,2 en D3DSCache y 0,6 en VkCache.
# Casi un giga, con 27 GB libres de 476. Y hay un segundo motivo, que es el que lo pone en la lista:
# al cambiar la VRAM hay que vaciarla o los juegos empiezan a petardear, y eso es algo que braya
# tiene que ACORDARSE de hacer a mano.
# SE REGENERA SOLA: borrar estas carpetas no pierde nada, el juego vuelve a compilar sus shaders la
# primera vez que arranca (tarda un poco mas ese arranque y se acabo). Por eso es de las pocas cosas
# que Nova puede borrar sin preguntar, y aun asi dice cuanto ha soltado.
# NO CON UN JUEGO DELANTE: esos ficheros los puede tener abiertos el juego que esta corriendo, y
# borrar por debajo de un proceso que lee es pedir un cuelgue.
$ShadersSitios = @('AMD\DxCache', 'AMD\DxcCache', 'AMD\GLCache', 'AMD\VkCache', 'D3DSCache', 'NVIDIA\DXCache')
$VramVistaPath = Join-Path $MemoriaDir 'vram-vista.json'

function Get-CacheShaders {
    $l = @()
    foreach ($rel in $ShadersSitios) {
        $p = Join-Path $env:LOCALAPPDATA $rel
        if (-not (Test-Path -LiteralPath $p)) { continue }
        try {
            $f = @(Get-ChildItem -LiteralPath $p -Recurse -File -ErrorAction SilentlyContinue)
            if ($f.Count -eq 0) { continue }
            $b = ($f | Measure-Object -Property Length -Sum).Sum
            $l += @{ ruta = $p; nombre = (Split-Path $rel -Leaf); n = $f.Count; bytes = [double]$b }
        } catch { continue }
    }
    return @($l | Sort-Object -Property @{ Expression = { $_.bytes }; Descending = $true })
}

function Get-FraseCacheShaders {
    $l = @(Get-CacheShaders)
    if ($l.Count -eq 0) { return 'No encuentro cache de shaders que vaciar.' }
    # MEASURE-OBJECT -Property NO VE LAS CLAVES DE UNA TABLA HASH (1/10, lo cazo su banco al
    # escribirla): busca PROPIEDADES, y Get-CacheShaders devuelve hashtables, asi que lanzaba
    # "el valor del argumento Property no es valido" y la frase no salia nunca. Se suman las claves
    # a mano, que es lo que vale para las dos formas.
    $tot = 0.0
    foreach ($x in $l) { $tot += [double]$x.bytes }
    $mb = [Math]::Round($tot / 1MB, 0)
    $t = 'La cache de shaders ocupa ' + $mb + ' megas'
    $gorda = $l[0]
    if ($l.Count -gt 1) { $t += ', y ' + [Math]::Round($gorda.bytes / 1MB, 0) + ' son de ' + $gorda.nombre }
    $t += '. Se regenera sola, asi que di "vacia la cache de shaders" y la suelto.'
    return $t
}

function Clear-CacheShaders {
    if ($script:juegoActivo) {
        return 'Mejor no: esos ficheros los puede estar usando ' + $script:juegoActivo + '. Cierralo y te la vacio.'
    }
    $l = @(Get-CacheShaders)
    if ($l.Count -eq 0) { return 'No hay cache de shaders que vaciar.' }
    $antes = 0.0
    foreach ($x in $l) { $antes += [double]$x.bytes }
    $borrados = 0
    foreach ($c in $l) {
        try {
            # SE BORRA EL CONTENIDO, NO LA CARPETA: si desaparece la carpeta, algunos drivers dejan
            # de cachear hasta el siguiente reinicio y entonces TODO va mas lento, que es lo
            # contrario de lo que se venia a hacer.
            foreach ($f in @(Get-ChildItem -LiteralPath $c.ruta -Recurse -File -ErrorAction SilentlyContinue)) {
                try { Remove-Item -LiteralPath $f.FullName -Force -ErrorAction Stop; $borrados++ } catch {}
            }
        } catch {}
    }
    $despues = 0.0
    foreach ($x in @(Get-CacheShaders)) { $despues += [double]$x.bytes }
    $soltado = [Math]::Round((($antes - $despues) / 1MB), 0)
    Log ('SHADERS: cache vaciada, ' + $borrados + ' ficheros y ' + $soltado + ' MB')
    if ($soltado -le 0) { return 'He podido borrar poco: los ficheros debian estar en uso.' }
    return 'Cache de shaders vaciada: ' + $soltado + ' megas libres. El primer arranque de cada juego tardara un poco mas.'
}

# Y EL AVISO CUANDO LA VRAM CAMBIA, que es la mitad que de verdad hacia falta: ese es el momento en
# que hay que vaciarla y el que se olvida. Se guarda la VRAM vista y se compara al arrancar.
function Watch-VramCambiada {
    try {
        $vram = 0
        try { $vram = [double](Get-CimInstance Win32_VideoController -ErrorAction Stop | Select-Object -First 1).AdapterRAM } catch {}
        if ($vram -le 0) { return }
        $antes = 0
        try {
            if (Test-Path -LiteralPath $VramVistaPath) {
                $antes = [double](Get-Content -LiteralPath $VramVistaPath -Raw -Encoding UTF8 | ConvertFrom-Json).vram
            }
        } catch {}
        if ($antes -gt 0 -and [Math]::Abs($vram - $antes) -gt 64MB) {
            $gbA = [Math]::Round($antes / 1GB, 1); $gbN = [Math]::Round($vram / 1GB, 1)
            Log ('VRAM: cambio de ' + $gbA + ' a ' + $gbN + ' GB')
            [void](Send-AvisoEntorno 'vram-cambiada' ('Le has cambiado la VRAM, de ' + $gbA + ' a ' + $gbN +
                  ' gigas. Conviene vaciar la cache de shaders o los juegos van a petardear: dime "vacia la cache de shaders".') 'medio' 120)
        }
        if ($antes -ne $vram) {
            Write-Atomico $VramVistaPath (@{ vram = $vram; cuando = (Get-Date).ToString('s') } | ConvertTo-Json -Depth 3)
        }
    } catch {}
}

# =====================================================================
# APAGA LA CONSOLA CUANDO ACABE LA DESCARGA (30/09, la 8 de las 20 funciones)
# =====================================================================
# LA MAS BARATA DE LAS VEINTE, Y SE NOTA: las dos piezas ya estaban enteras. Nova sabe apagar
# (apagado programado, con su confirmacion y sus 30 s para arrepentirse) y sabe cuando una descarga
# termina (BytesDownloaded contra BytesToDownload en el manifiesto). Lo unico que faltaba era
# juntarlas, y es justo la orden que se pide para dejar algo gordo bajando e irse a dormir.
#
# TRES GUARDAS, Y LAS TRES SON REGLAS DE LA CASA:
#  1. NO SE APAGA SI NO HABIA NADA BAJANDO: "apaga cuando acabe" sin descarga apagaria al instante,
#     que no es lo que se ha pedido. Se dice y no se arma nada.
#  2. NO SE QUEDA PUESTO PARA SIEMPRE (regla 2): si la descarga se para, se cancela o no acaba en
#     $ApagarAlAcabarMaxH horas, el modo se suelta SOLO y Nova lo dice. Un modo que se queda puesto y
#     apaga la consola tres dias despues es lo peor que puede hacer esta funcion.
#  3. Y AVISA ANTES DE APAGAR, con los 30 s de siempre: el apagado nunca es una sorpresa.
$ApagarAlAcabarMaxH = 8          # mas de una noche esperando es que la descarga se quedo parada
$script:apagarAlAcabar = $false
$script:apagarAlAcabarDesde = 0
$script:apagarAlAcabarQue = ''

function Start-ApagarAlAcabar {
    $bajando = @()
    try { $bajando = @(Get-JuegosSteam | Where-Object { $_.bajando -and ([double]$_.total -gt [double]$_.descargado) }) } catch {}
    if ($bajando.Count -eq 0) {
        return 'No hay ninguna descarga en marcha, asi que no hay nada que esperar.'
    }
    $script:apagarAlAcabar = $true
    $script:apagarAlAcabarDesde = $sw.ElapsedMilliseconds
    $script:apagarAlAcabarQue = [string]$bajando[0].nombre
    $falta = [Math]::Round((([double]$bajando[0].total - [double]$bajando[0].descargado) / 1GB), 2)
    Log ('APAGAR AL ACABAR: esperando a ' + $script:apagarAlAcabarQue + ' (' + $falta + ' GB)')
    return ('Vale: cuando acabe de bajar ' + $script:apagarAlAcabarQue + ' (le faltan ' + $falta +
            ' gigas) apago la consola. Di "cancela el apagado" si cambias de idea.')
}

function Stop-ApagarAlAcabar([string]$porque = '') {
    if (-not $script:apagarAlAcabar) { return $false }
    $script:apagarAlAcabar = $false
    $script:apagarAlAcabarQue = ''
    if ($porque) { Log ('APAGAR AL ACABAR: cancelado (' + $porque + ')') }
    return $true
}

# Se mira en la ronda del minuto: una descarga no acaba en 30 ms y leer los manifiestos cuesta disco.
function Watch-ApagarAlAcabar {
    if (-not $script:apagarAlAcabar) { return }
    try {
        # LA GUARDA DEL TIEMPO VA PRIMERO: si la descarga se quedo parada, esto no puede seguir
        # armado toda la noche y apagar la consola cuando braya este jugando al dia siguiente.
        $horas = ($sw.ElapsedMilliseconds - $script:apagarAlAcabarDesde) / 3600000.0
        if ($horas -ge $ApagarAlAcabarMaxH) {
            $q = $script:apagarAlAcabarQue
            [void](Stop-ApagarAlAcabar 'pasaron las horas de espera')
            Say ('Llevo ' + [int]$horas + ' horas esperando a que acabe ' + $q + ' y no ha acabado: suelto el apagado.')
            return
        }
        $bajando = @(Get-JuegosSteam | Where-Object { $_.bajando -and ([double]$_.total -gt [double]$_.descargado) })
        if ($bajando.Count -gt 0) { return }
        # Ya no baja nada: o acabo o se paro. Las dos cosas sueltan el modo, pero solo una apaga.
        $q = $script:apagarAlAcabarQue
        [void](Stop-ApagarAlAcabar 'la descarga termino')
        Log ('APAGADO: ' + $q + ' acabo de bajar, apago en 60 s')
        Say ('Ya acabo de bajar ' + $q + '. Apago la consola en un minuto; di "cancela el apagado" si estas ahi.')
        try {
            Start-Process -FilePath 'shutdown.exe' -ArgumentList @('/s', '/t', '60') -WindowStyle Hidden -Wait
        } catch { Say 'Queria apagar y no he podido.' }
    } catch {}
}

# =====================================================================
# LA DESCARGA QUE TE ESTROPEA LA PARTIDA (30/09, la 7 de las 20 funciones)
# =====================================================================
# LO QUE SE PROMETIO: "pausar la descarga al ponerte a jugar y reanudarla al salir". LO QUE SE PUEDE,
# medido: Steam NO deja pausar por software. No hay URL 'steam://' para pausar, y en
# localconfig.vdf de esta cuenta no existen ni 'AllowDownloadsDuringGameplay' ni
# 'DownloadThrottleWhileStreaming' -se buscaron las tres claves y ninguna esta-, asi que tocar esos
# ficheros mientras Steam corre seria pelearse con un programa que los reescribe cuando quiere.
# ASI QUE SE ENTREGA LO QUE SIRVE DE VERDAD: enterarte EN EL MOMENTO de que estas jugando con una
# descarga encima -que es cuando vienen los tirones y no sabes por que- con el dato de que se baja y
# cuanto le falta, y recordar que Steam tiene su propia casilla para que no vuelva a pasar. Avisar
# con el dato exacto es poco, pero es verdad; prometer una pausa que no pasa seria peor.
$script:descargaJugandoDicha = ''

function Get-FraseDescargaJugando {
    try {
        $bajando = @(Get-JuegosSteam | Where-Object { $_.bajando })
        if ($bajando.Count -eq 0) { return '' }
        $d = $bajando[0]
        $falta = [double]$d.total - [double]$d.descargado
        if ($falta -le 0) { return '' }
        $gb = [Math]::Round($falta / 1GB, 2)
        $pct = 0
        if ([double]$d.total -gt 0) { $pct = [int](([double]$d.descargado / [double]$d.total) * 100) }
        $t = 'Ojo: Steam esta bajando ' + $d.nombre + ' (' + $pct + ' %, le faltan ' + $gb + ' gigas) y eso te va a dar tirones.'
        $t += ' Di "pausa las descargas" y te abro donde se para.'
        return $t
    } catch { return '' }
}

# Y EL AVISO AL ENTRAR EN EL JUEGO, una sola vez por descarga: repetirlo en cada alt-tab seria
# exactamente el fallo que se arreglo el 28/09 con el aviso de las dos horas.
function Watch-DescargaJugando([string]$juego) {
    try {
        $bajando = @(Get-JuegosSteam | Where-Object { $_.bajando })
        if ($bajando.Count -eq 0) { $script:descargaJugandoDicha = ''; return }
        $quien = [string]$bajando[0].nombre
        if ($script:descargaJugandoDicha -eq $quien) { return }
        $script:descargaJugandoDicha = $quien
        $fr = Get-FraseDescargaJugando
        if ($fr) { [void](Send-AvisoEntorno 'descarga-jugando' $fr 'medio' 60) }
    } catch {}
}

# =====================================================================
# LA BATERIA DEL MANDO (30/09, la 6 de las 20 funciones)
# =====================================================================
# MEDIDO ANTES DE PROMETERLO, y el resultado cambia la funcion: el mando INTEGRADO de la Ally
# contesta BatteryType=0 (desconectado) y BatteryLevel=0. No reporta bateria propia porque no la
# tiene: es parte de la consola. Asi que "el mando esta al 0 %" seria mentir con un dato de verdad.
# LO QUE HACE ENTONCES: con un mando EXTERNO inalambrico (tipo 2 pilas o 3 recargable) dice el nivel
# y avisa cuando esta bajo; con el integrado dice que su bateria es la de la consola y manda a la
# pregunta que si tiene respuesta. XInput no da porcentaje: son cuatro escalones, y se dicen como
# escalones y no como un numero inventado.
$MandoBatNiveles = @{ 0 = 'vacia'; 1 = 'baja'; 2 = 'media'; 3 = 'llena' }

function Get-BateriaMando {
    for ($u = 0; $u -lt 4; $u++) {
        try {
            $st = New-Object AX+XINPUT_STATE
            if ([AX]::XInputGetState([uint32]$u, [ref]$st) -ne 0) { continue }
            $b = New-Object AX+XINPUT_BATTERY_INFORMATION
            if ([AX]::XInputGetBatteryInformation([uint32]$u, 0, [ref]$b) -ne 0) { continue }
            return @{ puerto = $u; tipo = [int]$b.BatteryType; nivel = [int]$b.BatteryLevel
                      propia = ([int]$b.BatteryType -eq 2 -or [int]$b.BatteryType -eq 3) }
        } catch { continue }
    }
    return $null
}

function Get-FraseBateriaMando {
    $m = Get-BateriaMando
    if ($null -eq $m) { return 'No veo ningun mando conectado.' }
    if (-not $m.propia) {
        # EL CASO DE ESTA CONSOLA, y se dice sin rodeos para no dejar a braya pensando que su mando
        # se va a quedar sin bateria a mitad de partida.
        return 'El mando de la consola no tiene bateria propia: la suya es la de la consola. ' +
               'Preguntame cuanto dura la bateria y te lo digo.'
    }
    $n = if ($MandoBatNiveles.ContainsKey($m.nivel)) { $MandoBatNiveles[$m.nivel] } else { 'no se sabe' }
    $t = 'El mando tiene la bateria ' + $n
    if ($m.tipo -eq 2) { $t += ' (son pilas)' }
    $t += '.'
    if ($m.nivel -le 1) { $t += ' Ve preparando el cable o las pilas.' }
    return $t
}

# Y EL AVISO, que es para lo que sirve de verdad: enterarse ANTES de que se muera a mitad de partida.
# Se mira en la ronda del minuto, no en cada vuelta: el nivel de un mando no cambia en 30 ms.
$script:mandoBatAvisado = -1
function Watch-BateriaMando {
    try {
        $m = Get-BateriaMando
        if ($null -eq $m -or -not $m.propia) { return }
        # SOLO AL BAJAR, Y UNA VEZ POR NIVEL: sin esto seria una linea por minuto hasta que lo cargue.
        if ($m.nivel -le 1 -and $m.nivel -ne $script:mandoBatAvisado) {
            $script:mandoBatAvisado = $m.nivel
            $n = if ($MandoBatNiveles.ContainsKey($m.nivel)) { $MandoBatNiveles[$m.nivel] } else { 'baja' }
            [void](Send-AvisoEntorno 'mando-bateria' ('El mando tiene la bateria ' + $n + '.') 'medio' 60)
        } elseif ($m.nivel -ge 2) { $script:mandoBatAvisado = -1 }
    } catch {}
}

# =====================================================================
# EL PERFIL DE ENERGIA POR JUEGO (30/09, la 5 de las 20 funciones)
# =====================================================================
# LO QUE SE MIDIO ANTES DE PROMETER NADA, que es lo que la ficha pedia. En esta consola NO hay WMI de
# ASUS accesible (ASUSWMI, AsusAtkWmi, ATKWMI: ninguna responde) y el TDP en vatios lo lleva Armoury
# Crate por su cuenta. Pero la consola SI expone sus perfiles como PLANES DE ENERGIA de Windows:
#   Turbo (activo), PD Turbo, Performance, Equilibrado
# y 'powercfg /setactive' los cambia. Asi que no se tocan vatios -eso seria pelearse con Armoury-,
# se cambia el perfil por el camino que la propia consola deja abierto, que es lo que de verdad
# mueve el consumo. Si algun dia desaparecen esos planes, Nova lo dice y no inventa ninguno.
$PlanesPath = Join-Path $MemoriaDir 'planes-juego.json'

function Get-PlanesEnergia {
    $l = @()
    try {
        foreach ($li in @(& powercfg /list 2>&1)) {
            $m = [regex]::Match([string]$li, '([0-9a-fA-F-]{36})\s+\(([^)]+)\)(\s*\*)?')
            if ($m.Success) {
                $l += @{ guid = $m.Groups[1].Value; nombre = $m.Groups[2].Value.Trim()
                         activo = [bool]$m.Groups[3].Value }
            }
        }
    } catch {}
    return @($l)
}

function Get-PlanEnergiaActual {
    $a = @(Get-PlanesEnergia | Where-Object { $_.activo }) | Select-Object -First 1
    if ($a) { return [string]$a.nombre }
    return ''
}

# Se busca por lo que diria braya, no por el nombre exacto: "turbo", "rendimiento", "equilibrado",
# "ahorro". Si lo que pide no existe en ESTA consola, se dice con los que si hay.
function Set-PlanEnergia([string]$como) {
    $planes = @(Get-PlanesEnergia)
    if ($planes.Count -eq 0) { return @{ ok = $false; texto = 'Esta consola no me da sus perfiles de energia.' } }
    $q = ConvertTo-Plain $como
    $elegido = $null
    # el mas largo primero: 'pd turbo' antes que 'turbo', o "pon pd turbo" se quedaria en Turbo
    # POR PALABRAS COMPLETAS, NO POR SUBCADENA (30/09, lo cazo su banco al escribirla). Esto llevaba
    # '$q.Contains($n)', y entonces "hiperturbo galactico" activaba TURBO, porque 'hiperturbo'
    # contiene 'turbo': cualquier frase con el nombre de un perfil metido dentro de otra palabra le
    # cambiaba el perfil a la consola sin que braya lo hubiera pedido. Con \b solo casa esa palabra.
    foreach ($p in @($planes | Sort-Object { -([string]$_.nombre).Length })) {
        $n = ConvertTo-Plain ([string]$p.nombre)
        if (-not $n) { continue }
        if ($n -eq $q -or ($q -match ('\b' + [regex]::Escape($n) + '\b'))) { $elegido = $p; break }
    }
    if (-not $elegido) {
        # sinonimos de lo que braya dice de verdad
        $mapa = @{ 'rendimiento' = 'performance'; 'maximo' = 'turbo'; 'potencia' = 'turbo'
                   'ahorro' = 'equilibrado'; 'normal' = 'equilibrado'; 'medio' = 'equilibrado' }
        foreach ($k in $mapa.Keys) {
            if ($q.Contains($k)) {
                $elegido = @($planes | Where-Object { (ConvertTo-Plain ([string]$_.nombre)).Contains($mapa[$k]) }) | Select-Object -First 1
                if ($elegido) { break }
            }
        }
    }
    if (-not $elegido) {
        return @{ ok = $false; texto = ('No tengo un perfil que se llame asi. Tienes: ' +
                  ((@($planes | ForEach-Object { $_.nombre })) -join ', ') + '.') }
    }
    if ($elegido.activo) { return @{ ok = $true; texto = ('Ya estabas en ' + $elegido.nombre + '.'); nombre = [string]$elegido.nombre } }
    try {
        $null = & powercfg /setactive $elegido.guid 2>&1
        # SE COMPRUEBA QUE DE VERDAD CAMBIO, no se presume: powercfg puede fallar sin decir nada y
        # dar por hecho un cambio que no paso es la regla 1 de esta casa.
        $ahora = Get-PlanEnergiaActual
        if ((ConvertTo-Plain $ahora) -eq (ConvertTo-Plain ([string]$elegido.nombre))) {
            Log ('ENERGIA: perfil cambiado a ' + $elegido.nombre)
            return @{ ok = $true; texto = ('Perfil de energia en ' + $elegido.nombre + '.'); nombre = [string]$elegido.nombre }
        }
        return @{ ok = $false; texto = ('He pedido ' + $elegido.nombre + ' y la consola sigue en ' + $ahora + '.') }
    } catch {
        return @{ ok = $false; texto = ('No he podido cambiarlo: ' + $_.Exception.Message) }
    }
}

function Get-PlanesJuego {
    try {
        if (Test-Path -LiteralPath $PlanesPath) {
            $j = Get-Content -LiteralPath $PlanesPath -Raw -Encoding UTF8 | ConvertFrom-Json
            $h = @{}
            foreach ($p in $j.PSObject.Properties) { $h[$p.Name] = [string]$p.Value }
            return $h
        }
    } catch {}
    return @{}
}

# SE APRENDE DEL USO, NO SE CONFIGURA. Si braya pide un perfil con un juego delante, ese es el perfil
# de ese juego: no hay que preguntarle nada ni abrir un fichero a mano.
function Save-PlanJuego([string]$juego, [string]$plan) {
    if (-not $juego -or -not $plan) { return }
    # EN MODO INVITADO NO SE APRENDE (1/10, lo cazo el banco 2n18). A cuantos vatios se juega a cada
    # cosa es GUSTO DE BRAYA: si un amigo coge la consola, pide turbo y Nova se lo queda como el
    # perfil de ese juego, le ha cambiado una preferencia suya por la de otro. El perfil SI se
    # cambia -lo ha pedido quien esta delante- pero no se apunta.
    if ($script:invitado) { Log 'ENERGIA: modo invitado, no me quedo con este perfil'; return }
    try {
        $h = Get-PlanesJuego
        $clave = (ConvertTo-Plain $juego) -replace '[^a-z0-9]', ''
        if (-not $clave) { return }
        if ($h[$clave] -eq $plan) { return }     # nada que escribir si no cambia (regla 4)
        $h[$clave] = $plan
        $o = New-Object PSObject
        foreach ($k in $h.Keys) { $o | Add-Member -NotePropertyName $k -NotePropertyValue $h[$k] -Force }
        Write-Atomico $PlanesPath ($o | ConvertTo-Json -Depth 3)
        Log ('ENERGIA: me quedo con ' + $plan + ' para ' + $juego)
    } catch {}
}

function Set-PlanDeEseJuego([string]$juego) {
    if (-not $juego) { return '' }
    $h = Get-PlanesJuego
    $clave = (ConvertTo-Plain $juego) -replace '[^a-z0-9]', ''
    if (-not $h.ContainsKey($clave)) { return '' }
    $r = Set-PlanEnergia $h[$clave]
    if ($r.ok) { return [string]$h[$clave] }
    return ''
}

# =====================================================================
# CUANTO DURARA LA BATERIA CON ESTE JUEGO (30/09, la 4 de las 20 funciones)
# =====================================================================
# EL DATO YA ESTABA Y NADIE LO PREGUNTABA. Update-BateriaJuego lleva desde el 13/09 apuntando el
# ritmo de gasto POR JUEGO en %/h, con media movil y aviso si un tramo se sale de SU media. Lo que
# no existia es la pregunta: Nova sabia el porcentaje -"te queda el 60 %"- y eso no dice nada en una
# portatil, porque las horas que quedan dependen brutalmente del juego.
# MEDIDO HOY: de nueve juegos con tiempos, solo UNO tiene ritmo apuntado (30 %/h, una muestra). Asi
# que esta funcion empieza sabiendo poco y mejora jugando, y eso hay que DECIRLO en vez de inventar
# un numero: de una sola muestra no sale una promesa.
function Get-FraseAutonomia([string]$juego = '') {
    $b = $null
    try { $b = Get-CimInstance Win32_Battery -ErrorAction SilentlyContinue | Select-Object -First 1 } catch {}
    if (-not $b) { return 'Esta consola no me dice nada de su bateria.' }
    $pct = 0
    try { $pct = [int]$b.EstimatedChargeRemaining } catch {}
    $cargando = $false
    try { $cargando = ([int]$b.BatteryStatus -eq 2) } catch {}
    $quien = if ($juego) { $juego } elseif ($script:juegoActivo) { [string]$script:juegoActivo } else { '' }
    if ($cargando) {
        $t = 'Estas enchufado, al ' + $pct + ' %.'
        if ($quien) { $t += ' Sin cargador, con ' + $quien + ' ' + (Get-TrozoAutonomia $pct $quien) }
        return $t
    }
    if (-not $quien) {
        # sin juego delante no hay a quien preguntarle el ritmo; se dice el porcentaje y se ofrece
        return 'Te queda el ' + $pct + ' % y no hay ningun juego abierto, asi que no se a que ritmo se va. Preguntame con el juego puesto.'
    }
    return 'Te queda el ' + $pct + ' % y con ' + $quien + ' ' + (Get-TrozoAutonomia $pct $quien)
}

# El trozo que convierte "%/h de este juego" en tiempo. Aparte porque lo usan las dos ramas de
# arriba, y porque es lo unico que de verdad hay que probar.
function Get-TrozoAutonomia([int]$pct, [string]$juego) {
    $ritmo = 0.0
    $muestras = 0
    $deQuien = ''
    try {
        $m = Get-JuegosMem
        $clave = (ConvertTo-Plain $juego) -replace '[^a-z0-9]', ''
        foreach ($p in $m.PSObject.Properties) {
            if (((ConvertTo-Plain $p.Name) -replace '[^a-z0-9]', '') -ne $clave) { continue }
            try { $ritmo = [double]$p.Value.ritmoBateria } catch {}
            try { $muestras = [int]$p.Value.muestrasBateria } catch {}
            if ($ritmo -gt 0) { $deQuien = 'suyo' }
            break
        }
        # SI DE ESTE JUEGO NO SE SABE, SE USA LA MEDIA DE LOS DEMAS Y SE DICE QUE ES UNA MEDIA.
        # Callarse seria mas honesto que inventar, pero menos util: una media de otros juegos es un
        # dato de verdad, solo hay que decir de donde sale.
        if ($ritmo -le 0) {
            $otros = @()
            foreach ($p in $m.PSObject.Properties) {
                try { if ([double]$p.Value.ritmoBateria -gt 0) { $otros += [double]$p.Value.ritmoBateria } } catch {}
            }
            if ($otros.Count) { $ritmo = ($otros | Measure-Object -Average).Average; $deQuien = 'media' }
        }
    } catch {}
    if ($ritmo -le 0) { return 'todavia no se cuanto gasta: lo aprendo jugando y te lo digo cuando lo sepa.' }
    $horas = $pct / $ritmo
    $min = [int][Math]::Floor($horas * 60)
    $t = ''
    if ($min -ge 120) { $t = 'te quedan unas ' + [Math]::Round($horas, 1) + ' horas' }
    elseif ($min -ge 60) { $t = 'te queda algo mas de una hora (' + $min + ' minutos)' }
    else { $t = 'te quedan ' + $min + ' minutos' }
    if ($deQuien -eq 'media') { $t += ', contando la media de tus otros juegos porque de este todavia no tengo medidas' }
    elseif ($muestras -le 1) { $t += ', aunque de una sola partida medida: el numero se afinara' }
    return $t + '.'
}

# =====================================================================
# MOVER UN JUEGO A OTRO DISCO, HABLANDO (30/09, la 3 de las 20 funciones)
# =====================================================================
# NOVA NO MUEVE LOS FICHEROS ELLA, Y ES A PROPOSITO. Mover un juego de Steam a mano es mover la
# carpeta de 'steamapps\common', mover su appmanifest_*.acf y que Steam se entere; si algo sale a
# medias, el juego queda roto y hay que volver a bajarlo -139,57 GB en el caso de Black Myth-. Con
# 27 GB libres y una conexion normal, eso es una tarde perdida por una orden de voz.
# LO QUE SI HACE ES TODO LO DEMAS, que es donde esta el trabajo de verdad: comprobar que el juego
# existe, que el disco destino esta PUESTO -braya tiene una biblioteca en E: y esa unidad no esta
# conectada ahora mismo-, que CABE, y abrir Steam donde esta el boton. Si no cabe o no esta, lo dice
# y no abre nada: eso es la regla 1, no hacer a medias algo que se puede dejar sin empezar.
function Get-FraseMoverJuego([string]$juego, [string]$destino = '') {
    $l = @(Get-EspacioPorJuego)
    if ($l.Count -eq 0) { return @{ texto = 'No tengo los tamanos de tus juegos todavia.'; abrir = '' } }
    $clave = (ConvertTo-Plain $juego) -replace '[^a-z0-9]', ''
    if ($clave.Length -lt 3) { return @{ texto = 'Dime el nombre del juego un poco mas largo.'; abrir = '' } }
    $uno = @($l | Where-Object {
        $c = (ConvertTo-Plain $_.nombre) -replace '[^a-z0-9]', ''
        $c -eq $clave -or $c.StartsWith($clave) }) | Select-Object -First 1
    if (-not $uno) { return @{ texto = "No encuentro $juego entre tus juegos instalados."; abrir = '' } }
    $us = @(Get-Unidades)
    $aqui = ''
    try { $aqui = $LogDir.Substring(0, 1).ToUpper() } catch {}
    # EL DESTINO: el que diga braya, o si no el que mas sitio tenga de los otros. 'la tarjeta' y
    # 'el de fuera' son como lo dice el, asi que entran por nombre y no solo por letra.
    $dest = $null
    if ($destino -match '^[a-zA-Z]$') {
        $dest = @($us | Where-Object { $_.letra -eq $destino.ToUpper() }) | Select-Object -First 1
        if (-not $dest) { return @{ texto = "El disco $($destino.ToUpper()) no esta puesto ahora mismo."; abrir = '' } }
    } elseif ($destino -match 'tarjeta|micro\s*sd|sd|fuera|extraible|externo') {
        $dest = @($us | Where-Object { $_.tipo -eq 'extraible' } | Sort-Object bytesLibres -Descending) | Select-Object -First 1
        if (-not $dest) { return @{ texto = 'No veo ninguna tarjeta ni disco de fuera puesto ahora mismo.'; abrir = '' } }
    } else {
        $dest = @($us | Where-Object { $_.letra -ne $aqui } | Sort-Object bytesLibres -Descending) | Select-Object -First 1
        if (-not $dest) { return @{ texto = 'Solo tienes un disco puesto, no hay donde moverlo.'; abrir = '' } }
    }
    # ¿CABE? Con un margen: dejar el destino a cero es dejarlo inservible. El 5 % o 5 GB, el mayor.
    $margen = [Math]::Max(5GB, $dest.bytesTotal * 0.05)
    $libre = [double]$dest.bytesLibres
    $necesita = [double]$uno.bytes
    $gbLibre = [Math]::Round($libre / 1GB, 1)
    if (($libre - $margen) -lt $necesita) {
        return @{ texto = ('No cabe: ' + $uno.nombre + ' ocupa ' + $uno.gb + ' gigas y en ' +
                           $dest.letra + ' solo quedan ' + $gbLibre + ', contando el margen que hay que dejar libre.')
                  abrir = '' }
    }
    $t = $uno.nombre + ' ocupa ' + $uno.gb + ' gigas y en ' + $dest.letra + ' quedan ' + $gbLibre +
         ': cabe. Te abro Steam en sus propiedades, y el boton de mover esta en "Archivos locales".'
    # NO LO MUEVO YO, Y SE DICE: braya tiene que saber que el ultimo paso es suyo, porque si cree
    # que ya esta movido y apaga la consola a medias, el que pierde el juego es el.
    $url = ''
    if ($uno.appid) { $url = 'steam://gameproperties/' + $uno.appid }
    return @{ texto = $t; abrir = $url; gb = $uno.gb; destino = $dest.letra }
}

# =====================================================================
# QUE BORRAR PARA HACER SITIO (30/09, la 2 de las 20 funciones)
# =====================================================================
# EL DATO QUE LA PIDE: 27 GB libres de 476, y 320,3 GB en veinte juegos. Black Myth: Wukong ocupa
# 139,57 GB EL SOLO -el 43 % de todo lo instalado- y Spider-Man otros 65,96: entre los dos, 205 GB.
# Nova ya sabia decir cuanto queda; lo que no sabia es QUE quitar, que es la pregunta de verdad.
#
# EL TAMANO SALE DEL MANIFIESTO DE STEAM, no de medir carpetas: 'SizeOnDisk' del appmanifest_*.acf
# esta ahi ya contado y leerlo cuesta milisegundos. Medir 320 GB de carpetas a mano seria barrer el
# disco entero por una pregunta que se contesta hablando.
# Y LOS DIAS SIN JUGAR SALEN DE LO QUE NOVA YA APUNTA (memoria\juegos.json): sin eso la lista seria
# solo "lo mas gordo", y lo mas gordo puede ser justo lo que esta jugando esta semana.
function Get-EspacioPorJuego {
    $fuera = @()
    try {
        $mem = @{}
        try {
            # las fechas en que se jugo cada uno, para saber cuanto lleva sin tocarse
            #
            # LA CLAVE SE APLASTA A LETRAS Y NUMEROS, no vale ConvertTo-Plain (30/09, lo canto la
            # primera prueba). El manifiesto de Steam trae "Marvel's Spider-Man Remastered" con el
            # apostrofe tipografico U+2019, y memoria\juegos.json lo guardo con otra forma: dos
            # textos que son el mismo juego y no casaban, asi que Nova decia "no tengo apuntado que
            # lo hayas jugado" de un juego que esta en su propio fichero de tiempos. Quitando todo
            # lo que no es a-z0-9 el apostrofe deja de existir y el cruce funciona.
            foreach ($p in (Get-JuegosMem).PSObject.Properties) {
                $dias = @()
                try { foreach ($d in $p.Value.dias.PSObject.Properties) { $dias += [string]$d.Name } } catch {}
                if ($dias.Count) {
                    $k = (ConvertTo-Plain $p.Name) -replace '[^a-z0-9]', ''
                    # EL @() DE DELANTE NO SOBRA (30/09, lo cazo su banco). Con UN solo dia jugado,
                    # 'Sort-Object' devuelve un escalar en vez de una lista, y el [0] sobre una
                    # cadena coge su PRIMER CARACTER: '2026-09-28'[0] es '2', que no es una fecha y
                    # deja el juego como "no tengo apuntado que lo hayas jugado". Con las pruebas
                    # sobre los juegos de braya no se veia, porque los suyos tienen varios dias.
                    # Es el mismo mordisco de PowerShell que ya esta fichado en esta casa dos veces.
                    if ($k) { $mem[$k] = @($dias | Sort-Object -Descending)[0] }
                }
            }
        } catch {}
        $hoy = Get-Date
        foreach ($j in @($script:Juegos)) {
            $b = 0.0
            foreach ($campo in @('bytes', 'tam', 'SizeOnDisk')) {
                try { if ($j.$campo) { $b = [double]$j.$campo; break } } catch {}
            }
            if ($b -le 0) { continue }
            $clave = (ConvertTo-Plain ([string]$j.nombre)) -replace '[^a-z0-9]', ''
            $sin = -1
            if ($mem.ContainsKey($clave)) {
                try {
                    # Y LA FECHA SE COMPRUEBA ANTES DE CREERLA: una clave que no sea una fecha de
                    # verdad se convierte en el ano 1 y salen "739889 dias sin jugar", que es lo que
                    # dijo en la primera prueba. Fuera de un rango razonable vale lo mismo que no
                    # saberlo, y no saberlo ya se dice de otra manera.
                    $f = [datetime]::MinValue
                    if ([datetime]::TryParseExact($mem[$clave], 'yyyy-MM-dd', $null,
                            [Globalization.DateTimeStyles]::None, [ref]$f)) {
                        # FLOOR Y NO [int] (30/09, lo cazo su banco): [int] en PowerShell REDONDEA,
                        # asi que un juego tocado hace tres dias a las 22:00 sale con 3,93 dias y se
                        # decia "hace 4 dias". Lo que se cuenta son dias COMPLETOS sin abrirlo.
                        $d = [int][Math]::Floor(($hoy - $f).TotalDays)
                        if ($d -ge 0 -and $d -le 3650) { $sin = $d }
                    }
                } catch { $sin = -1 }
            }
            $fuera += @{ nombre = [string]$j.nombre; gb = [Math]::Round($b / 1GB, 2); bytes = $b
                         dias = $sin; appid = [string]$j.appid }
        }
    } catch {}
    return @($fuera | Sort-Object -Property @{ Expression = { $_.gb }; Descending = $true })
}

# La frase, dicha como se dice. Y el candidato NO es solo el mas gordo: es el mas gordo DE LOS QUE
# no se tocan, porque recomendar borrar lo que esta jugando esta semana no es una recomendacion.
function Get-FraseQueBorrar([string]$juego = '') {
    $l = @(Get-EspacioPorJuego)
    if ($l.Count -eq 0) { return 'No tengo los tamanos de tus juegos todavia.' }
    if ($juego) {
        $clave = ConvertTo-Plain $juego
        $uno = @($l | Where-Object { (ConvertTo-Plain $_.nombre) -eq $clave -or (ConvertTo-Plain $_.nombre).StartsWith($clave) }) | Select-Object -First 1
        if (-not $uno) { return "No encuentro $juego entre tus juegos instalados." }
        $t = 'Si borras ' + $uno.nombre + ' recuperas ' + $uno.gb + ' gigas'
        if ($uno.dias -ge 0) { $t += ', y no lo tocas desde hace ' + $uno.dias + ' ' + $(if ($uno.dias -eq 1) { 'dia' } else { 'dias' }) }
        elseif ($uno.dias -lt 0) { $t += ', y no tengo apuntado que lo hayas jugado' }
        return $t + '.'
    }
    # EL CANDIDATO: el mas gordo que lleve al menos una semana sin tocarse. Si todos son recientes,
    # se dice el mas gordo igual pero avisando de que lo estas jugando, que no es lo mismo.
    $quietos = @($l | Where-Object { $_.dias -ge 7 -or $_.dias -lt 0 })
    $cand = if ($quietos.Count) { $quietos[0] } else { $l[0] }
    $libreGb = 0
    try { $libreGb = [Math]::Round(([System.IO.DriveInfo]::new($LogDir.Substring(0, 1)).AvailableFreeSpace) / 1GB, 1) } catch {}
    $t = ''
    if ($libreGb -gt 0) { $t = 'Te quedan ' + $libreGb + ' gigas. ' }
    $t += 'Lo que mas te sobra es ' + $cand.nombre + ': ' + $cand.gb + ' gigas'
    if ($cand.dias -ge 7) { $t += ' y llevas ' + $cand.dias + ' dias sin abrirlo' }
    elseif ($cand.dias -lt 0) { $t += ' y no tengo apuntado que lo hayas jugado' }
    else { $t += ', aunque lo jugaste hace ' + $cand.dias + ' ' + $(if ($cand.dias -eq 1) { 'dia' } else { 'dias' }) }
    $t += '.'
    # SI EL MAS GORDO NO ES EL CANDIDATO, SE DICE POR QUE (30/09). La primera version recomendaba
    # borrar uno de 65 GB y acto seguido decia "detras van" uno de 139: incoherente de leer, y
    # escondia justo el dato que decide. Si el mayor se ha jugado hace poco, eso es la informacion.
    if ($l[0].nombre -ne $cand.nombre) {
        $t += ' El mas gordo es ' + $l[0].nombre + ' con ' + $l[0].gb + ' gigas'
        if ($l[0].dias -ge 0) { $t += ', pero lo jugaste hace ' + $l[0].dias + ' ' + $(if ($l[0].dias -eq 1) { 'dia' } else { 'dias' }) }
        $t += '.'
    }
    # y los siguientes del MISMO criterio -los que tampoco tocas-, que es lo que sirve para decidir
    $otros = @($l | Where-Object { $_.nombre -ne $cand.nombre -and $_.nombre -ne $l[0].nombre -and ($_.dias -ge 7 -or $_.dias -lt 0) } | Select-Object -First 2)
    if ($otros.Count) {
        $t += ' Detras van ' + (($otros | ForEach-Object { $_.nombre + ' con ' + $_.gb }) -join ' gigas y ') + ' gigas.'
    }
    return $t
}

# =====================================================================
# LA COPIA DE LA PARTIDA GUARDADA, ANTES DE JUGAR (30/09, la 1 de las 20 funciones)
# =====================================================================
# LO QUE SE RESPALDABA HASTA HOY ERA LO QUE NOVA APRENDE, no lo que braya juega: la copia del dia
# se lleva memoria\, commands.json y config.json, y de las partidas no habia nada. Un parche que
# rompe un guardado o una corrupcion y no hay vuelta atras.
#
# MEDIDO EN ESTA CONSOLA, y es lo que decide el diseno:
#   - Steam Cloud NO sirve: de las 26 carpetas de userdata solo 6 tienen 'remote', y ocupan entre
#     0 y 9 KB. Los juegos que importan no estan ahi.
#   - Las carpetas de verdad se encuentran por el nombre del juego sin espacios:
#     %APPDATA%\EldenRing, %LOCALAPPDATA%\UnravelTwo, %LOCALAPPDATA%\REANIMAL, SilentBreath.
#   - Y pesan muy distinto: ELDEN RING son 110,51 MB en 6 ficheros; Unravel Two, 0,01 MB.
#
# POR ESO NO SE COPIA SIEMPRE NI SE COPIA AQUI:
#   1. Solo si el guardado CAMBIO desde la ultima copia. Con 27 GB libres de 476, copiar 110 MB en
#      cada alt-tab llena el disco en una tarde. El sello es cuantos ficheros, cuanto pesan y la
#      fecha del mas reciente: si no se ha jugado, no hay nada que copiar.
#   2. La copia se lanza APARTE, no en el bucle. Lo de hoy ya ensena lo que cuesta pagar 15 s en el
#      camino caliente: Nova tardaba treinta segundos en activarse. Aqui se lanza un robocopy y no
#      se espera; si tarda, tarda fuera.
#   3. Y rota: se quedan las ultimas $SavesCopiasMax. Un respaldo que llena el disco es un fallo,
#      no un respaldo.
$SavesCopiasMax = 3            # cuantas copias por juego se quedan
$SavesTopeMB = 600             # mas que esto no se copia: se dice y se deja decidir a braya

# Los sitios donde los juegos de Windows guardan, de mas probable a menos. Se resuelven al
# llamar y no antes: en una maquina nueva las variables de entorno son otras.
function Get-SitiosGuardado {
    $l = @()
    foreach ($p in @($env:APPDATA, $env:LOCALAPPDATA,
                     (Join-Path $env:USERPROFILE 'Documents\My Games'),
                     (Join-Path $env:USERPROFILE 'Saved Games'),
                     (Join-Path $env:USERPROFILE 'Documents'))) {
        if ($p -and (Test-Path -LiteralPath $p)) { $l += $p }
    }
    return $l
}

# EL NOMBRE DEL JUEGO NO ES EL DE LA CARPETA: 'ELDEN RING' guarda en 'EldenRing'. Se comparan los
# dos sin espacios, sin tildes y en minusculas, que es lo que ya hace ConvertTo-Plain para todo lo
# demas en esta casa.
function Get-CarpetaGuardado([string]$nombre) {
    if (-not $nombre) { return '' }
    $clave = (ConvertTo-Plain $nombre) -replace '[^a-z0-9]', ''
    if ($clave.Length -lt 3) { return '' }      # un nombre de dos letras casaria con cualquier cosa
    foreach ($sitio in (Get-SitiosGuardado)) {
        try {
            foreach ($d in @(Get-ChildItem -LiteralPath $sitio -Directory -ErrorAction SilentlyContinue)) {
                $c = (ConvertTo-Plain $d.Name) -replace '[^a-z0-9]', ''
                if (-not $c) { continue }
                # IGUAL, O UNO DENTRO DEL OTRO, pero nunca por una sola letra en comun: 'peak'
                # no puede casar con 'speakers'. Por eso se exige que empiece igual.
                if ($c -eq $clave -or $c.StartsWith($clave) -or $clave.StartsWith($c)) {
                    return $d.FullName
                }
            }
        } catch { continue }
    }
    return ''
}

# El sello de un guardado: cuantos ficheros, cuanto pesan y cuando se toco el ultimo. Si los tres
# son iguales que en la ultima copia, no se ha jugado y no hay nada que respaldar.
function Get-SelloGuardado([string]$carpeta) {
    if (-not $carpeta -or -not (Test-Path -LiteralPath $carpeta)) { return $null }
    try {
        $f = @(Get-ChildItem -LiteralPath $carpeta -Recurse -File -ErrorAction SilentlyContinue)
        if ($f.Count -eq 0) { return $null }
        $bytes = ($f | Measure-Object -Property Length -Sum).Sum
        $ultimo = ($f | Sort-Object LastWriteTimeUtc -Descending | Select-Object -First 1).LastWriteTimeUtc
        return @{ n = $f.Count; bytes = [long]$bytes; ultimo = $ultimo.ToString('o')
                  sello = ('' + $f.Count + '|' + [long]$bytes + '|' + $ultimo.ToString('o')) }
    } catch { return $null }
}

$SavesEstadoPath = Join-Path $MemoriaDir 'saves-copias.json'

function Get-SavesEstado {
    try {
        if (Test-Path -LiteralPath $SavesEstadoPath) {
            $j = Get-Content -LiteralPath $SavesEstadoPath -Raw -Encoding UTF8 | ConvertFrom-Json
            $h = @{}
            foreach ($p in $j.PSObject.Properties) { $h[$p.Name] = [string]$p.Value }
            return $h
        }
    } catch {}
    return @{}
}

function Backup-GuardadoJuego([string]$nombre) {
    if (-not $nombre) { return 'sin nombre' }
    $carpeta = Get-CarpetaGuardado $nombre
    if (-not $carpeta) { return 'no encuentro donde guarda' }
    $s = Get-SelloGuardado $carpeta
    if ($null -eq $s) { return 'la carpeta esta vacia' }
    $estado = Get-SavesEstado
    $clave = (ConvertTo-Plain $nombre) -replace '[^a-z0-9]', ''
    if ($estado.ContainsKey($clave) -and $estado[$clave] -eq $s.sello) { return 'ya estaba copiado' }
    # EL TOPE SE COMPARA EN BYTES, NO EN LOS MB REDONDEADOS (30/09, lo cazo su banco al escribirlo).
    # Aqui habia '$mb -gt $SavesTopeMB' con $mb ya redondeado a dos decimales: un guardado de 41
    # bytes da 0,00 y no supera NINGUN tope, asi que la guarda no se podia ni probar. En produccion
    # solo afectaba por debajo de 10 KB, pero una guarda que no se puede ejercitar es una guarda que
    # nadie sabe si funciona.
    $mb = [Math]::Round($s.bytes / 1MB, 2)
    if ($s.bytes -gt ($SavesTopeMB * 1MB)) {
        Log ("SAVES: " + $nombre + " ocupa " + $mb + " MB y el tope son " + $SavesTopeMB + "; no lo copio")
        return 'pesa demasiado'
    }
    $destino = Join-Path (Join-Path $CopiasDir 'saves') ($clave + '\' + (Get-Date -Format 'yyyy-MM-dd_HHmm'))
    try {
        if (-not (Test-Path -LiteralPath $destino)) { New-Item -ItemType Directory -Force -Path $destino | Out-Null }
        # ROBOCOPY Y SIN ESPERARLO: 110 MB dentro del bucle son 110 MB de sordera. /NFL /NDL /NJH
        # /NJS para que no escriba una linea por fichero, /R:1 /W:1 para que un fichero abierto por
        # el juego no lo deje reintentando treinta veces.
        $args = @('"' + $carpeta + '"', '"' + $destino + '"', '/E', '/NFL', '/NDL', '/NJH', '/NJS', '/R:1', '/W:1')
        Start-Process -FilePath 'robocopy.exe' -ArgumentList $args -WindowStyle Hidden | Out-Null
        $estado[$clave] = $s.sello
        $o = New-Object PSObject
        foreach ($k in $estado.Keys) { $o | Add-Member -NotePropertyName $k -NotePropertyValue $estado[$k] -Force }
        Write-Atomico $SavesEstadoPath ($o | ConvertTo-Json -Depth 3)
        Log ("SAVES: copio la partida de " + $nombre + " (" + $s.n + " ficheros, " + $mb + " MB) a copias\saves")
        # Y SE PODAN LAS VIEJAS, que si no el respaldo se come el disco que venia a proteger
        try {
            $padre = Split-Path $destino -Parent
            $viejas = @(Get-ChildItem -LiteralPath $padre -Directory -ErrorAction SilentlyContinue |
                        Sort-Object Name -Descending | Select-Object -Skip $SavesCopiasMax)
            foreach ($v in $viejas) { Remove-Item -LiteralPath $v.FullName -Recurse -Force -ErrorAction SilentlyContinue }
        } catch {}
        return 'copiada'
    } catch {
        Log ('SAVES: no pude copiar la partida de ' + $nombre + ': ' + $_.Exception.Message)
        return 'fallo'
    }
}

function Enter-Juego([string]$nombre) {
    # LA COPIA DE LA PARTIDA, LO PRIMERO (30/09): antes de que el juego escriba nada. No bloquea
    # -lanza un robocopy y sigue- y no copia si no se ha jugado desde la ultima.
    try { [void](Backup-GuardadoJuego $nombre) } catch {}
    # Y SU PERFIL DE ENERGIA, SI LE HA PUESTO UNO (30/09, la 5 de las 20). Solo si braya se lo enseno
    # antes pidiendolo con este juego delante: Nova no decide sola a cuantos vatios se juega a cada
    # cosa, eso es gusto suyo. Sin perfil aprendido no se toca nada.
    try {
        $planJ = Set-PlanDeEseJuego $nombre
        if ($planJ) { Log ('ENERGIA: ' + $nombre + ' se juega en ' + $planJ + ', lo pongo') }
    } catch {}
    # Y LA BATERIA DE PARTIDA, PARA EL RESUMEN DE LA SESION (1/10, la 20 de las 20). Solo si no esta
    # enchufado: con cargador no hay gasto que contar. Y solo la PRIMERA vez, no en cada alt-tab, o
    # el resumen diria que se fue un punto cuando se fueron veinte.
    try {
        if ($script:sesionBatDesde -lt 0) {
            $bE = Get-CimInstance Win32_Battery -ErrorAction SilentlyContinue | Select-Object -First 1
            if ($bE -and [int]$bE.BatteryStatus -ne 2) { $script:sesionBatDesde = [int]$bE.EstimatedChargeRemaining }
        }
    } catch {}
    # Y SI HAY UNA DESCARGA ENCIMA, SE DICE AHORA (30/09, la 7 de las 20): jugar con Steam bajando
    # son tirones, y lo peor es no saber por que. Una vez por descarga, no en cada alt-tab.
    try { Watch-DescargaJugando $nombre } catch {}
    # IDEA 11: el juego tiene algo pendiente. En los manifiestos de Steam, StateFlags 4
    # es "instalado y listo"; cualquier otra cosa (6, 550, 1026...) es actualizacion o
    # descarga a medias. Mejor saberlo AHORA que cuando el juego no arranca.
    try {
        $jE = @($script:Juegos | Where-Object { $_.nombre -eq $nombre }) | Select-Object -First 1
        if ($jE -and [int]$jE.estado -ne 4) {
            [void](Send-AvisoEntorno "juego-pendiente-$nombre" "Ojo, $nombre tiene una actualizacion o descarga pendiente en Steam." 'medio' 120)
        }
    } catch {}
    # (el aviso de las dos horas ya NO se rearma aqui: era lo que lo mataba en cada
    #  alt-tab. Ahora se cuenta por dia, en Get-MinutosJuegoHoy.)
    $script:juegoHoras = 0
    # C4 (19/09): los minutos de la partida SIGUEN contando si es el mismo juego al que
    # se acaba de volver (un alt-tab de 10 s parte la sesion en dos, y el log del 18/09
    # tiene tres de esos); con otro juego delante, la cuenta empieza de cero.
    if (-not ($script:juegoSalida -and $script:juegoSalida.nombre -eq $nombre)) { $script:juegoSesionMin = 0; $script:juegoSesionSeg = 0 }
    $script:juegoBrilloAntes = $null
    $script:logroArchivo = ''
    # VOLVER AL JUEGO NO ES ENTRAR EN EL JUEGO (26/09, idea 4 de las 121). Esta funcion la
    # llama el bucle en cuanto la ventana del juego vuelve al primer plano, asi que un alt-tab
    # de veinte segundos cuenta como entrar y Nova suelta "Modo juego" otra vez.
    #
    # MEDIDO sobre los dos registros: 56 entradas en 14 dias, 45 de ellas vueltas a un juego ya
    # visto, y TREINTA de esas 45 en menos de una hora. Los huecos hablan solos: 24 s, 24 s,
    # 30 s, 41 s, 47 s, 52 s, 110 s, 113 s, 121 s, 130 s, 141 s, 221 s... La mitad de los "Modo
    # juego" llegan a menos de cinco minutos del anterior. La tarjeta hermana
    # (Show-RecuerdoJuego, 8920) ya tiene su guarda de una hora desde siempre; la frase hablada
    # no tenia ninguna.
    #
    # Y LA SENAL BUENA NO ES EL RELOJ, ES EL PROCESO: si el PID del juego no ha cambiado, no
    # has salido de el, por muchas horas que hayan pasado; y si ha cambiado, es una partida
    # nueva aunque hayan pasado veinte segundos. Nova guarda ese PID desde el 19/09 (C4) justo
    # para no tener que enumerar procesos en un chip de 4 nucleos. El reloj queda de respaldo
    # para cuando no hay PID -Nova reinicio, o no se pudo leer-, y su hora es la MISMA que usa
    # la tarjeta hermana: no hay numero nuevo que justificar, y los datos lo sostienen, porque
    # las 15 vueltas que pasan de una hora son las partidas nuevas de verdad.
    $vuelveAlMismo = $false
    try { $vuelveAlMismo = [bool](Test-VuelveAlMismoJuego $nombre ([int]$script:juegoPid) $sw.ElapsedMilliseconds) }
    catch { $vuelveAlMismo = $false }
    try { Show-RecuerdoJuego $nombre } catch { Log ("juegos: " + $_.Exception.Message) }
    Invoke-Reglas 'juegoAbre' $nombre
    if (-not $JuegoPerfilEntrar) { return }
    if (-not (Test-Prop $cmds.perfiles $JuegoPerfilEntrar)) { return }
    # EL BRILLO DE ANTES SOBREVIVE A UN REINICIO DE NOVA (23/09, idea 2 de la cuarta tanda).
    # Este numero vivia solo en RAM. Si Nova muere con el juego delante -y muere mucho: 235
    # arranques en 14 dias-, la instancia nueva vuelve a aplicar el perfil y lee como "brillo
    # de antes" el 100 que dejo puesto la muerta; al salir del juego escribe "brillo
    # restaurado a 100" y no restaura nada. Medido: 33 perfiles aplicados contra 21
    # restauraciones, 12 sin deshacer, y de las 16 restauraciones desde que su brillo es 70,
    # las 12 con la cadena limpia devolvieron 70 y las 4 con un reinicio en medio devolvieron
    # 100. Cuatro de cuatro: el fallo es exactamente ese y no otro.
    # DOS LLAVES para que el fichero no se use rancio: el MISMO juego tiene que seguir vivo
    # (Test-JuegoVivo, con PID y ruta) y no puede pasar de doce horas. Sin eso, el caso real
    # del 20/09 -It Takes Two a las 15:44, Nova reinicia a las 18:53, y a las 18:59 entra
    # ELDEN RING- le habria movido la pantalla sola a un numero de otro juego.
    $brilloGuardado = Join-Path $TmpDir 'juego-brillo.json'
    $script:juegoBrilloAntes = $null
    try {
        if (Test-Path -LiteralPath $brilloGuardado) {
            $gB = $null
            try { $gB = Get-Content -LiteralPath $brilloGuardado -Raw -Encoding UTF8 | ConvertFrom-Json } catch {}
            $frescoB = $false
            if ($gB -and $gB.cuando) {
                $cB = [datetime]::MinValue
                if ([datetime]::TryParse([string]$gB.cuando, [ref]$cB)) { $frescoB = ((Get-Date) - $cB).TotalHours -lt 12 }
            }
            # LA LLAVE ES EL JUEGO, NO EL PID (28/09, tras la revision). Test-JuegoVivo pregunta por el
            # PID guardado, y el PID cambia cada vez que el juego parpadea: los siete ciclos del
            # 25/09 con ELDEN RING y NIGHTREIGN duraron de 8 a 21 s cada uno. Al fallar esa llave se
            # borraba el respaldo BUENO, se leia el panel -que sigue al 100 que puso el perfil,
            # porque la salida esta aplazada y el brillo no se ha restaurado- y se guardaba 100 como
            # "el brillo de antes". A partir de ahi el 70 de braya no existia en ningun sitio y la
            # restauracion era un no-op: en el registro, las 12 lineas "JUEGO: brillo restaurado a"
            # son 12 de 12 "a 100", y la ultima vez que restauro 70 fue el 20/09 a las 12:55.
            # El caso que las dos llaves protegian -el del 20/09: It Takes Two a las 15:44, reinicio
            # a las 18:53 y ELDEN RING a las 18:59- lo cubre igual de bien el nombre del juego, y
            # mejor: no depende de que el proceso siga siendo el mismo. Las 12 horas se quedan.
            $mismoJuegoB = ($gB.juego -and ([string]$gB.juego -eq [string]$nombre))
            if ($gB -and $frescoB -and ($mismoJuegoB -or (Test-JuegoVivo $gB))) {
                $script:juegoBrilloAntes = [int]$gB.brillo
                Log "JUEGO: recupero el brillo de antes ($($gB.brillo)) del disco; Nova reinicio con el juego delante"
            } else {
                Remove-Item -LiteralPath $brilloGuardado -Force -ErrorAction SilentlyContinue
            }
        }
    } catch {}
    if ($null -eq $script:juegoBrilloAntes) {
        try { $script:juegoBrilloAntes = (Get-CimInstance -Namespace root/WMI -ClassName WmiMonitorBrightness -ErrorAction Stop).CurrentBrightness } catch {}
        # y se guarda UNA vez por partida, no en cada alt-tab: Enter-Juego se dispara cada vez
        # que el juego vuelve al primer plano (diez veces la noche del 22).
        if ($null -ne $script:juegoBrilloAntes) {
            try {
                $oB = [ordered]@{ brillo = [int]$script:juegoBrilloAntes; proc = [int]$script:juegoPid
                                  exe = [string]$script:juegoExe; juego = [string]$nombre
                                  cuando = (Get-Date).ToString('s') }
                [System.IO.File]::WriteAllText($brilloGuardado, (ConvertTo-Json -InputObject $oB -Depth 3), (New-Object System.Text.UTF8Encoding($false)))
            } catch {}
        }
    }
    # NO se abren apps del perfil al entrar solo en un juego (abrir Discord
    # encima de un juego recien lanzado seria un estorbo): solo niveles
    $ordenes = @($cmds.perfiles.$JuegoPerfilEntrar) | Where-Object { (ConvertTo-Plain $_) -notmatch '^(?:abre|abrir|lanza|ejecuta)\b' }
    $hechas = @()
    foreach ($o in $ordenes) {
        $r = $null
        try { $r = Invoke-FastCommand $o } catch { $r = $null }
        if ($r) { $hechas += $r }
    }
    if ($hechas.Count -gt 0) {
        Log "JUEGO: perfil '$JuegoPerfilEntrar' aplicado al entrar en $nombre"
        # EL PERFIL SE APLICA IGUAL, LO QUE SE CALLA ES LA FRASE (26/09, idea 4). El brillo hay
        # que ponerlo vuelvas de donde vuelvas; lo que sobra es anunciarlo por trigesima vez.
        # Y se deja linea, que un silencio sin explicacion parece una averia.
        if ($vuelveAlMismo) {
            Log "JUEGO: no digo 'Modo $JuegoPerfilEntrar' porque es el mismo $nombre de antes (alt-tab, no partida nueva)"
        } else {
            Say "Modo $JuegoPerfilEntrar."
            Send-UIEvento 'hecho'
        }
    }
}

# PERDER EL PRIMER PLANO NO ES CERRAR EL JUEGO, Y AQUI SE APLAZA TODO (27/09, idea 108 de las 121)
#
# EL DATO: de las 45 salidas emparejadas de los dos registros, VEINTINUEVE (el 64 %) duran menos de
# dos minutos y VEINTE menos de treinta segundos. Las mas cortas: 4, 6, 8, 8, 9, 9, 10, 10, 10, 10,
# 10, 11, 11, 11, 14, 15, 15, 20, 20 y 21 segundos.
#
# EL 25/09 ENTRE LAS 21 Y LAS 23, siete ciclos completos con ELDEN RING y ELDEN RING NIGHTREIGN de
# 20, 10, 21, 9, 10, 11 y 8 segundos. Cada uno escribio "perfil 'juego' aplicado", "solo boton
# mientras juegas" y, ocho segundos despues, "brillo restaurado a 100" y "vuelve la palabra de
# activacion": el brillo subio y bajo SIETE veces y la escucha se apago y encendio SIETE veces en 75
# minutos.
#
# Y LA CONTRADICCION DENTRO DE NOVA, que es la prueba de que la partida se rompe: memoria\juegos.json
# dice ELDEN RING NIGHTREIGN = 75 SEGUNDOS el 2026-09-25, mientras memoria\uso-ally.json dice que el
# proceso 'nightreign' estuvo 4.038 SEGUNDOS en primer plano ese mismo dia. Cincuenta y cuatro veces
# mas.
#
# LO QUE NO SIRVE DE GUARDA, y hay que decirlo porque es lo primero que se piensa: Test-JuegoVivo. En
# los siete casos del 25/09 dio FALSO -el proceso si habia muerto un instante- asi que con esa
# condicion el parpadeo seguiria exactamente igual. La guarda es de TIEMPO: si el mismo nombre
# reaparece dentro de la ventana, no era una salida.
#
# Y LA VENTANA SE MIDE, no se escribe: cada vez que un juego se va y vuelve, se apunta cuanto tardo
# en volver. Sin datos de ESE juego, ventana cero y todo se comporta como hoy.
$JuegoVueltaMax = 12            # reapariciones que se recuerdan por juego
$JuegoVueltaTope = 300000       # cinco minutos: mas alla no se aplaza nada, sea lo que diga el dato

# PURA Y CON TODO POR PARAMETRO: el banco le pasa cualquier lista de reapariciones.
# Devuelve los ms que hay que esperar antes de dar la salida por buena.
function Get-VentanaVuelta($vueltas, [int]$tope) {
    $v = @($vueltas | ForEach-Object { [double]$_ } | Where-Object { $_ -gt 0 })
    if ($v.Count -eq 0) { return 0 }
    # EL MAXIMO VISTO Y NO UN PERCENTIL: aqui equivocarse por abajo es lo caro -el brillo parpadea y
    # la partida se parte- y equivocarse por arriba solo retrasa un aviso unos segundos. Con las
    # reapariciones medidas del 25/09 (8 a 21 s) esto da 21 s, que cubre las siete.
    $max = 0.0
    foreach ($x in $v) { if ($x -gt $max) { $max = $x } }
    # UN MARGEN DE LA MITAD, por el mismo motivo: la siguiente puede ser un poco mas lenta.
    $ms = [int]($max * 1.5)
    if ($ms -gt $tope) { $ms = $tope }
    return $ms
}

# Las reapariciones apuntadas de un juego, de memoria\juegos.json (donde ya viven 'ritmoBateria' y
# 'muestrasBateria': ni fichero nuevo ni formato nuevo).
function Get-VueltasJuego([string]$nombre) {
    try {
        $m = Get-JuegosMem
        if (-not $m.ContainsKey($nombre)) { return @() }
        return @($m[$nombre]['vueltas'])
    } catch { return @() }
}

function Add-VueltaJuego([string]$nombre, [int]$ms) {
    if (-not $nombre -or $ms -le 0 -or $ms -gt $JuegoVueltaTope) { return $false }
    try {
        $m = Get-JuegosMem
        if (-not $m.ContainsKey($nombre)) { $m[$nombre] = @{} }
        $l = New-Object System.Collections.ArrayList
        foreach ($x in @($m[$nombre]['vueltas'])) { if ([double]$x -gt 0) { [void]$l.Add([int]$x) } }
        [void]$l.Add($ms)
        while ($l.Count -gt $JuegoVueltaMax) { $l.RemoveAt(0) }
        $m[$nombre]['vueltas'] = @($l)
        Save-JuegosMem
        return $true
    } catch { return $false }
}

function Exit-Juego([string]$nombre) {
    try { Save-TiempoJuego } catch {}
    # "me quede en..." dicho justo despues de salir sigue siendo de este juego
    $script:ultimoJuego = $nombre
    $script:ultimoJuegoEn = $sw.ElapsedMilliseconds
    # C4 (19/09): PERDER EL PRIMER PLANO NO ES CERRAR EL JUEGO. Esta funcion la llama el
    # bucle en cuanto cambia la ventana de delante: de las 11 salidas del log (10-19/09)
    # CINCO duraron menos de 2 minutos (ELDEN RING 4 s, 10 s, 11 s y 100 s; Little
    # Nightmares III 83 s) y en tres de ellas se vuelve al MISMO juego en 20 s, 10 s y
    # 3 min 51 s: el juego nunca se habia cerrado, era un alt-tab. Por eso aqui ya no
    # sale ningun aviso de cierre: se suman los minutos jugados y se apunta una salida
    # EN DUDA que Test-SalidaJuego confirma cuando el PROCESO ha muerto de verdad.
    # [int] REDONDEA en PowerShell: 40 s daban 1 minuto entero, y tres alt-tabs de 40 s
    # sumaban 3 minutos sin haber jugado ni dos. Con Floor, un minuto es un minuto.
    $minsFg = [int][Math]::Floor(($sw.ElapsedMilliseconds - $script:juegoDesde) / 60000)
    if ($minsFg -gt 0 -and $minsFg -le 720) { $script:juegoSesionMin += $minsFg }
    # y los segundos del tramo, para la frase de "murio a los N segundos" (idea 47)
    $segsFg = [int][Math]::Floor(($sw.ElapsedMilliseconds - $script:juegoDesde) / 1000)
    if ($segsFg -gt 0 -and $segsFg -le 43200) { $script:juegoSesionSeg += $segsFg }
    # IDEAS 19 y 20: cuanto se juega cada dia. Se apunta AL CERRAR, que es cuando se
    # sabe lo que duro la partida; asi "cuanto llevo hoy" no se lo inventa nadie.
    # UNA SOLA FUENTE DE VERDAD: juegos.json (23/09). Aqui se escribia ADEMAS en
    # habitos.json, y esa copia solo se escribia si Nova estaba viva cuando cambiaba la
    # ventana: si se reiniciaba con el juego delante, esos minutos no se apuntaban NUNCA.
    # Se nota en el fichero: falta entero el 15/09 (5 h 38), falta el 16/09, y el 20/09
    # apunta 2 minutos donde juegos.json apunta 2 h 45. Encima los dos usaban un "dia"
    # distinto -aqui se restaban 5 horas y alli era el dia natural-, asi que no podian
    # cuadrar jamas. juegos.json sobrevive porque se vuelca cada 300 s desde el bucle.
    try {
        $minJ = [int][Math]::Floor(($sw.ElapsedMilliseconds - $script:juegoDesde) / 60000)
        if ($minJ -ge 2 -and $minJ -le 720) {
            $totJ = Get-MinutosJuegoHoy $nombre
            Log "JUEGO: $minJ min con $nombre (hoy van $totJ)"
            # el "hoy llevas N horas" se ha mudado a Test-SalidaJuego (C4, 19/09): aqui
            # nunca llegaba a decirse, porque $script:juegoActivo todavia vale el juego
            # que se acaba de dejar y Test-PuedoAvisar tira todo lo que no sea 'alto'
            # con un juego delante. Alli se dice al cerrarlo, que es cuando se escucha.
        }
    } catch {}
    Invoke-Reglas 'juegoCierra' $nombre
    # C4 (19/09): la salida queda EN DUDA hasta que se sepa que el proceso murio. El
    # "Cerraste X, dime donde te quedaste" lo suelta Test-SalidaJuego desde el bucle.
    if ($nombre) {
        $script:juegoSalida = @{
            nombre  = $nombre
            exe     = [string]$script:juegoExe
            proc    = [int]$script:juegoPid
            desdeMs = $sw.ElapsedMilliseconds
        }
    }
    # EL BRILLO YA NO SE TOCA AQUI (27/09, idea 108). Este bloque corria en el MISMO segundo en que
    # se perdia el primer plano, y por eso el brillo subia y bajaba siete veces en 75 minutos.
    # Ahora se guarda en la salida en duda y lo restaura Test-SalidaJuego cuando el juego NO ha
    # vuelto dentro de la ventana medida. Ver PERDER EL PRIMER PLANO NO ES CERRAR EL JUEGO.
    #
    # SI NO HAY VENTANA (juego sin datos todavia) se restaura AQUI MISMO, como hasta hoy: sin
    # medidas de ese juego no hay nada con que decidir y el comportamiento no cambia.
    if (-not $JuegoRestaurar -or $null -eq $script:juegoBrilloAntes) { return }
    $ventana = 0
    try { $ventana = [int](Get-VentanaVuelta (Get-VueltasJuego $nombre) $JuegoVueltaTope) } catch { $ventana = 0 }
    if ($ventana -gt 0 -and $script:juegoSalida) {
        $script:juegoSalida.brillo = [int]$script:juegoBrilloAntes
        $script:juegoSalida.ventana = $ventana
        Log ("JUEGO: salida en duda de $nombre; espero " + [int]($ventana / 1000) + " s antes de tocar el brillo")
        return
    }
    try {
        Set-Brillo ([int]$script:juegoBrilloAntes)
        Log "JUEGO: brillo restaurado a $($script:juegoBrilloAntes) al salir de $nombre"
        # restaurado: el respaldo ya no vale para nada y no debe sobrevivir a la partida
        try { Remove-Item -LiteralPath (Join-Path $TmpDir 'juego-brillo.json') -Force -ErrorAction SilentlyContinue } catch {}
    } catch {}
    $script:juegoBrilloAntes = $null
}

# --- C4 (19/09): SE CERRO EL JUEGO, O SOLO CAMBIASTE DE VENTANA ---
# Vivo = el proceso que tenia la ventana del juego sigue ahi. Se mira por PID, que es
# una consulta barata; enumerar todos los procesos cada 10 s en una maquina de 4 nucleos
# no lo es, y solo se hace si no hubo PID. Windows reutiliza los PID, asi que se
# comprueba ademas la ruta; si la ruta no se puede leer se da por VIVO, que como mucho
# retrasa un aviso (decir "cerraste ELDEN RING" jugando es mucho peor).
function Test-JuegoVivo($s) {
    if (-not $s) { return $false }
    $idJ = 0
    try { $idJ = [int]$s.proc } catch {}
    if ($idJ -gt 0) {
        $pJ = $null
        try { $pJ = Get-Process -Id $idJ -ErrorAction SilentlyContinue } catch {}
        if (-not $pJ) { return $false }
        $rutaJ = ''
        try { $rutaJ = [string]$pJ.Path } catch {}
        if (-not $s.exe -or -not $rutaJ -or $rutaJ -eq [string]$s.exe) { return $true }
        return $false
    }
    if ($s.exe) {
        try { return (@(Get-Process -ErrorAction SilentlyContinue | Where-Object { try { $_.Path -eq $s.exe } catch { $false } }).Count -gt 0) } catch {}
    }
    return $false
}

# Lo llama el bucle cada 10 s, justo despues de mirar que hay en primer plano. Aqui es
# donde salen los dos avisos del cierre, y no en Exit-Juego, por dos motivos:
#  (a) el proceso: hasta que no muere, lo que hubo fue un alt-tab, no una salida;
#  (b) $script:juegoActivo: el bucle ya lo ha puesto al dia cuando se llega aqui, asi
#      que Test-PuedoAvisar deja pasar el aviso en vez de tirarlo por "esta jugando",
#      que es lo que le pasaba a los dos desde que existen los frenos (16/09).
function Test-SalidaJuego {
    $s = $script:juegoSalida
    if (-not $s) { return }
    # HA VUELTO AL MISMO JUEGO: NO ERA UNA SALIDA, y ahora se APUNTA cuanto tardo en volver, que es
    # de donde sale la ventana de la proxima vez (27/09, idea 108).
    if ($script:juegoActivo -and $script:juegoActivo -eq $s.nombre) {
        $msVuelta = [int]($sw.ElapsedMilliseconds - [double]$s.desdeMs)
        if (Add-VueltaJuego $s.nombre $msVuelta) {
            Log ("JUEGO: $($s.nombre) volvio en " + [Math]::Round($msVuelta / 1000.0, 1) + " s; no era una salida" +
                 $(if ($s.brillo) { ' (el brillo no se toco)' } else { '' }))
        }
        # Y EL TRAMO SE SUMA, NO SE REINICIA: los minutos y los segundos siguen en
        # $script:juegoSesionMin/Seg desde Exit-Juego, asi que aqui solo hay que NO borrarlos.
        # Eso es lo que hacia que la partida se partiera en trozos de once segundos.
        $script:juegoSalida = $null
        return
    }
    # LA VENTANA MANDA, Y VA ANTES DE Test-JuegoVivo A PROPOSITO (27/09, idea 108): en los siete
    # ciclos del 25/09 el proceso SI habia muerto un instante, asi que preguntando primero por el
    # proceso el parpadeo seguiria igual. Mientras la ventana no venza, no se decide nada.

    if ($s.ventana -and ($sw.ElapsedMilliseconds - [double]$s.desdeMs) -lt [double]$s.ventana) { return }
    # EL BRILLO VUELVE EN CUANTO VENCE LA VENTANA, VIVA EL PROCESO O NO (28/09, tras la revision).
    # La idea 108 aplazo el Set-Brillo para no deshacerlo en un parpadeo, y eso estaba bien; lo que
    # no tocaba es que quedara DETRAS del 'if (Test-JuegoVivo)'. Con el proceso vivo -o sea el
    # alt-tab normal, que es el caso que la propia idea llama el corriente: minimizas el juego, que
    # sigue corriendo, y te vas al escritorio o a Discord- no se restauraba NUNCA, y a las 2 h la
    # rama de "sigue abierto" tiraba $script:juegoSalida sin llamar a Set-Brillo, asi que el 70 de
    # braya se perdia del todo. Y Test-JuegoVivo devuelve $true cuando no puede leer la ruta del
    # proceso, o sea que empuja hacia el lado de NO restaurar. Medido: 45 de las 56 entradas de los
    # dos registros son vueltas a un juego ya visto, asi que la ventana existe casi siempre.
    # AQUI YA SE SABE QUE ES UNA SALIDA: arriba se comprobo que el juego NO esta delante
    # ($script:juegoActivo -ne $s.nombre) y la ventana medida ha vencido. Que el proceso siga vivo
    # dice que el juego esta abierto, no que braya lo este mirando, y el brillo es de la pantalla
    # que braya mira.
    if ($s.brillo) {
        try {
            Set-Brillo ([int]$s.brillo)
            Log "JUEGO: brillo restaurado a $($s.brillo) al salir de $($s.nombre) (tras la espera)"
            try { Remove-Item -LiteralPath (Join-Path $TmpDir 'juego-brillo.json') -Force -ErrorAction SilentlyContinue } catch {}
            $script:juegoBrilloAntes = $null
        } catch {}
        # Y NO SE REINTENTA: esto corre cada 10 s mientras el proceso siga vivo, y volver a poner el
        # brillo cada diez segundos pisaria a braya si lo sube a mano despues de salir del juego.
        $s.brillo = 0
    }
    if (Test-JuegoVivo $s) {
        # dos horas con el juego abierto detras sin mirarlo: si se cierra ahora ya no
        # viene a cuento preguntar donde te quedaste, asi que se deja de vigilar
        if (($sw.ElapsedMilliseconds - [double]$s.desdeMs) -ge 7200000) {
            Log "JUEGO: $($s.nombre) sigue abierto 2 h despues de dejarlo; se olvida la salida"
            $script:juegoSalida = $null
            $script:juegoSesionMin = 0
            $script:juegoSesionSeg = 0
        }
        return
    }
    $script:juegoSalida = $null
    # los segundos ANTES de $minsS: hay un banco que exige < 240 caracteres entre esa linea y el
    # if de $JuegoMinimoPartida, asi que la captura del segundo va aqui arriba (idea 47).
    $segS = [int]$script:juegoSesionSeg
    $script:juegoSesionSeg = 0
    $minsS = [int]$script:juegoSesionMin
    $script:juegoSesionMin = 0
    if ($minsS -lt $JuegoMinimoPartida) {
        Log "JUEGO: $($s.nombre) cerrado con $minsS min de partida (minimo $JuegoMinimoPartida): sin aviso"
        # SE ABRE Y SE MUERE (idea 47): a la 3a muerte seguida del mismo juego, ofrece cerrar Steam.
        # >= 3 y no == 3: el 25/09 la 3a coincidio con una confirmacion viva y Test-PuedoAvisar la
        # habria tirado; asi la 4a (sin pendiente) si habla. Solo palabras: braya usa 'cierra steam'.
        $nSeg = Test-MuereAlArrancar $s.nombre $sw.ElapsedMilliseconds
        if ($nSeg -ge 3) {
            [void](Send-AvisoEntorno ("juego-muere-" + $s.nombre) "$($s.nombre) lleva $nSeg intentos muriendose al arrancar, el ultimo a los $segS segundos. Si quieres, dime 'cierra steam' y lo reinicias limpio." 'medio' 30)
        }
        return
    }
    Clear-MuereAlArrancar $s.nombre   # partida de verdad: la racha de muertes se rompe (idea 47)
    Log "JUEGO: cerrado de verdad $($s.nombre) ($minsS min de partida)"
    # EL RESUMEN DE LA PARTIDA QUE ACABA (1/10, la 20 de las 20 funciones). Nova tenia el parte del
    # dia y el resumen de la semana, pero no el de la sesion que se cierra, que es el momento en que
    # apetece oirlo. AQUI y no en Exit-Juego: aquel se dispara en cada alt-tab -cinco de once
    # salidas del log duraron menos de dos minutos- y un resumen por alt-tab seria insoportable.
    try {
        $frS = Get-FraseResumenSesion $s.nombre $minsS $segS
        if ($frS) { [void](Send-AvisoEntorno ('sesion-' + $s.nombre) $frS 'medio' 5) }
    } catch {}
    # Y SI TE DEJO LA PANTALLA CAMBIADA (25/09, idea 6). Medido el 24/09: braya cerro A Way Out
    # a las 00:01:13 y VEINTE MINUTOS despues el escritorio seguia a 1280x720 con un panel de
    # 1920x1080. El juego no le devolvio su resolucion y nadie se lo dijo.
    # NO SE LA CAMBIA SOLA, a proposito: en una consola portatil bajar la resolucion a veces es
    # deliberado, para que dure la bateria. Se dice y decide braya.
    try {
        $script:capsulaCiega = $false
        $nat = Get-ResolucionNativa
        $act = Get-ResolucionActual
        if ($nat -and $act -and (($nat[0] -ne $act[0]) -or ($nat[1] -ne $act[1]))) {
            [void](Send-AvisoEntorno 'pantalla-cambiada' (
                "El juego te ha dejado la pantalla en $($act[0]) por $($act[1]); la tuya es $($nat[0]) por $($nat[1])."
            ) 'medio' 120)
        }
    } catch {}
    # idea 9: es el momento en que te acuerdas; media hora despues, ya no
    [void](Send-AvisoEntorno 'juego-cierra' "Cerraste $($s.nombre). Si quieres, dime donde te quedaste." 'medio' 120)
    # IDEA 20: y de paso, lo que llevas hoy (se lee de habitos, que lo acaba de sumar
    # Exit-Juego; si el ultimo tramo no llego a 2 min, el total del dia sigue valiendo)
    try {
        $hbS = Get-Habitos
        $totS = Get-MinutosJuegoHoy    # la fuente buena: juegos.json, que sobrevive a los reinicios
        if ($totS -ge 240) {
            [void](Send-AvisoEntorno 'horas-hoy' "Hoy llevas $([Math]::Round($totS / 60.0, 1)) horas de juego." 'bajo' 480)
        }
    } catch { Log ("horas de hoy: " + $_.Exception.Message) }
}

# =====================================================================
# VER LA PANTALLA: captura de la ventana activa (o de toda la pantalla) y
# OCR con el motor integrado de Windows (WinRT, sin instalar nada).
# =====================================================================
$script:winrtAsTask = $null
function Await-WinRT($op, $tipo, [int]$esperaMs = 8000) {
    if (-not $script:winrtAsTask) {
        Add-Type -AssemblyName System.Runtime.WindowsRuntime
        $script:winrtAsTask = ([System.WindowsRuntimeSystemExtensions].GetMethods() |
            Where-Object { $_.Name -eq 'AsTask' -and $_.GetParameters().Count -eq 1 -and
                           $_.GetParameters()[0].ParameterType.Name -eq 'IAsyncOperation`1' })[0]
    }
    $t = $script:winrtAsTask.MakeGenericMethod($tipo).Invoke($null, @($op))
    if (-not $t.Wait($esperaMs)) { throw "WinRT: sin respuesta en $esperaMs ms" }
    return $t.Result
}

# QUÉ TROZO DE LA PANTALLA (C15, 20/09). Devuelve el rectángulo de "arriba",
# "abajo-derecha", "centro"... en FRACCIONES y no en píxeles, para que valga igual
# en la pantalla de 7 pulgadas de la consola y en un monitor de casa.
# El SOLAPE del 6 % no es un capricho: un renglón que cruce justo por la mitad se
# partiría en dos y el OCR leería medias palabras, que es peor que no leer nada.
# Así cada mitad se lleva un pellizco de la de al lado.
# El centro es el 20-80 % de cada lado: el cartel que sale en medio de un juego cabe
# de sobra ahí, y se queda fuera todo el HUD de los bordes, que es justo el ruido que
# hacía inútil leer la pantalla entera mientras juegas.
function Get-ZonaRect([int]$x, [int]$y, [int]$w, [int]$h, [string]$zona) {
    if (-not $zona) { return @{ x = $x; y = $y; w = $w; h = $h } }
    $sol = 0.06
    $x0 = 0.0; $x1 = 1.0; $y0 = 0.0; $y1 = 1.0
    if ($zona -eq 'centro') {
        $x0 = 0.2; $x1 = 0.8; $y0 = 0.2; $y1 = 0.8
    } else {
        if     ($zona -like '*arriba*')    { $y1 = 0.5 + $sol }
        elseif ($zona -like '*abajo*')     { $y0 = 0.5 - $sol }
        if     ($zona -like '*izquierda*') { $x1 = 0.5 + $sol }
        elseif ($zona -like '*derecha*')   { $x0 = 0.5 - $sol }
    }
    $nx = $x + [int][Math]::Round($w * $x0)
    $ny = $y + [int][Math]::Round($h * $y0)
    $nw = [int][Math]::Round($w * ($x1 - $x0))
    $nh = [int][Math]::Round($h * ($y1 - $y0))
    # un recorte ridículo no lo lee nadie: si la ventana ya era diminuta, entera.
    if ($nw -lt 80 -or $nh -lt 40) { return @{ x = $x; y = $y; w = $w; h = $h } }
    return @{ x = $nx; y = $ny; w = $nw; h = $nh }
}

# Guarda un PNG de la ventana en primer plano (o de toda la pantalla si no
# hay ventana util). Esconde la capsula un instante para que no salga.
# Con $zona guarda SOLO ese trozo (ver Get-ZonaRect). El recorte se hace aquí, al
# copiar de la pantalla, y no después sobre el PNG: así se copian menos píxeles y el
# OCR mira menos área, que es lo que hace que leer una esquina salga más rápido que
# leer la pantalla entera, y no al revés.
function Save-Captura([string]$ruta, [string]$zona = '') {
    if ($UiNuevaOn) { Send-UIEvento 'oculta'; Start-Sleep -Milliseconds 180 }
    # Y LA LUPA TAMBIEN SE APARTA (revision del 23/09). La lupa es una ventana siempre
    # encima, y CopyFromScreen copia lo que hay encima: con la lupa puesta, el OCR leia el
    # trozo YA ampliado y la vision de la nube describia la lupa en vez de la pantalla. Se
    # esconde y se vuelve a poner -no se cierra- porque braya la estaba mirando.
    $lupaTapa = $null
    if ($script:lupaForm) {
        try { $lupaTapa = $script:lupaForm.Handle; [void][AX]::ShowWindow($lupaTapa, 0); Start-Sleep -Milliseconds 60 } catch { $lupaTapa = $null }
    }
    try {
        $b = [System.Windows.Forms.Screen]::PrimaryScreen.Bounds
        $x = $b.Left; $y = $b.Top; $w = $b.Width; $h = $b.Height
        try {
            $hw = [AX]::GetForegroundWindow()
            if ($hw -ne [IntPtr]::Zero -and $hw -ne $capture.Handle) {
                $r = New-Object AX+RECT
                if ([AX]::GetWindowRect($hw, [ref]$r) -and ($r.Right - $r.Left) -gt 80 -and ($r.Bottom - $r.Top) -gt 60) {
                    $x = [Math]::Max($b.Left, $r.Left); $y = [Math]::Max($b.Top, $r.Top)
                    $w = [Math]::Min($b.Right, $r.Right) - $x; $h = [Math]::Min($b.Bottom, $r.Bottom) - $y
                }
            }
        } catch {}
        if ($zona) {
            $zR = Get-ZonaRect $x $y $w $h $zona
            $x = $zR.x; $y = $zR.y; $w = $zR.w; $h = $zR.h
        }
        $bmp = New-Object System.Drawing.Bitmap($w, $h)
        $g = [System.Drawing.Graphics]::FromImage($bmp)
        try {
            $g.CopyFromScreen($x, $y, 0, 0, (New-Object System.Drawing.Size($w, $h)))
            $bmp.Save($ruta, [System.Drawing.Imaging.ImageFormat]::Png)
        } finally { $g.Dispose(); $bmp.Dispose() }
        return $ruta
    } finally {
        if ($lupaTapa) { try { [void][AX]::ShowWindow($lupaTapa, 8) } catch {} }   # SW_SHOWNA
    }
}

# Un trozo de texto para decir en voz alta, desde $desde. Se corta en un PUNTO
# y, si no hay, en un espacio: partir una palabra por la mitad suena a fallo,
# no a pausa. Devuelve el texto y DONDE se quedo, para poder seguir.
function Get-Trozo([string]$todo, [int]$desde, [int]$largo = 320) {
    if ($desde -lt 0) { $desde = 0 }
    if ($desde -ge $todo.Length) { return @{ texto = ''; fin = $todo.Length } }
    $resto = $todo.Substring($desde)
    if ($resto.Length -le $largo) { return @{ texto = $resto.Trim(); fin = $todo.Length } }
    $cacho = $resto.Substring(0, $largo)
    # el ultimo punto que deje al menos media frase; si no, el ultimo espacio
    $corte = $cacho.LastIndexOf('. ')
    if ($corte -lt [int]($largo / 2)) { $corte = $cacho.LastIndexOf(' ') }
    if ($corte -lt [int]($largo / 2)) { $corte = $largo - 1 }
    $fin = $desde + $corte + 1
    return @{ texto = $resto.Substring(0, $corte + 1).Trim(); fin = $fin }
}

function Invoke-OCR([string]$png) {
    $null = [Windows.Media.Ocr.OcrEngine, Windows.Foundation, ContentType = WindowsRuntime]
    $null = [Windows.Storage.StorageFile, Windows.Storage, ContentType = WindowsRuntime]
    $null = [Windows.Graphics.Imaging.BitmapDecoder, Windows.Graphics.Imaging, ContentType = WindowsRuntime]
    $null = [Windows.Globalization.Language, Windows.Globalization, ContentType = WindowsRuntime]
    $null = [Windows.Storage.Streams.IRandomAccessStream, Windows.Storage.Streams, ContentType = WindowsRuntime]
    $null = [Windows.Storage.FileAccessMode, Windows.Storage, ContentType = WindowsRuntime]
    $null = [Windows.Graphics.Imaging.SoftwareBitmap, Windows.Graphics.Imaging, ContentType = WindowsRuntime]
    $null = [Windows.Media.Ocr.OcrResult, Windows.Foundation, ContentType = WindowsRuntime]
    $motor = $null
    try { $motor = [Windows.Media.Ocr.OcrEngine]::TryCreateFromLanguage((New-Object Windows.Globalization.Language 'es')) } catch { $motor = $null }
    if (-not $motor) { $motor = [Windows.Media.Ocr.OcrEngine]::TryCreateFromUserProfileLanguages() }
    if (-not $motor) { throw "no hay motor de OCR (instala el idioma en Windows)" }
    $archivo = Await-WinRT ([Windows.Storage.StorageFile]::GetFileFromPathAsync($png)) ([Windows.Storage.StorageFile])
    $flujo = Await-WinRT ($archivo.OpenAsync([Windows.Storage.FileAccessMode]::Read)) ([Windows.Storage.Streams.IRandomAccessStream])
    $dec = Await-WinRT ([Windows.Graphics.Imaging.BitmapDecoder]::CreateAsync($flujo)) ([Windows.Graphics.Imaging.BitmapDecoder])
    $bmp = Await-WinRT ($dec.GetSoftwareBitmapAsync()) ([Windows.Graphics.Imaging.SoftwareBitmap])
    $res = Await-WinRT ($motor.RecognizeAsync($bmp)) ([Windows.Media.Ocr.OcrResult])
    try { $flujo.Dispose() } catch {}
    # una linea por renglon, para que se lea con pausas naturales
    $lineas = @($res.Lines | ForEach-Object { $_.Text })
    return (($lineas -join '. ') -replace '\s+', ' ').Trim()
}

# =====================================================================
# VIBRACION DEL MANDO: patron de [on, off, on, ...] en ms, sin bloquear; el
# bucle principal lo va ejecutando. Un eco tactil de lo que hace la capsula.
# =====================================================================
$MandoVibracion = [bool](Get-Cfg 'mando' 'vibracion' $true)
$script:vibraCola = @()
$script:vibraHasta = 0
$script:vibraEncendida = $false
$script:vibraFuerza = 0
# CUANDO VIBRO POR ULTIMA VEZ (26/09, idea 42). Arranca en -100000, no en 0 ni $null: en la
# primera vuelta "$sw.ElapsedMilliseconds - $script:vibraUltimaEn" daria un hueco falso si no.
# Hoy no decide nada; es el dato por si algun dia hay que medir ese hueco.
$script:vibraUltimaEn = -100000

$script:vibraSiguienteOn = $true
$script:vibraAvisado = $false

function Start-Vibracion([int[]]$patron, [int]$fuerza = 22000) {
    if (-not $MandoVibracion -or -not $patron -or $patron.Count -eq 0) { return }
    $script:vibraUltimaEn = $sw.ElapsedMilliseconds   # idea 42: cuando fue el ultimo zumbido
    # el patron alterna encendido/apagado empezando por encendido
    $script:vibraCola = @($patron)
    $script:vibraFuerza = $fuerza
    $script:vibraHasta = 0
    $script:vibraSiguienteOn = $true
}

function Tick-Vibracion {
    if ($script:vibraHasta -gt 0) {
        if ($sw.ElapsedMilliseconds -lt $script:vibraHasta) { return }
        $script:vibraHasta = 0
        if ($script:vibraEncendida) { try { [void][AX]::Vibrar(0, 0, 0) } catch {}; $script:vibraEncendida = $false }
    }
    if ($script:vibraCola.Count -eq 0) { return }
    $ms = [int]$script:vibraCola[0]
    $script:vibraCola = @($script:vibraCola | Select-Object -Skip 1)
    if ($script:vibraSiguienteOn) {
        $ok = $false
        try { $ok = [AX]::Vibrar(0, [uint16]$script:vibraFuerza, [uint16]($script:vibraFuerza / 2)) } catch { $ok = $false }
        if (-not $script:vibraAvisado) { $script:vibraAvisado = $true; Log ("mando: vibracion " + $(if ($ok) { 'disponible' } else { 'no disponible (sin mando XInput)' })) }
        if (-not $ok) { $script:vibraCola = @(); return }   # sin mando: fuera
        $script:vibraEncendida = $true
    }
    $script:vibraSiguienteOn = -not $script:vibraSiguienteOn
    $script:vibraHasta = $sw.ElapsedMilliseconds + $ms
}

# Win + <tecla>: usado para colocar ventanas (Win+flechas)
# Win+Shift+<tecla>: mover la ventana entre monitores. Es Send-WinKey con el
# Shift por fuera; separadas para no meterle un parametro opcional a la que ya
# usan quince sitios.
function Send-WinShiftKey([int]$vk) {
    [AX]::keybd_event([byte]$VK_LWIN, 0, 0, [UIntPtr]::Zero)
    Start-Sleep -Milliseconds 60
    [AX]::keybd_event([byte]0x10, 0, 0, [UIntPtr]::Zero)      # Shift
    Start-Sleep -Milliseconds 40
    [AX]::keybd_event([byte]$vk, 0, 0, [UIntPtr]::Zero)
    Start-Sleep -Milliseconds 40
    [AX]::keybd_event([byte]$vk, 0, $KEYUP, [UIntPtr]::Zero)
    Start-Sleep -Milliseconds 40
    [AX]::keybd_event([byte]0x10, 0, $KEYUP, [UIntPtr]::Zero)
    Start-Sleep -Milliseconds 60
    [AX]::keybd_event([byte]$VK_LWIN, 0, $KEYUP, [UIntPtr]::Zero)
}

function Send-WinKey([int]$vk) {
    [AX]::keybd_event([byte]$VK_LWIN, 0, 0, [UIntPtr]::Zero)
    Start-Sleep -Milliseconds 60
    [AX]::keybd_event([byte]$vk, 0, 0, [UIntPtr]::Zero)
    Start-Sleep -Milliseconds 40
    [AX]::keybd_event([byte]$vk, 0, $KEYUP, [UIntPtr]::Zero)
    Start-Sleep -Milliseconds 60
    [AX]::keybd_event([byte]$VK_LWIN, 0, $KEYUP, [UIntPtr]::Zero)
}

if ($Probar) {
    if (-not (Test-Path -LiteralPath $Probar)) { Write-Output "no existe: $Probar"; exit 1 }
    # Reconocer una orden NO es gratis: "recuerdame manana a las diez que llame
    # al medico" crea el recordatorio de verdad nada mas detectarlo, y "cuando
    # abras elden ring..." guarda la regla. La primera version de este banco
    # llego a escribir ambas cosas en la memoria real. Aqui se desvia a una
    # carpeta de usar y tirar todo lo que persiste: probar no toca nada tuyo.
    $pruebaDir = Join-Path ([System.IO.Path]::GetTempPath()) ("nova-prueba-" + [guid]::NewGuid().ToString("N").Substring(0, 8))
    New-Item -ItemType Directory -Path $pruebaDir -Force | Out-Null
    New-Item -ItemType Directory -Path (Join-Path $pruebaDir 'diario') -Force | Out-Null
    $MemoriaDir = $pruebaDir
    # el banco escribia RECORDATORIO/REGLA de mentira en el assistant.log real
    $EventLog = Join-Path $pruebaDir 'probar.log'
    # el perfil y las recetas se calculan al cargar, ANTES de este bloque: sin
    # esto, "aprende que mi..." pasado por el banco escribiria en el perfil real
    $PerfilPath = Join-Path $pruebaDir 'perfil.md'
    $RecetasPath = Join-Path $pruebaDir 'recetas.json'
    $DiarioDir = Join-Path $pruebaDir 'diario'
    $ReglasPath = Join-Path $pruebaDir 'reglas.json'
    $RecordatoriosPath = Join-Path $pruebaDir 'recordatorios.json'
    $FechasPath = Join-Path $pruebaDir 'fechas.json'
    $TraduccionesPath = Join-Path $pruebaDir 'traducciones.json'
    $EstadisticasJson = Join-Path $pruebaDir 'estadisticas.json'
    $EstadisticasMd = Join-Path $pruebaDir 'estadisticas.md'
    $ok = 0; $no = 0; $salt = 0
    foreach ($linea in (Get-Content -LiteralPath $Probar -Encoding UTF8)) {
        $t = $linea.Trim()
        if (-not $t -or $t.StartsWith('#')) { continue }
        # LO QUE DEPENDE DE UN JUEGO QUE YA NO TIENES (19/09): el banco bajo de 88 a 85 y de
        # 183 a 181 sin que nadie tocara el codigo; los cinco "fallos" eran Little Nightmares
        # III, SILENT BREATH y REANIMAL, desinstalados de Steam esa semana. Un banco que se
        # pone rojo solo porque cambio la biblioteca no sirve para ver una regresion de
        # verdad. Con '@si-tienes:<juego>' la linea solo cuenta si ese juego esta instalado
        # AHORA, con el nombre exacto: parecido no vale, que "Little Nightmares III" casa de
        # sobra con "Little Nightmares Enhanced Edition" y eso taparia justo lo que se mira.
        $exige = ''
        $mJ = [regex]::Match($t, '\s*@si-tienes:\s*(.+)$')
        if ($mJ.Success) { $exige = $mJ.Groups[1].Value.Trim(); $t = $t.Substring(0, $mJ.Index).Trim() }
        if ($exige) {
            [void](Update-Juegos)
            $pe = (ConvertTo-Plain $exige).ToLowerInvariant()
            $hayJ = @($script:Juegos | Where-Object { (ConvertTo-Plain ([string]$_.nombre)).ToLowerInvariant() -eq $pe }).Count -gt 0
            if (-not $hayJ) {
                $salt++
                Write-Output ("  SALTO " + $t.PadRight(38) + "  (ya no tienes '$exige' instalado)")
                continue
            }
        }
        # mismo orden que Process-Texto: reglas y recordatorios se resuelven
        # antes que las ordenes sueltas, o el banco mentiria
        $r = $false; $via = ''
        try { if (Invoke-ReglaVoz $t) { $r = $true; $via = 'regla' } } catch { $via = 'REGLA ROTA' ; $r = $false }
        if (-not $r) { try { if (Invoke-RecordatorioVoz $t) { $r = $true; $via = 'recordatorio' } } catch { $via = 'RECORDATORIO ROTO' } }
        # Y SI Test-FastCommand LANZA, SE DICE (1/10/2026). Este catch se tragaba la excepcion y la
        # frase salia como '->IA' sin una palabra, que es indistinguible de "ningun patron la coge".
        # Me costo media hora de diagnosticos para "este esta descargando": no era que faltara un
        # patron, era que algo reventaba antes de llegar a los patrones.
        $porRoto = ''
        if (-not $r) { try { $r = Test-FastCommand $t } catch { $r = $false; $porRoto = '   [REVIENTA: ' + $_.Exception.Message + ']' } }
        if ($r) {
            $ok++
            # QUE haria, no solo si lo reconoce. Sin esto, el banco decia 'OK'
            # a 'pesa' sin contar que eso era un Ctrl+V en lo que tuvieras
            # delante, ni a 'abre el speaker' que lanzaba PEAK.
            $comoQue = ''
            # si lo cogio una regla o un recordatorio, decirlo: la descripcion
            # de Resolve-Fragment seria otra cosa y despistaria
            if ($via) { $comoQue = "  ->  [$via]" }
            elseif ($true) { try {
                $descs = @()
                foreach ($fr in @(Split-Ordenes $t)) {
                    $acc = Resolve-Fragment $fr
                    if ($acc) { $descs += @($acc | ForEach-Object { $_.desc }) }
                }
                $descs = @($descs | Where-Object { $_ })
                if ($descs.Count -gt 0) { $comoQue = '  ->  ' + ($descs -join ' + ') }
            } catch {} }
            Write-Output ("  OK    " + $t.PadRight(38) + $comoQue)
        }
        else {
            $no++
            # EN QUE TROZOS LA PARTIO (1/10/2026). Sin esto, un '->IA' no dice NADA: una frase puede
            # irse al agente porque ningun patron la coge, o porque Split-Ordenes la partio en dos y
            # uno de los trozos no resuelve, y son dos arreglos distintos. Me costo media hora
            # averiguarlo a mano para "este esta descargando" -que se partia en 'este' + el resto-,
            # con cinco scripts de diagnostico que no hacian falta. Solo se imprime cuando hay mas
            # de un trozo: para uno solo, el trozo ES la frase y la linea seria ruido.
            $porQue = ''
            try {
                $frT = @(Split-Ordenes $t)
                if ($frT.Count -eq 0) { $porQue = '   [Split-Ordenes no devolvio NINGUN trozo]' }
                # UN SOLO TROZO SOLO SE DICE SI NO ES LA FRASE: si coincide no aporta nada y seria
                # ruido en todas las lineas. Cuando NO coincide es la pista que importa, y es la que
                # resolvio lo de hoy: "este esta descargando" llegaba a los patrones como "esta
                # descargando", sin sujeto, porque 'este' estaba en la lista de muletillas.
                elseif ($frT.Count -eq 1 -and ([string]$frT[0]).Trim() -ne (ConvertTo-Plain $t).Trim()) {
                    $porQue = "   [llega como: '" + $frT[0] + "']"
                }
                elseif ($frT.Count -gt 1) {
                    $cuales = @($frT | ForEach-Object {
                        $aT = $null
                        try { $aT = Resolve-Fragment $_ } catch { $aT = $null }
                        $_ + $(if ($aT) { '' } else { ' <-- este no' })
                    })
                    $porQue = '   [' + $frT.Count + ' trozos: ' + ($cuales -join ' | ') + ']'
                }
            } catch {}
            # LA LINEA '->IA' NO SE TOCA, Y EL PORQUE VA DEBAJO. probar-destinos.ps1 lee esta salida y
            # usa LA FRASE COMO CLAVE ('^\s*->IA\s+(.*)$'), asi que cualquier cosa anadida detras -relleno
            # o diagnostico- la convierte en otra clave y el banco deja de reconocerla. Salieron 24 casos
            # MAL de golpe y ninguno era del codigo. En su propia linea no estorba a nadie: no empieza
            # por 'OK' ni por '->IA'.
            Write-Output ("  ->IA  " + $t)
            if ($porRoto -or $porQue) { Write-Output ("          " + ($porRoto + $porQue).Trim()) }
        }
    }
    Write-Output ""
    Write-Output ("reconocidas en local: $ok de " + ($ok + $no))
    # el listero de probar-todo.ps1 suma las dos: asi el minimo sigue siendo el mismo
    # aunque hoy falte un juego, y baja de verdad solo si se rompe algo
    Write-Output ("saltadas por juegos que ya no tienes: $salt")
    try { Remove-Item -LiteralPath $pruebaDir -Recurse -Force -ErrorAction SilentlyContinue } catch {}
    exit 0
}

# el candado ya se cogio arriba, antes de limpiar tmp\ (ver UNA SOLA NOVA)
if (-not $mutex) {
    $mutex = New-Object System.Threading.Mutex($false, "Local\VoiceAssistant")
    if (-not $mutex.WaitOne(0)) {
        Write-Output "VoiceAssistant ya esta ejecutandose."
        exit 0
    }
}

try {
    Add-Type -AssemblyName System.Windows.Forms, System.Drawing
} catch {
    # sin WinForms no hay captura ni popup: abortar aqui con un mensaje claro,
    # en vez de reventar 20 lineas mas abajo con un error incomprensible
    Log ("ERROR cargando WinForms: " + $_.Exception.Message)
    exit 1
}

$dll = Join-Path $LogDir "assistant-dx.dll"
if (-not (Test-Path $dll)) {
    Log "ERROR: falta $dll"
    exit 1
}
# Integridad del DLL: se carga con Add-Type desde una carpeta que cualquier
# proceso de tu cuenta puede escribir. La primera vez se anota el hash en
# config.json (confianza inicial); despues se compara. AVISA pero NO aborta:
# lo mas probable ante un cambio es que lo hayas recompilado tu, y dejarte sin
# asistente por eso seria peor. Si recompilas, borra seguridad.hashDll.
try {
    $hashAhora = (Get-FileHash -LiteralPath $dll -Algorithm SHA256).Hash
    $hashEsperado = [string](Get-Cfg 'seguridad' 'hashDll' '')
    if (-not $hashEsperado) {
        Log "hash del DLL registrado por primera vez: $hashAhora"
        Log "  (para fijarlo, copia ese valor en config.json -> seguridad.hashDll)"
    } elseif ($hashEsperado -ne $hashAhora) {
        Log "ALERTA: assistant-dx.dll NO coincide con el hash esperado."
        Log "  esperado: $hashEsperado"
        Log "  actual  : $hashAhora"
        Log "  Si lo recompilaste, actualiza config.json. Si no, revisa el archivo."
    }
} catch {}

try {
    Add-Type -Path $dll
} catch {
    Log ("ERROR cargando DLL: " + $_.Exception.Message)
    exit 1
}

try {
    $env:PATH = $NODEDIR + ";" + $env:PATH
} catch {}

if (-not (Test-Path -LiteralPath $TmpDir)) {
    try { New-Item -ItemType Directory -Path $TmpDir -Force | Out-Null } catch {}
}

# LA VERSION VA EN LA MISMA LINEA QUE YA SE ESCRIBIA (27/09, idea 95): asi las 259 lineas de
# arranque que ya hay en los registros y todas las que vengan se pueden comparar entre ellas, y un
# numero que empeora se puede atribuir a un cambio concreto.
$verNova = Get-VersionNova
Log "VoiceAssistant iniciado PID=$PID (version: $verNova; trigger: mantener ≡ $([Math]::Round($HOLD_MS/1000,1)) s; cerebro: $([string](Get-Cfg 'modelo' 'cerebro' 'claude-code')))."
try { Add-Estadistica 'version' $verNova } catch {}
# Y UNA LINEA AL CERRAR (18/09). Habia 188 "iniciado" en el registro y ninguna de salida, asi
# que no habia forma de distinguir "braya lo cerro" de "se murio" -el unico rastro era la marca
# huerfana de la sesion siguiente, que solo aparece cuando acabo mal-.
# No cubre el cierre brusco: ahi no se escribe nada por definicion, y precisamente por eso
# sirve. Un "iniciado" sin su "cerrado" detras ya dice que no fue un cierre normal.
try {
    $null = Register-EngineEvent PowerShell.Exiting -Action {
        try { Log ("VoiceAssistant cerrado PID=" + $PID) } catch {}
        # CIERRE LIMPIO (26/09, idea 50), DEBAJO del Log a proposito: probar-log.ps1 mide un hueco
        # corto entre 'PowerShell.Exiting' y 'cerrado', y meter algo ANTES lo reventaria. La guarda
        # NO es adorno: el "exit 1" de "opencode CLI no encontrado" corre DESPUES de registrarse
        # esto y ANTES de $sw, o sea sin haber contado 'arranque'; sin la guarda apuntaria un
        # cierre-limpio sin su arranque y la tasa se pasaria del 100 %.
        if ($script:arranqueContado) { try { Add-Estadistica 'cierre-limpio' } catch {} }
        # IDEA 52: el cuaderno de la Ally y el tiempo de juego, a disco al salir. Los dos Save-* salen
        # sin escribir si no hay nada pendiente, o sea que esto no estrena coste: es la escritura que
        # se iba a hacer igual, adelantada al cierre limpio (36 de 71 sesiones que hoy tiran hasta 299 s).
        try { Save-UsoAlly } catch {}
        try { Save-TiempoJuego } catch {}
        # IDEA 82: y los relojes de 'no repitas esto tan pronto', para que el proximo arranque no
        # nazca creyendo que hace horas que no pasa nada. El freno de un minuto de Set-Reloj se
        # salta aqui a proposito: es la ultima oportunidad de guardar lo de este ultimo minuto.
        try {
            $script:relojesEscritoEn = @{}
            if ($script:charlaUltima -gt 0) { [void](Set-Reloj 'charla') }
        } catch {}
    }
} catch {}
if ($cfgError) { Log "WARN: config.json ilegible, se usan los valores por defecto: $cfgError" }
elseif ($cfg) { Log "config.json cargado" }
if ($cmdsError) { Log "WARN: commands.json ilegible, todo ira a opencode: $cmdsError" }
elseif ($cmds) {
    Log ("commands.json cargado: " + @($cmds.apps.PSObject.Properties).Count + " apps, " +
         @($cmds.sitios.PSObject.Properties).Count + " sitios, " +
         @($cmds.busquedas.PSObject.Properties).Count + " buscadores")
} else { Log "WARN: no hay commands.json; todo ira a opencode"; Add-FalloArranque 'no tengo mi lista de ordenes, asi que todo ira al agente y sere lenta' }

# LA MEMORIA QUE NO SE BORRA, SEMBRADA (25/09). Solo hace algo la primera vez: si el fichero
# no existe, lo llena con los datos que el perfil tenga en ese momento. Sin esto naceria vacia
# y los 60 de hoy solo entrarian segun se fueran repitiendo.
try { Initialize-PerfilTodo } catch {}
# Y LOS QUE ERAN DE UN RATO, FUERA DEL QUE VIAJA (25/09, idea 4). Va DESPUES de sembrar la
# memoria permanente a proposito: asi lo que se saca del perfil ya tiene donde quedarse.
try { Clear-PerfilPasajeros } catch {}
# Y CON QUE ANIMO SE DESPIERTA (25/09, idea 15). Ver EL ANIMO CON EL QUE SE DESPIERTA: hasta
# hoy arrancaba en 0 y no se enteraba de que venia de un dia malo hasta la primera orden, que
# es DESPUES de haber soltado los avisos que se quedaron esperando. Ahora lo sabe antes.
try {
    $diasE = (Get-Estadisticas).dias
    $script:uiAnimo = Get-AnimoDeDias $diasE
    $lgA = Get-AnimoLargo $diasE
    $script:animoLargo = $lgA.animo
    $script:animoBase = $lgA.dias
    if ($lgA.dias -ge $AnimoLargoMinDias) {
        Log ("animo de fondo: " + $lgA.animo.ToString('0.00', [System.Globalization.CultureInfo]::InvariantCulture) + " con " + $lgA.dias + " dia(s) de base")
    }
    if ($script:uiAnimo -le $AnimoMalo) { Log ("animo de arranque: " + $script:uiAnimo.ToString('0.00', [System.Globalization.CultureInfo]::InvariantCulture) + " (dia malo: hoy hablo menos por mi cuenta)") }
} catch {}
# Y SI LA VEZ ANTERIOR ACABO MAL, SE DICE (25/09, idea 29). Va por Send-AvisoEntorno y no por
# Say a proposito: si braya no esta delante, el aviso se guarda y se suelta cuando vuelva, que
# es exactamente cuando sirve. Nivel 'medio': no es una urgencia, pero tampoco algo que deba
# quedarse solo en la capsula.
try {
    # Y SUS PROPIAS COSTUMBRES (25/09, idea 3): una vez al dia, mirar si algo que hacia a
    # diario ha dejado de pasar. Va aqui, al arrancar, porque es cuando ya estan montadas las
    # rutas y no cuesta nada; el propio Test-CostumbresPropias se frena a una vez por dia.
    try { Test-CostumbresPropias } catch {}
    # Y SU ANIMO DE FONDO, SI HA CAMBIADO (25/09, idea 38). Va aqui y no en el saludo de vuelta
    # por lo mismo que la caida: si braya no esta delante, Send-AvisoEntorno lo guarda y lo
    # suelta cuando vuelva. Y va DESPUES del bloque que calcula $script:animoLargo, aunque no
    # dependa de el: la frase se saca de las estadisticas del disco, no de esa variable.
    try { [void](Test-AnimoQueSeCuenta) } catch {}
    # Y QUE NO SE LE ESCAPE NADA AL REPOSITORIO (26/09, idea 1 de las 121). Una vez al dia, y
    # ni eso con un juego delante: son 120 ms de un proceso de git.
    try { [void](Test-MemoriaIgnorada) } catch {}
    # Y LOS TEMPORALES QUE NADIE VUELVE A MIRAR (26/09, idea 10 de las 121). Medido: 96
    # ficheros de mas de 7 dias que el codigo no nombra, 12,1 MB, y entre ellos una clave de
    # la API en claro del 12/09. Ver Clear-TmpViejo.
    try { [void](Clear-TmpViejo) } catch {}
    # Y LO QUE BAJASTE Y NO HAS ABIERTO (27/09, idea 49 de las 121). Una vez al dia, ni eso con
    # un juego delante: lee $script:Juegos (RAM), no toca disco caro.
    try { [void](Test-JuegoSinEstrenar) } catch {}
    # Y EL TIEMPO DE HACE UN RATO, QUE SIGUE VALIENDO (26/09, idea 6 de las 121). Dos de cada
    # tres consultas de clima caian en los tres minutos siguientes a un arranque.
    try {
        $minC = Restore-Clima
        if ($minC -ge 0) { Log "clima: recupero el de hace $minC min del disco; no hace falta preguntar" }
    } catch {}
    $caida = Get-CaidaAnterior $EventLog $PID
    if ($caida) {
        $fr = Get-FraseCaida $caida
        Log ("CAIDA ANTERIOR: a las " + $caida.cuando + ", " + $caida.minutos + " min fuera; hacia: " + $caida.haciendo)
        [void](Send-AvisoEntorno 'me-cai' $fr 'medio' 720)
    }
} catch {}
# ¿LE HAN CAMBIADO LA VRAM? (1/10, la 10 de las 20). Aqui y una sola vez por arranque: la VRAM se
# cambia en la BIOS o en Armoury y eso pide reiniciar, asi que mirarlo en el bucle seria mirar algo
# que no puede cambiar mientras Nova corre. Y es justo el momento en que hay que vaciar la cache de
# shaders, que es lo que se olvida.
try { Watch-VramCambiada } catch {}
Initialize-Voz
Initialize-Escucha
# LA SIEMBRA DE LA ESPERA APRENDIDA (27/09, idea 73). UNA sola vez en la vida, aqui y no en el
# bucle: son 6 MB de registro entre los dos ficheros. Si ya se hizo, vuelve sola en seguida.
try { [void](Seed-ReaccionesAviso) } catch { Log ('siembra de reacciones: ' + $_.Exception.Message) }
# y los minutos del saludo de vuelta, medidos de sus propios huecos (idea 104). Aqui y no en el
# bucle: lee los dos registros enteros.
try { [void](Update-VueltaMin) } catch { Log ('saludo de vuelta: ' + $_.Exception.Message) }
# y los testigos de oido que Vosk ya dejo en el registro de uso (idea 87). Tambien una vez.
try { [void](Read-TestigosVosk) } catch { Log ('testigos de oido: ' + $_.Exception.Message) }
# gestos propios (config.json -> ui.gestos): la capsula los lee de tmp\gestos.txt
try {
    $lineas = @()
    foreach ($g in @(Get-Cfg 'ui' 'gestos' @())) {
        if ($g.gesto -and $g.patron) { $lineas += ([string]$g.gesto + '|' + [string]$g.patron) }
    }
    [System.IO.File]::WriteAllLines((Join-Path $TmpDir 'gestos.txt'), [string[]]$lineas, (New-Object System.Text.UTF8Encoding($false)))
} catch {}
Initialize-UI

$script:Juegos = @(Get-JuegosSteam) + @(Get-JuegosXbox)
$script:JuegosStamp = Get-Date
# ARREGLAR LAS CLAVES DE MEMORIA GUARDADAS CON EL NOMBRE DE LA CARPETA (idea 38): con catch
# propio y Log dentro -un fallo aqui no puede tumbar el arranque, pero tampoco quedarse mudo-.
# Va DESPUES de leer la biblioteca: si no, $script:Juegos aun no existe y no arregla nada.
try { Repair-ClavesPorCarpeta } catch { Log ('claves de juego: ' + $_.Exception.Message) }
# Vocabulario para Whisper: nombres propios que el dictado suele destrozar.
# Se le pasan como "prompt" y los transcribe bien ("Steam", no "stim").
try {
    $voc = @($EscuchaNombre)
    if ($cmds) {
        $voc += @($cmds.apps.PSObject.Properties.Name | Where-Object { $_ -notmatch '\s' -or $_.Length -le 16 } | Select-Object -First 20)
        $voc += @($cmds.sitios.PSObject.Properties.Name | Select-Object -First 14)
    }
    # POR LO ULTIMO QUE JUGASTE, no por el orden en que Steam los tuviera apuntados
    # (21/09). Solo caben 20 nombres, y hasta hoy los que entraban dependian de en que
    # orden estuvieran los archivos: Wallpaper Engine, que no es un juego, ocupaba
    # sitio, y los de Game Pass -que van detras de los de Steam- se habrian caido en
    # cuanto instalara cinco juegos mas. Lo que tiene que oir bien es lo que juega.
    $voc += @($script:Juegos | Sort-Object -Property @{ Expression = { [long]$_.ultimo } } -Descending |
              ForEach-Object { $_.nombre } | Select-Object -First 20)
    $voc = @($voc | Where-Object { $_ } | Select-Object -Unique)
    # PARA QUIEN LO LEA HOY (22/09): esto NO alimenta a Whisper, por mucho que lo diga el
    # nombre. Whisper dejo de recibir nombres propios el 11/09 y la escucha dejo de abrir
    # este fichero el 19/09. Lo escrito -46 nombres, 498 bytes, ~12 ms UNA vez por arranque,
    # 0 ms por orden- lo lee solo tools\probar-audio.py, la herramienta que mide Whisper con
    # y sin pistas. O sea que esto es material de medicion, no del camino de una orden.
    [System.IO.File]::WriteAllText($RutaVocabulario, (($voc -join ', ') + '.'), (New-Object System.Text.UTF8Encoding($false)))
} catch {}
# TRES RECETAS DE INFORMACION YA PUESTAS (16/09). Para no empezar de cero: son las
# preguntas que el 15/09 se fueron al agente costando 44 s cada una. Se ponen solo si no
# existen ya (por su frase), y nacen confirmadas: leer una carpeta no pide permiso.
function Add-RecetasInfoBase {
    if (-not $RecetasOn) { return }
    $base = @(
        @{ frase = 'que hay en mis descargas'
           resumen = 'mirar la carpeta de descargas'
           script = '$d = Join-Path $env:USERPROFILE ''Downloads''; $i = @(Get-ChildItem -LiteralPath $d -File | Sort-Object LastWriteTime -Descending); [pscustomobject]@{ cuantos = $i.Count; nombres = @($i | Select-Object -First 5 | ForEach-Object { $_.Name }) } | ConvertTo-Json -Compress'
           plantilla = 'En descargas tienes {cuantos|archivo|archivos}. Los ultimos: {nombres}.'
           vacio = 'No tienes nada en la carpeta de descargas.' },
        @{ frase = 'que hay en mis documentos'
           resumen = 'mirar la carpeta de documentos'
           script = '$d = Join-Path $env:USERPROFILE ''Documents''; $i = @(Get-ChildItem -LiteralPath $d | Sort-Object LastWriteTime -Descending); [pscustomobject]@{ cuantos = $i.Count; nombres = @($i | Select-Object -First 5 | ForEach-Object { $_.Name }) } | ConvertTo-Json -Compress'
           plantilla = 'En documentos tienes {cuantos|cosa|cosas}. Lo ultimo: {nombres}.'
           vacio = 'No tienes nada en documentos.' },
        @{ frase = 'cuantos clips tengo'
           resumen = 'contar los clips de juego'
           script = '$d = Join-Path $env:USERPROFILE ''Videos\Captures''; $i = @(Get-ChildItem -LiteralPath $d -File -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending); [pscustomobject]@{ cuantos = $i.Count; ultimo = $(if ($i.Count -gt 0) { $i[0].Name } else { '''' }) } | ConvertTo-Json -Compress'
           plantilla = 'Tienes {cuantos|clip|clips} guardados. El ultimo es {ultimo}.'
           vacio = 'No tienes ningun clip guardado.' }
    )
    $g = Get-Recetas
    $puestas = 0
    foreach ($b in $base) {
        $clave = ConvertTo-Suave $b.frase
        if (@($g | Where-Object { (ConvertTo-Suave ([string]$_.frase)) -eq $clave }).Count -gt 0) { continue }
        if (-not (Test-ScriptSoloLectura $b.script)) { Log "receta base '$($b.frase)': su script no pasa la revision de solo lectura"; continue }
        $pasos = New-Object System.Collections.ArrayList
        [void]$pasos.Add(@{ tipo = 'lectura'; texto = $b.script })
        $id = 1; foreach ($x in $g) { if ($x.id -ge $id) { $id = $x.id + 1 } }
        [void]$g.Add(@{ id = $id; frase = $b.frase; resumen = $b.resumen; respuesta = ''; pasos = $pasos
                        variantes = (New-Object System.Collections.ArrayList); ejemplo = $b.frase; creada = (Get-Date -Format 's')
                        usos = 0; confirmadas = [Math]::Max(2, $RecetasConfirmar); fallos = 0; rechazos = 0
                        tipo = 'info'; voz = @{ modo = 'plantilla'; plantilla = $b.plantilla; vacio = $b.vacio; instruccion = '' } })
        $puestas++
    }
    if ($puestas -gt 0) { Save-Recetas; Log "recetas de informacion puestas de serie: $puestas" }
}
try { Add-RecetasInfoBase } catch { Log ("recetas base: " + $_.Exception.Message) }
