    Show-PanelRapido
}
function Close-PanelRapido([bool]$tocarUI = $true) {
    if (-not $script:panel) { return }
    $script:panel = $null
    Log "PANEL RAPIDO: cerrado"
    if ($tocarUI) { Set-UI 'reposo' }
}
function Show-Vistazo {
    # EL TOQUE SUELTO DEL MANDO YA NO SE PIERDE (26/09, idea 36 de las 121). Un toque corto en
    # el boton de menu no hacia NADA: medido, 62 toques sueltos apuntados en el registro (ni la
    # mitad de un doble toque: cero pares en el mismo segundo). Ahora, pasados 450 ms sin segundo
    # toque -o sea que no era doble toque-, pinta en la capsula lo que Nova sabe y se calla
    # -hora, bateria y el aviso aparcado si lo hay-, 2,5 s, y se va sola. Es el gemelo del
    # Vistazo() del raton (nova_ui.cs:1685), que en una consola de mano no se dispara: no hay raton.
    #
    # SOLO TEXTO: ni Say ni Start-Vibracion. El boton de menu lo usan tambien los juegos y la
    # mediana de esos toques es 158 ms, o sea que muchos son dentro de un juego; si esto hablara
    # o vibrara, un toque accidental se sentiria como una orden ejecutada (regla 1). El panel
    # rapido si vibra, asi que darle voz o vibracion volveria los dos gestos indistinguibles.
    if ($script:panel) { return $false }                                            # el panel manda en la capsula
    if ($script:armed -or $script:pendiente -or $script:busy) { return $false }     # las mismas tres de Open-PanelRapido
    if ($script:capsulaCiega) { return $false }                                     # juego a pantalla completa exclusiva: no se veria
    if ($script:uiRetirada) { return $false }                                       # Nova escondida: Set-UI 'reposo' se vuelve 'retirada'
    if ($script:uiTexto -or $script:uiHasta -gt $sw.ElapsedMilliseconds) { return $false }  # ya hay algo puesto: no lo pises
    $linea = (Get-Date).ToString('H:mm') + ' · ' + "$($script:uiBateria)%"
    if ($script:uiCargando -eq 1) { $linea += ' ' + [char]0x26A1 }
    # EL AVISO APARCADO, SI SIGUE VIVO. Se MIRA, no se consume: de decirlo tarde ya se encarga
    # Send-AvisoEsperaSuelta (idea 5 del 25/09). [void](Get-AvisoEspera) y luego leer
    # $script:avisoEspera directo, porque Get-AvisoEspera devuelve el ArrayList y PowerShell lo
    # desenvuelve: con un solo aviso, un .Count a la salida daria las 5 claves del hashtable, no 1.
    [void](Get-AvisoEspera)
    $ahora = Get-Date
    foreach ($a in $script:avisoEspera) {
        $v = $null; try { $v = [datetime]::Parse([string]$a.vence) } catch { continue }
        if ($v -gt $ahora -and [string]$a.texto) { $linea += ' · ' + [string]$a.texto; break }
    }
    if ($linea.Length -gt 70) { $linea = $linea.Substring(0, 67) + '...' }
    Log "VISTAZO: $linea"
    Add-Estadistica 'vistazo'
    Set-UI 'reposo' $linea 2500
    $script:toqueEn = 0   # consumido: sin esto el bucle lo repintaria cada vuelta (modo sin salida, regla 2)
    return $true
}
function Show-PanelRapido {
    if (-not $script:panel) { return }
    $item = $PanelItems[$script:panel.i]
    $etq = switch ($item) {
        'volumen' { 'Volumen' }
        # la etiqueta se lee de la variable, sin preguntarle nada al sistema (a diferencia de
        # 'brillo', que hace una consulta WMI)
        'voz' { if ($script:vozVelocidad -eq 0) { 'Voz normal' } else { 'Voz ' + $(if ($script:vozVelocidad -gt 0) { '+' } else { '' }) + [string]$script:vozVelocidad } }
        'brillo' { if ($script:panelBrillo -ge 0) { "Brillo $($script:panelBrillo)%" } else { 'Brillo' } }
        'musica' { if ($script:uiMusica -and $script:musicaTitulo) { $tt = $script:musicaTitulo; if ($tt.Length -gt 18) { $tt = $tt.Substring(0, 17) + '…' }; [string][char]0x266A + " $tt" } else { 'Musica' } }
        # ENERGIA Y SONIDO EN EL PANEL (13/09): se leen al llegar a ellos, no al abrir
        'energia' {
            if (-not $script:panelEnergia) { try { $script:panelEnergia = Get-ModoEnergia } catch {} }
            if ($script:panelEnergia) { "Energia: $($script:panelEnergia)" } else { 'Energia' }
        }
        'salida' {
            if ($null -eq $script:panelSalida) { try { $script:panelSalida = [string](@(Get-SalidasAudio | Where-Object { $_.actual }) | Select-Object -First 1).nombre } catch { $script:panelSalida = '' } }
            $ns = [string]$script:panelSalida; if ($ns.Length -gt 18) { $ns = $ns.Substring(0, 17) + '…' }
            if ($ns) { "Sonido: $ns" } else { 'Sonido' }
        }
    }
    if ($script:panel.nota) { $etq += " $($script:panel.nota)" }
    Set-UI 'atenta' ([string][char]0x2039 + " $etq " + [char]0x203A) 6500
}
function Invoke-PanelRapido([int]$pul) {
    $item = $PanelItems[$script:panel.i]
    $arriba = ($pul -band $XINPUT_ARR) -ne 0
    $abajo = ($pul -band $XINPUT_ABA) -ne 0
    $boton = ($pul -band $XINPUT_A) -ne 0
    switch ($item) {
        'volumen' {
            if ($boton) { Send-Key 0xAD; $script:panel.nota = 'silencio' }
            else { $vk = if ($arriba) { 0xAF } else { 0xAE }; Send-Key $vk; Send-Key $vk; $script:panel.nota = $(if ($arriba) { [string][char]0x25B2 } else { [string][char]0x25BC }) }
        }
        'voz' {
            # EL PASO DE 15 Y EL RANGO NO SON NUEVOS: son los mismos de la orden hablada
            # ("habla mas rapido", paso 15) y de Set-VozVelocidad, que recorta a -30..+45.
            # Aqui no se repite el recorte: lo hace ella.
            if ($arriba) { Set-VozVelocidad ($script:vozVelocidad + 15) }
            elseif ($abajo) { Set-VozVelocidad ($script:vozVelocidad - 15) }
            elseif ($boton) { Set-VozVelocidad 0 }
            # SOLO SI CAMBIO, la misma linea que el ejecutor hablado: config.json se reescribe
            # entero, y manteniendo arriba serian varias escrituras por segundo dentro del bucle.
            if ([int](Get-Cfg 'voz' 'velocidad' 0) -ne $script:vozVelocidad) { [void](Set-Cfg 'voz' 'velocidad' $script:vozVelocidad) }
            $script:panel.nota = ''
        }
        'brillo' {
            if ($arriba -or $abajo) {
                if ($script:panelBrillo -lt 0) { $script:panelBrillo = 50 }
                $script:panelBrillo = [Math]::Max(0, [Math]::Min(100, $script:panelBrillo + $(if ($arriba) { 10 } else { -10 })))
                Set-Brillo $script:panelBrillo
                $script:panel.nota = ''
            }
        }
        'energia' {
            # arriba/A: mas rendimiento; abajo: mas ahorro
            $ordenE = @('ahorro', 'equilibrado', 'rendimiento')
            $actE = [array]::IndexOf($ordenE, [string]$script:panelEnergia)
            if ($actE -lt 0) { $actE = 1 }
            $nuevoE = if ($abajo) { [Math]::Max(0, $actE - 1) } else { [Math]::Min(2, $actE + 1) }
            try { if (Set-ModoEnergia $ordenE[$nuevoE]) { $script:panelEnergia = $ordenE[$nuevoE] } } catch {}
            $script:panel.nota = ''
        }
        'salida' {
            # arriba/abajo/A: la siguiente o la anterior salida de sonido
            try {
                $listaP = @(Get-SalidasAudio)
                if ($listaP.Count -gt 1) {
                    $iP = 0; for ($k = 0; $k -lt $listaP.Count; $k++) { if ($listaP[$k].actual) { $iP = $k } }
                    $iP = if ($abajo) { ($iP + $listaP.Count - 1) % $listaP.Count } else { ($iP + 1) % $listaP.Count }
                    [NovaAudio.Salida]::Poner($listaP[$iP].id)
                    try { [AX]::OlvidarVolumen() } catch {}   # el endpoint cacheado era del aparato de antes
                    $script:panelSalida = $listaP[$iP].nombre
                    $script:panel.nota = ''
                } else { $script:panel.nota = '(solo hay una)' }
            } catch { $script:panel.nota = '(no pude)' }
        }
        'musica' {
            if ($boton) { Send-Key 0xB3; $script:panel.nota = 'play/pausa' }
            elseif ($arriba) { Send-Key 0xB0; $script:panel.nota = 'siguiente' }
            elseif ($abajo) { Send-Key 0xB1; $script:panel.nota = 'anterior' }
        }
    }
    Start-Vibracion @(20) 12000
    Log "PANEL RAPIDO: $item $(if ($boton) { 'A' } elseif ($arriba) { 'arriba' } else { 'abajo' })"
}

# =============== ELEGIR CON EL MANDO (23/09, funcion 10) ================================
# EL DATO QUE LO PIDE: en catorce dias el mando se uso para contestar una pregunta CERO
# veces. Cero. Y no es que no haya preguntas: hubo VEINTE, y CINCO murieron por plazo
# -"CONFIRMAR: no se ejecuta '...' (plazo)"-, o sea que braya no contesto o Nova no le oyo.
# Eso es una de cada cuatro. Una de ellas era "abre Hollow Knight en steam", que es
# exactamente la clase de orden que ya venia de un oido dudoso.
# (El log escribe DOS lineas por pregunta -la pregunta y el desenlace-, asi que las 40
#  lineas con "CONFIRMAR" son 20 preguntas: 12 normales + 8 de traduccion. Desenlaces:
#  7 si, 5 no, 5 muertas por plazo, 2 ejecutadas al vencer y 1 cancelada. Suman 20.)
#
# Y NO ES QUE EL MANDO NO ESTE: esta siempre, es una consola de mano. Medido hoy, XInput lo
# ve en el puerto 0 y leerlo cuesta 0,197 ms. Lo que pasa es que NADIE LO SABE: Nova pregunta
# y no dice en ningun sitio que se puede contestar con un boton. Un atajo invisible es un
# atajo que no existe.
#
# Asi que esto son dos cosas:
#   1. QUE SE VEA. Cuando hay una pregunta esperando, la capsula lo dice: "A si / B no", y
#      con un juego delante "≡+A / ≡+B", que es lo que vale ahi. Sin decirlo en voz alta:
#      eso ya se alarga bastante.
#   2. QUE VALGA PARA LISTAS, no solo para si/no. El oido va al 70,4 % y ese techo no lo
#      mueve nada; pero cuando la respuesta es UNA DE ESTAS DOS, el mando acierta al 100 %.
#      La cruceta mueve, A elige, B cancela, y la voz ("la primera") sigue valiendo igual.
#
# TIENE LAS TRES SALIDAS DE LA CASA, porque es un modo: la cruceta+A, la voz de siempre, y
# un plazo de 15 s que lo cierra solo. Y B tambien.
$EleccionMs = 15000
$script:eleccion = $null
$script:mandoHay = $false

# LA TRIVIA, CON PREGUNTAS DE VERDAD (23/09, idea 8).
# Vive aqui, pegada al selector del mando, porque es su principal via de respuesta: el mando
# se uso para contestar CERO veces en catorce dias, y con el oido al 70,4 % una trivia se
# contesta con nombres propios, que es lo peor que le puede llegar.
function Get-TriviaPath { return (Join-Path $MemoriaDir 'trivia.json') }
# OCHO, Y NO ES UN NUMERO REDONDO PORQUE SI: por debajo de ocho, una tanda seguida se come
# el banco entero y Show-PreguntaTrivia empieza a dar la vuelta -a repetir- dentro de la misma
# sentada, que es exactamente lo que mato a la trivia el 13/09 (le devolvio su propia pregunta
# de hacia tres minutos). Por encima, pedir mas antes de tiempo es gastar el modelo local para
# nada.
$TriviaMinBanco = 8
# NO HAY MEDICION, Y ES QUE NO PUEDE HABERLA: la trivia se uso UNA vez en catorce dias, el
# 13/09 a las 20:48:52, y braya contesto "no se, me rindo". Cinco minutos es lo que dan unas
# diez preguntas al ritmo de una pregunta leida en voz alta mas su respuesta, y es el mismo
# numero que la sordina. Se ajusta con la primera tanda de verdad que juegue.
$TriviaModoMs = 300000
$script:triviaBanco = $null
$script:triviaActual = $null
$script:triviaModoHasta = 0
$script:triviaGenerando = $false
$script:triviaBien = 0
$script:triviaTotal = 0

# SE VALIDA AL LEER, y se tira lo que no cuadre: una opcion de mas de 26 caracteres la corta
# el selector al pintarla, y una opcion cortada es una opcion que no se puede elegir a ciegas.
function Get-BancoTrivia {
    if ($null -ne $script:triviaBanco) { return $script:triviaBanco }
    $script:triviaBanco = @{ preguntas = @(); hechas = @() }
    try {
        if (Test-Path -LiteralPath (Get-TriviaPath)) {
            $j = Get-Content -LiteralPath (Get-TriviaPath) -Raw -Encoding UTF8 | ConvertFrom-Json
            $buenas = @()
            foreach ($q in @($j.preguntas)) {
                if ($null -eq $q -or -not [string]$q.pregunta) { continue }
                $ops = @($q.opciones | ForEach-Object { [string]$_ })
                if ($ops.Count -ne 3) { continue }
                if (@($ops | Where-Object { $_.Length -gt 26 -or -not $_.Trim() }).Count -gt 0) { continue }
                $b = [int]$q.buena
                if ($b -lt 1 -or $b -gt 3) { continue }
                $buenas += @{ id = [string]$q.id; pregunta = [string]$q.pregunta; opciones = $ops; buena = $b }
            }
            $script:triviaBanco.preguntas = $buenas
            $script:triviaBanco.hechas = @($j.hechas | ForEach-Object { [string]$_ })
        }
    } catch { Save-Corrupto (Get-TriviaPath) 'trivia' }
    return $script:triviaBanco
}

function Save-BancoTrivia {
    if ($null -eq $script:triviaBanco) { return }
    try {
        $o = [ordered]@{ preguntas = @(); hechas = @($script:triviaBanco.hechas) }
        foreach ($q in @($script:triviaBanco.preguntas)) {
            $o.preguntas += New-Object PSObject -Property @{ id = $q.id; pregunta = $q.pregunta; opciones = @($q.opciones); buena = $q.buena }
        }
        Write-Atomico (Get-TriviaPath) (ConvertTo-Json -InputObject $o -Depth 5)
    } catch {}
}

# SE PIDEN AL MODELO LOCAL, UNA VEZ, y nunca jugando: generar veinte preguntas es una llamada
# de la misma clase que la que ya contesta "cuantas patas tiene una arana" -13,1 s la primera,
# por el arranque en frio-, y despues cuesta cero. Con un juego delante, ni eso.
function Request-BancoTrivia {
    if ($script:juegoActivo) { Log 'TRIVIA: no pido preguntas con un juego delante'; return $false }
    # Y CON PLAZO (24/09, repaso): si el aviso del worker no llega -porque se murio, porque
    # estaba ocupado, o por cualquier camino que no lo emita-, esto se quedaba en $true para
    # siempre y la trivia no volvia a pedir preguntas hasta reiniciar Nova. Tres minutos es
    # el doble largo de lo que tarda la llamada mas lenta medida al modelo local (13,1 s en
    # frio, y aqui son veinte preguntas de una vez con num_predict 2000).
    if ($script:triviaGenerando -and ($sw.ElapsedMilliseconds - $script:triviaGenerandoEn) -lt 180000) { return $false }
    if ($script:triviaGenerando) { Log 'TRIVIA: el banco no llego en tres minutos; lo doy por perdido' }
    if (-not $ConversacionOn) { return $false }
    try { if (-not (Test-RamParaCharla)) { Log 'TRIVIA: no hay RAM para pedir preguntas'; return $false } } catch {}
    $script:charlaId++
    # NO se usa Send-Charla: esa pone la capsula a esperar y limpia la cola de frases, y esto
    # no habla. Solo se pide el banco y se sigue con lo que se estuviera haciendo.
    if (-not (Send-CharlaPedido @{ op = 'triviabanco'; id = $script:charlaId; ruta = (Get-TriviaPath); cuantas = 20 } (-not $script:juegoActivo))) { return $false }
    $script:triviaGenerando = $true
    $script:triviaGenerandoEn = $sw.ElapsedMilliseconds
    Log 'TRIVIA: pedidas 20 preguntas al modelo local'
    return $true
}

function Get-MarcadorTrivia {
    if ($script:triviaTotal -le 0) { return 'aun no llevamos ninguna' }
    return "llevas $($script:triviaBien) de $($script:triviaTotal)"
}

function Show-PreguntaTrivia {
    $b = Get-BancoTrivia
    $cand = @($b.preguntas | Where-Object { @($b.hechas) -notcontains [string]$_.id })
    if ($cand.Count -eq 0) {
        # dadas todas la vuelta: se empieza otra ronda en vez de quedarse sin preguntas
        $b.hechas = @()
        $cand = @($b.preguntas)
    }
    if ($cand.Count -eq 0) { return $false }
    $q = $cand[(Get-Random -Minimum 0 -Maximum $cand.Count)]
    # SE BARAJAN AQUI, SIEMPRE: un modelo pequeno pone la buena la primera casi siempre, y
    # entonces "la primera" acierta sin saber nada.
    $idx = @(0, 1, 2) | Sort-Object { Get-Random }
    $ops = @($idx | ForEach-Object { [string]$q.opciones[$_] })
    $buena = ([array]::IndexOf($idx, ($q.buena - 1))) + 1
    $script:triviaActual = @{ id = [string]$q.id; pregunta = [string]$q.pregunta; opciones = $ops; buena = $buena }
    $script:triviaModoHasta = $sw.ElapsedMilliseconds + $TriviaModoMs
    $texto = [string]$q.pregunta + ' Uno, ' + $ops[0] + '. Dos, ' + $ops[1] + '. Tres, ' + $ops[2] + '.'
    Show-Popup $texto
    Say $texto
    [void](Open-Eleccion $ops 'trivia')
    return $true
}

function Start-Trivia {
    $b = Get-BancoTrivia
    if (@($b.preguntas).Count -lt $TriviaMinBanco) { [void](Request-BancoTrivia) }
    if (@($b.preguntas).Count -eq 0) { return $false }
    $script:triviaBien = 0
    $script:triviaTotal = 0
    Log 'TRIVIA: empieza la tanda'
    return (Show-PreguntaTrivia)
}

function Complete-Trivia([int]$n) {
    $q = $script:triviaActual
    if (-not $q) { return }
    $script:triviaActual = $null
    $b = Get-BancoTrivia
    if (@($b.hechas) -notcontains [string]$q.id) { $b.hechas = @(@($b.hechas) + [string]$q.id) }
    $script:triviaTotal++
    if ($n -eq [int]$q.buena) {
        $script:triviaBien++
        Say ('Bien. ' + (Get-MarcadorTrivia) + '.')
    } elseif ($n -le 0) {
        Say ('Era ' + [string]$q.opciones[[int]$q.buena - 1] + '. ' + (Get-MarcadorTrivia) + '.')
    } else {
        Say ('No, era ' + [string]$q.opciones[[int]$q.buena - 1] + '. ' + (Get-MarcadorTrivia) + '.')
    }
    Save-BancoTrivia
    [void](Show-PreguntaTrivia)
}

# TRES SALIDAS, como pide la casa: decirlo, el boton B del selector, y el plazo.
function Stop-Trivia([string]$motivo = '') {
    if ($script:triviaModoHasta -le 0) { return }
    try { Close-Eleccion } catch {}
    $script:triviaModoHasta = 0
    $script:triviaActual = $null
    Save-BancoTrivia
    Log "TRIVIA: se acabo ($motivo)"
    if ($script:triviaTotal -gt 0) { Say ('Lo dejamos. ' + (Get-MarcadorTrivia) + '.') } else { Say 'Vale, lo dejamos.' }
    $script:triviaBien = 0
    $script:triviaTotal = 0
}

function Test-TriviaPlazo {
    if ($script:triviaModoHasta -gt 0 -and $sw.ElapsedMilliseconds -ge $script:triviaModoHasta) { Stop-Trivia 'plazo' }
}

function Show-Eleccion {
    if (-not $script:eleccion) { return }
    $e = $script:eleccion
    $op = [string]$e.opciones[$e.i]
    if ($op.Length -gt 26) { $op = $op.Substring(0, 25) + [string][char]0x2026 }
    # el mismo prefijo que la pista: con un juego delante A a secas no vale, y decir "A"
    # a pelo seria ensenar el atajo que justo no funciona ahi
    $preE = if ($script:juegoActivo) { [string][char]0x2261 + '+' } else { '' }
    $etq = [string][char]0x2039 + " $op " + [char]0x203A + "  $($e.i + 1)/$($e.opciones.Count)  ${preE}A"
    # EL ANILLO TIENE QUE CONTAR ESTE PLAZO, no el de la pregunta anterior. Sin esto la
    # capsula dibuja 'confirmando' con un confirmaFin viejo: o el anillo sale lleno para
    # siempre o sale vacio de entrada, y en las dos parece que ya se acabo el tiempo.
    $quedaE = [Math]::Max(0, $e.hasta - $sw.ElapsedMilliseconds)
    $script:confirmaFin = [DateTimeOffset]::Now.ToUnixTimeMilliseconds() + $quedaE
    $script:confirmaTotal = [Math]::Max(1, $EleccionMs)
    Set-UI 'confirmando' $etq ($EleccionMs + 500)
}

# Devuelve $true si se abrio. Si no hay mando, o hay otra cosa mandando en la capsula, no
# se abre y quien llama sigue con la voz de siempre: esto NUNCA es la unica salida.
function Open-Eleccion([string[]]$opciones, [string]$origen) {
    if (-not $script:mandoHay) { return $false }
    if ($script:panel -or $script:pendiente -or $script:eleccion) { return $false }
    $ops = @($opciones | Where-Object { $_ })
    if ($ops.Count -lt 2 -or $ops.Count -gt 6) { return $false }
    $script:eleccion = @{ opciones = $ops; i = 0; origen = [string]$origen
                          hasta = $sw.ElapsedMilliseconds + $EleccionMs }
    Log ("ELEGIR ($origen): " + ($ops -join ' | '))
    Start-Vibracion @(30, 40, 30) 14000
    Show-Eleccion
    return $true
}

function Close-Eleccion([bool]$tocarUI = $true) {
    if (-not $script:eleccion) { return }
    $script:eleccion = $null
    # EL ANILLO SOLO SE APAGA SI NO HAY OTRA PREGUNTA VIVA. Se cerraba a ciegas, y el
    # camino normal es justo ese: llega una pregunta de si/no -> el bucle cierra el selector
    # -> y de paso le borraba el anillo a la pregunta que acababa de nacer.
    if (-not $script:pendiente) { $script:confirmaFin = 0; $script:confirmaTotal = 0 }
    if ($tocarUI -and -not $script:pendiente) { Set-UI 'reposo' }
}

# Elegida la numero $n (1..N). Cada origen sabe que hacer con su numero; lo que se diga
# vuelve por la voz de siempre.
function Complete-Eleccion([int]$n) {
    if (-not $script:eleccion) { return }
    $e = $script:eleccion
    $script:eleccion = $null
    if (-not $script:pendiente) { $script:confirmaFin = 0; $script:confirmaTotal = 0 }
    if ($n -lt 1 -or $n -gt $e.opciones.Count) { Set-UI 'reposo'; return }
    Log ("ELEGIR ($($e.origen)): la $n, " + [string]$e.opciones[$n - 1])
    Start-Vibracion @(70) 14000
    switch ([string]$e.origen) {
        'ajedrez' {
            $r = Invoke-AjedrezPy @('--elegir', [string]$n)
            if ($r -and $r.decir) { Say ([string]$r.decir) } else { Set-UI 'reposo' }
        }
        'trivia' { Complete-Trivia $n }
        'amigo' {
            $rA = Complete-AmigoElige $n
            if ($rA) { Say $rA } else { Set-UI 'reposo' }
        }
        'perfil' { Say (Resolve-PerfilPar $n) }
        default { Set-UI 'reposo' }
    }
}

# LA PISTA, que es la mitad de esta funcion. Con un juego delante A y B son del juego y
# aqui solo valen con ≡ apretado; fuera del juego valen solos. Y en una pregunta peligrosa
# A NO vale nunca (esa regla es del 13/09 y no se toca): ahi la pista solo ofrece el no.
# LA QUIETUD DEL MANDO Y LA MESA (27/09, idea 69)
#
# EL UMBRAL NO LO ESCRIBE NADIE: 'quieto de verdad' es el percentil 90 de los huecos que de verdad
# hace braya entre movimiento y movimiento. Un hueco mas largo que el 90 % de los suyos ya no es
# una pausa de partida: es que ha soltado el mando. Con menos de MandoHuecosMin muestras se
# devuelve 0, que es como se dice 'todavia no lo se' -y entonces Get-EnLaMesa no afirma nada-.
$MandoHuecosJson = Join-Path $MemoriaDir 'mando-huecos.json'
$MandoHuecosMax = 300           # huecos guardados; a ~7 dias de uso sobra
$MandoHuecosMin = 20            # menos que esto y no hay percentil que valga
$MandoQuietoPct = 90
function Get-HuecosMando {
    $l = New-Object System.Collections.ArrayList
    if (Test-Path -LiteralPath $MandoHuecosJson) {
        try {
            $j = Get-Content -LiteralPath $MandoHuecosJson -Raw -Encoding UTF8 | ConvertFrom-Json
            foreach ($v in @($j.huecos)) {
                $n = 0
                if ([int]::TryParse([string]$v, [ref]$n) -and $n -gt 0) { [void]$l.Add($n) }
            }
        } catch { }
    }
    return ,$l   # la coma no sobra: una lista vacia desenrollada se queda en $null
}

# los huecos que se juntan entre volcado y volcado: ver la llamada en el bloque del minuto (28/09)
$script:huecosMandoRam = New-Object System.Collections.ArrayList
function Add-HuecoMando([int]$segundos) {
    if ($segundos -le 0) { return $false }
    try {
        $l = Get-HuecosMando
        [void]$l.Add($segundos)
        while ($l.Count -gt $MandoHuecosMax) { $l.RemoveAt(0) }
        Write-Atomico $MandoHuecosJson (ConvertTo-Json @{ huecos = @($l); visto = (Get-Date -Format 's') } -Compress)
        return $true
    } catch { return $false }
}

# Segundos desde que el mando se movio por ultima vez. -1 si no se ha visto moverse nunca en esta
# sesion (recien arrancada, o el mando no esta): eso NO es quietud, es no saber.
function Get-QuietudMando {
    if (-not $script:mandoHay -or $script:mandoMovidoEn -le 0) { return -1 }
    return [int](($sw.ElapsedMilliseconds - $script:mandoMovidoEn) / 1000)
}

function Get-UmbralQuietud {
    $l = Get-HuecosMando
    if (@($l).Count -lt $MandoHuecosMin) { return 0 }
    return (Get-PercentilLista $l $MandoQuietoPct)
}

# ¿ESTA EN LA MESA? Plana Y el mando quieto mas que su propio umbral. Las dos cosas, porque cada
# una sola se equivoca: tumbada en la cama jugando tambien da Faceup, y el mando quieto un rato
# largo pasa leyendo un dialogo. Si falta cualquiera de las dos senales -sensor apagado o umbral
# sin aprender- devuelve $false: no se inventa una certeza que no hay.
function Get-EnLaMesa {
    if (-not $script:orientacionPlana) { return $false }
    $q = Get-QuietudMando
    if ($q -lt 0) { return $false }
    $u = Get-UmbralQuietud
    if ($u -le 0) { return $false }
    return ($q -gt $u)
}
function Get-PistaMando([string]$tipo) {
    if (-not $script:mandoHay) { return '' }
    # Y SI ESTA EN LA MESA, NO ES UNA VIA REAL (27/09, idea 69). En los dos registros hay 41
    # lineas CONFIRMAR -20 preguntas-, cinco murieron por plazo y NINGUNA se contesto con el
    # mando. Ofrecer 'A si / B no' con el mando en la mesa gasta sitio en la capsula y ensena
    # un camino que no existe; sin la pista, la pregunta se contesta hablando, que si funciona.
    if (Get-EnLaMesa) { return '' }
    $pre = if ($script:juegoActivo) { [string][char]0x2261 + '+' } else { '' }
    if ($tipo -eq 'peligrosa') { return "   ${pre}B no" }
    return "   ${pre}A si  ${pre}B no"
}

$pollErrs = 0
# botones del mando en la vuelta anterior: A y B contestan preguntas (ver abajo)
$XINPUT_A = 0x1000
$XINPUT_B = 0x2000
$script:botonesPrev = 0
$script:mandoRespondioEn = -100000

# LOS PUERTOS QUE NUNCA HAN TENIDO NADA NO SE PREGUNTAN EN CADA VUELTA (27/09, idea 66).
# MEDIDO HOY en esta Ally con la clase AX del proyecto, 300 llamadas por puerto: puerto 0 (el
# mando de la consola, ret=0) 0,1534 ms; puertos 1, 2 y 3, todos 1167 -no conectado-, 0,3592 /
# 0,3876 / 0,3944 ms. De los 1,2946 ms que cuesta una vuelta, 1,1412 se van en puertos vacios:
# el 88,2 %. A 33 vueltas por segundo son 42,7 ms de CPU por segundo, de los que 37,7 se tiran.
# El puerto 0 contesto en los 130 arranques de los dos registros.
#
# EL PUERTO 0 NO ENTRA AQUI NUNCA: es el mando fisico de la consola y el que dispara el gatillo.
# El plazo del repaso NO lo escribe nadie a mano en el sentido que importa: empieza en 1 s, se
# dobla hasta 4 s cada vez que un repaso sale vacio, y vuelve a 1 s en cuanto aparece un mando.
# Un puerto que ya contesto se pregunta en todas las vueltas mientras siga contestando; si deja
# de hacerlo mas tiempo que el tope del repaso, vuelve a la cola de los aplazados.
# EL PAQUETE DEL MANDO, QUE SE LEIA Y SE TIRABA (27/09, idea 69). XInput sube dwPacketNumber solo
# cuando el mando cambia de estado, asi que sale gratis saber cuanto lleva braya sin tocarlo:
# el estado ya se lee cada 30 ms y de la struct solo se usaba wButtons (dwPacketNumber no aparecia
# NI UNA VEZ en las 31.000 lineas del script). Comprobado hoy en esta Ally: puerto 0 ret=0,
# paquete 11481, y 700 ms despues sin tocarlo sigue en 11481; las setas tienen valor en reposo
# (LX=0 LY=-1) asi que cualquier roce lo mueve.
#
# PARA QUE SIRVE, y es lo que la idea no decia: GetLastInputInfo -la unica senal de presencia que
# habia- NO cuenta el mando. Jugando con el mando una hora, para Windows braya lleva una hora sin
# tocar nada, asi que Nova puede dar por hecho que no hay nadie y aparcar avisos con el delante.
$script:mandoPaquete = -1          # ultimo dwPacketNumber visto en el puerto 0
$script:mandoMovidoEn = -100000    # ms del bucle cuando cambio por ultima vez

$RescanMandoMin = 1000
$RescanMandoTope = 4000
$script:puertoVisto = @{}          # puerto -> ms del ultimo ret=0
$script:rescanMandoMs = $RescanMandoMin
$script:rescanMandoEn = 0          # cuando toca el proximo repaso de los vacios

# ¿Se pregunta a este puerto en esta vuelta? Aparte del bucle (que no se puede extraer) para que
# el banco la ejecute de verdad en vez de mirar el texto: ver tools\probar-mando-puertos.ps1.
function Test-SondearPuerto([int]$u, [bool]$repasa, [double]$ahora) {
    if ($u -le 0) { return $true }            # el puerto 0 siempre: es el mando de la consola
    if ($repasa) { return $true }             # en el repaso entran todos
    $vistoEn = $script:puertoVisto[$u]
    if ($null -eq $vistoEn) { return $false } # nunca contesto
    return (($ahora - [double]$vistoEn) -le $RescanMandoTope)   # dejo de contestar: a la cola
}

# El plazo del proximo repaso, a la vista de lo que encontro este.
function Get-RescanMandoMs([bool]$mandoNuevo, [double]$msAhora) {
    if ($mandoNuevo) { return $RescanMandoMin }
    return [Math]::Min($RescanMandoTope, $msAhora * 2)
}

# EL MODO INVITADO, SI VENIA DE ANTES (24/09, repaso). Va aqui, justo antes del bucle, para
# que ni una sola vuelta corra creyendo que el que habla es braya.
try { Restore-Invitado } catch {}

$script:erroresBucle = 0
while ($true) {
    # RED DEL BUCLE (auditoria del 13/09): con $ErrorActionPreference = Stop, una
    # sola excepcion sin capturar en cualquier punto de la vuelta apagaba el
    # asistente hasta el siguiente inicio de sesion. Ahora se anota y se sigue.
    try {
    # EL PULSO (27/09, idea 72). Lo primero de la vuelta: lo que tardo la ANTERIOR, que es una resta
    # y no cuesta nada. Ver EL PULSO DEL BUCLE.
    $vAhora = $sw.ElapsedMilliseconds
    if ($script:vueltaDesde -gt 0) {
        $script:vueltaMs = [int]($vAhora - $script:vueltaDesde)
        try { Add-VueltaMedida $script:vueltaMs } catch {}
    }
    $script:vueltaDesde = $vAhora
    [System.Windows.Forms.Application]::DoEvents()
    $startNow = $false
    $botones = 0
    $pollOk = $true
    # tras un fallo de XInput se espera 5 s SIN bloquear el bucle: el resto
    # (escucha, popups, trabajos) tiene que seguir atendiendose
    $saltarPoll = ($script:pollReintento -gt 0 -and $sw.ElapsedMilliseconds -lt $script:pollReintento)
    # ver LOS PUERTOS QUE NUNCA HAN TENIDO NADA: en esta vuelta, ¿toca repasar los vacios?
    $repasaMando = ($sw.ElapsedMilliseconds -ge $script:rescanMandoEn)
    $mandoNuevo = $false
    for ($u = 0; (-not $saltarPoll) -and $u -lt 4; $u++) {
        if (-not (Test-SondearPuerto $u $repasaMando $sw.ElapsedMilliseconds)) { continue }
        try {
            $state = New-Object AX+XINPUT_STATE
            $r = [AX]::XInputGetState([uint32]$u, [ref]$state)
            if ($r -eq 0) {
                $botones = $botones -bor [int]$state.Gamepad.wButtons; $script:mandoHay = $true
                # ¿SE HA MOVIDO? (idea 69). Solo el puerto 0, que es el mando de la consola.
                if ($u -eq 0) {
                    $pq = [int]$state.dwPacketNumber
                    if ($script:mandoPaquete -ge 0 -and $pq -ne $script:mandoPaquete) {
                        # el HUECO que acaba de cerrarse, para aprender que es 'quieto de verdad'
                        if ($script:mandoMovidoEn -gt 0) {
                            $huecoS = [int](($sw.ElapsedMilliseconds - $script:mandoMovidoEn) / 1000)
                            # AL MINUTO, NO EN CADA ROCE (28/09, tras la revision). Add-HuecoMando
                            # lee memoria\mando-huecos.json entero, le anade uno y lo reescribe con
                            # Write-Atomico: 19 ms medidos por escritura, DENTRO del sondeo del mando
                            # y sin reloj ni freno. Se dispara cada vez que el paquete de XInput
                            # cambia tras un hueco de un segundo o mas, o sea cada vez que braya toca
                            # el mando despues de dejarlo quieto un rato; y el propio comentario de
                            # Add-HuecoMando avisa de que "las setas tienen valor en reposo, asi que
                            # cualquier roce lo mueve": navegando menus son varias veces por minuto.
                            # Es un fichero dentro del bucle que se puede evitar (regla 4), y el
                            # patron de acumular en RAM y volcar al minuto ya esta en casa: es lo que
                            # hace el pulso de la vuelta.
                            if ($huecoS -gt 0) { [void]$script:huecosMandoRam.Add($huecoS) }
                        }
                        $script:mandoMovidoEn = $sw.ElapsedMilliseconds
                    }
                    $script:mandoPaquete = $pq
                }
                if ($u -gt 0 -and $null -eq $script:puertoVisto[$u]) { $mandoNuevo = $true; Log "mando: aparecio uno en el puerto $u" }
                $script:puertoVisto[$u] = $sw.ElapsedMilliseconds
            }
            if ($r -eq 0 -and (($state.Gamepad.wButtons -band $TRIGGER) -eq $TRIGGER)) {
                $startNow = $true
                break
            }
        } catch {
            # NADA de Start-Sleep aqui dentro: estaba en un bucle sobre los 4
            # mandos, asi que un fallo persistente de XInput dormia hasta 20 s
            # POR VUELTA con el boton sin responder. El contador solo silenciaba
            # el log, no evitaba la espera. Ahora se corta el tick y se aplaza
            # el siguiente intento sin bloquear.
            $pollOk = $false
            $pollErrs++
            if ($pollErrs -le 5) {
                Log "poll error: $($_.Exception.Message)"
                if ($pollErrs -eq 5) { Log "poll error: se silencian los siguientes avisos hasta que vuelva a funcionar" }
            }
            $script:pollReintento = $sw.ElapsedMilliseconds + 5000
            break
        }
    }
    # SOLO CUENTA COMO BUENO SI SE LLEGO A MIRAR (21/09). Cuando XInput falla se aplaza
    # el siguiente intento 5 segundos, y en las vueltas de ese rato $saltarPoll es cierto:
    # el for no se ejecuta, $pollOk se queda en $true por no haberse tocado, y el contador
    # volvia a cero. O sea que al reintentar y fallar otra vez, $pollErrs valia 1 y se
    # escribia la linea en el log de nuevo... cada 5 segundos, para siempre. El silencio
    # de los cinco primeros no llegaba a aplicarse nunca, que era justo para lo que se
    # puso. Un mando desconectado llenaba assistant.log el solo.
    if ($pollOk -and -not $saltarPoll) { $pollErrs = 0 }

    # EL PLAZO DEL REPASO, a la vista de lo que encontro (idea 66). Al primer mando nuevo vuelve a
    # 1 s para que enchufar otro se note enseguida; si el repaso sale vacio se dobla hasta 4 s.
    # y NO si el gatillo corto el for a medias ($startNow): ese repaso no llego a mirar los
    # puertos de atras, y darlo por hecho aplazaria el siguiente sin haber visto nada.
    if ($repasaMando -and -not $saltarPoll -and -not $startNow) {
        $script:rescanMandoMs = Get-RescanMandoMs $mandoNuevo $script:rescanMandoMs
        $script:rescanMandoEn = $sw.ElapsedMilliseconds + $script:rescanMandoMs
    }

    # RESPONDER CON EL MANDO (13/09): con una pregunta de si/no esperando, A es
    # si y B es no. Solo mientras hay pregunta: el resto del tiempo A y B son
    # del juego y aqui no se tocan. Cuenta la PULSACION (el flanco), no tenerlo
    # apretado: si ya lo tenias pulsado jugando cuando llego la pregunta, no
    # vale como respuesta. Una pregunta peligrosa ("cierra todos los
    # programas") sigue pidiendo un si hablado; B si la cancela.
    $pulsadoA = (($botones -band $XINPUT_A) -ne 0) -and (($script:botonesPrev -band $XINPUT_A) -eq 0)
    $pulsadoB = (($botones -band $XINPUT_B) -ne 0) -and (($script:botonesPrev -band $XINPUT_B) -eq 0)
    # todos los botones que se ACABAN de pulsar en esta vuelta (los usa el panel)
    $pulsados = [int]$botones -band (-bnot [int]$script:botonesPrev)
    $script:botonesPrev = $botones
    # Revision del 13/09: jugando, A es el boton que mas se pulsa; ahi solo vale
    # con ≡ apretado a la vez (≡+A / ≡+B). Y nunca mientras suena la pregunta.
    $conMenu = (($botones -band $TRIGGER) -eq $TRIGGER)
    $mandoVale = ((-not $script:juegoActivo) -or $conMenu) -and ($sw.ElapsedMilliseconds -ge $script:pausaHasta)
    if (($pulsadoA -or $pulsadoB) -and $mandoVale -and $conMenu) { $holdFired = $true; $script:mandoRespondioEn = $sw.ElapsedMilliseconds }   # que ≡ no dispare el hold
    if (($pulsadoA -or $pulsadoB) -and $mandoVale -and $script:pendiente -and -not $script:busy -and -not $script:panel) {
        try {
            if ($pulsadoB) {
                Log "CONFIRMAR con el mando: B (no)"
                Start-Vibracion @(40, 50, 40) 14000
                Complete-Confirmacion 'no'
                Send-UIEvento 'gesto:negar'   # la carita niega (13/09)
            } elseif ($script:pendiente.tipo -eq 'peligrosa') {
                Log "mando: A no vale para una pregunta peligrosa; hace falta un si hablado"
                Start-Vibracion @(120) 20000
                Set-UI 'confirmando' 'Dimelo en voz alta'
            } else {
                Log "CONFIRMAR con el mando: A (si)"
                Start-Vibracion @(70) 14000
                # la carita asiente ANTES de hacerlo: lo que venga despues (el "hecho")
                # pisaria el gesto en la misma vuelta de la capsula (13/09)
                Send-UIEvento 'gesto:asentir'
                Start-Sleep -Milliseconds 120
                Complete-Confirmacion 'si'
            }
        } catch { Log "mando A/B error: $($_.Exception.Message)" }
    }

    # PANEL RAPIDO abierto: la cruceta y A/B son suyos (ver PANEL RAPIDO)
    if ($script:panel) {
        try {
            if ($script:pendiente -or $script:busy -or $script:armed) {
                Close-PanelRapido $false   # otra cosa manda en la capsula: no la pises
            } elseif ($sw.ElapsedMilliseconds -ge $script:panel.hasta) {
                Close-PanelRapido
            } elseif ($pulsados -ne 0) {
                $script:panel.hasta = $sw.ElapsedMilliseconds + 6000
                if ($pulsados -band $XINPUT_B) { Close-PanelRapido }
                elseif ($pulsados -band $XINPUT_IZQ) { $script:panel.i = ($script:panel.i + $PanelItems.Count - 1) % $PanelItems.Count; $script:panel.nota = ''; Show-PanelRapido }
                elseif ($pulsados -band $XINPUT_DER) { $script:panel.i = ($script:panel.i + 1) % $PanelItems.Count; $script:panel.nota = ''; Show-PanelRapido }
                elseif ($pulsados -band ($XINPUT_ARR -bor $XINPUT_ABA -bor $XINPUT_A)) { Invoke-PanelRapido $pulsados; Show-PanelRapido }
            }
        } catch { Log ("panel rapido: " + $_.Exception.Message); $script:panel = $null }
    }

    # MOVIENDO LA LUPA (23/09, idea 15): con la lupa puesta, la cruceta corre el trozo que se
    # ve y los hombros cambian el aumento (x2, x3, x4). La captura ya esta hecha, asi que esto
    # no vuelve a fotografiar nada: es un DrawImage sobre la misma imagen.
    #
    # VA DESPUES DEL SELECTOR Y DEL PANEL, y solo si ninguno de los dos esta abierto: los tres
    # se pelean por la misma cruceta. Y manda $mandoVale, como todo lo que lee botones aqui:
    # con un juego delante hace falta ≡, porque ahi la cruceta es del juego.
    if ($script:lupaForm -and -not $script:eleccion -and -not $script:panel -and -not $script:pendiente) {
        try {
            if ($pulsados -ne 0 -and $mandoVale) {
                $movida = $false
                # el paso es un tercio de lo que se ve, para que siempre quede solapado y no
                # se pierda el hilo de lo que se estaba leyendo
                $paso = [Math]::Max(20, [int]($script:lupaNW / (3.0 * $script:lupaEsc)))
                $pasoV = [Math]::Max(20, [int]($script:lupaNH / (3.0 * $script:lupaEsc)))
                if ($pulsados -band $XINPUT_IZQ) { $script:lupaDx -= $paso; $movida = $true }
                elseif ($pulsados -band $XINPUT_DER) { $script:lupaDx += $paso; $movida = $true }
                elseif ($pulsados -band $XINPUT_ARR) { $script:lupaDy -= $pasoV; $movida = $true }
                elseif ($pulsados -band $XINPUT_ABA) { $script:lupaDy += $pasoV; $movida = $true }
                elseif ($pulsados -band $XINPUT_RB) {
                    $i = [array]::IndexOf($LupaEscalas, [double]$script:lupaEsc)
                    if ($i -lt 0) { $i = 0 }
                    if ($i -lt $LupaEscalas.Count - 1) { $script:lupaEsc = $LupaEscalas[$i + 1]; $movida = $true }
                }
                elseif ($pulsados -band $XINPUT_LB) {
                    $i = [array]::IndexOf($LupaEscalas, [double]$script:lupaEsc)
                    if ($i -lt 0) { $i = 0 }
                    if ($i -gt 0) { $script:lupaEsc = $LupaEscalas[$i - 1]; $movida = $true }
                }
                elseif ($pulsados -band $XINPUT_B) { Log 'LUPA: quitada con B'; Close-Lupa }
                if ($movida) {
                    # EL PLAZO SE RENUEVA SOLO CON LO QUE LA LUPA CONSUME (misma leccion que
                    # el selector): si se renovara con cualquier boton, jugando no venceria.
                    $script:lupaUntil = $sw.ElapsedMilliseconds + $LupaMs
                    [void](Update-Lupa)
                }
            }
        } catch { Log ('lupa: ' + $_.Exception.Message); Close-Lupa }
    }

    # EL PLAZO DEL MODO DE TRIVIA (23/09, idea 8), en el mismo sitio que el del selector:
    # cinco minutos sin contestar y se cierra solo. Es una comparacion de enteros.
    try { Test-TriviaPlazo } catch {}

    # ELIGIENDO DE UNA LISTA (23/09, funcion 10): la cruceta mueve, A elige, B cancela.
    # Igual que el panel rapido, y por lo mismo: XInput no es exclusivo, asi que con un
    # juego delante la cruceta le llega tambien al juego. Por eso dura 15 s y no mas.
    #
    # Y POR ESO MANDA $mandoVale, LA MISMA DE LA PREGUNTA DE SI/NO (revision del 23/09).
    # Nacio sin ella y era el fallo mas grave de la tanda: con un juego delante, A es el
    # boton que mas se pulsa -saltar-, asi que saltando en Hollow Knight se hacia una jugada
    # de ajedrez que braya no habia elegido. Eso es exactamente la regla de la casa que no se
    # negocia. $mandoVale exige ≡ apretado si hay juego, y ademas que Nova haya terminado de
    # hablar, que es la otra mitad: un boton pulsado MIENTRAS suena la pregunta tampoco vale
    # como respuesta.
    if ($script:eleccion) {
        try {
            if ($script:pendiente -or $script:busy -or $script:panel) {
                Close-Eleccion $false            # otra cosa manda en la capsula: no la pises
            } elseif ($sw.ElapsedMilliseconds -ge $script:eleccion.hasta) {
                Log "ELEGIR: se acabo el plazo"
                Close-Eleccion
            } else {
                # LA CAPSULA SE REDIBUJA AQUI, y no solo al abrirla. Open-Eleccion pinta la
                # lista y un instante despues Say la pisa con 'hablando' (es la voz leyendo la
                # pregunta): el selector se quedaba abierto 15 s SIN NADA EN PANTALLA, y el
                # manual promete que se ve. Mismo remedio que el bloque de si/no: en cuanto
                # acaba la voz, se vuelve a pintar.
                if ($script:uiEstado -ne 'confirmando' -and -not $script:busy -and $script:uiHasta -le $sw.ElapsedMilliseconds) { Show-Eleccion }
                if ($pulsados -ne 0 -and $mandoVale) {
                    $n = $script:eleccion.opciones.Count
                    # EL PLAZO SE RENUEVA SOLO CON LO QUE EL SELECTOR CONSUME. Estaba en el if
                    # de fuera, asi que jugando -donde llueven botones- el plazo no vencia
                    # nunca y la lista se quedaba puesta para siempre.
                    # LA B SALE DEL MODO, no solo de la lista (23/09, idea 8). Close-Eleccion
                    # borra el selector y ya esta: la trivia se quedaba viva cinco minutos con
                    # la pregunta puesta y sin nada en pantalla. Con el oido al 70,4 % el mando
                    # es la via fiable, asi que aqui tiene que salir de verdad.
                    if ($pulsados -band $XINPUT_B) {
                        $eraTrivia = ([string]$script:eleccion.origen -eq 'trivia')
                        Log "ELEGIR: cancelado con B"
                        Close-Eleccion
                        if ($eraTrivia) { Stop-Trivia 'boton B' }
                    }
                    elseif ($pulsados -band $XINPUT_A) { Complete-Eleccion ($script:eleccion.i + 1) }
                    elseif ($pulsados -band ($XINPUT_IZQ -bor $XINPUT_ARR)) { $script:eleccion.i = ($script:eleccion.i + $n - 1) % $n; $script:eleccion.hasta = $sw.ElapsedMilliseconds + $EleccionMs; Show-Eleccion }
                    elseif ($pulsados -band ($XINPUT_DER -bor $XINPUT_ABA)) { $script:eleccion.i = ($script:eleccion.i + 1) % $n; $script:eleccion.hasta = $sw.ElapsedMilliseconds + $EleccionMs; Show-Eleccion }
                }
            }
        } catch { Log ("elegir: " + $_.Exception.Message); $script:eleccion = $null }
    }

    # DOBLE TOQUE en ≡ (dos pulsaciones cortas en menos de 450 ms): abre o cierra
    # el panel rapido. Un toque corto no hacia nada hasta ahora, y mantenerlo
    # (dictar) sigue igual: soltar despues del hold no cuenta como toque.
    if (-not $startNow -and $startPrev -and -not $holdFired) {
        # se solto ANTES de que disparase el dictado: lo unico que dice si holdMs esta alto
        if ($downSince -gt 0) { try { [void](Add-ToqueCorto ($sw.ElapsedMilliseconds - $downSince)) } catch {} }
        if ($script:toqueEn -gt 0 -and ($sw.ElapsedMilliseconds - $script:toqueEn) -le 450) {
            $script:toqueEn = 0
            try {
                if ($script:panel) { Close-PanelRapido }
                elseif (-not $script:armed -and -not $script:pendiente -and -not $script:busy) { Open-PanelRapido }
            } catch { Log ("panel rapido: " + $_.Exception.Message) }
        } else {
            $script:toqueEn = $sw.ElapsedMilliseconds
        }
    }
    # TOQUE SUELTO (idea 36 de las 121): si paso un toque y ya no hay boton apretado y han
    # cruzado los 450 ms sin segundo toque, no era un doble toque -> vistazo. El '-not $startNow'
    # es obligatorio: sin el, un toque seguido de mantener para dictar abriria el vistazo a los
    # 450 ms con el boton todavia apretado. El '-gt 450' es complementario del '-le 450' del
    # panel: en el borde manda el panel. El $script:toqueEn = 0 se repite aqui (cinturon y
    # tirantes): aunque una guarda de Show-Vistazo devuelva $false, el toque queda consumido.
    if ($script:toqueEn -gt 0 -and -not $startNow -and ($sw.ElapsedMilliseconds - $script:toqueEn) -gt 450) {
        try { [void](Show-Vistazo) } catch { Log ("vistazo: " + $_.Exception.Message) }
        $script:toqueEn = 0
    }
    if ($startNow -and -not $startPrev) {
        $downSince = $sw.ElapsedMilliseconds
        $holdFired = $false
        # ¿MOVIO ALGO EL ZUMBIDO? (27/09, idea 77). Tocar el gatillo tras vibrar es la
        # reaccion mas clara que hay; la llamada por el nombre y el panel se apuntan en sus
        # propios sitios. Si no pasa nada en la ventana, lo recoge el bloque de abajo.
        if ($script:vibroVence -gt 0) { [void](Set-VibradoReaccion $true) }
    }
    # y la ventana que se pasa sin que nada se mueva: ese zumbido no sirvio de nada
    if ($script:vibroVence -gt 0 -and $sw.ElapsedMilliseconds -gt $script:vibroVence) { [void](Set-VibradoReaccion $false) }
    # si ≡ se uso como ≡+A / ≡+B para contestar, mantenerlo no dicta (revision 13/09)
    if ($startNow -and -not $holdFired -and ($sw.ElapsedMilliseconds - $downSince) -ge $HOLD_MS -and
        ($sw.ElapsedMilliseconds - $script:mandoRespondioEn) -gt 1500) {
        $holdFired = $true
        try {
            if ($script:pendiente -and -not $script:busy) {
                # HAY UNA PREGUNTA ESPERANDO. Contestar "si" en voz alta con un
                # juego sonando es lo que menos funciona, y el mando ya lo tienes
                # en la mano: mantener el boton vale por un si.
                # ...SALVO que sea peligrosa ("cierra todos los programas"):
                # ahi el mismo gesto que cancela cuando estoy ocupada no puede
                # valer por un si. Un boton mantenido "para cortar" cerraba todo.
                if ($script:pendiente.tipo -eq 'peligrosa') {
                    Log "CANCELAR con el boton (la pregunta era peligrosa: solo vale un si hablado)"
                    Start-Vibracion @(70, 60, 70) 16000
                    Complete-Confirmacion 'no'
                } else {
                    Log "CONFIRMAR con el boton"
                    Start-Vibracion @(70) 14000      # un toque corto: "recibido"
                    Complete-Confirmacion 'si'
                }
            } elseif ($script:busy) {
                # Un hold mientras opencode trabaja = cancelar. Antes esta
                # pulsacion se perdia: el bucle estaba bloqueado esperando.
                Log "CANCELAR (hold durante procesamiento)"
                if (-not $UiNuevaOn) { Play-Sonido 'no-pude' ([System.Media.SystemSounds]::Hand) }
                Stop-OpencodeJob
                Add-Estadistica 'error' 'cancelado'
                Send-UIEvento 'gesto:sobresalto'
                Show-Popup "Orden cancelada." 'error'
            } elseif ($script:dictandoLargo) {
                # SALIDA POR EL BOTON. Un modo que escribe en la ventana de
                # delante tiene que poder cerrarse sin hablar: si el microfono
                # no te oye, decir "ya esta" no vale de nada.
                Log "DICTADO LARGO: cerrado con el boton"
                Start-Vibracion @(70, 60, 70) 16000
                Remove-Item -LiteralPath $MarcaDictar -Force -ErrorAction SilentlyContinue
                $script:armed = $false
                $capture.Hide()
                Stop-DictadoLargo 'el boton'
            } elseif (-not $script:armed) {
                Start-Dictado "mantener ≡"
            } elseif ($script:ordenPorWorker -and $script:wakeProc) {
                # con Vosk el boton solo dice "ya termine": el worker entrega
                # lo que lleve transcrito y el bucle lo recoge
                Log "ENVIAR (boton)"
                Remove-Item -LiteralPath $MarcaDictar -Force -ErrorAction SilentlyContinue
            } else {
                Finish-Dictation "boton"
            }
        } catch {
            Log "accion error: $($_.Exception.Message)"
            $script:armed = $false
        }
    }

    # --- EL AVISO QUE NO MOVIO NADA (25/09, idea 24) ---
    # Si la ventana vence sin que braya haya hablado, ese aviso no sirvio. Se apunta y de ahi
    # sale la espera aprendida. NO se calla el aviso: se espacia (ver Get-EsperaAviso).
    # AL REVES PARA PODER QUITAR MIENTRAS SE RECORRE (idea 91): de atras adelante, que quitar por
    # delante mueve los indices de lo que queda por mirar.
    if ($script:avisosMirar.Count -gt 0) {
        for ($iM = $script:avisosMirar.Count - 1; $iM -ge 0; $iM--) {
            if ($sw.ElapsedMilliseconds -ge $script:avisosMirar[$iM].hasta) {
                Add-Estadistica ("aviso-nada:" + [string]$script:avisosMirar[$iM].clave)
                $script:avisosMirar.RemoveAt($iM)
            }
        }
    }

    # --- VIGILANCIA DEL OIDO DE WINDOWS ---
    # Si muere, el asistente sigue tan campante con Whisper, asi que el fallo
    # es invisible: el usuario solo notaria que "ya no acierta como antes".
    if ($VozWindowsOn -and ($sw.ElapsedMilliseconds - $script:vozWinCheck) -ge 30000) {
        $script:vozWinCheck = $sw.ElapsedMilliseconds
        if ($script:vozWinProc -and $script:vozWinProc.HasExited) {
            if ($script:vozWinIntentos -lt 2) {
                $script:vozWinIntentos++
                Log "WARN: el oido de Windows murio; relanzando (intento $($script:vozWinIntentos)/2)"
                try { $script:vozWinProc.Dispose() } catch {}
                $script:vozWinProc = $null
                try {
                    $wv = Join-Path $LogDir "voz_windows.py"
                    # y el relanzado tambien, que si no quedaba huerfano igual que el primero
                    $env:NOVA_PID_PADRE = "$PID"
                    $script:vozWinProc = Start-Process -FilePath $PyWorker `
                        -ArgumentList @('-u', $wv, $MarcaDictar, $RutaDictadoWin, $EventLog, 'es-ES') `
                        -WorkingDirectory $LogDir -WindowStyle Hidden -PassThru
                    $null = $script:vozWinProc.Handle
                    try { $script:vozWinProc.PriorityClass = [System.Diagnostics.ProcessPriorityClass]::BelowNormal } catch {}
                } catch { Log ("no se pudo relanzar: " + $_.Exception.Message) }
            } elseif ($script:vozWinIntentos -eq 2) {
                $script:vozWinIntentos++   # avisar una sola vez, y sin voz: no es grave
                Log "ERROR: el oido de Windows no se sostiene; se sigue con Whisper"
            }
        }
    }

    # --- LO QUE PASA SIN QUE DIGAS NADA (fase 2) ---
    # LA GUIA, SI YA LLEGO (23/09, idea 6; movida aqui el 24/09 en el repaso): un HasExited y
    # cero red, asi que va en el bucle de verdad y no dentro de Watch-Entorno, que solo mira
    # cada 30 s y ademas se apaga entero si entorno.avisos esta en false -el valor por defecto
    # del codigo-. Ahi dentro, braya preguntaba "de que va este juego" y Nova contestaba entre
    # 0 y 30 s despues, quince de media, o no contestaba nunca. Y el plazo de 4-15 s no podia
    # dispararse a tiempo mirandose cada medio minuto.
    try { Receive-Guia } catch { Log ("guia: " + $_.Exception.Message) }
    try { Watch-Entorno $botones } catch { Log ("entorno: " + $_.Exception.Message) }

    # --- VIGILANCIA DEL WORKER DE ESCUCHA ---
    # Si muere, la palabra de activacion deja de funcionar EN SILENCIO durante
    # el resto de la sesion: el bucle solo miraba el archivo marca, que nunca
    # volveria a aparecer. Se comprueba cada 30 s y se relanza.
    if ($EscuchaOn -and ($sw.ElapsedMilliseconds - $script:wakeCheck) -ge 30000) {
        $script:wakeCheck = $sw.ElapsedMilliseconds
        if ($script:wakeProc -and $script:wakeProc.HasExited) {
            if ($script:wakeIntentos -lt 3) {
                $script:wakeIntentos++
                # LA AUTOPSIA DEL OIDO ANTES DE RELANZARLO (27/09, idea 110 de las 121)
                #
                # EL DATO: 28 relanzamientos del worker en el registro -25 al primer intento, 2 al
                # segundo y 1 al tercero- y NI UNA autopsia: la linea decia "murio; relanzando" y
                # nada mas. Mientras, la capsula SI lo hace bien desde siempre: su relanzamiento
                # imprime el codigo de salida y la ultima linea de ui-error.log, y en el registro
                # hay tres lineas suyas con "( codigo -1)".
                #
                # Y LA CAUSA SE SABE EN LA MITAD DE LOS CASOS: seis de esas muertes son SUICIDIOS
                # con causa apuntada -"el microfono lleva N s sin entregar audio; salgo para que me
                # relancen", que es un sys.exit(3)-, asi que el codigo 3 dice "el microfono se paro"
                # sin tener que adivinar nada. Y las tres autopsias que existen en todo el registro
                # (las tres del 15/09) apuntan al mismo sitio: "Windows fatal exception: access
                # violation", comtypes/_post_coinit/unknwn.py line 420 in Release y "ValueError: COM
                # method call without VTable", que es el medidor de altavoces.
                #
                # SE DICE, NO SE DECIDE, y eso es a proposito: relanzar distinto segun la causa -sin
                # el medidor de altavoces, reenumerando dispositivos- es un cambio de comportamiento
                # que con TRES autopsias en 17 dias no se puede justificar. Primero se mide; el dia
                # que haya autopsias suficientes, la decision tendra con que tomarse. Hoy lo que
                # faltaba era saber POR QUE se muere.
                # NO SUSTITUYE AL VUELCO ENTERO que ya hace Initialize-Escucha al relanzar: ese
                # pasa los ultimos 2.000 caracteres del stderr al registro, y sigue ahi. Lo que
                # faltaba era tener la CAUSA en la misma linea del "murio", como la capsula.
                $porQueW = ''
                try { $porQueW = " codigo $($script:wakeProc.ExitCode)" } catch {}
                # EL CODIGO 3 ES SUYO Y LO DICE EL PROPIO WORKER: sys.exit(3) cuando el microfono
                # lleva demasiado sin entregar audio. No hay que adivinarlo.
                try { if ([int]$script:wakeProc.ExitCode -eq 3) { $porQueW += ' (el microfono se paro y salio el solo)' } } catch {}
                try {
                    $rutaErrW = Join-Path $TmpDir 'wake-err.log'
                    if ((Test-Path -LiteralPath $rutaErrW) -and ((Get-Item -LiteralPath $rutaErrW).LastWriteTime -gt (Get-Date).AddMinutes(-2))) {
                        # LA ULTIMA LINEA CON ALGO, no la ultima a secas: el fichero suele acabar en
                        # blanco y entonces la autopsia decia "su ultimo error: " y nada mas.
                        $lineasW = @(Get-Content -LiteralPath $rutaErrW -Tail 12 -ErrorAction SilentlyContinue |
                                     Where-Object { $_ -and $_.Trim().Length -gt 0 })
                        if ($lineasW.Count -gt 0) {
                            $ultW = [string]$lineasW[$lineasW.Count - 1]
                            $porQueW += "; su ultimo error: " + $ultW.Substring(0, [Math]::Min(400, $ultW.Length))
                            # Y SI HUELE A COM, SE NOMBRA: las tres autopsias que hay apuntan todas al
                            # medidor de altavoces. Nombrarlo es lo que permitira decidir algun dia.
                            if ($ultW -match '(?i)comtypes|VTable|access violation|CoInitialize') {
                                $porQueW += ' [huele al medidor de altavoces]'
                            }
                        }
                    }
                } catch {}
                Log "WARN: el worker de escucha murio ($porQueW); relanzando (intento $($script:wakeIntentos)/3)"
                Add-Estadistica 'relanza:oido'   # idea 50: pegado al Log y ANTES del Dispose/Initialize-Escucha, que pueden tirar
                # liberar el handle antes de soltar la referencia: este proceso
                # vive meses y cada relanzo filtraria uno
                try { $script:wakeProc.Dispose() } catch {}
                $script:wakeProc = $null
                Initialize-Escucha
            } elseif ($script:wakeIntentos -eq 3) {
                $script:wakeIntentos++   # avisar una sola vez
                Log "ERROR: el worker de escucha no se sostiene; se sigue solo con el boton"
                try { $script:wakeProc.Dispose() } catch {}
                $script:wakeProc = $null   # el boton dicta con Windows, no espera a un worker muerto
                Show-Popup "La palabra de activacion fallo. Sigue funcionando el boton." 'error'
                Say "La escucha por voz fallo. Puedes seguir usando el boton."
            }
        } elseif ($script:wakeProc -and ($sw.ElapsedMilliseconds - $script:wakeDesde) -gt 300000) {
            # 5 min vivo, no 30 s: un worker que muere cada 40 s reiniciaba el
            # contador sin parar y nunca se daba por perdido (auditoria del 13/09)
            $script:wakeIntentos = 0   # lleva vivo un rato: se rearman los reintentos
        }
    }

    # --- INTERRUMPIR A NOVA (M5): "espera", "para", "calla"... dicho mientras habla ---
    $rutaCorte = Join-Path $TmpDir 'corte.flag'
    if (Test-Path -LiteralPath $rutaCorte) {
        # LA LECTURA QUE PODIA CALLARLA (27/09, idea 80). Esto era un ReadAllText crudo dentro de un
        # catch vacio, y ese fichero lo escribe el worker con la misma funcion escribir() que ya ha
        # fallado 36 veces con "Acceso denegado". Si la lectura fallaba, $palabraCorte quedaba VACIA:
        # con sordina puesta, decir "nova" para volver -que es justo para lo que existe- dejaba de
        # parecerse al nombre y Resolve-Corte devolvia 'tarde'; en pausa, 'corta-y-calla'. O sea que
        # un fallo de lectura se convertia en callar a Nova, en silencio.
        #
        # DOS ARREGLOS: se lee con FileShare::Delete, que es la unica forma de leer mientras el worker
        # hace su os.replace -el patron ya estaba en casa, en la lectura del parcial-, y si aun asi
        # falla NO se decide nada: una palabra que no se pudo leer no es una palabra vacia.
        $palabraCorte = ''
        $corteLeido = $false
        $fsC = $null; $srC = $null
        try {
            $fsC = New-Object System.IO.FileStream($rutaCorte, [System.IO.FileMode]::Open,
                    [System.IO.FileAccess]::Read,
                    ([System.IO.FileShare]::ReadWrite -bor [System.IO.FileShare]::Delete))
            $srC = New-Object System.IO.StreamReader($fsC, [System.Text.Encoding]::UTF8)
            $palabraCorte = ($srC.ReadToEnd()).Trim()
            $corteLeido = $true
        } catch {
            # y se DICE, que antes se tragaba: es la unica forma de saber si esto pasa de verdad
            Log ('corte: no pude leer lo que dijiste (' + $_.Exception.Message + '); no decido nada')
            Add-Estadistica 'corte-ilegible'
        } finally {
            if ($srC) { $srC.Dispose() }
            if ($fsC) { $fsC.Dispose() }
        }
        Remove-Item -LiteralPath $rutaCorte -Force -ErrorAction SilentlyContinue
        # ME HAS LLAMADO ESTANDO CALLADA: vuelvo entera (22/09, ver SALIR DE LA SORDINA en
        # wake_vosk.py). Va DELANTE del corte de toda la vida porque en sordina el worker
        # solo escucha el nombre, y "interrumpir a Nova" no tiene sentido si no esta
        # hablando. Se deshace por el mismo camino que 'despertarEscucha' dicho a mano: la
        # hora a cero, el aviso de vuelta retirado y la escucha reanudada. De una pieza, que
        # es justo lo que fallo el 21/09.
        # LA DECISION, ANTES DE NADA (24/09, idea 2). Aqui habia dos ramas para tres
        # situaciones: con un dictado abierto no entraba ninguna y el corte se perdia en
        # silencio. Cuatro de las cinco perdidas de quince dias son ese caso.
        # sin haber podido leer, no se decide nada: ver LA LECTURA QUE PODIA CALLARLA
        $dCorte = if (-not $corteLeido) {
                      @{ accion = 'tarde'; abreMicro = $false; estadistica = 'corte-ilegible' }
                  } else {
                      Resolve-Corte $palabraCorte $EscuchaNombre $script:armed `
                                    ($sw.ElapsedMilliseconds -lt $script:pausaHasta) `
                                    ($script:sordinaHasta -gt $sw.ElapsedMilliseconds)
                  }
        if ($dCorte.accion -eq 'cancela-dictado') {
            # LO QUE FALTABA. El 20/09 a las 12:54 y a las 13:34 hubo dos dictados colgados
            # de 48 segundos con "para", "nova" y "basta" dichos dentro, y no pasaba nada.
            # Un modo abierto 48 s con dos ordenes de parar dentro es un modo sin salida.
            Log "CORTE: '$palabraCorte' con un dictado abierto; lo cancelo"
            $script:armed = $false
            $script:seguimientoPendiente = $false
            Remove-Item -LiteralPath $MarcaDictar -Force -ErrorAction SilentlyContinue
            Send-UIEvento 'gesto:paciencia'
            Set-UI 'reposo'
            Add-Estadistica 'corte-dictado' $palabraCorte
        } elseif ($dCorte.accion -eq 'tarde') {
            # Y LA QUINTA: llego cuando ya no hablaba. Es correcto no hacer nada, pero hasta
            # hoy tampoco dejaba rastro, y por eso el agujero tardo quince dias en verse.
            Log "CORTE: '$palabraCorte' llego cuando ya no hablaba; no hago nada"
            Add-Estadistica 'corte-tarde' $palabraCorte
        } elseif ($dCorte.accion -eq 'sordina-vuelve') {
            Log "SORDINA: me has llamado por mi nombre, vuelvo entera"
            $script:sordinaHasta = 0
            for ($i = $script:temporizadores.Count - 1; $i -ge 0; $i--) {
                if ($script:temporizadores[$i].tipo -eq 'sordina') { $script:temporizadores.RemoveAt($i) }
            }
            $script:pausaHasta = 0
            Reanudar-Escucha -Forzar
            Add-Estadistica 'sordina-nombre' ''
            Say 'Aqui estoy.'
        } else {
            $esNombreC = $dCorte.abreMicro
            Log ("INTERRUMPIDA: '$palabraCorte' mientras hablaba -> " + $(if ($esNombreC) { 'me callo y te escucho' } else { 'me callo, y no abro el microfono' }))
            try { if ($script:reproductor) { $script:reproductor.Stop() } } catch {}
            try { if ($script:vozPlayer) { $script:vozPlayer.Stop() } } catch {}
            try { Stop-Charla } catch {}
            $script:vozFinReal = 0
            Send-UIEvento 'gesto:paciencia'
            # DECIR TU NOMBRE Y MANDARLA CALLAR NO SON LO MISMO (22/09 por la noche).
            # Por esta rama entran las dos cosas: el nombre -que significa "voy a hablar",
            # asi que reabrir el microfono es lo correcto- y las seis palabras de parada
            # ("para", "calla", "basta"...), que significan justo lo contrario. Las tres
            # lineas de abajo estaban puestas para el primer caso y se aplicaban a los seis.
            # LO QUE PASO DE VERDAD, y es el unico caso del log de una frase que no era para
            # Nova colandose entera: el 21/09 a las 00:07:53 braya dijo "para" (confianza
            # 0,96), Nova paro, reabrio el microfono, y diez segundos despues cogio
            # "¿Botoncito atras y el boton abajo?" -braya explicandole los mandos a quien
            # juega con el-. Eso fue a Parakeet, a Whisper, a Gemini y a la API de Claude, y
            # VEINTIUN SEGUNDOS despues de mandarla callar volvio a hablar: "No te entiendo
            # bien, ¿que quieres hacer?". En total, 78 segundos de microfono abierto despues
            # de siete ordenes de callarse.
            # pausaHasta se queda FUERA a proposito, en los dos caminos: es lo que hace
            # vencer la pausa y dispara Reanudar-Escucha. Metido aqui dentro, al decirle
            # "callate" se quedaria sorda hasta que venciera la frase que acabas de cortar.
            # Callarse si; quedarse sorda no.
            # Y al callarse no dice nada: el gesto de la capsula ya lo cuenta sin hablar.
            # QUIEN DECIDE ES Resolve-Corte, no un segundo -eq repetido aqui (24/09): dos
            # sitios que comparan lo mismo acaban separandose, y este es el bloque donde ya
            # paso una vez.
            if ($dCorte.abreMicro) {
                # tu nombre: te escucha, sin que tengas que repetirlo
                $script:seguimientoPendiente = $true
                $script:seguimientoFactor = 1.0
                $script:ventanaCharla = (($sw.ElapsedMilliseconds - $script:charlaUltima) -lt 60000)
            } else {
                # una palabra de parada: se calla y NO abre nada
                $script:seguimientoPendiente = $false
                $script:ventanaCharla = $false
                Add-Estadistica 'corte-callar' $palabraCorte
            }
            $script:pausaHasta = $sw.ElapsedMilliseconds + 150
        }
    }

    # --- CONVERSACION: lo que contesta el worker, frase a frase (ver CONVERSACION DE VERDAD) ---
    # tambien solo con la voz preparada viva: Receive-Charla es quien la cierra
    if ($script:charlaProc -or $script:prepVozProc) { try { Receive-Charla } catch { Log ("charla: " + $_.Exception.Message) } }
    # --- SUBTITULOS: lo que va oyendo del juego (1/10, la 17 de las 20) ---
    # Solo si estan puestos: con $script:subProc a $null esto no entra ni a la funcion, asi que el
    # 99,9 % del tiempo cuesta una comparacion. Y los tres plazos que la apagan viven DENTRO de
    # Receive-Subtitulos a proposito, para que no haya forma de que se queden puestos si alguien
    # olvida una guarda aqui (regla 2).
    if ($script:subProc) { try { Receive-Subtitulos } catch { Log ("subtitulos: " + $_.Exception.Message) } }
    # EL MP3 ABIERTO ANTES DE HABLAR: mientras suena una frase de la charla, la voz
    # preparada ya le esta haciendo el mp3 a la siguiente. Abrirlo AHORA le quita los
    # 433 ms de Open al decirla (ver Open-VozAdelantada). Con la cola vacia no hace nada.
    if ($script:charlaFrases.Count -gt 0) { Open-VozAdelantada }
    # EN FRIO el modelo tarda en cargar (~12-16 s medido): pasados 5 s sin nada,
    # una palabra corta para que no parezca colgada. Una vez por respuesta.
    if ($script:charlaEsperando -and -not $script:charlaRelleno -and $script:charlaFrases.Count -eq 0 -and -not $script:armed -and
        ($sw.ElapsedMilliseconds - $script:charlaDesde) -gt $script:charlaUmbralMuletilla -and $sw.ElapsedMilliseconds -ge $script:pausaHasta) {
        $script:charlaRelleno = $true
        Log "charla: tarda mas de $($script:charlaUmbralMuletilla) ms, digo algo mientras"
        # variadas y NUNCA la misma dos veces seguidas (14/09): con tres, se repetian
        $rellenosC = @('Deja que lo piense.', 'A ver...', 'Un segundito.', 'Mmm, buena pregunta.', 'Dame un momento.',
                       'Espera, que lo pienso.', 'Vale, a ver.', 'Uy, eso tiene miga.')
        $rellenoC = Get-Random -InputObject @($rellenosC | Where-Object { $_ -ne $script:ultimoRelleno })
        $script:ultimoRelleno = $rellenoC
        Say $rellenoC
    }
    # LA ESPERA SE VE (D3): si la charla tarda mas de 2 s, la linea de la capsula se
    # va llenando (en frio son 12-16 s); al llegar la primera frase, se vacia
    $esperaC = ($script:charlaEsperando -and $script:charlaFrases.Count -eq 0 -and ($sw.ElapsedMilliseconds - $script:charlaDesde) -gt $script:charlaUmbralBarra)
    if ($esperaC) {
        # la escala, la de lo que va a tardar DE VERDAD (14/09): con el modelo caliente
        # o recien precargado contesta en 2-3 s, y la linea de 16 s apenas se movia
        $escalaE = if ((Test-CharlaCaliente) -or ($sw.ElapsedMilliseconds - $script:precargaEn) -lt 110000) { [double]$script:charlaEscalaCaliente } else { [double]$script:charlaEscalaFria }
        $frE = [Math]::Min(0.9, ($sw.ElapsedMilliseconds - $script:charlaDesde) / $escalaE)
        if (-not $script:progresoCharla -or ($frE - $script:uiProgreso) -ge 0.04) { $script:progresoCharla = $true; $script:uiProgreso = $frE; Refresh-UI }
    } elseif ($script:progresoCharla) {
        $script:progresoCharla = $false
        $script:uiProgreso = 0
        Refresh-UI
    }
    if ($script:charlaFrases.Count -gt 0 -and -not $script:armed) {
        # la siguiente frase entra cuando acaba la que suena (su duracion real)
        $finFrase = if ($script:vozFinReal -gt 0) { $script:vozFinReal } else { $script:pausaHasta }
        if ($sw.ElapsedMilliseconds -ge ($finFrase - 150)) {
            $frC = $script:charlaFrases.Dequeue()
            $fraseC = [string]$frC.t
            $script:uiOrigen = [string]$frC.o
            Log "charla dice: $fraseC"
            $script:ultimaRespuesta = $fraseC
            Add-Turno $script:charlaTexto $fraseC
            # IDEA 55: si Nova admite que se equivoco, ella misma lo apunta como sospecha de fallo
            # (senal 'me-disculpe', peso medio). La escribe Nova, no braya, asi que no se confunde con
            # una charla que empieza por "no". Patron del verificador sobre el texto SIN tildes; deja
            # fuera las disculpas por limitacion ("lo siento, no tengo informacion sobre..."), que no
            # llevan ninguno de estos verbos. Write-FalloDeducido no consume el id: un "no era eso"
            # posterior sigue pudiendo apuntar la queja humana.
            if ((ConvertTo-Plain $fraseC) -match 'tienes (toda la )?razon|me equivoque|me confundi|mi mal|mi error|meti la pata|no deberia haber') {
                try { [void](Write-FalloDeducido 'me-disculpe' $script:charlaTexto) } catch {}
            }
            Say $fraseC (Get-EmocionFrase $fraseC)
        }
    }

    # reanuda la escucha cuando vence la pausa (fin estimado de la voz)
    if ($script:pausaHasta -gt 0 -and $sw.ElapsedMilliseconds -ge $script:pausaHasta -and -not $script:armed -and $script:charlaFrases.Count -eq 0) {
        Reanudar-Escucha
        # SEGUIMIENTO: acabo de responder a una orden; vuelvo a escuchar un
        # rato sin palabra de activacion por si encadenas otra
        if ($script:aprenderPendiente -and -not $script:busy -and -not $script:pendiente) {
            # antes del seguimiento, la pregunta de aprendizaje ("¿quieres que
            # 'calcu' sea siempre 'calculadora'?"); el seguimiento se pierde,
            # es una pregunta y espera si/no
            $ap = $script:aprenderPendiente
            $script:aprenderPendiente = $null
            $script:pendiente = @{ texto = ''; vence = 0; tipo = 'aprender'; alias = $ap.alias; objetivo = $ap.objetivo }
            Log "APRENDER: pregunto por '$($ap.alias)' -> '$($ap.objetivo)'"
            Say $ap.pregunta
            Set-UI 'escuchando' $ap.pregunta
            Start-Confirmacion
        } elseif ($script:resumenPendiente -and -not $script:busy -and -not $script:pendiente) {
            # HAS VUELTO (ver RESUMEN AL VOLVER): una linea, sin voz.
            # Desde el 16/09 tambien lo prepara Watch-Entorno, asi que sale aunque no
            # le hayas dicho nada; antes habia que hablarle para enterarte.
            $txtRes = $script:resumenPendiente
            $script:resumenPendiente = ''
            # dicho: fuera tambien del disco, o volveria a salir en cada arranque (idea 8)
            try {
                $hbR = Get-Habitos
                if ($hbR.parteTexto) { $hbR.parteTexto = ''; Save-Habitos }
            } catch {}
            Send-UIEvento 'gesto:saludo'
            Set-UI 'hablando' $txtRes 4500
        } elseif ($script:invitadoPropuesta -and -not $script:busy -and -not $script:pendiente -and -not $script:invitado) {
            # VOZ AJENA VARIAS VECES (M7): se pregunta, nunca se pone solo
            $script:invitadoPropuesta = $false
            $script:invitadoPropuestoEn = $sw.ElapsedMilliseconds
            [void](Set-Reloj 'invitado-propuesto')
            $script:vozAjenaVeces = @()
            $script:pendiente = @{ texto = ''; vence = 0; tipo = 'invitadoAuto' }
            $pregI = 'No reconozco esta voz. ¿Pongo el modo invitado?'
            Log "MODO INVITADO: lo propongo (voz ajena varias veces)"
            Say $pregI
            Set-UI 'escuchando' $pregI
            Start-Confirmacion
        } elseif ($script:nivelPendiente -gt 0 -and -not $script:busy -and -not $script:pendiente) {
            # SUBIO DE NIVEL (ver NOVA EVOLUCIONA): un destello y la palabra, sin voz
            $nvP = $script:nivelPendiente
            $script:nivelPendiente = 0
            Send-UIEvento 'gesto:nivel'
            Set-UI 'hablando' "Nivel $nvP" 2500
        } elseif (-not $script:juegoActivo -and -not $script:busy -and -not $script:pendiente -and
                  ($propH =$(try { Find-Propuesta } catch { $null }))) {
            # UNA COSTUMBRE QUE AUTOMATIZAR (ver HABITOS): justo despues de hacer
            # una orden, que es cuando estas pendiente; nunca jugando. Se apunta
            # el dia al preguntar, conteste lo que conteste: una al dia.
            $hbP = Get-Habitos
            $hbP.ultimaPropuesta = (Get-Date).ToString('yyyy-MM-dd')
            Save-Habitos
            $script:pendiente = @{ texto = ''; vence = 0; tipo = 'propuesta'; propuesta = $propH }
            Log "PROPUESTA: $($propH.clave)"
            Say $propH.pregunta
            Set-UI 'escuchando' $propH.pregunta
            Start-Confirmacion
        } elseif ($script:seguimientoPendiente -and $SeguimientoMs -gt 0 -and $script:seguimientoFactor -gt 0 -and $DictadoWorker -and $script:wakeProc -and
            -not $script:wakeProc.HasExited -and -not $script:busy -and -not $script:pendiente -and $script:reintentoVence -le 0 -and
            (Test-AbrirSeguimiento)) {
            Start-Dictado 'seguimiento'
        }
        $script:seguimientoPendiente = $false
    }

    # --- PARAR LIMPIO (18/09): la marca de tools\parar-nova.ps1 ---
    if (Test-Path -LiteralPath $MarcaSalir) {
        Remove-Item -LiteralPath $MarcaSalir -Force -ErrorAction SilentlyContinue
        Log "SALIDA pedida por marca: me cierro limpiamente"
        try { Set-UI 'reposo' } catch {}
        # Y LOS WORKERS, CERRADOS (18/09): el de escucha mira al padre solo en su pulso, cada
        # 15 s, y se quedaba vivo hasta que alguien lo mataba desde fuera. La charla por su
        # camino; escucha y voz por Kill, que es lo que les iba a pasar 15 s despues.
        try { Stop-Charla } catch {}
        # piperProc entra aqui desde el 21/09: antes no hacia falta porque no arrancaba
        # nunca; ahora que el respaldo lo levanta de verdad, al parar limpio quedaba vivo.
        # guiaProc entra aqui desde el 24/09 (repaso): si Nova se cerraba con una guia en
        # vuelo quedaba un powershell.exe huerfano y su .json en tmp sin borrar.
        try { Stop-Guia } catch {}
        # vozWinProc entra aqui desde el 24/09: era el UNICO residente al que no mataba
        # nadie, ni aqui ni en el barrido del arranque. Por ahi salian los 44.
        # LA LISTA, CONSTRUIDA SOLA (25/09, idea 20): antes iban los cinco escritos a mano y
        # esa lista crecio tres veces en cuatro dias, siempre tarde. Ver Get-ProcesosResidentes.
        foreach ($pW in @(Get-ProcesosResidentes)) {
            try { if ($pW -and -not $pW.HasExited) { $pW.Kill() } } catch {}
        }
        exit 0    # por aqui SI se dispara PowerShell.Exiting y se escribe "cerrado"
    }

    # --- CONFIRMACION PENDIENTE (si / no / plazo) ---
    if ($script:pendiente) {
        # QUE SE VEA QUE ESPERA UN SI O UN NO. Mientras la pregunta suena manda
        # 'hablando'; en cuanto termina, la capsula pasa a 'confirmando' y dibuja
        # el plazo vaciandose. Sin esto se queda igual que en reposo y nadie sabe
        # que le estan preguntando algo, que es justo como el silencio acababa
        # cancelando ordenes buenas.
        # UNA VEZ POR PREGUNTA, TAMBIEN CON LA CAPSULA APAGADA (28/09, tras la revision). Set-UI
        # empieza con 'if (-not $UiNuevaOn) { return }', asi que con la capsula apagada NUNCA toca
        # $script:uiEstado ni $script:uiHasta: las tres condiciones de aqui abajo se cumplen SIEMPRE y
        # el bloque entero se repetia en cada vuelta mientras hubiera pregunta. Cuatro danos, y el
        # primero es de los gordos: (1) el 'vence' se reescribia cada 30 ms, asi que
        # Complete-Confirmacion 'plazo' era INALCANZABLE y la pregunta se quedaba puesta hasta que
        # braya contestara -la regla 2, ningun modo se queda puesto-; (2) el zumbido se relanzaba en
        # cuanto se vaciaba la cola de vibracion, unas tres veces por segundo y sin fin, porque la
        # guarda $p.zumbo se rearma DENTRO de este mismo bloque tres lineas mas abajo y no guardaba
        # nada; (3) 'nace' se reescribia igual, asi que Add-ZumbidoTiempo apuntaba ~30 ms en vez de
        # lo que tardo braya, y el numero adaptativo que decide si el zumbido sirve se alimentaba de
        # datos falsos; (4) Get-ZumbidoTiempos leia memoria\zumbido-tiempos.json del disco una vez
        # por vuelta, que es la regla 4. Medido ejecutando el bloque real con la capsula apagada: 424
        # vueltas en 20 s, 61 zumbidos, el vence empujado 26 s y 424 lecturas del fichero.
        # $UiNuevaOn es false en tres casos reales: ui.nueva = false en config, falta nova_ui.exe sin
        # compilar, y despues de tres relanzos fallidos de la capsula, que lo pone el propio bucle.
        # LA MARCA VA EN $script:pendiente, que nace de cero en cada pregunta (son todas @{}), asi
        # que no hay que acordarse de limpiarla en ningun sitio.
        if (-not $script:pendiente.arrancada -and $script:uiEstado -ne 'confirmando' -and -not $script:busy -and $script:uiHasta -le $sw.ElapsedMilliseconds) {
            $script:pendiente.arrancada = $true
            # EL PLAZO EMPIEZA AQUI, cuando de verdad termina de hablar (18/09). Hasta hoy
            # empezaba al hacer la pregunta, con una ESTIMACION de lo que iba a durar la voz:
            # si la frase real tardaba mas, el plazo se comia hablando. Caso de las 18:47:
            # pregunta a las :18, micro libre a las :26, cancelada por plazo a las :29. Tres
            # segundos reales para contestar. El worker ya esperaba a que acabara la pausa;
            # el que contaba mal era este lado.
            $script:pendiente.vence = $sw.ElapsedMilliseconds + (Get-PlazoConfirmacion)
            $queda = [Math]::Max(0, $script:pendiente.vence - $sw.ElapsedMilliseconds)
            $script:confirmaFin = [DateTimeOffset]::Now.ToUnixTimeMilliseconds() + $queda
            $script:confirmaTotal = [Math]::Max(1, $queda)
            # Y AQUI SE DICE QUE EL MANDO VALE (23/09, funcion 10). En catorce dias se uso
            # cero veces para contestar, teniendolo en las manos: nadie se lo habia dicho.
            # ZUMBIDO AL NACER LA PREGUNTA (26/09, idea 42): la segunda via del mando. Puerta = HAY
            # MANDO (no juego). Dos guardas obligatorias porque con la capsula apagada este bloque
            # se repite cada vuelta: la marca $p.zumbo y la cola de vibracion libre. Se mide en Complete-Confirmacion.
            $script:pendiente.nace = $sw.ElapsedMilliseconds
            $script:pendiente.zumbo = $false
            $ztP = Get-ZumbidoTiempos
            if ($script:mandoHay -and $script:pendiente.tipo -ne 'peligrosa' -and $script:vibraCola.Count -eq 0 -and $script:vibraHasta -le 0 -and (Test-ZumbidoSirve $ztP.con $ztP.sin $DecisionMinIntentos)) {
                Start-Vibracion @(70, 90, 70) 16000
                $script:pendiente.zumbo = $true
            }
        }
        # PINTAR SI QUE ES CADA VEZ QUE HAGA FALTA (28/09): arrancar la pregunta es una sola vez -el
        # plazo, el reloj de la medida y el zumbido- pero volver a poner la capsula en 'confirmando'
        # hay que hacerlo tambien si una voz de por medio la paso a 'hablando'. Con la capsula
        # apagada no se paga nada: ni Set-UI, que saldria por su primera linea, ni Get-PistaMando.
        if ($UiNuevaOn -and $script:uiEstado -ne 'confirmando' -and -not $script:busy -and $script:uiHasta -le $sw.ElapsedMilliseconds) {
            Set-UI 'confirmando' ($script:uiTexto + (Get-PistaMando ([string]$script:pendiente.tipo)))
        }
        $resp = ''
        if (Test-Path -LiteralPath $RutaConfirmacion) {
            try { $resp = ([System.IO.File]::ReadAllText($RutaConfirmacion)).Trim().ToLowerInvariant() } catch {}
            if ($resp -ne 'si' -and $resp -ne 'no') { $resp = '' }
        }
        # MIENTRAS NOVA HABLA, EL PLAZO NO CORRE (18/09, segunda vez). A las 20:15 la pregunta
        # vencio a los 7 s con la voz todavia sonando: el worker ni llego a escuchar. El plazo
        # se empuja en cada vuelta a "fin de la voz + ConfirmacionMs", asi que solo puede
        # vencer tras ese tiempo de silencio. (El rearme de arriba, al pasar a 'confirmando',
        # se queda; pero ya no es de lo que depende.)
        $finVozC = [Math]::Max([double]$script:pausaHasta, [double]$script:uiHasta)
        if ($finVozC -gt $sw.ElapsedMilliseconds) {
            $minimoC = $finVozC + (Get-PlazoConfirmacion)
            if ($script:pendiente.vence -lt $minimoC) { $script:pendiente.vence = $minimoC }
            # Y EL RELOJ DE LA MEDIDA SE EMPUJA IGUAL (idea 102): si no, se estaria midiendo lo que
            # tarda la voz de Nova mas lo que tarda braya, que es justo la cuenta que enganaba.
            if ([double]$script:pendiente.desde -lt $finVozC) { $script:pendiente.desde = $finVozC }
        }
        if ($resp) { Complete-Confirmacion $resp }
        elseif ($sw.ElapsedMilliseconds -ge $script:pendiente.vence) { Complete-Confirmacion 'plazo' }
    }

    # --- PALABRA DE ACTIVACION ---
    # El worker deja un archivo marca; aqui solo se mira si existe. Nada de
    # eventos ni hilos compartidos: eso es lo que mataba el proceso.
    if ($script:wakeProc -and (Test-Path -LiteralPath $MarcaWake)) {
        Remove-Item -LiteralPath $MarcaWake -Force -ErrorAction SilentlyContinue
        # reintentoVence: el oido fino esta repasando la orden anterior. Un
        # "nova" ahora abria otro dictado y el repaso ejecutaba despues la
        # orden VIEJA encima de la nueva.
        if ($script:armed -or $script:busy -or $script:pendiente -or $script:reintentoVence -gt 0) {
            # ya estabamos escuchando o procesando: se ignora sin ruido
        } elseif (($sw.ElapsedMilliseconds - $script:finVoz) -lt 1500) {
            # acabamos de hablar: evita despertarse con su propia voz
            Log "despertar ignorado (acabamos de hablar)"
        } else {
            # idea 77: llamarla por su nombre tras un zumbido es la segunda reaccion clara
            if ($script:vibroVence -gt 0) { [void](Set-VibradoReaccion $true) }
            Start-Dictado "nombre '$EscuchaNombre'"
        }
    }

    # --- una RESPUESTA escrita ("si"/"no") a una pregunta pendiente ---
    # Para probar sin voz lo que pasa despues de un "¿lo hago?".
    if ($script:pendiente -and -not $script:busy -and (Test-Path -LiteralPath $RutaOrdenEscrita)) {
        $escritaC = ''
        try { $escritaC = [System.IO.File]::ReadAllText($RutaOrdenEscrita, [System.Text.Encoding]::UTF8).Trim() } catch {}
        if ($escritaC -match '^(?i)(?:s[ií]|no)$') {
            Remove-Item -LiteralPath $RutaOrdenEscrita -Force -ErrorAction SilentlyContinue
            Log "RESPUESTA ESCRITA: $escritaC"
            Complete-Confirmacion $(if ($escritaC -match '^(?i)no$') { 'no' } else { 'si' })
        }
    }

    # --- una orden ESCRITA (tools\decir.ps1) ---
    # Pasa por Process-Texto igual que una dicha, pero sin audio: ni oido fino
    # (no hay nada que repasar) ni juicio de la voz (no hay tono que medir).
    if (-not $script:armed -and -not $script:busy -and -not $script:pendiente -and $script:reintentoVence -le 0 -and
        (Test-Path -LiteralPath $RutaOrdenEscrita)) {
        $escrita = ''
        try { $escrita = [System.IO.File]::ReadAllText($RutaOrdenEscrita, [System.Text.Encoding]::UTF8).Trim() } catch {}
        Remove-Item -LiteralPath $RutaOrdenEscrita -Force -ErrorAction SilentlyContinue
        if ($escrita) {
            Log "ORDEN ESCRITA: $escrita"
            $script:ordenPorWorker = $false
            $script:yaReintentado = $true
            $script:ultimaF0 = 0
            try { Process-Texto $escrita } catch { Log ("orden escrita: " + $_.Exception.Message) }
        }
    }

    # --- DICTADO POR VOSK: recoger lo transcrito y mostrarlo en vivo ---
    if ($script:armed -and $script:ordenPorWorker) {
        # LA ONDA VERDE SEGUIA MOVIENDOSE CUANDO YA NO TE OIA (22/09). Al callarte, la
        # escucha cierra el microfono y se pone a transcribir (Parakeet, el repaso de
        # ingles, Whisper), pero este lado no se enteraba hasta que aparecia dictado.txt.
        # Medido en el log: 412 veces de "cerro el micro" a "texto listo", media 3,48 s,
        # mediana 2,0 s, p90 7,0 s, maximo 37 s, y 229 de las 412 por encima de dos
        # segundos. Todo ese rato la capsula seguia en 'escuchando', con la onda animada
        # y los ojos atentos: "sigue, te escucho" a alguien que ya habia terminado. Y las
        # 54 veces en que el texto no llego nunca, la mentira duro 38,9 s de media hasta
        # la red de seguridad de aqui abajo.
        # Ahora la escucha deja transcribiendo.flag al cerrar el micro y la capsula pasa
        # a 'pensando', que es exactamente lo que esta haciendo. CERO palabras habladas:
        # esto solo se ve, no se oye, y no toca ni un plazo ni una decision.
        # Se mira UNA sola vez por dictado: en cuanto se sabe sorda no hace falta volver
        # a tocar el disco en cada vuelta de 30 ms.
        if (-not $script:dictaSordo -and (Test-Path -LiteralPath $RutaTranscribiendo)) {
            $script:dictaSordo = $true
            Set-UI 'pensando' $script:uiTexto
        }
        # transcripcion en vivo: ver lo que oye mientras hablas
        if (Test-Path -LiteralPath $RutaParcial) {
            try {
                # COMPARTIENDO EL ARCHIVO (22/09). ReadAllText lo abre SIN dejar que nadie
                # lo borre ni lo renombre mientras tanto, y la escucha reescribe el parcial
                # en cada palabra que oye, con un cambio atomico (.tmp + os.replace). Cuando
                # el replace caia justo en esta lectura, Windows lo tumbaba con "WinError 5:
                # Acceso denegado", la escucha se rendia y escribia encima sin atomicidad,
                # que es justo la ventana por la que se puede leer una orden a medias. En el
                # log hay 6 casos de dictado-parcial.txt en tres dias distintos, y el
                # contador de la escucha esta topado a 5 por proceso: 6 es un suelo.
                # FileShare.Delete es la parte que importa: es la que deja que el os.replace
                # de la escucha ocurra mientras esto lee.
                $par = ''
                $fsP = $null; $srP = $null
                try {
                    $fsP = New-Object System.IO.FileStream($RutaParcial, [System.IO.FileMode]::Open,
                            [System.IO.FileAccess]::Read,
                            ([System.IO.FileShare]::ReadWrite -bor [System.IO.FileShare]::Delete))
                    $srP = New-Object System.IO.StreamReader($fsP, [System.Text.Encoding]::UTF8)
                    $par = $srP.ReadToEnd()
                } finally {
                    if ($srP) { $srP.Dispose() }
                    if ($fsP) { $fsP.Dispose() }
                }
                $vista = ($par -replace '\s+', ' ').Trim()
                if ($vista.Length -gt 44) {
                    # por PALABRAS (14/09): cortar a 41 letras dejaba "...lume al setenta"
                    $colaV = $vista.Substring($vista.Length - 41)
                    $espV = $colaV.IndexOf(' ')
                    if ($espV -ge 0 -and $espV -lt 20) { $colaV = $colaV.Substring($espV + 1) }
                    $vista = "..." + $colaV
                }
                $nuevo = if ($vista) { "● $vista" } else { "● VOZ..." }
                if ($lbl.Text -ne $nuevo) {
                    # Y NO VUELVE A 'escuchando' SI YA ESTA TRANSCRIBIENDO: la escucha
                    # escribe un parcial MAS -el de Vosk- justo antes de llamar a Whisper,
                    # con el microfono cerrado desde hace rato. Sin este reparo ese ultimo
                    # parcial rearmaba la onda verde en plena transcripcion, que es justo
                    # lo que se venia a quitar.
                    $lbl.Text = $nuevo
                    $estadoCapsula = if ($script:dictaSordo) { 'pensando' } else { 'escuchando' }
                    Set-UI $estadoCapsula $vista
                    Test-LoTengo $vista
                    # CERRAR ANTES LO QUE YA SE ENTIENDE (14/09): se le dice a la escucha
                    # QUE texto se entendio; si sigues hablando, ya no coincide y espera
                    # los 1,4 s de siempre. Solo con la frase entera delante, no con "...".
                    if ($script:loTengo -and -not $script:loTengoEscrito -and -not $vista.StartsWith('...')) {
                        $script:loTengoEscrito = $true
                        try { [System.IO.File]::WriteAllText($RutaLoTengo, (($par -replace '\s+', ' ').Trim()), (New-Object System.Text.UTF8Encoding($false))) } catch {}
                    }
                    # PRECARGA POR LO QUE VAS DICIENDO (14/09): en frio el modelo tarda
                    # 7,8 s en cargar y la primera frase llego a 19 s. Si lo que llevas
                    # dicho ya suena a charla, empieza a cargar mientras terminas. No
                    # jugando (la RAM es del juego) ni si ya es una orden conocida.
                    if ($ConversacionOn -and -not $script:juegoActivo -and ($sw.ElapsedMilliseconds - $script:precargaEn) -gt 90000 -and
                        @($vista -split '\s+').Count -ge 3 -and -not $vista.StartsWith('...') -and
                        (Test-PareceCharla $vista) -and -not (Test-FastCommand $vista) -and -not (Test-ApiContestaPrimero)) {
                        $script:precargaEn = $sw.ElapsedMilliseconds
                        [void](Set-Reloj 'precarga')
                        try { if ((Test-RamParaCharla) -and (Send-CharlaPedido @{ op = 'calentar' })) { $script:charlaDescargada = $false; Log "charla: precargo el modelo, '$vista' suena a charla" } } catch {}
                    }
                }
            } catch {}
        }
        # el worker ya termino: entrega el texto
        if (Test-Path -LiteralPath $RutaDictado) {
            $dic = ''
            try { $dic = [System.IO.File]::ReadAllText($RutaDictado, [System.Text.Encoding]::UTF8) } catch {}
            # UNA SEGUNDA MIRADA (15/09): "abre youtube y reproduce Pitbull" llego en el mismo
            # segundo en que se leyo el archivo vacio, y la ventana se cerro como silencio
            if (-not $dic.Trim()) {
                Start-Sleep -Milliseconds 150
                try { $dic = [System.IO.File]::ReadAllText($RutaDictado, [System.Text.Encoding]::UTF8) } catch {}
                if ($dic.Trim()) { Log "DICTADO: el texto llego justo al leerlo; en la segunda mirada si esta" }
            }
            Remove-Item -LiteralPath $RutaDictado -Force -ErrorAction SilentlyContinue
            Remove-Item -LiteralPath $RutaLoTengo -Force -ErrorAction SilentlyContinue
            # ¿dijo algo el motor de Windows? Entonces se prefiere lo suyo. Si no
            # llego nada -o no oye este microfono- se sigue con lo de Whisper,
            # que es justo lo que hace que activarlo no pueda empeorar nada.
            if ($VozWindowsOn -and (Test-Path -LiteralPath $RutaDictadoWin)) {
                $porWin = ''
                try { $porWin = [System.IO.File]::ReadAllText($RutaDictadoWin, [System.Text.Encoding]::UTF8) } catch {}
                Remove-Item -LiteralPath $RutaDictadoWin -Force -ErrorAction SilentlyContinue
                if ($porWin.Trim()) {
                    if ($porWin.Trim() -ne $dic.Trim()) { Log "DICTADO de Windows: '$($dic.Trim())' -> '$($porWin.Trim())'" }
                    $dic = $porWin
                    Add-Estadistica 'vozwin' $porWin.Trim()
                } elseif ($dic.Trim()) {
                    # oyo Whisper pero Windows no: si esto pasa siempre, ese motor
                    # no oye este microfono y el ajuste se puede apagar
                    Add-Estadistica 'vozwin-mudo'
                }
            }
            Remove-Item -LiteralPath $MarcaDictar -Force -ErrorAction SilentlyContinue
            $script:armed = $false
            $capture.Hide()
            # la voz que dicto (por tono): la capsula tine la escucha por persona,
            # y el TONO en Hz decide si esto lo has dicho tu o sale de un video
            try {
                # LO QUE SE HABLABA ANTES DE LLAMARLA (20/09, ver ESCUCHAR NO ES GRABAR
                # en wake_vosk.py). Solo existe con escucha.ambiente = "si"; el worker lo
                # escribe en el instante de la activacion y AQUI se lee y se borra, asi que
                # vive en disco unos milisegundos. No se apunta en el log ni en ningun lado:
                # es contexto para entender un "eso" y se va con la orden.
                $script:ambienteUltimo = ''
                try {
                    $ra = Join-Path $TmpDir 'ambiente.txt'
                    if (Test-Path -LiteralPath $ra) {
                        $script:ambienteUltimo = ([System.IO.File]::ReadAllText($ra, [System.Text.Encoding]::UTF8)).Trim()
                        Remove-Item -LiteralPath $ra -Force -ErrorAction SilentlyContinue
                        if ($script:ambienteUltimo) { Log ("AMBIENTE: tengo " + $script:ambienteUltimo.Length + " caracteres de lo de antes (no se guardan)") }
                    }
                } catch {}
                $rv = Join-Path $TmpDir 'dictado-voz.txt'
                if (Test-Path -LiteralPath $rv) {
                    $campos = @(([System.IO.File]::ReadAllText($rv).Trim() -split '\s+'))
                    $script:uiVoz = [int]$campos[0]
                    if ($campos.Count -gt 1) { $script:ultimaF0 = [double]$campos[1] }
                    Remove-Item -LiteralPath $rv -Force -ErrorAction SilentlyContinue
                }
                # y lo seguro que estaba Whisper (ver RECETAS QUE CONFIRMAN EL DATO DUDOSO)
                $rc = Join-Path $TmpDir 'dictado-confianza.txt'
                if (Test-Path -LiteralPath $rc) {
                    # "-0.52" o "-0.52 eco" (lo oido es la frase de ejemplo de Whisper)
                    $partesC = @(([System.IO.File]::ReadAllText($rc)).Trim() -split '\s+')
                    $numC = [double]::Parse($partesC[0], [System.Globalization.CultureInfo]::InvariantCulture)
                    # DOS NUMEROS DISTINTOS EN EL MISMO FICHERO (26/09, idea 12). Si la segunda
                    # palabra es "acuerdo", esto NO es el avg_logprob de Whisper -que es
                    # negativo y mide otra cosa- sino el acuerdo entre Vosk y Parakeet, de 0 a 1.
                    # Mezclarlos seria comparar un numero con el umbral del otro.
                    if ($partesC.Count -gt 1 -and $partesC[1] -eq 'acuerdo') {
                        $script:dictadoAcuerdo = $numC
                        $script:dictadoAcuerdoEn = $sw.ElapsedMilliseconds
                        if ($partesC.Count -gt 2) {
                            try { $script:dictadoAcuerdoListon = [double]::Parse($partesC[2], [System.Globalization.CultureInfo]::InvariantCulture) } catch {}
                        }
                        # y lo de Whisper se deshace: no corrio, asi que su numero seria de antes
                        $script:dictadoConfianza = 0.0
                        $script:dictadoConfianzaEn = -999999
                        $script:dictadoEco = $false
                    } else {
                        $script:dictadoConfianza = $numC
                        $script:dictadoEco = ($partesC.Count -gt 1 -and $partesC[1] -eq 'eco')
                        $script:dictadoConfianzaEn = $sw.ElapsedMilliseconds
                        # y al reves: un acuerdo viejo no sobrevive a un dictado de Whisper
                        $script:dictadoAcuerdoEn = -999999
                    }
                    Remove-Item -LiteralPath $rc -Force -ErrorAction SilentlyContinue
                }
                # ¿lo oyo Parakeet? (ver PARAKEET PRIMERO)
                $script:dictadoPorParakeet = $false
                $rm = Join-Path $TmpDir 'dictado-motor.txt'
                if (Test-Path -LiteralPath $rm) {
                    $script:dictadoPorParakeet = ([System.IO.File]::ReadAllText($rm)) -match 'parakeet'
                    Remove-Item -LiteralPath $rm -Force -ErrorAction SilentlyContinue
                }
            } catch {}
            if ($script:enSeguimiento -and -not $dic.Trim()) {
                $script:enSeguimiento = $false
                if (($sw.ElapsedMilliseconds - $script:charlaUltima) -lt 60000 -and $script:charlaSilencios -lt 1) {
                    # en una CONVERSACION se espera una ventana mas antes de dejarlo
                    $script:charlaSilencios++
                    Log "seguimiento: silencio en una conversacion, espero otro poco"
                    $script:seguimientoPendiente = $true
                    if ($script:seguimientoFactor -le 0) { $script:seguimientoFactor = 1.0 }   # o esta espera no abre nada
                    $script:ventanaCharla = $true
                    $script:pausaHasta = $sw.ElapsedMilliseconds + 100
                } else {
                    # ventana de seguimiento sin voz: se cierra sin decir nada
                    Log "seguimiento: silencio, se cierra"
                    Set-UI 'reposo'
                }
            } else {
                if ($script:enSeguimiento) { try { Add-RitmoSeguimiento } catch {} }   # ver EL RITMO DE BRAYA
                # PARAKEET PRIMERO: si lo que oyo no es una orden que se entienda, Whisper
                # repasa el mismo audio y eso sigue el camino de siempre
                $dicPar = $dic.Trim()
                $puedeRepaso = ($script:dictadoPorParakeet -and $dicPar -and -not $script:dictandoLargo)
                $esOrdenPar = $false
                if ($puedeRepaso) { $esOrdenPar = [bool](Test-FastCommand $dicPar) }
                # NO REPASAR LO QUE YA SE VA A TIRAR (22/09). Cuando Parakeet ya ha oido una
                # frase larga en espanol, pedir el repaso es pagar por un texto que se va a
                # tirar entero. En el log hay 328 peticiones de repaso y 227 acaban en
                # "Whisper no saca una orden: sigo con lo de Parakeet": se espera, se mira y
                # se descarta. El corte de aqui -espanol largo Y mas de $RepasoMaxPalabras
                # palabras- coge 148 de esas 328 (45 %), que son 474,3 s de reloj de
                # transcripcion y 432,1 s de audio tirado con Nova sorda mientras repasaba;
                # en el propio log, entre "lo repasa" y "PARAKEET -> WHISPER" pasan 5,1 s de
                # media. NO SE PIERDE NI UNA ORDEN: de esas 148, en 120 ya se seguia con el
                # texto de Parakeet, y en las 22 restantes Whisper tampoco sacaba ninguna
                # orden local; en dos de ellas era Parakeet quien la tenia BIEN y Whisper la
                # destrozo ("abre youtube y reproduce musica de Pitbull" -> "abre y duro y
                # reproducente en musica de Pipboon"). La nube tampoco se pierde nada: en
                # todo el log rescato 2 frases, las dos de menos de 8 palabras.
                # POR QUE LAS DOS CONDICIONES Y NO SOLO EL NUMERO: de las 149 frases de mas
                # de 8 palabras, 1 no era espanol largo ("No, but I don't know if it's a
                # bien"), y esa si merece que la repase alguien que sepa de idiomas.
                # LO CORTO NO ENTRA: si lo que oyo Parakeet ya es una orden que la capa
                # local entiende, esto ni se mira ($esOrdenPar), y las frases cortas -donde
                # el repaso SI rescata ordenes- se siguen repasando igual que siempre.
                $repasoInutil = $false
                if ($puedeRepaso -and -not $esOrdenPar -and $RepasoMaxPalabras -gt 0 -and
                    @(((ConvertTo-Plain $dicPar) -split '\s+') | Where-Object { $_ }).Count -gt $RepasoMaxPalabras -and
                    (Test-EspanolLargo $dicPar)) {
                    $repasoInutil = $true
                    # Y SE CIERRA LA PUERTA DE ATRAS. Sin esta linea la frase cae tres lineas
                    # mas abajo en el oido fino, que repasa con small: 8649 ms por audio frente
                    # a los 3425 de base, ~4 veces mas lento, para volver a preguntar justo lo
                    # que se acaba de decidir no preguntar. El pestillo dura solo esta frase:
                    # el siguiente dictado lo abre otra vez (ver Start-Dictado).
                    $script:yaReintentado = $true
                    Add-Estadistica 'repaso-ahorrado' $dicPar
                    Log "REPASO AHORRADO: '$dicPar' es espanol largo de mas de $RepasoMaxPalabras palabras; Whisper no lo iba a mejorar, sigo con lo de Parakeet"
                }
                if ($puedeRepaso -and -not $esOrdenPar -and -not $repasoInutil -and (Request-WhisperTras $dicPar)) {
                    # lo recoge OIDO FINO: recoger el repaso
                } else {
                    if ($script:dictadoPorParakeet) { Add-Estadistica 'parakeet' $dicPar }
                    Process-Texto $dicPar
                }
            }
        }
        # "me perdi": 25 s dictando sin que nada encaje todavia
        elseif (-not $script:perdida -and -not $script:loTengo -and ($sw.ElapsedMilliseconds - $script:dictaInicio) -ge 25000) {
            $script:perdida = $true
            Send-UIEvento 'gesto:perdida'
        # 50 s: el worker corta el dictado a los 30 y Whisper ha llegado a tardar
        # 13,6 s mas; con 35 se cancelaba y el texto llegaba despues sin dueno
        } elseif (($sw.ElapsedMilliseconds - $script:dictaInicio) -ge 50000) {
            # ANTES DE RENDIRSE, MIRAR SI EL OIDO SIGUE VIVO (26/09, idea 35 de las 121).
            # Esta rama vive dentro de 'if ($script:armed -and $script:ordenPorWorker)', o sea
            # que el transcriptor ES el worker de Vosk: no hace falta guarda de motor aparte.
            # MEDIDO sobre 59 cancelaciones (assistant.log + .1): en 58 el worker seguia VIVO y
            # solo mudo -el texto no llego nunca, "la mentira duro 38,9 s de media"- y en 1
            # (1,7 %) habia muerto dentro de los 60 s. Hasta hoy las 59 se cancelaban igual, sin
            # mirar. Ahora se mira: si murio de verdad, se relanza aqui mismo -sin esperar hasta
            # 30 s a la vigilancia de mas abajo- respetando SU MISMO contador de 3 intentos.
            #
            # SI SIGUE VIVO, NO SE TOCA, y esto es a proposito: relanzar un worker vivo -aunque
            # su estado lleve rato sin moverse- exigiria matarlo primero (Dispose no mata, solo
            # suelta el handle), y matarlo seria (a) tirar una transcripcion que quiza esta
            # llegando -esas vueltas van a 72 s de maximo, ver $EstadoMaxSegundos = 45- y (b)
            # dejar un proceso huerfano sujetando el microfono si el relanzado falla (regla 5).
            # Test-EstadoFresco entra SOLO en el texto del log, nunca en la decision de relanzar:
            # esa decision es "vivo o muerto", que es lo unico seguro de actuar.
            #
            # $script:wakeProc puede valer $null aqui (lo pone a null la vigilancia de 27694):
            # por eso el '$script:wakeProc -and' va delante, nunca .HasExited a pelo.
            $vivoW = ($script:wakeProc -and -not $script:wakeProc.HasExited)
            $frescoW = Test-EstadoFresco
            $mudoSeg = Get-OidoMudoDesde
            if (-not $vivoW) {
                if ($script:wakeIntentos -lt 3) {
                    $script:wakeIntentos++
                    Log "dictado sin respuesta: el worker de escucha estaba MUERTO; relanzo (intento $($script:wakeIntentos)/3)"
                    # Dispose antes de soltar la referencia: este proceso vive meses y cada
                    # relanzo filtraria un handle (misma leccion que la vigilancia de 30 s).
                    try { $script:wakeProc.Dispose() } catch {}
                    $script:wakeProc = $null
                    Initialize-Escucha
                } else {
                    Log "dictado sin respuesta: el worker estaba MUERTO y ya agote los 3 intentos; sigo con el boton"
                }
                $textoCorte = 'El microfono se cayo; lo reabro'
            } else {
                Log "dictado sin respuesta: el worker sigue vivo ($mudoSeg s sin escribir, estado $(if ($frescoW) { 'fresco' } else { 'parado' })); no llego el texto"
                $textoCorte = 'No me llego nada'
            }
            # CANCELAR EL DICTADO NO ES NEGOCIABLE: los tres pasos se hacen SIEMPRE -vivo o
            # muerto- y despues de decidir, nunca dentro de una rama.
            Remove-Item -LiteralPath $MarcaDictar -Force -ErrorAction SilentlyContinue
            $script:armed = $false
            $capture.Hide()
            Set-UI 'error' $textoCorte 2500
            # SOLO SE HABLA SI EL OIDO ESTABA VIVO. Si estaba muerto y se acaba de relanzar, Say
            # pausaria (Pausar-Escucha) el worker recien abierto; y del oido caido ya habla el
            # aviso 'oido-mudo' (90 s) por su propio canal con freno por hora -dos bocas para la
            # misma averia es el fallo de los 25 del 22/09-. El Say va DESPUES del Set-UI: Say
            # hace Set-UI 'hablando' por dentro, asi que ponerlo antes se comeria el mensaje.
            if ($vivoW) { Say 'No me llego nada, repitemelo.' }
        }
    }

    # --- ENVIO AUTOMATICO (solo para el dictado antiguo de Windows).
    # Con Vosk el propio worker detecta el silencio y entrega el texto.
    if ($script:armed -and -not $script:ordenPorWorker -and $AutoSubmitMs -gt 0) {
        $actual = $tb.Text
        if ($actual -ne $script:lastText) {
            $script:lastText = $actual
            $script:lastChange = $sw.ElapsedMilliseconds
            # TRANSCRIPCION EN VIVO: ver lo que oye mientras hablas. Asi notas
            # al momento si transcribio mal, en vez de descubrirlo al ejecutar.
            $vista = ($actual -replace '\s+', ' ').Trim()
            if ($vista.Length -gt 44) { $vista = "..." + $vista.Substring($vista.Length - 41) }
            $lbl.Text = if ($vista) { "● $vista" } else { "● VOZ..." }
            Set-UI 'escuchando' $vista
            Test-LoTengo $vista
        } elseif ($actual.Trim().Length -gt 0 -and ($sw.ElapsedMilliseconds - $script:lastChange) -ge $AutoSubmitMs) {
            try { Finish-Dictation "silencio" }
            catch { Log "auto-envio error: $($_.Exception.Message)"; $script:armed = $false }
        } elseif ($actual.Trim().Length -eq 0 -and ($sw.ElapsedMilliseconds - $script:dictaInicio) -ge 10000) {
            # 10 s sin una sola palabra: Win+H se ha rendido solo (o no oye).
            # Sin esto se quedaba armado para siempre, con la escucha propia
            # en pausa y el panel de Windows a la vista.
            Log "Win+H: 10 s sin texto, se cierra"
            try { Finish-Dictation "sin voz" }
            catch { Log "cierre sin voz: $($_.Exception.Message)"; $script:armed = $false }
        }
    }

    # --- una receta con script corriendo aparte (ver RECETA SIN BLOQUEAR) ---
    if ($script:recetaEnCurso) {
        try { Watch-Receta } catch { Log ("receta: " + $_.Exception.Message); $script:recetaEnCurso = $null }
    }

    # --- atencion al trabajo en curso, sin bloquear el sondeo del boton ---
    if ($script:busy -and $script:proc) {
        Watch-OpencodeProgress
        if ($script:proc.HasExited) {
            $script:uiProgreso = 0
            Report-Reply (Complete-OpencodeJob)
        } elseif (($sw.ElapsedMilliseconds - $script:jobStart) -ge (Get-PlazoJob)) {
            Log "RUNNER timeout tras $([Math]::Round((Get-PlazoJob)/1000)) s ($($script:jobModo))"
            $script:uiProgreso = 0
            Stop-OpencodeJob
            Add-Estadistica 'error' 'timeout de opencode'
            Show-Popup "El modelo tardo demasiado y lo he dejado." 'error'
        }
    }

    # --- OIDO FINO: recoger el repaso (o rendirse cuando vence el plazo) ---
    # No se espera bloqueando: el bucle sigue vivo, la capsula sigue animandose
    # y el boton sigue respondiendo mientras el worker repasa el audio.
    if ($script:reintentoVence -gt 0) {
        $fino = $null
        if (Test-Path -LiteralPath $RutaReintento) {
            try { $fino = [System.IO.File]::ReadAllText($RutaReintento, [System.Text.Encoding]::UTF8) } catch { $fino = '' }
            Remove-Item -LiteralPath $RutaReintento -Force -ErrorAction SilentlyContinue
        } elseif ($sw.ElapsedMilliseconds -ge $script:reintentoVence) {
            # EL PLAZO, EN LA LINEA: ya no hay un unico 15, asi que sin decirlo un "sin
            # respuesta a tiempo" no se puede leer ni contar (26/09, idea 8).
            Log ("OIDO FINO: sin respuesta a tiempo (plazo " + [int]($script:reintentoPlazo / 1000) + " s); sigo con lo que tenia")
            Remove-Item -LiteralPath $MarcaReintento -Force -ErrorAction SilentlyContinue
            $fino = ''
        }
        # lo que pidio PARAKEET PRIMERO: Whisper sobre el mismo audio, que entra como si
        # fuera el dictado (con su seguridad y su marca de eco, y con el repaso disponible)
        # EL SIGUIENTE ESCALON DE LA CASCADA, si este no saco una orden (21/09).
        # Va ANTES del bloque de abajo y no dentro a proposito: poniendo $fino a $null
        # se sale sin tocar nada mas, y el bloque de siempre queda intacto. Meter un
        # 'continue' aqui se saltaria el final de la vuelta del bucle, que es un fallo
        # que ya esta apuntado en la lista.
        # SOLO SE ENCADENA SI EL ESCALON NO DIO ORDEN: si Canary la saca, se hace y ya,
        # que es mas rapido que cualquier otra cosa. Y la nube no se relanza (ver
        # Request-WhisperTras): sigue esperando desde el primer paso.
        # CADA ESCALON SE APUNTA SI SIRVIO O NO (25/09, ver EL ESCALON QUE NO SACA NADA).
        # Hasta hoy la cascada no dejaba NI UN numero con el que juzgarla: se sabia cuantas
        # veces se pedia un repaso, no cual de los motores acababa sacando la orden.
        # Va AQUI y no mas abajo por una razon concreta: cuando un escalon SI acierta no se
        # encadena, o sea que no vuelve a pasar por el bloque de abajo, y contarlo alli seria
        # contar solo los fallos -el mismo fallo de "tres contadores de desenlace y ninguno de
        # intento" que ya se pago el 24/09-. Dos claves, como el oido fino: el total y los
        # aciertos, porque el total es lo que necesita el reparto por dias.
        if ($null -ne $fino -and $script:reintentoBase -and
            $script:repasoPaso -lt $RepasoCascada.Count) {
            try {
                $motorC = [string]$RepasoCascada[$script:repasoPaso]
                Add-Estadistica "repaso:$motorC" $script:repasoOriginal $true
                if (Test-FastCommand ([string]$fino).Trim()) {
                    Add-Estadistica "repaso-sirvio:$motorC" $script:repasoOriginal $true
                }
            } catch {}
        }
        if ($null -ne $fino -and $script:reintentoBase -and
            ($script:repasoPaso + 1) -lt $RepasoCascada.Count -and
            -not (Test-FastCommand ([string]$fino).Trim())) {
            $script:reintentoBase = $false
            if (Request-WhisperTras $script:repasoOriginal ($script:repasoPaso + 1)) {
                Log "REPASO: $([string]$RepasoCascada[$script:repasoPaso]) tampoco dio una orden; sigo la cascada"
                $fino = $null
            } else {
                $script:reintentoBase = $true
            }
        }
        if ($null -ne $fino -and $script:reintentoBase) {
            $script:reintentoVence = 0
            $script:reintentoBase = $false
            $origP = $script:reintentoTexto
            $script:reintentoTexto = ''
            $script:dictadoConfianzaEn = -999999
            $script:dictadoEco = $false
            try {
                $rcP = Join-Path $TmpDir 'dictado-confianza.txt'
                if (Test-Path -LiteralPath $rcP) {
                    $partesP = @(([System.IO.File]::ReadAllText($rcP)).Trim() -split '\s+')
                    $script:dictadoConfianza = [double]::Parse($partesP[0], [System.Globalization.CultureInfo]::InvariantCulture)
                    $script:dictadoEco = ($partesP.Count -gt 1 -and $partesP[1] -eq 'eco')
                    $script:dictadoConfianzaEn = $sw.ElapsedMilliseconds
                    Remove-Item -LiteralPath $rcP -Force -ErrorAction SilentlyContinue
                }
            } catch {}
            $limpioW = $fino.Trim()
            $script:yaReintentado = $false
            $sigueCon = if ($limpioW) { $limpioW } else { $origP }
            $script:siguioParakeet = $false
            # LA NUBE, SI YA CONTESTO (ver SEGUNDA OPINION EN LA NUBE). Solo cuando ni
            # Parakeet ni Whisper sacan una orden: si alguno la saca, se hace y punto,
            # que es mas rapido que cualquier cosa que venga de fuera.
            if ($script:nubeOut) {
                $nubeTxt = Receive-NubeOir
                $localOk = (Test-FastCommand $limpioW) -or (Test-FastCommand $origP)
                # ESPERAR A LA NUBE CUANDO EL OIDO LOCAL SE HA QUEDADO SIN NADA (19/09).
                # El oido fino tarda ~4 s (4,4 / 3,9 / 3,6 s en el log) y la nube vence a los
                # 5,8 s: al llegar aqui la nube muchas veces AUN NO HA CONTESTADO, y su
                # respuesta -que llega un segundo despues- no la recogia nadie, porque este es
                # el UNICO punto donde se consulta. Se perdian ordenes que la nube habia sacado
                # bien. Si el oido local no saco orden, se espera lo que le quede de plazo: la
                # alternativa a esperar no es responder rapido, es no entender. Si el oido local
                # SI saco algo, no se espera ni un milisegundo.
                # EL BUCLE YA NO ESPERA A LA NUBE (24/09, idea 7). Aqui habia un while con
                # Start-Sleep que llegaba a 7,8 s con un juego delante, y el argumento que lo
                # sostenia -"la alternativa a esperar no es responder rapido, es no entender"-
                # se cae con los datos: de las 12 esperas, CERO acabaron en 'nube-sirvio'.
                # Se mira una vez, sin dormir. Si ya llego, se usa; si no, se sigue.
                if (-not $nubeTxt -and -not $localOk -and $script:nubeOut) {
                    if ((Get-EsperaNubeMs $localOk ([bool]$nubeTxt) ([int]($script:nubeVence - $sw.ElapsedMilliseconds))) -gt 0) {
                        Start-Sleep -Milliseconds 120
                    }
                    $nubeTxt = Receive-NubeOir
                    if ($nubeTxt) { Add-Estadistica 'nube-esperada' '' }
                }
                if ($nubeTxt -and -not $localOk) {
                    $esOrdenN = $false
                    try { $esOrdenN = [bool](Test-FastCommand $nubeTxt) } catch { $esOrdenN = $false }
                    if (Test-NubeSirve $nubeTxt $origP $esOrdenN) {
                        Log "NUBE: '$origP' / '$limpioW' -> '$nubeTxt' (lo saca la nube)"
                        Add-Estadistica 'nube-sirvio' "$origP -> $nubeTxt"
                        $script:reintentoVence = 0
                        $script:yaReintentado = $true
                        Process-Texto $nubeTxt
                        $fino = $null
                        # EL FLANCO DEL BOTON, ANTES DE SALTAR (21/09). Este 'continue' se
                        # salta el final de la vuelta, y ahi esta '$startPrev = $startNow',
                        # que es lo que convierte 'el boton esta pulsado' en 'el boton se
                        # ACABA de pulsar'. Sin esto, startPrev se queda con el valor de dos
                        # vueltas atras: si braya tenia el menu apretado cuando contesto la
                        # nube, la vuelta siguiente ve un flanco que no existe (o se pierde
                        # el que si). Son dos lineas mas abajo en el codigo y aqui no cuestan
                        # nada; el Start-Sleep que tambien se salta da igual, solo adelanta
                        # una vuelta.
                        $startPrev = $startNow
                        continue
                    }
                    Log "NUBE: '$nubeTxt' tampoco es una orden que sepa hacer; sigo con el oido local"
                    Add-Estadistica 'nube-nada' "$origP -> $nubeTxt"
                } elseif ($nubeTxt) {
                    # CONTESTO, PERO YA NO HACIA FALTA: el oido local saco la orden antes.
                    # No es que se equivoque, es que SOBRA, y son cosas distintas: una nube
                    # que siempre llega tarde no aporta aunque acierte siempre (17/09).
                    Add-Estadistica 'nube-sobra' "$origP -> $nubeTxt"
                }
            }
            # ver PARAKEET PARA LO QUE NO ES UNA ORDEN. El repaso con small se mantiene (oye
            # el AUDIO, no este texto): en las 202 grabaciones rescata 2 ordenes que Parakeet
            # oyo mal ("si agradezco y abre spotify" por "cierra discord y abre spotify").
            if ($limpioW -and -not (Test-FastCommand $limpioW) -and (Test-EspanolLargo $origP)) {
                $sigueCon = $origP
                $script:siguioParakeet = $true
                Log "PARAKEET -> WHISPER: '$origP' -> '$limpioW'; Whisper no saca una orden: sigo con lo de Parakeet"
            } else {
                Log "PARAKEET -> WHISPER: '$origP' -> '$limpioW'"
            }
            # SI LOS DOS OYEN LO MISMO, NO SE REPASA (15/09). "Revisa mi correo", "puedes
            # reproducir esta cancion", "instala en Steam It Takes Two": Parakeet y Whisper
            # oyeron lo mismo y aun asi pasaban por small y turbo, 30-47 s para oir otra vez lo
            # mismo. Medido: con un parecido de 0,9 o mas, en su uso real el repaso saco una
            # orden en 0 de 24 frases; en las 202 grabaciones en 1 ("abre otras" por "abre
            # outlast", de 2 palabras: por eso hacen falta 3 o mas).
            if ($limpioW -and $origP -and -not (Test-FastCommand $limpioW)) {
                $plP = ConvertTo-Plain $origP
                $plW = ConvertTo-Plain $limpioW
                $largoPW = [Math]::Max($plP.Length, $plW.Length)
                $parecidoPW = if ($largoPW -gt 0) { 1.0 - (Get-Distancia $plP $plW) / $largoPW } else { 0.0 }
                if ($largoPW -gt 0 -and @($plP -split '\s+' | Where-Object { $_ }).Count -ge 3 -and
                    $parecidoPW -ge 0.9) {
                    $script:yaReintentado = $true
                    # DICE EL PARECIDO, Y NO "LO MISMO" (25/09). La linea decia "oyen lo mismo"
                    # con un parecido de 0,9, que NO es lo mismo: el 25/09 a las 01:22 Parakeet
                    # oyo "conectado en el team" y Whisper "conectado en Steam" -la correccion
                    # que hacia falta- y el log de al lado afirmaba que oian igual. Mirando ese
                    # par se pierde media hora creyendo que hay un fallo donde no lo hay: los
                    # 215 pares del log dicen que Parakeet acierta mas ("mi escritorio" contra
                    # "mi criadorio", "un bate" contra "un bat de pata de la tonosombre"), asi
                    # que quedarse con Parakeet esta bien. Lo que estaba mal era la linea.
                    Log ("PARAKEET y WHISPER oyen casi lo mismo (parecido " +
                         $parecidoPW.ToString('0.00', [System.Globalization.CultureInfo]::InvariantCulture) +
                         "): sin repaso")
                }
            }
            Process-Texto $sigueCon
            $fino = $null
        }
        if ($null -ne $fino) {
            $script:reintentoVence = 0
            $orig = $script:reintentoTexto
            $script:reintentoTexto = ''
            $reconocida = $script:reintentoReconocida
            $script:reintentoReconocida = $false
            $ecoR = $script:reintentoEco
            $script:reintentoEco = $false
            $esUltimo = $script:reintentoUltimo
            $script:reintentoUltimo = $false
            $alFallar = $script:reintentoAlFallar
            $script:reintentoAlFallar = 'procesar'
            $limpio = $fino.Trim()
            # si lo que oyo quien repaso es la frase de ejemplo (la escucha lo apunta con "eco")
            $ecoFino = $false
            try {
                $rcF = Join-Path $TmpDir 'dictado-confianza.txt'
                if (Test-Path -LiteralPath $rcF) {
                    $ecoFino = ([System.IO.File]::ReadAllText($rcF)) -match '\beco\b'
                    Remove-Item -LiteralPath $rcF -Force -ErrorAction SilentlyContinue
                }
            } catch {}
            # dos modelos que oyen EXACTAMENTE lo mismo se confirman, aunque sea la frase de ejemplo
            $mismoQueAntes = [bool]($limpio -and (ConvertTo-Plain $limpio) -eq (ConvertTo-Plain $orig))
            if ($esUltimo) {
                # ULTIMO RECURSO (turbo): vale si trae una orden entendible, con la misma guarda del eco
                if ($limpio -and (Test-FastCommand $limpio) -and (-not $ecoFino -or $mismoQueAntes)) {
                    Log "ULTIMO RECURSO: '$orig' -> '$limpio'"
                    Add-Estadistica 'turbo-sirvio' "$orig -> $limpio"
                    Process-Texto $limpio
                } elseif ($reconocida -or $alFallar -eq 'noentendi') {
                    Log "ULTIMO RECURSO: turbo tampoco lo saca ('$orig' -> '$limpio'); no hago nada"
                    Add-Estadistica 'turbo-nada' $orig
                    $script:seguimientoPendiente = $false
                    Send-UIEvento 'gesto:confuso'
                    Show-Popup "No te entendi. Repitelo." 'error'
                    Say "No te entendi"
                    Open-EscuchaTrasNoEntendi
                } else {
                    # lo que oyo turbo, si se parece, es el mejor oido que hay: con lo primero, la
                    # charla contesto a "la distancia del solo de la tierra" cuando turbo habia oido
                    # "cual es la distancia del sol a la tierra" (15/09)
                    $sigue = if ($limpio -and (Test-MismoAudio $orig $limpio)) { $limpio } else { $orig }
                    Log "ULTIMO RECURSO: turbo tampoco saca una orden de '$orig' ('$limpio'); sigue su camino con '$sigue'"
                    Add-Estadistica 'turbo-nada' $orig
                    Add-OidoDudoso $sigue
                    $script:yaReintentado = $true   # ya se repaso: que no vuelva a pedir el oido fino
                    Process-Texto $sigue
                }
            } elseif ($reconocida -and $ecoR) {
                # lo primero era un eco de la frase de ejemplo: solo vale lo que confirme el repaso
                # ... y un eco no confirma a otro eco (tanda dirigida, 14/09): "pon modo noche"
                # desde lejos, base lo oyo bien, small oyo "Que hora es" y se hizo la hora. Si el
                # repaso no lo confirma, se intenta con turbo antes de rendirse
                if ($limpio -and (-not $ecoFino -or $mismoQueAntes) -and (Test-MismoAudio $orig $limpio) -and (Test-FastCommand $limpio)) {
                    Log "OIDO FINO: el eco '$orig' lo confirma el repaso como '$limpio'"
                    Add-Estadistica 'fino-sirvio' "$orig -> $limpio"
                    Process-Texto $limpio
                } elseif (-not (Request-UltimoRecurso $orig $true $true 'noentendi')) {
                    Log "OIDO FINO: '$orig' era la frase de ejemplo y el repaso ('$limpio') no lo confirma; no hago nada"
                    Add-Estadistica 'fino-eco' $orig
                    $script:seguimientoPendiente = $false
                    Send-UIEvento 'gesto:confuso'
                    Show-Popup "No te entendi. Repitelo." 'error'
                    Say "No te entendi"
                    Open-EscuchaTrasNoEntendi
                }
            } elseif ($reconocida -and ((-not $limpio) -or (ConvertTo-Plain $limpio) -eq (ConvertTo-Plain $orig) -or
                -not (Test-MismoAudio $orig $limpio) -or -not (Test-FastCommand $limpio))) {
                # se repaso una orden que YA se entendia (ver REPASO DE LO DUDOSO): si
                # el repaso no trae otra orden entendible, vale lo que se oyo primero
                Log "OIDO FINO: el repaso ('$limpio') no mejora '$orig'; la hago tal cual"
                Add-Estadistica 'fino-igual' $orig
                Process-Texto $orig
            } elseif ($limpio -and (ConvertTo-Plain $limpio) -ne (ConvertTo-Plain $orig) -and (Test-MismoAudio $orig $limpio) -and
                      ($mismoQueAntes -or -not ($ecoFino -or (Test-EsFraseEjemplo $limpio)))) {
                # la guarda del eco va TAMBIEN aqui (16/09, ver UNA SOLA FRASE DEL EJEMPLO):
                # antes solo la miraba la rama de abajo, y por esta entraban las cuatro
                # equivocadas graves que se midieron con las grabaciones leidas
                if ((Test-FastCommand $limpio) -or -not (Request-UltimoRecurso $orig $false $false 'procesar')) {
                    if ($script:siguioParakeet -and -not (Test-FastCommand $limpio)) {
                        # SMALL NO PISA A PARAKEET (15/09): "mueve It Takes Two a la carpeta Games"
                        # lo oyo bien Parakeet; small oyo "state 2", se siguio con eso y el agente
                        # busco "state 2" 48 s. Si small tampoco saca una orden, vale Parakeet.
                        Log "OIDO FINO: '$limpio' tampoco es una orden; sigo con lo de Parakeet: '$orig'"
                        Process-Texto $orig
                    } else {
                        Log "OIDO FINO: '$orig' -> '$limpio'"
                        Add-Estadistica 'fino-sirvio' "$orig -> $limpio"
                        Process-Texto $limpio
                    }
                }
            } elseif ($limpio -and -not (Test-MismoAudio $orig $limpio) -and $script:siguioParakeet -and -not (Test-FastCommand $limpio)) {
                # lo de Parakeet era una frase en espanol y el repaso no trae una orden: se sigue
                # con Parakeet en vez de "no te entendi" (ver SMALL NO PISA A PARAKEET)
                Log "OIDO FINO: '$limpio' no se parece a lo de Parakeet ni es una orden; sigo con Parakeet: '$orig'"
                Process-Texto $orig
            } elseif ($limpio -and -not (Test-MismoAudio $orig $limpio) -and -not $ecoFino -and
                      -not (Test-EsFraseEjemplo $limpio) -and (Test-FastCommand $limpio)) {
                # EL REPASO ACIERTA AUNQUE NO SE PAREZCA (15/09). Cuando base oye basura, lo de small
                # no comparte ninguna palabra con ello y se tiraba como "invento suyo". Medido con las
                # 202 grabaciones: base sin orden y small con orden que no se parecen, 16 eran la orden
                # correcta ("cierra steam", "abre spotify", "abre elden ring") y 2 equivocadas, y las
                # dos inofensivas. Jugando, braya lo sufrio y la autosordina se callo 10 minutos. Vale
                # si el repaso trae una orden clara y no es la frase de ejemplo de Whisper (el eco).
                Log "OIDO FINO: '$orig' -> '$limpio' (no se parece, pero el repaso trae una orden clara)"
                Add-Estadistica 'fino-sirvio' "$orig -> $limpio"
                Process-Texto $limpio
            } elseif ($limpio -and -not (Test-MismoAudio $orig $limpio)) {
                if (-not (Request-UltimoRecurso $orig $false $false 'noentendi')) {
                    Log "OIDO FINO descartado: '$limpio' no se parece en nada a '$orig'; es invento suyo"
                    Add-Estadistica 'fino-invento' "$orig -> $limpio"
                    Add-Estadistica 'ruido' $orig
                    Add-RuidoRacha
                    $script:seguimientoPendiente = $false
                    Send-UIEvento 'gesto:confuso'
                    Show-Popup "No te entendi. Repitelo." 'error'
                    Say "No te entendi"
                    Open-EscuchaTrasNoEntendi
                }
            } else {
                # el oido fino oyo lo mismo: se intenta con turbo; si no, sigue su camino. Si no oyo
                # NADA (o ya no quedaba audio: "no queda audio de la orden anterior"), turbo
                # tampoco va a oir mas y solo sumaria 15-28 s
                if (-not $limpio -or -not (Request-UltimoRecurso $orig $false $false 'procesar')) {
                    Add-Estadistica 'fino-igual' $orig
                    Process-Texto $orig
                }
            }
        }
    }

    # --- abrir Win+H en cuanto el asistente se calle ---
    # Tiene que ser DESPUES de hablar (si no, se transcribe a si mismo) y con la
    # ventana de destino delante, porque Win+H escribe donde este el cursor.
    if ($script:dictadoWinHPendiente -and $script:pausaHasta -le 0 -and -not $script:busy) {
        $script:dictadoWinHPendiente = $false
        if ($script:dictadoVentana -ne [IntPtr]::Zero) {
            [void][AX]::ForceForeground($script:dictadoVentana)
            Start-Sleep -Milliseconds 250
        }
        # el oido propio se calla mientras: si no, Vosk y Windows se pelean por
        # el microfono y no gana ninguno. El boton sigue vivo, que es la salida.
        Pausar-Escucha $DictadoLargoMs
        Send-WinH
        Log "DICTADO LARGO: Win+H abierto sobre la ventana $($script:dictadoVentana)"
        Set-UI 'escuchando' 'dictando con Windows... manten el boton para terminar'
    }

    # --- el dictado largo se vuelve a abrir solo ---
    # Va SUELTO en el bucle, no colgado de "acabo de hablar": en este modo el
    # asistente no dice nada, asi que aquel bloque no se alcanza nunca y el modo
    # escribia un trozo y se quedaba sordo. Se espera a que no haya pausa de voz
    # en marcha para no competir por el microfono.
    if ($script:dictandoLargo -and -not $script:dictadoWinH -and -not $script:armed -and -not $script:busy -and -not $script:pendiente -and
        $script:pausaHasta -le 0 -and $DictadoWorker -and $script:wakeProc -and -not $script:wakeProc.HasExited) {
        Start-Dictado 'largo'
    }

    # --- la sordina vuelve tras un dictado con el boton (ver Start-Dictado) ---
    if ($script:sordinaRepausar -and -not $script:armed -and -not $script:busy -and -not $script:pendiente -and $script:reintentoVence -le 0) {
        $script:sordinaRepausar = $false
        $restanSordina = $script:sordinaHasta - $sw.ElapsedMilliseconds
        if ($restanSordina -gt 1000) {
            Pausar-Escucha $restanSordina
            Log "SORDINA: vuelve ($([int][Math]::Ceiling($restanSordina / 60000)) min)"
        }
    }

    # --- el dictado largo tiene plazo ---
    # La tercera salida, la que no depende de ti: si pasan los minutos sin
    # escribir nada, se cierra solo y lo dice. Un modo que escribe en la ventana
    # de delante no puede quedarse puesto porque te fuiste a otra cosa.
    if ($script:dictandoLargo -and $script:dictadoLargoHasta -gt 0 -and $sw.ElapsedMilliseconds -ge $script:dictadoLargoHasta) {
        Stop-DictadoLargo 'se acabo el plazo'
    }

    # --- escondida un rato: vuelve sola al vencer (ver ESCONDERSE UN RATO) ---
    if ($script:retiradaHasta -gt 0 -and $sw.ElapsedMilliseconds -ge $script:retiradaHasta) {
        $script:retiradaHasta = 0
        $estabaEscondida = ($script:uiEstado -eq 'retirada')
        $script:uiRetirada = $false
        if ($estabaEscondida) { Set-UI 'reposo'; Send-UIEvento 'gesto:saludo' }
    }

    # --- avisos que esperaban a que terminaras de dictar (ver Send-Aviso) ---
    if (-not $script:armed -and -not $script:pendiente -and $script:avisosAplazados.Count -gt 0) {
        $avA = $script:avisosAplazados[0]
        $script:avisosAplazados.RemoveAt(0)
        Send-Aviso $avA.texto $avA.tipo
    }

    # --- temporizadores vencidos ---
    if ($script:temporizadores.Count -gt 0) {
        for ($i = $script:temporizadores.Count - 1; $i -ge 0; $i--) {
            $t = $script:temporizadores[$i]
            # mientras dictas no suena: hablar encima congelaba el dictado (auditoria 13/09)
            if ($sw.ElapsedMilliseconds -ge $t.vence -and -not $script:armed) {
                $script:temporizadores.RemoveAt($i)
                Log "TEMPORIZADOR: $($t.texto)"
                # el sonido propio si suena: son dos notas de medio segundo, no
                # una frase encima, y es lo que hace que un temporizador sirva
                Play-Sonido 'te-oigo' ([System.Media.SystemSounds]::Exclamation)
                if ($t.tipo -eq 'foco' -and -not $script:pendiente -and -not $script:busy) {
                    # FIN DEL FOCO: se ofrece el descanso (si / no, o A / B)
                    $script:pendiente = @{ texto = ''; vence = 0; tipo = 'descanso' }
                    Say 'Fin del foco. ¿Descanso de cinco minutos?'
                    Set-UI 'escuchando' '¿Descanso de 5 minutos?'
                    Start-Confirmacion
                } else {
                    Send-Aviso $t.texto 'tiempo'
                }
            }
        }
    }

    # --- descargas de Steam: avisar cuando una termina ---
    # Cada dos minutos se releen los manifiestos (es leer texto de disco, no
    # hablar con Steam) y se compara con lo que estaba bajando antes.
    if (($sw.ElapsedMilliseconds - $script:descargaCheck) -ge 120000) {
        $script:descargaCheck = $sw.ElapsedMilliseconds
        try {
            $ahoraBajan = @{}
            # De paso, LO QUE LLEVA la mas avanzada: son los mismos bytes que ya
            # se acaban de leer, y la capsula ya sabe dibujar una fraccion en el
            # anillo. Se elige la mas avanzada porque es la que va a terminar
            # antes, que es lo que se quiere saber mirando de reojo.
            $frac = 0.0
            $jsD = @(Get-JuegosSteam)
            foreach ($j in $jsD) {
                if ($j.bajando) {
                    $ahoraBajan[[string]$j.id] = $j.nombre
                    if ([double]$j.total -gt 0) {
                        $f = [double]$j.descargado / [double]$j.total
                        if ($f -gt $frac) { $frac = [Math]::Max(0.0, [Math]::Min(1.0, $f)) }
                    }
                }
            }
            # solo se reescribe el estado si el anillo se movio de verdad (1 %)
            if ([Math]::Abs($frac - $script:uiDescarga) -gt 0.01) {
                $script:uiDescarga = $frac
                Refresh-UI
            }
            # QUIEN DECIDE ES Test-DescargasFlanco (23/09, idea 3). Aqui la unica condicion
            # era "ya no esta bajando", sin mirar si el juego quedo instalado, asi que
            # cancelar la descarga, cerrar Steam o quitar la microSD se cantaban como final.
            # Esta en su registro: 15/09 11:26:50 "cierra Steam" y ONCE SEGUNDOS despues
            # "DESCARGA terminada: PEAK", dicho en voz alta. PEAK hoy no esta instalado, y de
            # los 15 avisos del registro cinco son de juegos que ya no estan.
            # La primera lectura sigue sin anunciar nada, y ademas mira lo que quedo apuntado
            # en el disco del arranque anterior (agujero B).
            #
            # Y LAS REGLAS COMEN DE AQUI. Antes habia OTRO flanco, en el bloque del minuto,
            # con el mismo fallo y encima disparando ACCIONES suyas ("cuando termine de
            # descargarse X, abrelo"): cerrar Steam a mitad de una descarga podia abrir un
            # juego que nadie pidio. Los dos no pueden llamar a la funcion, porque el primero
            # que pase se come el flanco y el otro no ve nada: se hace UNA vez, aqui.
            $primeraD = $script:descargasArranque
            foreach ($nomD in @(Test-DescargasFlanco $jsD)) {
                Log "DESCARGA terminada: $nomD"
                try { Add-DescargaHecha $nomD } catch {}   # para el resumen del dia (idea 19)
                try { Invoke-Reglas 'descarga' $nomD } catch { Log ("regla de descarga: " + $_.Exception.Message) }
                # UNA SOLA VOZ POR DESCARGA (21/09): si una regla suya ya lo dijo, este se
                # calla; si no tenia regla, habla.
                if ($script:reglasDisparadas -eq 0) {
                    # PALABRAS DISTINTAS A PROPOSITO: decir "ya acabo" de algo que termino
                    # hace seis horas es inventarse un cuando.
                    if ($primeraD) { Send-Aviso "$nomD se descargo mientras no estaba." 'descarga' }
                    else { Send-Aviso "$nomD ya acabo de descargarse." 'descarga' }
                }
            }
        } catch { Log ("descargas: " + $_.Exception.Message) }
    }

    # QUIEN SE CONECTA EN STEAM (23/09, idea 10). Justo detras de las descargas porque es la
    # misma clase de sensor y la misma cadencia -120 s, la que lleva catorce dias ahi sin dar
    # un problema-. Lo primero que hace la funcion es irse si no hay ninguna vigilancia
    # armada, asi que sin regla puesta esto no gasta ni una peticion ni un objeto.
    # LA CLAVE VIAJA DENTRO DE LA URL, asi que cualquier excepcion que se escape de aqui la
    # arrastra entera al registro. El mismo -replace que llevan Start-SteamAsync y
    # Get-AmigosLista, tambien en la red de fuera.
    # LA RESPUESTA DE STEAM, SI YA LLEGO: un IsCompleted, cero espera. Va fuera de
    # Watch-AmigoConecta a proposito, porque esa se va en su primera linea cuando no hay
    # ninguna vigilancia armada, y esto pasa justo ANTES de que haya una.
    # LAS PREGUNTAS SUELTAS A STEAM (1/10, las 14 y 15 de las 20), ANTES que las de los amigos y
    # saliendose solas si la respuesta que viene es de ellos: el canal es uno y el acuerdo es que
    # nadie recoge lo que no ha pedido.
    try { Receive-SteamPregunta } catch { Log ("steam: " + ($_.Exception.Message -replace 'key=[^&\s]+', 'key=***')) }
    try { Receive-AmigoPregunta } catch { Log ("amigos: " + ($_.Exception.Message -replace 'key=[^&\s]+', 'key=***')) }
    try { Watch-AmigoConecta } catch { Log ("amigos: " + ($_.Exception.Message -replace 'key=[^&\s]+', 'key=***')) }
    # Y SI ALGUN AMIGO SE PONE A TU MISMO JUEGO (1/10, la 13 de las 20). Solo con un juego delante y
    # como mucho cada cinco minutos: son dos llamadas por ronda y el canal es uno.
    try { Watch-AmigoEnMiJuego } catch { Log ("amigos: " + ($_.Exception.Message -replace 'key=[^&\s]+', 'key=***')) }

    # --- juegos colgados: avisar, NUNCA cerrar por su cuenta ---
    # Solo avisa (y una vez por proceso): cerrar un juego a la fuerza pierde lo
    # que no este guardado, y eso lo decide el usuario, no el asistente.
    if (($sw.ElapsedMilliseconds - $script:zombiCheck) -ge 600000) {
        $script:zombiCheck = $sw.ElapsedMilliseconds
        if (-not $script:busy -and -not $script:armed -and -not $script:pendiente) {
            if ($script:zombisAvisados.Count -gt 20) { $script:zombisAvisados = @{} }
            foreach ($z in @(Get-JuegosZombis)) {
                if ($script:zombisAvisados.ContainsKey($z.proc.Id)) { continue }
                $script:zombisAvisados[$z.proc.Id] = $true
                $h = [int]($z.minutos / 60)
                $cuanto = if ($h -gt 0) { "$h horas" } else { "$($z.minutos) minutos" }
                $msg = "$($z.nombre) lleva $cuanto abierto sin ventana y gastando procesador. Parece colgado. Si quieres, di: cierra lo colgado."
                Log "ZOMBI: $($z.nombre) PID=$($z.proc.Id) $($z.minutos) min uso=$([Math]::Round($z.uso, 2))"
                Show-Popup $msg
                Say $msg
                break   # de uno en uno: dos avisos seguidos serian una encerrona
            }
        }
    }

    # --- ¿se abrio lo que mande abrir? (cada 2 s, y solo si hay algo que mirar) ---
    # LO QUE YA HA ESPERADO BASTANTE, AL DISCO (26/09, idea 15). Con la cola vacia no cuesta ni
    # una comparacion de mas, que es lo que pide la regla 4.
    if ($script:traduccionesCuarentena.Count -gt 0 -and ($sw.ElapsedMilliseconds - $script:cuarentenaCheck) -ge 2000) {
        $script:cuarentenaCheck = $sw.ElapsedMilliseconds
        try { [void](Flush-Cuarentena) } catch { Log ('cuarentena: ' + $_.Exception.Message) }
    }
    # --- juzgar UN texto de repaso del registro (26/09, idea 19) ---
    # DE UNO EN UNO Y SOLO CON NOVA PARADA, y la razon esta medida: Test-FastCommand tarda una
    # media de 70 ms por frase y hasta 300 ms en las peores, asi que juzgar los treinta textos
    # de canary de una tacada serian dos segundos con el bucle quieto. La regla 4 dice que el
    # bucle no se bloquea, y esto no tiene ninguna prisa: el veredicto de cada linea se calcula
    # una sola vez en la vida y se guarda. Las guardas de estar ocupada son las mismas que usa
    # el aviso de juegos colgados, doce lineas mas arriba.
    if (-not $script:busy -and -not $script:armed -and -not $script:pendiente -and
        ($sw.ElapsedMilliseconds - $script:motoresCheck) -ge 3000) {
        $script:motoresCheck = $sw.ElapsedMilliseconds
        try { $script:motoresQuedan = Step-MotorVeredicto } catch { Log ('motores: ' + $_.Exception.Message); $script:motoresQuedan = 0 }
    }
    if (($script:aperturas.Count -gt 0 -or $script:juegosPedidos.Count -gt 0) -and ($sw.ElapsedMilliseconds - $script:aperturaCheck) -ge 2000) {
        $script:aperturaCheck = $sw.ElapsedMilliseconds
        try {
            foreach ($avisoAp in (Test-AperturasPendientes)) { Send-Aviso $avisoAp 'error' }
            # y los juegos, que hasta hoy no se comprobaban (idea 81)
            foreach ($avisoJ in (Test-JuegosPedidos)) { Send-Aviso $avisoJ 'error' }
        } catch { Log ("aperturas: " + $_.Exception.Message) }
    }

    # --- portapapeles (cada 4 s; ver HISTORIAL DEL PORTAPAPELES) ---
    if (($sw.ElapsedMilliseconds - $script:portaCheck) -ge 4000) {
        $script:portaCheck = $sw.ElapsedMilliseconds
        try { if ([System.Windows.Forms.Clipboard]::ContainsText()) { Watch-Portapapeles ([System.Windows.Forms.Clipboard]::GetText()) } } catch {}
    }

    # --- que musica suena (cada 5 s; ver LA MUSICA EN LA CAPSULA) ---
    if (($sw.ElapsedMilliseconds - $script:musicaCheck) -ge 5000) {
        $script:musicaCheck = $sw.ElapsedMilliseconds
        try { Watch-Musica (Get-MusicaActual) } catch { Log ("musica: " + $_.Exception.Message) }
    }

    # --- dock y cascos conectados (cada 15 s; ver DOCK Y CASCOS) ---
    if (($sw.ElapsedMilliseconds - $script:dispCheck) -ge 15000) {
        $script:dispCheck = $sw.ElapsedMilliseconds
        try { Watch-Dispositivos } catch { Log ("dispositivos: " + $_.Exception.Message) }
    }

    # --- notificaciones nuevas (cada 30 s; ver NOTIFICACIONES MIENTRAS JUEGAS) ---
    if (($sw.ElapsedMilliseconds - $script:notifCheck) -ge 30000) {
        $script:notifCheck = $sw.ElapsedMilliseconds
        if (-not $script:invitado) { try { [void](Watch-Notificaciones @(Get-Notificaciones)) } catch { Log ("notificaciones: " + $_.Exception.Message) } }
    }

    # --- reglas sobre apps: se abrio o se cerro una (cada 3 s; sin reglas de
    #     apps no mira nada) ---
    if (($sw.ElapsedMilliseconds - $script:appsCheck) -ge 3000) {
        $script:appsCheck = $sw.ElapsedMilliseconds
        try { Watch-AppsReglas } catch { Log ("reglas de apps: " + $_.Exception.Message) }
    }

    # --- que juego esta en primer plano (cada 10 s, es una consulta cara) ---
    if (($sw.ElapsedMilliseconds - $script:juegoCheck) -ge 10000) {
        $script:juegoCheck = $sw.ElapsedMilliseconds
        try {
            $script:juegoExeCandidato = ''
            $script:juegoPidCandidato = 0
            $j = Get-JuegoEnPrimerPlano
            # los segundos con el juego delante desde la ultima mirada (ver TIEMPO DE JUEGO)
            if ($script:juegoActivo -and $script:tiempoJuegoVisto -gt 0) {
                try { Add-TiempoJuego $script:juegoActivo ([int](($sw.ElapsedMilliseconds - $script:tiempoJuegoVisto) / 1000)) } catch {}
            }
            $script:tiempoJuegoVisto = $sw.ElapsedMilliseconds
            # EL CUADERNO DE LA ALLY, en la misma mirada (25/09). Se aprovecha este tic porque
            # Get-JuegoEnPrimerPlano ya ha pagado la consulta cara; pedir la ventana de delante
            # otra vez en su propio bucle seria gastar dos veces por el mismo dato (regla 5).
            # Aqui entra TODO lo que haya delante, sea juego o no: hasta hoy Nova miraba la
            # ventana y solo se quedaba con ella si era un juego.
            try {
                $appU = if ($j) { $j } else {
                    $prU = Get-ProcesoEnPrimerPlano
                    if ($prU) { [string]$prU.ProcessName } else { '' }
                }
                if ($script:usoAllyVisto -gt 0 -and $appU) {
                    Add-UsoAlly $appU ([int](($sw.ElapsedMilliseconds - $script:usoAllyVisto) / 1000)) (Get-InactividadMin)
                }
                $script:usoAllyVisto = $sw.ElapsedMilliseconds
                # Y UN VOLCADO POR RELOJ, NO SOLO POR CANTIDAD (26/09, idea 52). Medido en el log: 35
                # de las 71 sesiones terminadas desde el 18/09 (49 %) murieron sin cierre limpio, y 10
                # de ellas no llegaron ni a 300 s de vida, o sea que no volcaron NUNCA y perdieron su
                # cuenta entera. Save-UsoAlly ya sale sin escribir si no hay nada pendiente, asi que esto
                # no toca el disco cuando no hay nada nuevo. Segundo camino: el $sumaU -ge 300 de
                # Add-UsoAlly sigue en pie (regla 7). Un Stop-Process no dispara el manejador de salida;
                # este reloj es lo unico que salva esas 35 muertes sucias.
                if (($sw.ElapsedMilliseconds - $script:usoAllyVolcado) -ge ($UsoAllyVolcadoSeg * 1000)) {
                    $script:usoAllyVolcado = $sw.ElapsedMilliseconds
                    try { Save-UsoAlly } catch {}
                }
                # EL CANDIDATO A JUEGO DESCONOCIDO (26/09, idea 26). Se reusa el $appU que la
                # linea de arriba ya tiene en la mano: CERO consultas nuevas al sistema, que es
                # la regla 5. Si Nova ya sabe que es un juego ($j lleno) no hay nada que
                # aprender; si el proceso cambia, la cuenta empieza de nuevo.
                if ($j -or -not $appU) {
                    $script:exeSinJuego = ''
                    $script:exeSinJuegoDesde = 0
                } elseif ([string]$appU -ne [string]$script:exeSinJuego) {
                    $script:exeSinJuego = [string]$appU
                    $script:exeSinJuegoDesde = $sw.ElapsedMilliseconds
                }
            } catch {}
            if ($j -ne $script:juegoActivo) {
                if ($script:juegoActivo) { Exit-Juego $script:juegoActivo }
                if ($j) {
                    Log "juego en primer plano: $j"
                    $script:juegoDesde = $sw.ElapsedMilliseconds
                    $script:juegoExe = $script:juegoExeCandidato
                    $script:juegoPid = $script:juegoPidCandidato   # C4 (19/09): para saber si muere
                    Enter-Juego $j
                    if ($SoloBotonEnJuego) {
                        try {
                            # SOLO SE DICE CUANDO CAMBIA (idea 108): sin la bandera, con la salida
                            # aplazada esta linea se repetiria en cada vuelta del bucle.
                            if (-not $script:soloBotonPuesto) {
                                Log 'escucha: solo boton mientras juegas (config: escucha.soloBotonEnJuego)'
                            }
                            [System.IO.File]::WriteAllText($MarcaSoloBoton, $j)
                            $script:soloBotonPuesto = $true
                        } catch {}
                    }
                } else {
                    $script:juegoExe = ''
                    $script:juegoPid = 0
                    # LA PALABRA DE ACTIVACION TAMBIEN SE APLAZA (27/09, idea 108). Este borrado
                    # corria en el mismo segundo que el brillo, y por eso la escucha se apagaba y
                    # encendia SIETE veces en 75 minutos el 25/09. Mientras haya una salida en duda
                    # con ventana por delante, se deja como esta: si el juego vuelve -y en esos
                    # siete casos volvio- no ha pasado nada.
                    $dudaJ = $script:juegoSalida
                    $esperaJ = ($dudaJ -and $dudaJ.ventana -and
                                ($sw.ElapsedMilliseconds - [double]$dudaJ.desdeMs) -lt [double]$dudaJ.ventana)
                    if (-not $esperaJ) {
                        try { Remove-Item -LiteralPath $MarcaSoloBoton -Force -ErrorAction SilentlyContinue } catch {}
                        if ($SoloBotonEnJuego -and $script:soloBotonPuesto) {
                            $script:soloBotonPuesto = $false
                            Log 'escucha: vuelve la palabra de activacion (fuera del juego)'
                        }
                    }
                }
                $script:juegoActivo = $j
                # Y SE NOTA A QUE ESTAS JUGANDO (25/09, ideas 17 y 38): una racha o una vuelta
                # despues de mucho. Va por Send-AvisoEntorno, asi que con el juego ya delante
                # se guarda para cuando pueda decirse en vez de interrumpir la partida.
                try {
                    $frJ = Get-FraseJuegoNotado $j
                    if ($frJ) { [void](Send-AvisoEntorno 'juego-notado' $frJ 'bajo' 720) }
                } catch {}
                # Y SI ESE JUEGO NOS DEJA CIEGAS (25/09, idea 1): con el modo exclusivo la
                # capsula no se dibuja, asi que lo que solo va ahi no llega a nadie.
                try {
                    $ciegaAntes = $script:capsulaCiega
                    $script:capsulaCiega = Test-CapsulaCiega
                    if ($script:capsulaCiega -ne $ciegaAntes) {
                        Log ("CAPSULA " + $(if ($script:capsulaCiega) { "CIEGA: el juego esta en pantalla completa exclusiva; lo que solo se ve no llega" } else { "visible otra vez" }))
                    }
                } catch {}
                Refresh-UI   # la capsula cambia de avatar
            } elseif ($j) {
                Watch-LogrosSteam
                # cada hora completa de juego, una "medalla" en la capsula (sin voz)
                $horasJugadas = [int][Math]::Floor(($sw.ElapsedMilliseconds - $script:juegoDesde) / 3600000)
                if ($horasJugadas -gt $script:juegoHoras) {
                    $script:juegoHoras = $horasJugadas
                    Log "JUEGO: $horasJugadas h con $j"
                    Send-UIEvento 'logro'
                }
            }
            # C4 (19/09): se cerro de verdad el juego que dejamos? Va DESPUES de poner al
            # dia $script:juegoActivo a proposito: con el puesto, Test-PuedoAvisar tiraba
            # los dos avisos del cierre por "esta jugando".
            try { Test-SalidaJuego } catch { Log ("salida de juego: " + $_.Exception.Message) }
            # EL AVISO DE LAS DOS HORAS, CONTADO POR EL DIA Y NO POR EL TRAMO (23/09).
            # Antes pedia 120 minutos de primer plano SIN UN SOLO CORTE: $script:juegoDesde
            # se pone a cero cada vez que cambia la ventana de delante -Discord, el
            # navegador, la propia capsula de Nova- y encima cada reinicio lo reiniciaba.
            # Medido: con avisoMinutos=120 el aviso debio saltar TRES dias (It Takes Two el
            # 15/09 con 5 h 38, el 20/09 con 2 h 45 y el 22/09 con 3 h 12) y "JUEGO: aviso de
            # tiempo" sale UNA SOLA VEZ en catorce dias. El unico que salto es el unico tramo
            # de dos horas sin alt-tab ni reinicio.
            $diaAv = Get-DiaJuego
            if ($script:juegoAvisoDia -ne $diaAv) {
                $script:juegoAvisoDia = $diaAv; $script:juegoAvisoUlt = 0; Save-AvisoJuego
            }
            $pasoAv = if ($script:juegoAvisoCada -gt 0) { $script:juegoAvisoCada } else { $JuegoAvisoMin }
            if ($j -and $pasoAv -gt 0 -and $script:juegoAvisoNo -ne $diaAv -and
                -not ($script:juegoAvisoCada -eq 0 -and $script:juegoAvisoUlt -gt 0)) {
                $minHoy = Get-MinutosJuegoHoy $j
                if ($minHoy -ge ($script:juegoAvisoUlt + $pasoAv)) {
                    $script:juegoAvisoUlt = [int][Math]::Floor($minHoy / $pasoAv) * $pasoAv
                    Save-AvisoJuego
                    # IDEA 10: pasa por el freno de mano como todo lo demas. Es 'alto'
                    # porque suena JUGANDO, que es justo cuando hace falta oirlo.
                    [void](Test-PuedoAvisar 'juego-rato' 'alto' $pasoAv)
                    Log "JUEGO: aviso de tiempo ($minHoy min hoy con $j)"
                    # "HOY ya llevas", que es lo que de verdad se ha medido. Antes decia "ya
                    # llevas dos horas" queriendo decir "llevas dos horas sin cambiar de
                    # ventana", que no es lo mismo ni de lejos.
                    Send-Aviso ("Oye, hoy ya llevas " + (Format-Minutos $minHoy) + " con $j.") 'tiempo'
                }
            }
        } catch {}
    }

    # --- reglas por hora y periodicas; fechas; nota semanal (cada minuto) ---
    $minutoAhora = Get-Date -Format 'HH:mm'
    if ($minutoAhora -ne $script:minutoVisto) {
        # LOS HUECOS DEL MANDO, UNA VEZ AL MINUTO (28/09, ver Add-HuecoMando). Se juntan en RAM
        # durante el sondeo -donde escribir el json costaba 19 ms por roce- y bajan aqui. Al
        # minuto y no al dia: si Nova se reinicia, como mucho se pierde lo del ultimo minuto.
        try {
            if ($script:huecosMandoRam.Count -gt 0) {
                foreach ($hM in @($script:huecosMandoRam)) { [void](Add-HuecoMando ([int]$hM)) }
                [void]$script:huecosMandoRam.Clear()
            }
        } catch { Log ('huecos del mando: ' + $_.Exception.Message) }
        $script:minutoVisto = $minutoAhora
        try { Invoke-Reglas 'hora' $minutoAhora; Invoke-Reglas 'cada' } catch {}
        # Y SI REVIENTA, SE DICE (24/09). Este catch estaba vacio, asi que un fallo dentro de
        # Test-Recordatorios -leer el fichero, una entrada rara- desaparecia sin dejar nada. Es la
        # unica funcion de Nova que promete algo a futuro, y llevaba quince dias sin sonar ni una
        # vez sin que nadie pudiera saber por que.
        try { Test-Recordatorios } catch { Log ("recordatorios: " + $_.Exception.Message) }
        try { Update-BrilloAuto } catch {}   # ver BRILLO AUTOMATICO
        try { Test-FinSilencio } catch {}    # ver Set-AvisosEntorno: el silencio caduca al dia
        try { Test-FinInvitado } catch {}    # ver MODO INVITADO
        try { Test-LimiteJuego } catch {}    # ver LIMITE DE JUEGO PROPIO
        # jugando, el modelo de charla sale de la RAM (si no se esta hablando con el)
        try {
            if ($script:juegoActivo -and $script:charlaProc -and -not $script:charlaDescargada -and -not $script:charlaEsperando -and
                ($sw.ElapsedMilliseconds - $script:charlaUltima) -gt 30000) {
                if (Send-CharlaPedido @{ op = 'descargar' } $false) { $script:charlaDescargada = $true }
            }
        } catch {}
        # la copia del dia, tambien en el PRIMER minuto tras arrancar: diaVisto
        # nace con la fecha de hoy, asi que el bloque de "cambio de dia" no se
        # alcanza al arrancar y la copia no se hacia nunca (revision del 12/09)
        if (-not $script:copiaMirada) {
            $script:copiaMirada = $true
            # Y EN UN RATO QUE NO MOLESTE (25/09, idea 27). Ver TRABAJAR CUANDO NO MOLESTA:
            # las trece copias del registro se hicieron entre las 17 y las 22 h, las horas de
            # mas uso, porque esto corre al arrancar y braya arranca Nova cuando va a usarla.
            try {
                if (Test-CopiaPendiente) {
                    $ausC = 999
                    try { $ausC = [int](Get-AusenciaMin) } catch {}
                    if (Test-BuenRatoParaTrabajo $ausC ([bool]$script:juegoActivo) (Get-CopiaHorasEsperando)) {
                        [void](New-CopiaSeguridad 'la del dia')
                    }
                }
            } catch {}
            # LAS TAREAS DEL DIA VAN APARTE (27/09): colgaban dentro del try de la copia y detras de
            # su Compress-Archive, asi que un zip fallido -disco lleno, que es lo que Nova vigila-
            # se llevaba las siete en silencio. Fuera del 'if (Test-CopiaPendiente)' tambien a
            # proposito: que la copia de hoy ya estuviera hecha no es motivo para no repasar lo demas.
            #
            # PERO SI DENTRO DEL BUEN RATO (28/09, corregido con Nova delante). Al sacarlas de la
            # copia se las saco tambien de Test-BuenRatoParaTrabajo, y eso no tocaba: las siete son
            # LO MAS PESADO que hace Nova -la poda recomprime las 28 copias- y corren SINCRONAS en
            # el bucle, o sea que mientras duran Nova no oye. Medido en vivo el 28/09: mas de media
            # hora sorda desde el arranque, con braya delante preguntando que le pasaba.
            # La guarda ya existia y es la misma que usa la copia: sin juego delante y sin nadie
            # desde hace un rato, salvo que lleven demasiado esperando (ahi el plazo manda, que es
            # la regla 2: nada se queda sin hacerse para siempre).
            try {
                $ausT = 999
                try { $ausT = [int](Get-AusenciaMin) } catch {}
                if (Test-BuenRatoParaTrabajo $ausT ([bool]$script:juegoActivo) (Get-CopiaHorasEsperando)) {
                    [void](Invoke-TareasDelDia)
                }
            } catch { Log ('DIA: ' + $_.Exception.Message) }
        }
        $diaAhora = Get-Date -Format 'yyyy-MM-dd'
        if ($diaAhora -ne $script:diaVisto) {
            $script:diaVisto = $diaAhora
            try { Test-FechasHoy } catch {}
            # la copia del dia, en silencio (tambien al arrancar, si toca)
            # Y EN UN RATO QUE NO MOLESTE (25/09, idea 27). Ver TRABAJAR CUANDO NO MOLESTA:
            # las trece copias del registro se hicieron entre las 17 y las 22 h, las horas de
            # mas uso, porque esto corre al arrancar y braya arranca Nova cuando va a usarla.
            try {
                if (Test-CopiaPendiente) {
                    $ausC = 999
                    try { $ausC = [int](Get-AusenciaMin) } catch {}
                    if (Test-BuenRatoParaTrabajo $ausC ([bool]$script:juegoActivo) (Get-CopiaHorasEsperando)) {
                        [void](New-CopiaSeguridad 'la del dia')
                    }
                }
            } catch {}
            # LAS TAREAS DEL DIA VAN APARTE (27/09): colgaban dentro del try de la copia y detras de
            # su Compress-Archive, asi que un zip fallido -disco lleno, que es lo que Nova vigila-
            # se llevaba las siete en silencio. Fuera del 'if (Test-CopiaPendiente)' tambien a
            # proposito: que la copia de hoy ya estuviera hecha no es motivo para no repasar lo demas.
            #
            # PERO SI DENTRO DEL BUEN RATO (28/09, corregido con Nova delante). Al sacarlas de la
            # copia se las saco tambien de Test-BuenRatoParaTrabajo, y eso no tocaba: las siete son
            # LO MAS PESADO que hace Nova -la poda recomprime las 28 copias- y corren SINCRONAS en
            # el bucle, o sea que mientras duran Nova no oye. Medido en vivo el 28/09: mas de media
            # hora sorda desde el arranque, con braya delante preguntando que le pasaba.
            # La guarda ya existia y es la misma que usa la copia: sin juego delante y sin nadie
            # desde hace un rato, salvo que lleven demasiado esperando (ahi el plazo manda, que es
            # la regla 2: nada se queda sin hacerse para siempre).
            try {
                $ausT = 999
                try { $ausT = [int](Get-AusenciaMin) } catch {}
                if (Test-BuenRatoParaTrabajo $ausT ([bool]$script:juegoActivo) (Get-CopiaHorasEsperando)) {
                    [void](Invoke-TareasDelDia)
                }
            } catch { Log ('DIA: ' + $_.Exception.Message) }
            # lo que Windows apunto de los dias que Nova no estaba (idea 70). Una vez al dia y
            # nunca en el bucle: el informe cuesta ~248 ms.
            try { [void](Update-BateriaWindows) } catch { Log ('bateria de Windows: ' + $_.Exception.Message) }

            try { Write-NotaSemanal } catch {}
        }
        # micro-charla: un comentario si viene a cuento, una vez al dia
        # POR LA PUERTA DE SIEMPRE (18/09). Estas dos eran las unicas frases de toda Nova que
        # se saltaban todos los frenos: Say directo, y encima solo salen CON un juego delante,
        # que es justo lo que avisos.sinVozEnJuego prohibe para el resto. Son del 11/09, de
        # antes de que existieran los frenos (16/09). Ahora van por Send-Aviso, que aplaza si
        # estas dictando y calla -dejando el pulso en la capsula- con juego, sordina, modo
        # silencio o el microfono cogido por otra app.
        # NO por Send-AvisoEntorno: Test-PuedoAvisar mata todo lo que no sea 'alto' con un
        # juego activo, asi que estas dos, que solo salen jugando, desaparecerian del todo.
        if ($CharlaOn -and $script:juegoActivo) {
            $minsJuego = ($sw.ElapsedMilliseconds - $script:juegoDesde) / 60000
            if ($minsJuego -ge 180 -and $script:charlaAgua -ne $diaAhora) {
                $script:charlaAgua = $diaAhora
                Send-Aviso "Oye, ya van tres horas seguidas. Un vaso de agua no vendria mal." 'tiempo'
            }
            if ($minutoAhora -ge '01:00' -and $minutoAhora -le '01:05' -and $script:charlaTarde -ne $diaAhora) {
                $script:charlaTarde = $diaAhora
                Send-Aviso "Es la una de la manana. ¿Seguimos, o lo dejamos por hoy?" 'tiempo'
            }
        }
    }

    # --- vibracion del mando (patron en curso) ---
    if ($script:vibraCola.Count -gt 0 -or $script:vibraHasta -gt 0) { Tick-Vibracion }

    # --- acelerometro (cada 250 ms) y logros de Steam (con el juego) ---
    # CADA 500 ms Y NO 250 (27/09, idea 83). Medido con el banco: una vuelta del vigilante cuesta
    # 14,7 ms de media en esta consola -mas de lo que cuesta la lectura suelta- y la vuelta del
    # bucle entero son 31 ms, asi que a 250 ms se llevaria el 6 % del tiempo de Nova. A 500 se
    # queda en el 3 % y el sobresalto sigue viendose: un golpe dura mas que medio segundo en la
    # senal. Si algun dia estorba, la forma buena es ReadingChanged y no preguntar en el bucle.
    if ($script:acelerometro -and ($sw.ElapsedMilliseconds - $script:acelCheck) -ge 500) { $script:acelCheck = $sw.ElapsedMilliseconds; Watch-Acelerometro }
    # la orientacion, una vez por segundo: cuesta 0,157 ms medidos y no cambia mas deprisa que
    # se mueve una consola en una mesa (idea 69)
    if ($script:orientacion -and ($sw.ElapsedMilliseconds - $script:orientaCheck) -ge 1000) { $script:orientaCheck = $sw.ElapsedMilliseconds; Watch-Orientacion }

    # --- carga de CPU (cada 30 s): la capsula se agita si va al limite ---
    if (($sw.ElapsedMilliseconds - $script:cargaCheck) -ge 30000) {
        $script:cargaCheck = $sw.ElapsedMilliseconds
        try {
            $cpu = Get-CargaCPU
            if ($null -ne $cpu) {
                $cpu = [int]$cpu
                if ([Math]::Abs($cpu - $script:uiCarga) -ge 10 -or (($cpu -ge 85) -ne ($script:uiCarga -ge 85))) { $script:uiCarga = $cpu; Refresh-UI }
            }
        } catch {}
    }

    # --- el tiempo (una vez por hora; la primera, a los 20 s de arrancar) ---
    # Y SOLO SI HAY ALGUIEN A QUIEN CONTARSELO (27/09, idea 112). Medido en los dos registros: 62
    # consultas del tiempo entre las 02:00 y las 08:59, la franja donde no hay NI UNA de las 170
    # ordenes. Sin nadie, la cadencia pasa a ser lo que lleve sin nadie, y en cuanto vuelve, la
    # ronda cae en la siguiente vuelta del bucle. Test-RondaDeFondo trae ademas el Test-RedParaFondo
    # que a esto le faltaba: el correo de fondo si lo tenia desde la idea 84, el clima no, asi que
    # con la red caida salia a internet igual.
    if ($ClimaOn -and $sw.ElapsedMilliseconds -ge 20000 -and (Test-RondaDeFondo $script:climaCheck 3600000 'el tiempo')) {
        $script:climaCheck = $sw.ElapsedMilliseconds
        Update-Clima
    }

    # --- aviso proactivo de bateria (se comprueba una vez por minuto) ---
    if (($sw.ElapsedMilliseconds - $script:bateriaCheck) -ge 60000) {
        $script:bateriaCheck = $sw.ElapsedMilliseconds
        # LOS ERRORES QUE SE TRAGARON LOS catch VACIOS (27/09, idea 80). Gratis: ya estan en $Error.
        try {
            $petes = Watch-ErroresTragados
            if ($petes -gt 0) {
                $peor = Get-PeorPete
                if ($peor) { Add-Estadistica ('pete:' + $peor.linea) ([string]$peor.veces + ' veces: ' + $peor.que) }
                # Y SE DICE, QUE ES LO QUE FALTABA (1/10, idea 1 de las 20 nuevas). Ver
                # Get-PeorPeteHistorico: 1.087 errores tragados apuntados cuatro dias y leidos por
                # nadie. Aqui dentro porque el dato ya esta calculado y este bloque corre una vez
                # por minuto; el Add-Estadistica de arriba va PRIMERO a proposito, para que la
                # cuenta de hoy este dentro de la suma que mira el aviso.
                $hist = Get-PeorPeteHistorico
                if ($hist -and [int]$hist.veces -ge $PeteAvisaDesde) {
                    # LA CLAVE LLEVA LA LINEA, no solo 'pete': si se arregla uno y empieza otro, es
                    # otra noticia y tiene que poder salir. Y el 'veces' NO va en la clave -seria
                    # una noticia nueva cada minuto-, va en $script:peteDicho con un tope: se
                    # vuelve a decir solo si ha DOBLADO, igual que hace Add-LogRepe con las rachas.
                    $marca = [string]$hist.linea + ':' + [string]$hist.veces
                    $yaDicho = 0
                    if ($script:peteDicho -match '^(\d+):(\d+)$' -and $Matches[1] -eq [string]$hist.linea) { $yaDicho = [int]$Matches[2] }
                    if ($yaDicho -le 0 -or [int]$hist.veces -ge ($yaDicho * 2)) {
                        $script:peteDicho = $marca
                        $script:uiMia = $true   # idea 54: esto no lo ha preguntado nadie
                        [void](Send-AvisoEntorno ('pete-' + [string]$hist.linea) (Get-FrasePetes) 'medio' 1440)
                    }
                }
            }
        } catch {}
        # LO QUE SE ESTA REPITIENDO EN BUCLE (27/09, idea 76). Log solo cuenta; aqui se recoge y
        # se dice, que dentro de Log una llamada que escriba seria una recursion sin fin.
        try {
            foreach ($rp in @(Get-LogRepetido)) {
                $cortaR = if ($rp.clave.Length -gt 60) { $rp.clave.Substring(0, 60) } else { $rp.clave }
                Add-Estadistica 'repetido' ([string]$rp.veces + ' veces en ' + [string]$rp.minutos + ' min: ' + $cortaR)
                Log ('EN BUCLE: llevo ' + $rp.veces + ' veces lo mismo en ' + $rp.minutos + ' min: ' + $cortaR)
                # SOLO SE HABLA DE LO GORDO, y por la puerta que ya respeta el juego y la noche.
                if ([int]$rp.veces -ge ($LogRepeListon * 4)) {
                    [void](Send-AvisoEntorno 'en-bucle' ('Llevo ' + $rp.veces + ' intentos fallando lo mismo desde hace ' + $rp.minutos + ' minutos.') 'medio' 360)
                }
            }
        } catch {}
        try {
            $bat = Get-CimInstance Win32_Battery -ErrorAction SilentlyContinue | Select-Object -First 1
            if ($bat -and $bat.EstimatedChargeRemaining) {
                $pc = [int]$bat.EstimatedChargeRemaining
                # CUANTO TIEMPO QUEDA, ANTES DE QUE NADIE LO USE (21/09). Esto estaba 26 lineas
                # MAS ABAJO, detras del flanco del cargador que es el unico que lo lee: al
                # desenchufar, 'te quedan N minutos' miraba el valor de la vuelta ANTERIOR -la de
                # cuando aun estaba enchufada, que es justo cuando Windows no sabe estimarlo- y
                # soltaba el texto corto, 'Sin cargador, al 47 por ciento'. El dato sale del mismo
                # $bat que se acaba de leer dos lineas arriba, asi que no cuesta nada traerlo aqui.
                $script:bateriaMin = 0
                try {
                    $rt = [int]$bat.EstimatedRunTime
                    if ($rt -gt 0 -and $rt -lt 1000) { $script:bateriaMin = $rt }
                } catch {}
                $cargando = ($bat.BatteryStatus -eq 2)   # 2 = conectado a la red
                # la insignia de la capsula avisa por debajo del 20 % y
                # celebra la carga
                $cg = if ($cargando) { 1 } else { 0 }
                if ($pc -ne $script:uiBateria -or $cg -ne $script:uiCargando) {
                    # Y SE APUNTA LA SERIE (24/09, idea 7 de la tanda nueva). En quince dias el
                    # registro trae ~21 lecturas de porcentaje y casi todas dicen 100 %, asi que
                    # no hay con que decidir nada: la bateria por juego lleva quince dias sin
                    # aprender ni un tramo -0 lineas BATERIA:- y el motivo medido no es el
                    # umbral de 10 minutos, es que braya juega ENCHUFADO. El 23/09 jugo 191
                    # minutos y el unico desenchufe duro 1 minuto, 28 antes de abrir el juego.
                    # El solape juego-sin-cargador de quince dias son CINCO minutos.
                    # Esto no cambia ninguna decision: solo deja la serie para poder tomarla.
                    # VA AL FICHERO DEL LATIDO y no al registro: es una linea por punto
                    # porcentual, del orden de cien al dia, y el registro acaba de adelgazar.
                    if ($pc -ne $script:uiBateria) {
                        try {
                            $lineaB = ((Get-Date).ToString('yyyy-MM-dd HH:mm:ss') + '  [bateria] ' + $pc +
                                       ' % ' + $(if ($cargando) { 'cargando' } else { 'sin cargador' }) +
                                       $(if ($script:juegoActivo) { ' jugando a ' + $script:juegoActivo } else { '' }) +
                                       $(if ($script:bateriaMin -gt 0) { ' (Windows dice ' + $script:bateriaMin + ' min)' } else { '' }))
                            [System.IO.File]::AppendAllText($PulsoPath, $lineaB + "`r`n", (New-Object System.Text.UTF8Encoding $false))
                        } catch {}
                    }
                    $script:uiBateria = $pc; $script:uiCargando = $cg
                    Refresh-UI
                }
                # Y LA SERIE DE LA TEMPERATURA, AL LADO DE LA DE LA BATERIA (27/09, idea 103). Aqui
                # y no en su propio reloj: este bloque ya corre cada minuto y ya paga un
                # Get-CimInstance, que es justo lo que hace que la lectura termica sea barata (24-38
                # ms en caliente contra los 480 de la sonda de CPU que se apago por cara).
                #
                # SOLO CUANDO CAMBIA EL GRADO, como la bateria: Temperature viene en kelvin ENTEROS,
                # asi que esto son del orden de unas pocas lineas por hora, no una por minuto.
                try {
                    $tP = Get-Temperatura
                    if ($null -ne $tP -and [int]$tP.c -ne [int]$script:tempApuntada) {
                        $script:tempApuntada = [int]$tP.c
                        $lineaT = ((Get-Date).ToString('yyyy-MM-dd HH:mm:ss') + '  [temperatura] ' + [int]$tP.c +
                                   ' grados' + $(if ([int]$tP.throttle -ne 0) { ' FRENANDO (' + [int]$tP.throttle + ')' } else { '' }) +
                                   $(if ([int]$tP.pasivo -lt 100) { ' pasivo ' + [int]$tP.pasivo + ' %' } else { '' }) +
                                   $(if ($script:juegoActivo) { ' jugando a ' + $script:juegoActivo } else { '' }))
                        [System.IO.File]::AppendAllText($PulsoPath, $lineaT + "`r`n", (New-Object System.Text.UTF8Encoding $false))
                    }
                } catch {}
                # Y LO QUE ELLA MISMA OCUPA (27/09, idea 111). Aqui por lo mismo que la temperatura:
                # este bloque ya corre una vez por minuto y no hace falta estrenar reloj. Un proceso
                # por vuelta, 4 ms medidos, y la sonda se apaga sola si algun dia cuesta mas.
                try { [void](Update-Consumo) } catch {}
                # Y LA BATERIA DEL MANDO (30/09, la 6 de las 20). Aqui y no en el bucle porque el
                # nivel de un mando no cambia en 30 ms, y porque con el mando integrado de esta
                # consola no hay nada que mirar: Watch-BateriaMando sale en la primera linea.
                try { Watch-BateriaMando } catch {}
                # Y SI HAY UN "APAGA CUANDO ACABE" ARMADO (30/09, la 8 de las 20). Aqui porque una
                # descarga no acaba en 30 ms y leer los manifiestos cuesta disco; y la guarda de las
                # horas vive dentro, para que el modo no se quede puesto si la descarga se paro.
                try { Watch-ApagarAlAcabar } catch {}
                # Y EL RELOJ DEL REEMBOLSO (1/10, la 11 de las 20): la ventana de las dos horas se
                # pasa sola mientras juegas, y es dinero. Solo con un juego delante.
                if ($script:juegoActivo) { try { Watch-Reembolso ([string]$script:juegoActivo) } catch {} }
                # Y LA PANTALLA, SI BRAYA LO HA ENCENDIDO (27/09, idea 121, cableada tras la
                # revision). Nace apagado: con entorno.apagarPantalla en $false esto sale en la
                # primera linea sin mirar nada. Aqui y no en el bucle porque la decision necesita
                # Get-NadieMin, que lee habitos, el ocio de Windows, el mando y el acelerometro.
                try { [void](Watch-PantallaDormida) } catch { Log ('PANTALLA: ' + $_.Exception.Message) }
                if (-not $cargando) { Invoke-Reglas 'bateria' ([string]$pc) }
                # CARGADOR: solo en el FLANCO, cuando cambia. Por estado se
                # repetiria cada minuto mientras siguiera enchufado.
                if ($null -ne $script:cargandoAntes -and $cg -ne $script:cargandoAntes) {
                    Invoke-Reglas 'cargadorQuita' $(if ($cg -eq 0) { 'quita' } else { '' })
                    Invoke-Reglas 'cargadorPone' $(if ($cg -eq 1) { 'pone' } else { '' })
                    Log "cargador: $(if ($cg -eq 1) { 'enchufado' } else { 'desenchufado' })"
                    # solo al PONERLO: el dato que falta es a que % decide enchufar
                    if ($cg -eq 1) { try { [void](Add-CargaConectada $pc) } catch {} }
                    # idea 13: al enchufar, lo util es cuanto le falta
                    if ($cg -eq 1) {
                        [void](Send-AvisoEntorno 'cargador-pone' "Cargando, vas por el $pc por ciento." 'bajo' 20)
                    } else {
                        # idea 7: al desenchufar, cuanto te queda EN TIEMPO, no en porcentaje
                        $txtB = "Sin cargador, al $pc por ciento."
                        if ($script:bateriaMin -gt 0) { $txtB = "Sin cargador: te quedan unos $([int]$script:bateriaMin) minutos." }
                        [void](Send-AvisoEntorno 'cargador-quita' $txtB 'medio' 20)
                    }
                }
                # idea 15: la dejaste cargando toda la noche y ya esta llena.
                # POR FLANCO, COMO EL CARGADOR DE VEINTE LINEAS MAS ARRIBA (22/09 noche).
                # Estaba por ESTADO, dentro de un bloque que corre cada minuto: mientras la
                # consola siguiera enchufada al 100 %, esto era cierto el dia entero. Lo
                # unico que frenaba el aviso era su propio plazo de 240 min, y el resultado
                # medido son 19 avisos identicos en el log, cuatro al dia desde el 19/09
                # (08:00, 12:00, 16:00, 20:02) -el segundo aviso mas repetido despues del
                # ventilador-, y el ultimo 'cargador: desenchufado' es del 19/09 a las 09:24:
                # o sea que los quince ultimos salieron sin un solo cambio de estado.
                # Y EL AVISO ERA LO DE MENOS. La linea de al lado, Invoke-Reglas
                # 'bateriaLlena', NO tiene plazo ninguno -el 240 vive dentro de
                # Send-AvisoEntorno- y su rama del despacho es estado pelado
                # ('bateriaLlena' { $dispara = ($dato -eq 'llena') }), sin el $r.ultima que
                # si tienen 'bateria' y 'disco'. Hoy no se nota porque reglas.json esta
                # vacio, pero el dia que braya diga "cuando termine de cargar, pon el modo
                # trabajo" -una frase que el propio codigo sabe entender-, esa accion se
                # ejecutaria CADA SESENTA SEGUNDOS mientras no desenchufara. Eso ya no es un
                # aviso pesado: es una orden que nadie dio, repetida toda la tarde.
                # Se pierde a proposito: si Nova reinicia justo mientras cruza el 100 %, ese
                # episodio no avisa. Es el mismo trato que ya aceptan cargador-pone y
                # cargador-quita.
                if (Test-BateriaLlenaFlanco ($cargando -and $pc -ge 100)) {
                    Invoke-Reglas 'bateriaLlena' 'llena'
                    [void](Send-AvisoEntorno 'bateria-llena' (Get-FraseVariada 'bateria-llena' @(
                        'Ya esta cargada del todo, puedes desenchufarla.',
                        'Bateria al cien. Ya puedes quitar el cargador.',
                        'Carga completa; el cargador ya no hace falta.',
                        'Ya esta llena. Desenchufala cuando quieras.')) 'bajo' 240)
                }
                # EL RECORDATORIO mientras sigas sin enchufar (idea 14; repartido el 25/09,
                # ver QUE AVISO DE BATERIA TOCA). Antes decia "$pc -le 15" a pelo y saltaba a la
                # vez que la frase hablada de mas abajo: lo mismo dicho dos veces. Ahora solo
                # habla cuando el primer aviso YA salio, y su plazo de 20 min hace el resto.
                if ((Get-AvisoBateria $pc ([bool]$cargando) ([bool]$script:bateriaAvisada)) -eq 'recordatorio') {
                    [void](Send-AvisoEntorno 'bateria-baja' "Te queda el $pc por ciento de bateria." 'alto' 20)
                }
                $script:cargandoAntes = $cg
                # cuanto gasta el juego de delante (ver BATERIA POR JUEGO)
                try { Update-BateriaJuego $pc $cg } catch { Log ("bateria por juego: " + $_.Exception.Message) }
                # a tu hora de dejarla y con poca bateria (ver RECORDATORIO PARA CARGAR)
                try {
                    if (Test-RecordarCarga $pc $cg) {
                        Log "CARGA: recordatorio ($pc %)"
                        Send-UIEvento 'pulso:bateria'
                        if (-not $script:busy -and -not $script:pendiente -and $script:uiEstado -eq 'reposo') { Set-UI 'hablando' 'Enchufame antes de dormir' 4000 }
                    }
                } catch { Log ("recordatorio de carga: " + $_.Exception.Message) }
                # DESCARGAS DE STEAM: ya no se miran aqui (23/09, idea 3). Habia un SEGUNDO
                # flanco, por nombre, con el mismo fallo que el hablado: disparaba las reglas
                # suyas al dejar de bajar, sin mirar si el juego habia quedado instalado.
                # Ahora los dos comen del mismo Test-DescargasFlanco, que vive en el bloque
                # de 120 s de arriba, con las lineas de log de las tres ramas silenciosas.
                # DISCO: se mira aqui mismo, que ya estamos en el chequeo por minuto
                try {
                    $di = New-Object System.IO.DriveInfo('C')
                    if ($di.IsReady) {
                        $gbLibres = [Math]::Round($di.AvailableFreeSpace / 1073741824.0, 1)
                        # UNA LINEA POR GIGA PERDIDO (23/09, idea 5 de la cuarta tanda). El
                        # 22/09, entre el ultimo aviso de disco (08:33, 11,1 GB) y las 22:50
                        # (0,81 GB), el disco se miro unas 831 veces y se escribieron CERO
                        # lineas: el 0,81 no aparece en el log ni una vez. En 14 dias hay tres
                        # cifras de disco en todo el registro, las tres de avisos que salieron.
                        # Asi, "no salio" y "no hacia falta" se escriben igual: nada. Con esto,
                        # el aviso de disco critico que se puso anoche se puede comprobar la
                        # proxima vez que baje, en vez de esperar semanas.
                        # SOLO AL BAJAR y por gigas enteros: un juego descargando que oscila
                        # entre 13,9 y 14,0 escribiria una linea por minuto. Y la primera de
                        # cada arranque se apunta siempre, que sirve de marca.
                        $suelo = [int][Math]::Floor($gbLibres)
                        if ($null -eq $script:discoUltimoGb -or $suelo -lt [int]$script:discoUltimoGb) {
                            Log "DISCO: $gbLibres GB libres"
                            $script:discoUltimoGb = $suelo
                        } elseif ($suelo -gt [int]$script:discoUltimoGb) {
                            $script:discoUltimoGb = $suelo    # subio (borraste algo): se reengancha sin escribir
                        }
                        Invoke-Reglas 'disco' ([string]$gbLibres)
                        # LA OTRA UNIDAD, SI TIENE MAS SITIO (26/09, idea 41). Se calcula UNA vez
                        # y AQUI ARRIBA -no dentro del try del aviso- para no partir la ventana
                        # de '} catch {}' que probar-disco-critico usa para acotar el bloque. Se
                        # interpola una variable corta en los dos textos.
                        $otraU = ''
                        try { $otraU = Get-FraseOtraUnidad 'C' } catch {}
                        # y el juego mas grande que bajaste y no abriste (27/09, idea 49). Se monta
                        # aqui arriba -fuera de la ventana de la regla del banco disco-critico- y se
                        # interpola en el aviso; si no hay ninguno, la frase se queda sin la promesa.
                        $colaDisco = ''
                        try { $sinD = @(Get-JuegosSinAbrir); if ($sinD.Count -gt 0) { $colaDisco = " $($sinD[0].nombre) ocupa $([Math]::Round([double]$sinD[0].tamano / 1GB, 1)) gigas y no lo has abierto nunca." } } catch { }
                        # idea 25: con menos de 15 gigas, un juego ya no cabe
                        # Y CON MENOS DE DOS, YA NO CABE NI WINDOWS (22/09 por la noche, con
                        # el dato delante). Este aviso es de nivel 'medio' y con plazo de 720
                        # minutos, y eso, que esta bien para "te quedan 11 gigas", fue un
                        # desastre para lo de hoy: el ultimo salio a las 08:33 diciendo 11,1
                        # gigas y a las 22:50 quedaban 0,81 -el 0,18 % del disco- sin que
                        # hubiera dicho ni una palabra en catorce horas. Doce son el plazo y
                        # dos y media el silencio del modo juego; y a las 23:00 entraba el
                        # silencio de la noche, asi que no habria hablado hasta las 08:00 de
                        # la mañana, con el disco a cero.
                        # Por debajo del liston critico pasa a 'alto', que es el unico nivel
                        # que se salta el juego, la noche y el tope por hora -el mismo trato
                        # que la bateria al 15 %-, y con plazo corto: cuando quedan minutos
                        # de escritura, repetirlo cada hora no es pesado, es lo unico util.
                        # Los dos numeros son de config, que braya los pueda tocar.
                        $discoCritico = [double](Get-Cfg 'entorno' 'discoCriticoGb' 2)
                        if ($gbLibres -lt $discoCritico) {
                            [void](Send-AvisoEntorno 'disco-critico' "Quedan $gbLibres gigas en el disco, casi nada$otraU. Voy a empezar a fallar: borra algo o dime que ocupa mas." 'alto' 60)
                        } elseif ($gbLibres -lt 15) {
                            [void](Send-AvisoEntorno 'disco-poco' "Te quedan $gbLibres gigas en el disco$otraU.$colaDisco" 'medio' 720)
                        }
                    }
                } catch {}
                # EL PRIMER AVISO del episodio (ver QUE AVISO DE BATERIA TOCA, 25/09)
                if ((Get-AvisoBateria $pc ([bool]$cargando) ([bool]$script:bateriaAvisada)) -eq 'primero') {
                    $script:bateriaAvisada = $true
                    Log "AVISO: bateria al $pc %"
                    # AHORRO JUGANDO (13/09): con un juego delante no se habla. Pulso
                    # ambar y la pregunta en la capsula; se contesta con ≡+A / ≡+B o
                    # la voz. Solo si el brillo esta alto: si no, no hay que ahorrar.
                    $brilloAhora = -1
                    if ($script:juegoActivo) { try { $brilloAhora = [int]((Get-CimInstance -Namespace root/WMI -ClassName WmiMonitorBrightness -ErrorAction Stop | Select-Object -First 1).CurrentBrightness) } catch {} }
                    if ($script:juegoActivo -and $brilloAhora -gt 40 -and -not $script:pendiente -and -not $script:busy) {
                        Send-UIEvento 'pulso:bateria'
                        $script:pendiente = @{ texto = ''; vence = 0; tipo = 'ahorro' }
                        Set-UI 'escuchando' "Bateria al $pc%. ¿Bajo el brillo?"
                        Start-Confirmacion
                    } else {
                        Send-Aviso "Oye, te queda $pc por ciento de bateria." 'bateria'
                    }
                }
                # rearmar cuando se recupera, para que pueda volver a avisar
                if (Test-BateriaRearme $pc ([bool]$cargando)) { $script:bateriaAvisada = $false }
            }
        } catch {}
    }

    # cierra el popup al vencer su plazo (antes se esperaba 8 s bloqueando)
    # el plazo cuenta despues de que Nova termine de LEERLA (mientras habla el
    # oido esta en pausa y no puedes decir "dejala ahi"), y se congela mientras
    # dictas: si no, cerraba justo cuando ibas a fijarla (revision del 13/09)
    if ($script:popupUntil -gt 0 -and $sw.ElapsedMilliseconds -ge $script:popupUntil -and
        $sw.ElapsedMilliseconds -ge ($script:pausaHasta + 5000) -and -not $script:armed) {
        Close-Popup
    }

    # LA LUPA SE QUITA SOLA A LOS 12 s, Y AQUI SON 12 DE VERDAD (revision del 23/09). Nacio
    # dentro de Watch-Entorno, que sale de su cuerpo con un "si no han pasado 30 s, vuelve":
    # los 12 s prometidos eran 12 mas lo que faltara para la siguiente vuelta buena, o sea
    # hasta 42, con una ventana que tapa el 92 % de la pantalla. Su propio comentario decia
    # "como la tarjeta", y la tarjeta se cierra justo aqui.
    if ($script:lupaForm -and $script:lupaUntil -gt 0 -and $sw.ElapsedMilliseconds -ge $script:lupaUntil) { Close-Lupa }

    # Y EL VOLUMEN DEL JUEGO SE DEVUELVE SIEMPRE (ver HACERSE SITIO PARA HABLAR). Aqui y no
    # pegado al final de la frase: si Nova muere, si la cortan, o si la voz falla a medias, el
    # juego tiene que recuperar su volumen igual. Con techo duro de 20 s.
    # AQUI Y NO EN Watch-Entorno (revision del 23/09): estaba debajo del mismo freno de 30 s,
    # asi que "se lo devuelvo en cuanto callo" era en realidad "entre 0 y 30 s despues de
    # callar", con el juego sonando al 35 % mientras tanto. El techo duro de 20 s tampoco
    # salvaba nada, porque se miraba en la misma linea, detras del mismo freno.
    if ($script:juegoVolAntes -ge 0) {
        $callada = ($sw.ElapsedMilliseconds -ge $script:vozFinReal -and $sw.ElapsedMilliseconds -ge $script:pausaHasta)
        if ($callada -or $sw.ElapsedMilliseconds -ge $script:juegoBajadoHasta) { Pop-VolumenJuego }
    }

    # el tiempo vuelve a ser la carita al vencer su plazo
    if ($script:uiClimaHasta -gt 0 -and $sw.ElapsedMilliseconds -ge $script:uiClimaHasta) {
        $script:uiClimaHasta = 0
        $script:uiClima = ''
        Refresh-UI
    }

    # --- INTERFAZ: vuelta al reposo y vigilancia del proceso ---
    if ($script:uiHasta -gt 0 -and $sw.ElapsedMilliseconds -ge $script:uiHasta) {
        # solo si no hay nada en marcha: escuchando o pensando mandan
        if (-not $script:armed -and -not $script:busy) { Set-UI 'reposo' } else { $script:uiHasta = 0 }
    }
    if ($UiNuevaOn -and ($sw.ElapsedMilliseconds - $script:uiCheck) -ge 30000) {
        $script:uiCheck = $sw.ElapsedMilliseconds
        # ¿SE LA VE? (27/09, idea 67). Antes esto solo se miraba al cambiar de juego, y un juego
        # que entra en exclusivo a los diez minutos de abrirse no se notaba nunca. Ahora la capsula
        # lo escribe cada 5 s y aqui se lee, con juego delante o sin el.
        try {
            $ciegaAntes30 = $script:capsulaCiega
            $script:capsulaCiega = Test-CapsulaCiega
            if ($script:capsulaCiega -ne $ciegaAntes30) {
                Log ("CAPSULA " + $(if ($script:capsulaCiega) { "CIEGA: el juego esta en pantalla completa exclusiva; lo que solo se ve no llega" } else { "visible otra vez" }))
            }
        } catch {}
        # Y SI SE COLGO VIVA (27/09, idea 67). Hasta hoy solo se vigilaba el proceso MUERTO:
        # una capsula colgada con su ventana pintada y sin atender nada se quedaba asi para
        # siempre. El latido de ui-visible.txt lo delata. Solo cuenta si el fichero EXISTE: con
        # un nova_ui.exe viejo -que no lo escribe- su ausencia no puede valer de sintoma, o seria
        # un relanzamiento cada 30 s para siempre.
        # EL TOPE TIENE QUE CONTAR TAMBIEN POR AQUI (28/09, tras la revision). Esta rama subia
        # $script:uiIntentos, mataba la capsula y llamaba a Initialize-UI... y en la MISMA vuelta el
        # 'elseif ($script:uiProc)' de mas abajo lo devolvia a cero, porque el if de enmedio exige
        # '-not $colgada' y uiProc ya era el proceso NUEVO. O sea que el contador nunca acumulaba:
        # una capsula que se cuelga viva se mataba y se relanzaba cada 30 segundos PARA SIEMPRE,
        # con el registro diciendo "intento 1/3" cada vez, que es exactamente el "relanzamiento cada
        # 30 s para siempre" que el comentario de aqui arriba dice estar evitando. Comprobado
        # ejecutando el bloque real seis veces: seis relanzos, uiIntentos = 0 en todas, y el
        # "no se sostiene" inalcanzable. Por la via de MUERTE el tope si funcionaba.
        # Y AL AGOTARSE, SE BAJA A LA BARRA ANTIGUA como en la otra via: si no, tras tres intentos
        # la guarda dejaba de entrar y la capsula se quedaba colgada para siempre sin salida, que es
        # la regla 2. Se mata ademas, o quedaria una ventana fantasma encima.
        $colgada = $false
        if ($script:uiProc -and -not $script:uiProc.HasExited) {
            try {
                $vLat = Get-UiVisible
                if ($vLat -and $vLat.hace -gt (6 * $vLat.cada) -and $script:uiIntentos -ge 3) {
                    $colgada = $true
                    if ($script:uiIntentos -eq 3) {
                        $script:uiIntentos++
                        Log "ERROR: la interfaz se queda colgada y no se sostiene; vuelve la barra antigua"
                        $script:UiNuevaOn = $false
                        $capture.Opacity = 1
                        try { $script:uiProc.Kill() } catch {}
                        try { $script:uiProc.Dispose() } catch {}
                        $script:uiProc = $null
                    }
                }
                elseif ($vLat -and $vLat.hace -gt (6 * $vLat.cada)) {
                    $colgada = $true
                    Log ("WARN: la interfaz lleva " + [int]($vLat.hace / 1000) + " s sin latir (su cadencia son " + [int]($vLat.cada / 1000) + " s); relanzando (intento " + ($script:uiIntentos + 1) + "/3)")
                    $script:uiIntentos++
                    Add-Estadistica 'relanza:capsula'
                    try { $script:uiProc.Kill() } catch {}
                    try { $script:uiProc.Dispose() } catch {}
                    $script:uiProc = $null
                    Initialize-UI
                }
            } catch { Log ('latido de la capsula: ' + $_.Exception.Message) }
        }
        if (-not $colgada -and $script:uiProc -and $script:uiProc.HasExited) {
            if ($script:uiIntentos -lt 3) {
                $script:uiIntentos++
                # POR QUE murio (14/09): el codigo de salida y lo ultimo que apunto
                # la propia capsula en tmp\ui-error.log
                $porQueUi = ''
                try { $porQueUi = " codigo $($script:uiProc.ExitCode)" } catch {}
                try {
                    $rutaErrUi = Join-Path $TmpDir 'ui-error.log'
                    if ((Test-Path -LiteralPath $rutaErrUi) -and ((Get-Item -LiteralPath $rutaErrUi).LastWriteTime -gt (Get-Date).AddMinutes(-2))) {
                        $ultErrUi = @(Get-Content -LiteralPath $rutaErrUi -Tail 1)[0]
                        if ($ultErrUi) { $porQueUi += "; su ultimo error: " + $ultErrUi.Substring(0, [Math]::Min(400, $ultErrUi.Length)) }
                    }
                } catch {}
                Log "WARN: la interfaz murio ($porQueUi); relanzando (intento $($script:uiIntentos)/3)"
                Add-Estadistica 'relanza:capsula'   # idea 50: pegado al Log y ANTES del Dispose/Initialize-UI
                try { $script:uiProc.Dispose() } catch {}
                $script:uiProc = $null
                Initialize-UI
            } elseif ($script:uiIntentos -eq 3) {
                $script:uiIntentos++
                Log "ERROR: la interfaz no se sostiene; vuelve la barra antigua"
                $script:UiNuevaOn = $false
                $capture.Opacity = 1
            }
        } elseif (-not $colgada -and $script:uiProc) {
            # EL '-not $colgada' ES LO QUE FALTABA (28/09): sin el, la rama de colgada de arriba
            # dejaba el contador a cero en su misma vuelta y el tope no llegaba a contar nunca.
            $script:uiIntentos = 0
        }
    }

    $startPrev = $startNow
    } catch {
        $script:erroresBucle++
        $dondeErr = ''
        try { $dondeErr = " (linea $($_.InvocationInfo.ScriptLineNumber))" } catch {}
        if ($script:erroresBucle -le 50) { Log ("ERROR en una vuelta del bucle, sigo: " + $_.Exception.Message + $dondeErr) }
        # lo que pudo quedar a medias no puede dejar a Nova esperando para siempre
        $script:armed = $false
        $script:pendiente = $null
        $startPrev = $startNow
        try { Set-UI 'reposo' } catch {}
        Start-Sleep -Milliseconds 300
    }
    Start-Sleep -Milliseconds $BucleSuenoMs
}